// Magias fora do SRD 5.2.1 (PHB 2024 e suplementos) e nomes em português das
// magias do SRD. Só metadados + resumos ORIGINAIS (nunca texto de livro pago).
// Formato de cada magia igual a srd2024-spells.json:
// { id, name: {pt, en}, level, school, classes: [...], castingTime, range,
//   components, duration, ritual, concentration, desc: {pt, en}, rulesVersion: '2024', source }
// PHB24 usa as listas de classe do PHB 2024 (+ artífice); suplementos usam as listas do próprio livro
// (com as expansões de artífice do TCE). `desc` é um resumo curto, não o texto da magia.
// `metaPt` (tempo, alcance, componentes e duração em pt, em metros) é gerado no fim do
// arquivo por translateSpellMeta — os campos em inglês continuam para os filtros.
const RAW_EXTRA_SPELLS = [
  // Já citadas pelas classes/subclasses (prioridade)
  {"id": "mindSliver", "name": {"pt": "Lasca Mental", "en": "Mind Sliver"}, "level": 0, "school": "enchantment", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V", "duration": "1 round", "ritual": false, "concentration": false, "desc": {"pt": "Você tenta despedaçar temporariamente a mente de uma criatura que possa ver dentro do alcance. O alvo deve ser bem-sucedido em uma salvaguarda de Inteligência ou sofrerá 1d6 de dano Psíquico e subtrairá 1d4 da próxima salvaguarda que fizer antes do final do seu próximo turno.\n\nAprimoramento de Truque. O dano aumenta em 1d6 quando você atinge os níveis 5 (2d6), 11 (3d6) e 17 (4d6).", "en": "You try to temporarily sliver the mind of one creature you can see within range. The target must succeed on an Intelligence saving throw or take 1d6 Psychic damage and subtract 1d4 from the next saving throw it makes before the end of your next turn.\n\nCantrip Upgrade. The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6)."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "armorOfAgathys", "name": {"pt": "Armadura de Agathys", "en": "Armor of Agathys"}, "level": 1, "school": "abjuration", "classes": ["warlock"], "castingTime": "Bonus Action", "range": "Self", "components": "V, S, M (a shard of blue glass)", "duration": "1 hour", "ritual": false, "concentration": false, "desc": {"pt": "Uma geada mágica protetora envolve você. Você ganha 5 Pontos de Vida Temporários. Se uma criatura atingir você com uma jogada de ataque corpo a corpo antes da magia acabar, ela sofre 5 de dano de Frio. A magia termina antecipadamente se você não possuir mais Pontos de Vida Temporários.\n\nUsando um Espaço de Magia de Círculo Superior. Os Pontos de Vida Temporários e o dano de Frio aumentam em 5 para cada círculo do espaço de magia acima do 1º.", "en": "Protective magical frost surrounds you. You gain 5 Temporary Hit Points. If a creature hits you with a melee attack roll before the spell ends, the creature takes 5 Cold damage. The spell ends early if you have no Temporary Hit Points.\n\nUsing a Higher-Level Spell Slot. The Temporary Hit Points and the Cold damage both increase by 5 for each spell slot level above 1."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "armsOfHadar", "name": {"pt": "Braços de Hadar", "en": "Arms of Hadar"}, "level": 1, "school": "conjuration", "classes": ["warlock"], "castingTime": "Action", "range": "Self (10-foot Emanation)", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Invocando Hadar, você faz gavinhas irromperem de você. Cada criatura em uma Emanação de 3 metros originada de você faz uma salvaguarda de Força. Em uma salvaguarda com falha, o alvo sofre 2d6 de dano Necrótico e não pode realizar Reações até o início do próximo turno dele. Em uma salvaguarda bem-sucedida, o alvo sofre apenas metade do dano.", "en": "Invoking Hadar, you cause tendrils to erupt from yourself. Each creature in a 10-foot Emanation originating from you makes a Strength saving throw. On a failed save, a target takes 2d6 Necrotic damage and can't take Reactions until the start of its next turn. On a successful save, a target takes half as much damage only."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "compelledDuel", "name": {"pt": "Duelo Compelido", "en": "Compelled Duel"}, "level": 1, "school": "enchantment", "classes": ["paladin"], "castingTime": "Bonus Action", "range": "30 feet", "components": "V", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você tenta compelir uma criatura para um duelo. Uma criatura que você possa ver dentro do alcance faz uma salvaguarda de Sabedoria. Em uma salvaguarda com falha, o alvo tem Desvantagem em jogadas de ataque contra criaturas que não sejam você, e não pode se mover voluntariamente para um espaço que esteja a mais de 9 metros de você.\nA magia termina se você fizer uma jogada de ataque contra uma criatura que não seja o alvo, se conjurar uma magia em um inimigo que não seja o alvo, se um aliado seu causar dano ao alvo ou se você terminar seu turno a mais de 9 metros de distância do alvo.", "en": "You try to compel a creature into a duel. One creature that you can see within range makes a Wisdom saving throw. On a failed save, the target has Disadvantage on attack rolls against creatures other than you, and it can't willingly move to a space that is more than 30 feet away from you.\nThe spell ends if you make an attack roll against a creature other than the target, if you cast a spell on an enemy other than the target, if an ally of yours damages the target, or if you end your turn more than 30 feet away from the target."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "wrathfulSmite", "name": {"pt": "Destruição Colérica", "en": "Wrathful Smite"}, "level": 1, "school": "necromancy", "classes": ["paladin"], "castingTime": "Bonus Action, which you take immediately after hitting a creature with a Melee weapon or an Unarmed Strike", "range": "Self", "components": "V", "duration": "1 minute", "ritual": false, "concentration": false, "desc": {"pt": "O alvo sofre 1d6 de dano Necrótico adicional pelo ataque, e deve ser bem-sucedido em uma salvaguarda de Sabedoria ou ficará com a condição Amedrontado até a magia acabar. No final de cada um dos turnos dele, o alvo Amedrontado repete a salvaguarda, encerrando a magia sobre si mesmo em caso de sucesso.\n\nUsando um Espaço de Magia de Círculo Superior. O dano aumenta em 1d6 para cada círculo do espaço de magia acima do 1º.", "en": "The target takes an extra 1d6 Necrotic damage from the attack, and it must succeed on a Wisdom saving throw or have the Frightened condition until the spell ends. At the end of each of its turns, the Frightened target repeats the save, ending the spell on itself on a success.\n\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "beastSense", "name": {"pt": "Sentido Bestial", "en": "Beast Sense"}, "level": 2, "school": "divination", "classes": ["druid", "ranger"], "castingTime": "Action or Ritual", "range": "Touch", "components": "S", "duration": "Concentration, up to 1 hour", "ritual": true, "concentration": true, "desc": {"pt": "Você toca uma Besta voluntária. Pela duração, você pode perceber através dos sentidos da Besta bem como através dos seus próprios. Ao perceber através dos sentidos da Besta, você se beneficia de quaisquer sentidos especiais que ela possua.", "en": "You touch a willing Beast. For the duration, you can perceive through the Beast's senses as well as your own. When perceiving through the Beast's senses, you benefit from any special senses it has."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "crownOfMadness", "name": {"pt": "Coroa da Loucura", "en": "Crown of Madness"}, "level": 2, "school": "enchantment", "classes": ["bard", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "120 feet", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Uma criatura que você possa ver dentro do alcance deve ser bem-sucedida em uma salvaguarda de Sabedoria ou terá a condição Enfeitiçado pela duração. A criatura é bem-sucedida automaticamente se não for um Humanoide.\nUma coroa espectral surge na cabeça do alvo Enfeitiçado, e ele deve usar sua ação antes de se mover em cada um de seus turnos para fazer um ataque corpo a corpo contra uma criatura que não seja ele mesmo e que você escolha mentalmente. O alvo pode agir normalmente no turno dele se você não escolher criatura alguma ou se nenhuma criatura estiver dentro do alcance dele. O alvo repete a salvaguarda no final de cada um dos turnos dele, encerrando a magia sobre si mesmo em caso de sucesso.\nEm seus turnos posteriores, você deve realizar a ação de Magia para manter o controle do alvo, caso contrário a magia termina.", "en": "One creature that you can see within range must succeed on a Wisdom saving throw or have the Charmed condition for the duration. The creature succeeds automatically if it isn't Humanoid.\nA spectral crown appears on the Charmed target's head, and it must use its action before moving on each of its turns to make a melee attack against a creature other than itself that you mentally choose. The target can act normally on its turn if you choose no creature or if no creature is within its reach. The target repeats the save at the end of each of its turns, ending the spell on itself on a success.\nOn your later turns, you must take the Magic action to maintain control of the target, or the spell ends."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "summonBeast", "name": {"pt": "Invocar Besta", "en": "Summon Beast"}, "level": 2, "school": "conjuration", "classes": ["druid", "ranger"], "castingTime": "Action", "range": "90 feet", "components": "V, S, M (a feather, tuft of fur, and fish tail inside a gilded acorn worth 200+ GP)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você invoca um espírito bestial. Ele se manifesta em um espaço desocupado que você possa ver dentro do alcance e usa o bloco de estatísticas de Espírito Bestial. Quando você conjura a magia, escolha um ambiente: Ar, Terra ou Água. A criatura se assemelha a um animal de sua escolha nativo do ambiente escolhido, o que determina certos detalhes em seu bloco de estatísticas. A criatura desaparece quando cai a 0 Pontos de Vida ou quando a magia acaba.\nA criatura é uma aliada para você e seus aliados. Em combate, a criatura compartilha sua contagem de Iniciativa, mas realiza o turno dela imediatamente após o seu. Ela obedece aos seus comandos verbais (nenhuma ação exigida de você). Se você não der nenhum comando, ela realiza a ação de Desviar e usa seu movimento para evitar perigo.\n\nUsando um Espaço de Magia de Círculo Superior. Use o círculo do espaço de magia para o nível da magia no bloco de estatísticas.\n\nEspírito Bestial\n\nBesta Pequena, Neutro\n\nCA 11 + o nível da magia\nPV 20 (apenas Ar) ou 30 (apenas Terra e Água) + 5 para cada círculo de magia acima do 2º\nDeslocamento 9 m; Escalada 9 m (apenas Terra); Voo 18 m (apenas Ar); Natação 9 m (apenas Água)\n\nMOD SALVAGUARDA\nFor 18 +4 +4 · Des 11 +0 +0 · Con 16 +3 +3\nInt 4 -3 -3 · Sab 14 +2 +2 · Car 5 -3 -3\n\nSentidos Visão no Escuro 18 m, Percepção Passiva 12\nIdiomas compreende os idiomas que você conhece\nND Nenhum (XP 0; BP é igual ao seu Bônus de Proficiência)\n\nTraços\n\nBote Aéreo (Apenas Ar). O espírito não provoca Ataques de Oportunidade quando sai voando do alcance de um inimigo.\n\nTáticas de Matilha (Apenas Terra e Água). O espírito tem Vantagem em uma jogada de ataque contra uma criatura se pelo menos um dos aliados do espírito estiver a até 1,5 metro da criatura e o aliado não estiver com a condição Incapacitado.\n\nRespiração Aquática (Apenas Água). O espírito pode respirar apenas debaixo d'água.\n\nAções\n\nAtaque Múltiplo. O espírito faz um número de ataques de Dilacerar igual à metade do nível desta magia (arredondado para baixo).\n\nDilacerar. Jogada de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque mágico, alcance 1,5 m. Acerto: 1d8 + 4 + o nível da magia de dano Perfurante.", "en": "You call forth a bestial spirit. It manifests in an unoccupied space that you can see within range and uses the Bestial Spirit stat block. When you cast the spell, choose an environment: Air, Land, or Water. The creature resembles an animal of your choice that is native to the chosen environment, which determines certain details in its stat block. The creature disappears when it drops to 0 Hit Points or when the spell ends.\nThe creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot’s level for the spell’s level in the stat block.\n\nBestial Spirit\n\nSmall Beast, Neutral\n\nAC 11 + the spell’s level\nHP 20 (Air only) or 30 (Land and Water only) + 5 for each spell level above 2\nSpeed 30 ft.; Climb 30 ft. (Land only); Fly 60 ft. (Air only); Swim 30 ft. (Water only)\n\nMOD SAVE\nStr 18 +4 +4 · Dex 11 +0 +0 · Con 16 +3 +3\nInt 4 -3 -3 · Wis 14 +2 +2 · Cha 5 -3 -3\n\nSenses Darkvision 60 ft., Passive Perception 12\nLanguages understands the languages you know\nCR None (XP 0; PB equals your Proficiency Bonus)\n\nTraits\n\nFlyby (Air Only). The spirit doesn’t provoke Opportunity Attacks when it flies out of an enemy’s reach.\n\nPack Tactics (Land and Water Only). The spirit has Advantage on an attack roll against a creature if at least one of the spirit’s allies is within 5 feet of the creature and the ally doesn’t have the Incapacitated condition.\n\nWater Breathing (Water Only). The spirit can breathe only underwater.\n\nActions\n\nMultiattack. The spirit makes a number of Rend attacks equal to half this spell’s level (round down).\n\nRend. Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: 1d8 + 4 + the spell’s level Piercing damage."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "auraOfVitality", "name": {"pt": "Aura de Vitalidade", "en": "Aura of Vitality"}, "level": 3, "school": "abjuration", "classes": ["cleric", "druid", "paladin"], "castingTime": "Action", "range": "Self (30-foot Emanation)", "components": "V", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Uma aura irradia de você em uma Emanação de 9 metros pela duração. Quando você cria a aura e no início de cada um dos seus turnos enquanto ela persistir, você pode restaurar 2d6 Pontos de Vida para uma criatura dentro dela.", "en": "An aura radiates from you in a 30-foot Emanation for the duration. When you create the aura and at the start of each of your turns while it persists, you can restore 2d6 Hit Points to one creature in it."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "conjureBarrage", "name": {"pt": "Conjurar Barragem", "en": "Conjure Barrage"}, "level": 3, "school": "conjuration", "classes": ["ranger"], "castingTime": "Action", "range": "Self (60-foot Cone)", "components": "V, S, M (a Melee or Ranged weapon worth at least 1 CP)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você brande a arma usada para conjurar a magia e conjura armas espectrais similares (ou munição apropriada para a arma) que disparam para frente e depois desaparecem. Cada criatura à sua escolha que você possa ver em um Cone de 18 metros faz uma salvaguarda de Destreza, sofrendo 5d8 de dano de Força em uma salvaguarda com falha ou metade desse dano em uma bem-sucedida.\n\nUsando um Espaço de Magia de Círculo Superior. O dano aumenta em 1d8 para cada círculo do espaço de magia acima do 3º.", "en": "You brandish the weapon used to cast the spell and conjure similar spectral weapons (or ammunition appropriate to the weapon) that launch forward and then disappear. Each creature of your choice that you can see in a 60-foot Cone makes a Dexterity saving throw, taking 5d8 Force damage on a failed save or half as much damage on a successful one.\n\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 3."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "crusadersMantle", "name": {"pt": "Manto do Cruzado", "en": "Crusader's Mantle"}, "level": 3, "school": "evocation", "classes": ["paladin"], "castingTime": "Action", "range": "Self (30-foot Emanation)", "components": "V", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você irradia uma aura mágica em uma Emanação de 9 metros. Enquanto estiverem na aura, você e seus aliados causam, cada um, 1d4 de dano Radiante adicional ao atingir com uma arma ou um Golpe Desarmado.", "en": "You radiate a magical aura in a 30-foot Emanation. While in the aura, you and your allies each deal an extra 1d4 Radiant damage when hitting with a weapon or an Unarmed Strike."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "elementalWeapon", "name": {"pt": "Arma Elemental", "en": "Elemental Weapon"}, "level": 3, "school": "transmutation", "classes": ["artificer", "druid", "paladin", "ranger"], "castingTime": "Action", "range": "Touch", "components": "V, S", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Uma arma não mágica tocada por você se torna uma arma mágica. Escolha um dos seguintes tipos de dano: Ácido, Frio, Fogo, Elétrico ou Trovejante. Pela duração, a arma tem um bônus de +1 nas jogadas de ataque e causa 1d4 de dano adicional do tipo escolhido quando atinge.\n\nUsando um Espaço de Magia de Círculo Superior. Se você usar um espaço de magia de 5º ou 6º círculo, o bônus nas jogadas de ataque aumenta para +2 e o dano adicional aumenta para 2d4. Se usar um espaço de magia de 7º círculo ou superior, o bônus aumenta para +3 e o dano adicional aumenta para 3d4.", "en": "A nonmagical weapon you touch becomes a magic weapon. Choose one of the following damage types: Acid, Cold, Fire, Lightning, or Thunder. For the duration, the weapon has a +1 bonus to attack rolls and deals an extra 1d4 damage of the chosen type when it hits.\n\nUsing a Higher-Level Spell Slot. If you use a level 5-6 spell slot, the bonus to attack rolls increases to +2, and the extra damage increases to 2d4. If you use a level 7+ spell slot, the bonus increases to +3, and the extra damage increases to 3d4."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "feignDeath", "name": {"pt": "Fingir-se de Morto", "en": "Feign Death"}, "level": 3, "school": "necromancy", "classes": ["bard", "cleric", "druid", "wizard"], "castingTime": "Action or Ritual", "range": "Touch", "components": "V, S, M (a pinch of graveyard dirt)", "duration": "1 hour", "ritual": true, "concentration": false, "desc": {"pt": "Você toca uma criatura voluntária e a coloca em um estado cataléptico indistinguível da morte.\nPela duração, o alvo parece morto a uma inspeção externa e a magias usadas para determinar a condição do alvo. O alvo fica com as condições Cego e Incapacitado, e seu Deslocamento é 0.\nO alvo também tem Resistência a todo tipo de dano, exceto dano Psíquico, e tem Imunidade à condição Envenenado.", "en": "You touch a willing creature and put it into a cataleptic state that is indistinguishable from death.\nFor the duration, the target appears dead to outward inspection and to spells used to determine the target's status. The target has the Blinded and Incapacitated conditions, and its Speed is 0.\nThe target also has Resistance to all damage except Psychic damage, and it has Immunity to the Poisoned condition."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "hungerOfHadar", "name": {"pt": "Fome de Hadar", "en": "Hunger of Hadar"}, "level": 3, "school": "conjuration", "classes": ["warlock"], "castingTime": "Action", "range": "150 feet", "components": "V, S, M (a pickled tentacle)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você abre um portal para o Reino Distante, uma região infestada de horrores indescritíveis. Uma Esfera de Escuridão com raio de 6 metros surge, centrada em um ponto dentro do alcance e durando pela duração da magia. A Esfera é Terreno Difícil e está repleta de sussurros estranhos e ruídos de sucção que podem ser ouvidos a até 9 metros de distância. Nenhuma luz, mágica ou não, pode iluminar a área, e criaturas totalmente dentro dela ficam com a condição Cego.\nQualquer criatura que iniciar seu turno na área sofre 2d6 de dano de Frio. Qualquer criatura que terminar seu turno ali deve ser bem-sucedida em uma salvaguarda de Destreza ou sofrerá 2d6 de dano Ácido de tentáculos de outro mundo.\n\nUsando um Espaço de Magia de Círculo Superior. O dano de Frio ou Ácido (sua escolha) aumenta em 1d6 para cada círculo do espaço de magia acima do 3º.", "en": "You open a gateway to the Far Realm, a region infested with unspeakable horrors. A 20-foot-radius Sphere of Darkness appears, centered on a point within range and lasting for the duration. The Sphere is Difficult Terrain, and it is filled with strange whispers and slurping noises, which can be heard up to 30 feet away. No light, magical or otherwise, can illuminate the area, and creatures fully within it have the Blinded condition.\nAny creature that starts its turn in the area takes 2d6 Cold damage. Any creature that ends its turn there must succeed on a Dexterity saving throw or take 2d6 Acid damage from otherworldly tentacles.\n\nUsing a Higher-Level Spell Slot. The Cold or Acid damage (your choice) increases by 1d6 for each spell slot level above 3."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "summonFey", "name": {"pt": "Invocar Fada", "en": "Summon Fey"}, "level": 3, "school": "conjuration", "classes": ["druid", "ranger", "warlock", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V, S, M (a gilded flower worth 300+ GP)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você invoca um espírito feérico. Ele se manifesta em um espaço desocupado que você possa ver dentro do alcance e usa o bloco de estatísticas de Espírito Feérico. Quando você conjura a magia, escolha um humor: Furioso, Alegre ou Trapaceiro. A criatura se assemelha a uma criatura Feérica de sua escolha marcada pelo humor escolhido, o que determina certos detalhes em seu bloco de estatísticas. A criatura desaparece quando cai a 0 Pontos de Vida ou quando a magia acaba.\nA criatura é uma aliada para você e seus aliados. Em combate, a criatura compartilha sua contagem de Iniciativa, mas realiza o turno dela imediatamente após o seu. Ela obedece aos seus comandos verbais (nenhuma ação exigida de você). Se você não der nenhum comando, ela realiza a ação de Desviar e usa seu movimento para evitar perigo.\n\nUsando um Espaço de Magia de Círculo Superior. Use o círculo do espaço de magia para o nível da magia no bloco de estatísticas.\n\nEspírito Feérico\n\nFada Pequena, Neutro\n\nCA 12 + o nível da magia\nPV 30 + 10 para cada círculo de magia acima do 3º\nDeslocamento 9 m, Voo 9 m\n\nMOD SALVAGUARDA\nFor 13 +1 +1 · Des 16 +3 +3 · Con 14 +2 +2\nInt 14 +2 +2 · Sab 11 +0 +0 · Car 16 +3 +3\n\nImunidades Enfeitiçado\nSentidos Visão no Escuro 18 m, Percepção Passiva 10\nIdiomas Silvestre, compreende os idiomas que você conhece\nND Nenhum (XP 0; BP é igual ao seu Bônus de Proficiência)\n\nAções\n\nAtaque Múltiplo. O espírito faz um número de ataques de Lâmina Feérica igual à metade do nível desta magia (arredondado para baixo).\n\nLâmina Feérica. Jogada de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque mágico, alcance 1,5 m. Acerto: 2d6 + 3 + o nível da magia de dano de Força.\n\nAções Bônus\n\nPasso Feérico. O espírito se teletransporta magicamente até 9 metros para um espaço desocupado que possa ver. Então, um dos seguintes efeitos ocorre, com base no humor escolhido do espírito:\n\nFurioso. O espírito tem Vantagem na próxima jogada de ataque que fizer antes do final deste turno.\n\nAlegre. Salvaguarda de Sabedoria: CD igual à CD de salvaguarda de sua magia, uma criatura que o espírito possa ver a até 3 metros de si mesmo. Falha: O alvo fica Enfeitiçado por você e pelo espírito durante 1 minuto ou até o alvo sofrer qualquer dano.\n\nTrapaceiro. O espírito preenche um Cubo de 3 metros a até 1,5 metro dele com Escuridão mágica, que dura até o final do próximo turno dele.", "en": "You call forth a Fey spirit. It manifests in an unoccupied space that you can see within range and uses the Fey Spirit stat block. When you cast the spell, choose a mood: Fuming, Mirthful, or Tricksy. The creature resembles a Fey creature of your choice marked by the chosen mood, which determines certain details in its stat block. The creature disappears when it drops to 0 Hit Points or when the spell ends.\nThe creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot’s level for the spell’s level in the stat block.\n\nFey Spirit\n\nSmall Fey, Neutral\n\nAC 12 + the spell’s level\nHP 30 + 10 for each spell level above 3\nSpeed 30 ft., Fly 30 ft.\n\nMOD SAVE\nStr 13 +1 +1 · Dex 16 +3 +3 · Con 14 +2 +2\nInt 14 +2 +2 · Wis 11 +0 +0 · Cha 16 +3 +3\n\nImmunities Charmed\nSenses Darkvision 60 ft., Passive Perception 10\nLanguages Sylvan, understands the languages you know\nCR None (XP 0; PB equals your Proficiency Bonus)\n\nActions\n\nMultiattack. The spirit makes a number of Fey Blade attacks equal to half this spell’s level (round down).\n\nFey Blade. Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: 2d6 + 3 + the spell’s level Force damage.\n\nBonus Actions\n\nFey Step. The spirit magically teleports up to 30 feet to an unoccupied space it can see. Then one of the following effects occurs, based on the spirit’s chosen mood:\n\nFuming. The spirit has Advantage on the next attack roll it makes before the end of this turn.\n\nMirthful. Wisdom Saving Throw: DC equals your spell save DC, one creature the spirit can see within 10 feet of itself. Failure: The target is Charmed by you and the spirit for 1 minute or until the target takes any damage.\n\nTricksy. The spirit fills a 10-foot Cube within 5 feet of it with magical Darkness, which lasts until the end of its next turn."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "auraOfPurity", "name": {"pt": "Aura de Pureza", "en": "Aura of Purity"}, "level": 4, "school": "abjuration", "classes": ["cleric", "paladin"], "castingTime": "Action", "range": "Self (30-foot Emanation)", "components": "V", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Uma aura irradia de você em uma Emanação de 9 metros pela duração. Enquanto estiverem na aura, você e seus aliados têm Resistência a dano de Veneno e Vantagem em salvaguardas para evitar ou encerrar efeitos que incluam a condição Cego, Enfeitiçado, Surdo, Amedrontado, Paralisado, Envenenado ou Atordoado.", "en": "An aura radiates from you in a 30-foot Emanation for the duration. While in the aura, you and your allies have Resistance to Poison damage and Advantage on saving throws to avoid or end effects that include the Blinded, Charmed, Deafened, Frightened, Paralyzed, Poisoned, or Stunned condition."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "fountOfMoonlight", "name": {"pt": "Fonte de Luar", "en": "Fount of Moonlight"}, "level": 4, "school": "evocation", "classes": ["bard", "druid"], "castingTime": "Action", "range": "Self", "components": "V, S", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Uma luz suave e fria envolve seu corpo pela duração, emitindo Luz Brilhante em um raio de 6 metros e Meia-Luz por 6 metros adicionais.\nAté a magia acabar, você tem Resistência a dano Radiante, e seus ataques corpo a corpo causam 2d6 de dano Radiante adicional em um acerto.\nAlém disso, imediatamente após sofrer dano de uma criatura que possa ver a até 18 metros de você, você pode usar uma Reação para forçar a criatura a fazer uma salvaguarda de Constituição. Em uma salvaguarda com falha, a criatura fica com a condição Cego até o final do seu próximo turno.", "en": "A cool light wreathes your body for the duration, emitting Bright Light in a 20-foot radius and Dim Light for an additional 20 feet.\nUntil the spell ends, you have Resistance to Radiant damage, and your melee attacks deal an extra 2d6 Radiant damage on a hit.\nIn addition, immediately after you take damage from a creature you can see within 60 feet of yourself, you can take a Reaction to force the creature to make a Constitution saving throw. On a failed save, the creature has the Blinded condition until the end of your next turn."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "graspingVine", "name": {"pt": "Vinha Constritora", "en": "Grasping Vine"}, "level": 4, "school": "conjuration", "classes": ["druid", "ranger"], "castingTime": "Bonus Action", "range": "60 feet", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você conjura uma videira que brota de uma superfície em um espaço desocupado que você possa ver dentro do alcance. A videira permanece pela duração.\nFaça um ataque mágico corpo a corpo contra uma criatura a até 9 metros da videira. Em um acerto, o alvo sofre 4d8 de dano Contundente e é puxado até 9 metros em direção à videira; se o alvo for Implacável (Enorme) ou menor, ele fica com a condição Agarrado (CD de escape igual à CD de salvaguarda da sua magia). A videira pode agarrar apenas uma criatura por vez, e você pode fazer a videira soltar uma criatura Agarrada (nenhuma ação exigida).\nComo uma Ação Bônus nos seus turnos posteriores, você pode repetir o ataque contra uma criatura a até 9 metros da videira.\n\nUsando um Espaço de Magia de Círculo Superior. O número de criaturas que a videira pode agarrar aumenta em uma para cada círculo do espaço de magia acima do 4º.", "en": "You conjure a vine that sprouts from a surface in an unoccupied space that you can see within range. The vine lasts for the duration.\nMake a melee spell attack against a creature within 30 feet of the vine. On a hit, the target takes 4d8 Bludgeoning damage and is pulled up to 30 feet toward the vine; if the target is Huge or smaller, it has the Grappled condition (escape DC equal to your spell save DC). The vine can grapple only one creature at a time, and you can cause the vine to release a Grappled creature (no action required).\nAs a Bonus Action on your later turns, you can repeat the attack against a creature within 30 feet of the vine.\n\nUsing a Higher-Level Spell Slot. The number of creatures the vine can grapple increases by one for each spell slot level above 4."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "staggeringSmite", "name": {"pt": "Destruição Estonteante", "en": "Staggering Smite"}, "level": 4, "school": "enchantment", "classes": ["paladin"], "castingTime": "Bonus Action, which you take immediately after hitting a creature with a Melee weapon or an Unarmed Strike", "range": "Self", "components": "V", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "O alvo sofre 4d6 de dano Psíquico adicional pelo ataque, e o alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou ficará com a condição Atordoado até o final do seu próximo turno.\n\nUsando um Espaço de Magia de Círculo Superior. O dano adicional aumenta em 1d6 para cada círculo do espaço de magia acima do 4º.", "en": "The target takes an extra 4d6 Psychic damage from the attack, and the target must succeed on a Wisdom saving throw or have the Stunned condition until the end of your next turn.\n\nUsing a Higher-Level Spell Slot. The extra damage increases by 1d6 for each spell slot level above 4."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "summonAberration", "name": {"pt": "Invocar Aberração", "en": "Summon Aberration"}, "level": 4, "school": "conjuration", "classes": ["warlock", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V, S, M (a pickled tentacle and an eyeball in a platinum-inlaid vial worth 400+ GP)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você invoca um espírito aberrante. Ele se manifesta em um espaço desocupado que você possa ver dentro do alcance e usa o bloco de estatísticas de Espírito Aberrante. Quando você conjura a magia, escolha Parente de Observador, Devorador de Mentes ou Slaad. A criatura se assemelha a uma Aberração daquele tipo, o que determina certos detalhes em seu bloco de estatísticas. A criatura desaparece quando cai a 0 Pontos de Vida ou quando a magia acaba.\nA criatura é uma aliada para você e seus aliados. Em combate, ela compartilha sua contagem de Iniciativa, mas realiza o turno dela imediatamente após o seu. Ela obedece aos seus comandos verbais (nenhuma ação exigida de você). Se você não der nenhum comando, ela realiza a ação de Desviar e usa seu movimento para evitar perigo.\n\nUsando um Espaço de Magia de Círculo Superior. Use o círculo do espaço de magia para o nível da magia no bloco de estatísticas.\n\nEspírito Aberrante\n\nAberração Média, Neutro\n\nCA 11 + o nível da magia\nPV 40 + 10 para cada círculo de magia acima do 4º\nDeslocamento 9 m; Voo 9 m (flutuar; apenas Parente de Observador)\n\nMOD SALVAGUARDA\nFor 16 +3 +3 · Des 10 +0 +0 · Con 15 +2 +2\nInt 16 +3 +3 · Sab 10 +0 +0 · Car 6 -2 -2\n\nImunidades Psíquico\nSentidos Visão no Escuro 18 m, Percepção Passiva 10\nIdiomas Dialeto Profundo, compreende os idiomas que você conhece\nND Nenhum (XP 0; BP é igual ao seu Bônus de Proficiência)\n\nTraços\n\nRegeneração (Apenas Slaad). O espírito recupera 5 Pontos de Vida no início do turno dele se tiver pelo menos 1 Ponto de Vida.\n\nAura Sussurrante (Apenas Devorador de Mentes). No início de cada um dos turnos do espírito, ele emite energia psiônica se não estiver com a condição Incapacitado. Salvaguarda de Sabedoria: CD igual à CD de salvaguarda de sua magia, cada criatura (que não seja você) a até 1,5 metro do espírito. Falha: 2d6 de dano Psíquico.\n\nAções\n\nAtaque Múltiplo. O espírito faz uma quantidade de ataques igual à metade do nível desta magia (arredondado para baixo).\n\nGarra (Apenas Slaad). Jogada de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque mágico, alcance 1,5 m. Acerto: 1d10 + 3 + o nível da magia de dano Cortante, e o alvo não pode recuperar Pontos de Vida até o início do próximo turno do espírito.\n\nRaio Ocular (Apenas Parente de Observador). Jogada de Ataque à Distância: Bônus igual ao seu modificador de ataque mágico, alcance 45 m. Acerto: 1d8 + 3 + o nível da magia de dano Psíquico.\n\nPancada Psiônica (Apenas Devorador de Mentes). Jogada de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque mágico, alcance 1,5 m. Acerto: 1d8 + 3 + o nível da magia de dano Psíquico.", "en": "You call forth an aberrant spirit. It manifests in an unoccupied space that you can see within range and uses the Aberrant Spirit stat block. When you cast the spell, choose Beholderkin, Mind Flayer, or Slaad. The creature resembles an Aberration of that kind, which determines certain details in its stat block. The creature disappears when it drops to 0 Hit Points or when the spell ends.\nThe creature is an ally to you and your allies. In combat, it shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot’s level for the spell’s level in the stat block.\n\nAberrant Spirit\n\nMedium Aberration, Neutral\n\nAC 11 + the spell’s level\nHP 40 + 10 for each spell level above 4\nSpeed 30 ft.; Fly 30 ft. (hover; Beholderkin only)\n\nMOD SAVE\nStr 16 +3 +3 · Dex 10 +0 +0 · Con 15 +2 +2\nInt 16 +3 +3 · Wis 10 +0 +0 · Cha 6 -2 -2\n\nImmunities Psychic\nSenses Darkvision 60 ft., Passive Perception 10\nLanguages Deep Speech, understands the languages you know\nCR None (XP 0; PB equals your Proficiency Bonus)\n\nTraits\n\nRegeneration (Slaad Only). The spirit regains 5 Hit Points at the start of its turn if it has at least 1 Hit Point.\n\nWhispering Aura (Mind Flayer Only). At the start of each of the spirit’s turns, the spirit emits psionic energy if it doesn’t have the Incapacitated condition. Wisdom Saving Throw: DC equals your spell save DC, each creature (other than you) within 5 feet of the spirit. Failure: 2d6 Psychic damage.\n\nActions\n\nMultiattack. The spirit makes a number of attacks equal to half this spell’s level (round down).\n\nClaw (Slaad Only). Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: 1d10 + 3 + the spell’s level Slashing damage, and the target can’t regain Hit Points until the start of the spirit’s next turn.\n\nEye Ray (Beholderkin Only). Ranged Attack Roll: Bonus equals your spell attack modifier, range 150 ft. Hit: 1d8 + 3 + the spell’s level Psychic damage.\n\nPsychic Slam (Mind Flayer Only). Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: 1d8 + 3 + the spell’s level Psychic damage."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "summonConstruct", "name": {"pt": "Invocar Constructo", "en": "Summon Construct"}, "level": 4, "school": "conjuration", "classes": ["artificer", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V, S, M (a lockbox worth 400+ GP)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você invoca o espírito de um Constructo. Ele se manifesta em um espaço desocupado que você possa ver dentro do alcance e usa o bloco de estatísticas de Espírito de Constructo. Quando você conjura a magia, escolha um material: Argila, Metal ou Pedra. A criatura se assemelha a uma estátua animada (você determina a aparência) feita do material escolhido, o que determina certos detalhes em seu bloco de estatísticas. A criatura desaparece quando cai a 0 Pontos de Vida ou quando a magia acaba.\nA criatura é uma aliada para você e seus aliados. Em combate, a criatura compartilha sua contagem de Iniciativa, mas realiza o turno dela imediatamente após o seu. Ela obedece aos seus comandos verbais (nenhuma ação exigida de você). Se você não der nenhum comando, ela realiza a ação de Desviar e usa seu movimento para evitar perigo.\n\nUsando um Espaço de Magia de Círculo Superior. Use o círculo do espaço de magia para o nível da magia no bloco de estatísticas.\n\nEspírito de Constructo\n\nConstructo Médio, Neutro\n\nCA 13 + o nível da magia\nPV 40 + 15 para cada círculo de magia acima do 4º\nDeslocamento 9 m\n\nMOD SALVAGUARDA\nFor 18 +4 +4 · Des 10 +0 +0 · Con 18 +4 +4\nInt 14 +2 +2 · Sab 11 +0 +0 · Car 5 -3 -3\n\nResistências Veneno\nImunidades Enfeitiçado, Exaustão, Amedrontado, Paralisado, Envenenado\nSentidos Visão no Escuro 18 m, Percepção Passiva 10\nIdiomas Compreende os idiomas que você conhece\nND Nenhum (XP 0; BP é igual ao seu Bônus de Proficiência)\n\nTraços\n\nCorpo Aquecido (Apenas Metal). Uma criatura que atingir o espírito com um ataque corpo a corpo ou que iniciar o turno agarrada ao espírito sofre 1d10 de dano de Fogo.\n\nLetargia Pétrea (Apenas Pedra). Quando uma criatura iniciar seu turno a até 3 metros do espírito, o espírito pode mirar nela com energia mágica se puder vê-la. Salvaguarda de Sabedoria: CD igual à CD de salvaguarda de sua magia, o alvo. Falha: Até o início do próximo turno do alvo, ele não pode fazer Ataques de Oportunidade e seu Deslocamento é reduzido pela metade.\n\nAções\n\nAtaque Múltiplo. O espírito faz uma quantidade de ataques de Pancada igual à metade do nível desta magia (arredondado para baixo).\n\nPancada. Jogada de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque mágico, alcance 1,5 m. Acerto: 1d8 + 4 + o nível da magia de dano Contundente.\n\nReações\n\nAçoite Frenético (Apenas Argila). Gatilho: O espírito sofre dano de uma criatura. Resposta: O espírito faz um ataque de Pancada contra aquela criatura se possível, ou o espírito se move até metade de seu Deslocamento em direção àquela criatura sem provocar Ataques de Oportunidade.", "en": "You call forth the spirit of a Construct. It manifests in an unoccupied space that you can see within range and uses the Construct Spirit stat block. When you cast the spell, choose a material: Clay, Metal, or Stone. The creature resembles an animate statue (you determine the appearance) made of the chosen material, which determines certain details in its stat block. The creature disappears when it drops to 0 Hit Points or when the spell ends.\nThe creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot’s level for the spell’s level in the stat block.\n\nConstruct Spirit\n\nMedium Construct, Neutral\n\nAC 13 + the spell’s level\nHP 40 + 15 for each spell level above 4\nSpeed 30 ft.\n\nMOD SAVE\nStr 18 +4 +4 · Dex 10 +0 +0 · Con 18 +4 +4\nInt 14 +2 +2 · Wis 11 +0 +0 · Cha 5 -3 -3\n\nResistances Poison\nImmunities Charmed, Exhaustion, Frightened, Paralyzed, Poisoned\nSenses Darkvision 60 ft., Passive Perception 10\nLanguages Understands the languages you know\nCR None (XP 0; PB equals your Proficiency Bonus)\n\nTraits\n\nHeated Body (Metal Only). A creature that hits the spirit with a melee attack or that starts its turn in a grapple with the spirit takes 1d10 Fire damage.\n\nStony Lethargy (Stone Only). When a creature starts its turn within 10 feet of the spirit, the spirit can target it with magical energy if the spirit can see it. Wisdom Saving Throw: DC equals your spell save DC, the target. Failure: Until the start of its next turn, the target can’t make Opportunity Attacks, and its Speed is halved.\n\nActions\n\nMultiattack. The spirit makes a number of Slam attacks equal to half this spell’s level (round down).\n\nSlam. Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: 1d8 + 4 + the spell’s level Bludgeoning damage.\n\nReactions\n\nBerserk Lashing (Clay Only). Trigger: The spirit takes damage from a creature. Response: The spirit makes a Slam attack against that creature if possible, or the spirit moves up to half its Speed toward that creature without provoking Opportunity Attacks."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "summonElemental", "name": {"pt": "Invocar Elemental", "en": "Summon Elemental"}, "level": 4, "school": "conjuration", "classes": ["druid", "ranger", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V, S, M (air, a pebble, ash, and water inside a gold-inlaid vial worth 400+ GP)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você invoca um espírito elemental. Ele se manifesta em um espaço desocupado que você possa ver dentro do alcance e usa o bloco de estatísticas de Espírito Elemental. Quando você conjura a magia, escolha um elemento: Ar, Terra, Fogo ou Água. A criatura se assemelha a uma forma bípede envolta pelo elemento escolhido, o que determina certos detalhes em seu bloco de estatísticas. A criatura desaparece quando cai a 0 Pontos de Vida ou quando a magia acaba.\nA criatura é uma aliada para você e seus aliados. Em combate, a criatura compartilha sua contagem de Iniciativa, mas realiza o turno dela imediatamente após o seu. Ela obedece aos seus comandos verbais (nenhuma ação exigida de você). Se você não der nenhum comando, ela realiza a ação de Desviar e usa seu movimento para evitar perigo.\n\nUsando um Espaço de Magia de Círculo Superior. Use o círculo do espaço de magia para o nível da magia no bloco de estatísticas.\n\nEspírito Elemental\n\nElemental Médio, Neutro\n\nCA 11 + o nível da magia\nPV 50 + 10 para cada círculo de magia acima do 4º\nDeslocamento 12 m; Escavação 12 m (apenas Terra); Voo 12 m (flutuar; apenas Ar); Natação 12 m (apenas Água)\n\nMOD SALVAGUARDA\nFor 18 +4 +4 · Des 15 +2 +2 · Con 17 +3 +3\nInt 4 -3 -3 · Sab 10 +0 +0 · Car 16 +3 +3\n\nResistências Ácido (apenas Água), Elétrico e Trovejante (apenas Ar), Perfurante e Cortante (apenas Terra)\nImunidades Fogo (apenas Fogo), Veneno; Exaustão, Paralisado, Petrificado, Envenenado\nSentidos Visão no Escuro 18 m, Percepção Passiva 10\nIdiomas Primordial, compreende os idiomas que você conhece\nND Nenhum (XP 0; BP é igual ao seu Bônus de Proficiência)\n\nTraços\n\nForma Amorfa (Apenas Ar, Fogo e Água). O espírito pode se mover através de um espaço tão estreito quanto 2,5 centímetros de largura sem que conte como Terreno Difícil.\n\nAções\n\nAtaque Múltiplo. O espírito faz uma quantidade de ataques de Pancada igual à metade do nível desta magia (arredondado para baixo).\n\nPancada. Jogada de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque mágico, alcance 1,5 m. Acerto: 1d10 + 4 + o nível da magia de dano Contundente (apenas Terra), Frio (apenas Água), Elétrico (apenas Ar) ou Fogo (apenas Fogo).", "en": "You call forth an Elemental spirit. It manifests in an unoccupied space that you can see within range and uses the Elemental Spirit stat block. When you cast the spell, choose an element: Air, Earth, Fire, or Water. The creature resembles a bipedal form wreathed in the chosen element, which determines certain details in its stat block. The creature disappears when it drops to 0 Hit Points or when the spell ends.\nThe creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot’s level for the spell’s level in the stat block.\n\nElemental Spirit\n\nMedium Elemental, Neutral\n\nAC 11 + the spell’s level\nHP 50 + 10 for each spell level above 4\nSpeed 40 ft.; Burrow 40 ft. (Earth only); Fly 40 ft. (hover; Air only); Swim 40 ft. (Water only)\n\nMOD SAVE\nStr 18 +4 +4 · Dex 15 +2 +2 · Con 17 +3 +3\nInt 4 -3 -3 · Wis 10 +0 +0 · Cha 16 +3 +3\n\nResistances Acid (Water only), Lightning and Thunder (Air only), Piercing and Slashing (Earth only)\nImmunities Fire (Fire only), Poison; Exhaustion, Paralyzed, Petrified, Poisoned\nSenses Darkvision 60 ft., Passive Perception 10\nLanguages Primordial, understands the languages you know\nCR None (XP 0; PB equals your Proficiency Bonus)\n\nTraits\n\nAmorphous Form (Air, Fire, and Water Only). The spirit can move through a space as narrow as 1 inch wide without it counting as Difficult Terrain.\n\nActions\n\nMultiattack. The spirit makes a number of Slam attacks equal to half this spell’s level (round down).\n\nSlam. Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: 1d10 + 4 + the spell’s level Bludgeoning (Earth only), Cold (Water only), Lightning (Air only), or Fire (Fire only) damage."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "banishingSmite", "name": {"pt": "Destruição Banidora", "en": "Banishing Smite"}, "level": 5, "school": "conjuration", "classes": ["paladin"], "castingTime": "Bonus Action, which you take immediately after hitting a creature with a Melee weapon or an Unarmed Strike", "range": "Self", "components": "V", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "O alvo atingido pela jogada de ataque sofre 5d10 de dano de Força adicional pelo ataque. Se o ataque reduzir o alvo a 50 Pontos de Vida ou menos, o alvo deve ser bem-sucedido em uma salvaguarda de Carisma ou será transportado para um semiplano inofensivo pela duração. Enquanto estiver lá, o alvo fica com a condição Incapacitado. Quando a magia acaba, o alvo reaparece no espaço que deixou ou no espaço desocupado mais próximo caso aquele espaço esteja ocupado.", "en": "The target hit by the attack roll takes an extra 5d10 Force damage from the attack. If the attack reduces the target to 50 Hit Points or fewer, the target must succeed on a Charisma saving throw or be transported to a harmless demiplane for the duration. While there, the target has the Incapacitated condition. When the spell ends, the target reappears in the space it left or in the nearest unoccupied space if that space is occupied."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "circleOfPower", "name": {"pt": "Círculo de Poder", "en": "Circle of Power"}, "level": 5, "school": "abjuration", "classes": ["cleric", "paladin", "wizard"], "castingTime": "Action", "range": "Self (30-foot Emanation)", "components": "V", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Uma aura irradia de você em uma Emanação de 9 metros pela duração. Enquanto estiverem na aura, você e seus aliados têm Vantagem em salvaguardas contra magias e outros efeitos mágicos. Quando uma criatura afetada faz uma salvaguarda contra uma magia ou efeito mágico que permita uma salvaguarda para sofrer apenas metade do dano, ela não sofre dano algum se for bem-sucedida na salvaguarda.", "en": "An aura radiates from you in a 30-foot Emanation for the duration. While in the aura, you and your allies have Advantage on saving throws against spells and other magical effects. When an affected creature makes a saving throw against a spell or magical effect that allows a save to take only half damage, it takes no damage if it succeeds on the save."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "destructiveWave", "name": {"pt": "Onda Destrutiva", "en": "Destructive Wave"}, "level": 5, "school": "evocation", "classes": ["paladin"], "castingTime": "Action", "range": "Self (30-foot Emanation)", "components": "V", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Energia destruidora ondula para fora a partir de você em uma Emanação de 9 metros. Cada criatura escolhida por você na Emanação faz uma salvaguarda de Constituição. Em uma salvaguarda com falha, o alvo sofre 5d6 de dano Trovejante e 5d6 de dano Radiante ou Necrótico (sua escolha) e fica com a condição Caído. Em uma salvaguarda bem-sucedida, o alvo sofre apenas metade do dano.", "en": "Destructive energy ripples outward from you in a 30-foot Emanation. Each creature you choose in the Emanation makes a Constitution saving throw. On a failed save, a target takes 5d6 Thunder damage and 5d6 Radiant or Necrotic damage (your choice) and has the Prone condition. On a successful save, a target takes half as much damage only."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "steelWindStrike", "name": {"pt": "Golpe do Vento de Aço", "en": "Steel Wind Strike"}, "level": 5, "school": "conjuration", "classes": ["ranger", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "S, M (a Melee weapon worth 1+ SP)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você brande a arma usada na conjuração e desaparece para golpear como o vento. Escolha até cinco criaturas que você possa ver dentro do alcance. Faça um ataque mágico corpo a corpo contra cada alvo. Em um acerto, o alvo sofre 6d10 de dano de Força.\nVocê então se teletransporta para um espaço desocupado que possa ver a até 1,5 metro de um dos alvos.", "en": "You flourish the weapon used in the casting and then vanish to strike like the wind. Choose up to five creatures you can see within range. Make a melee spell attack against each target. On a hit, a target takes 6d10 Force damage.\nYou then teleport to an unoccupied space you can see within 5 feet of one of the targets."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "summonCelestial", "name": {"pt": "Invocar Celestial", "en": "Summon Celestial"}, "level": 5, "school": "conjuration", "classes": ["cleric", "paladin"], "castingTime": "Action", "range": "90 feet", "components": "V, S, M (a reliquary worth 500+ GP)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você invoca um espírito celestial. Ele se manifesta em uma forma angelical em um espaço desocupado que você possa ver dentro do alcance e usa o bloco de estatísticas de Espírito Celestial. Quando você conjura a magia, escolha Vingador ou Defensor. Sua escolha determina certos detalhes em seu bloco de estatísticas. A criatura desaparece quando cai a 0 Pontos de Vida ou quando a magia acaba.\nA criatura é uma aliada para você e seus aliados. Em combate, a criatura compartilha sua contagem de Iniciativa, mas realiza o turno dela imediatamente após o seu. Ela obedece aos seus comandos verbais (nenhuma ação exigida de você). Se você não der nenhum comando, ela realiza a ação de Desviar e usa seu movimento para evitar perigo.\n\nUsando um Espaço de Magia de Círculo Superior. Use o círculo do espaço de magia para o nível da magia no bloco de estatísticas.\n\nEspírito Celestial\n\nCelestial Grande, Neutro\n\nCA 11 + o nível da magia + 2 (apenas Defensor)\nPV 40 + 10 para cada círculo de magia acima do 5º\nDeslocamento 9 m, Voo 12 m\n\nMOD SALVAGUARDA\nFor 16 +3 +3 · Des 14 +2 +2 · Con 16 +3 +3\nInt 10 +0 +0 · Sab 14 +2 +2 · Car 16 +3 +3\n\nResistências Radiante\nImunidades Enfeitiçado, Amedrontado\nSentidos Visão no Escuro 18 m, Percepção Passiva 12\nIdiomas Celestial, compreende os idiomas que você conhece\nND Nenhum (XP 0; BP é igual ao seu Bônus de Proficiência)\n\nAções\n\nAtaque Múltiplo. O espírito faz uma quantidade de ataques igual à metade do nível desta magia (arredondado para baixo).\n\nArco Radiante (Apenas Vingador). Jogada de Ataque à Distância: Bônus igual ao seu modificador de ataque mágico, alcance 180 m. Acerto: 2d6 + 2 + o nível da magia de dano Radiante.\n\nMaça Radiante (Apenas Defensor). Jogada de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque mágico, alcance 1,5 m. Acerto: 1d10 + 3 + o nível da magia de dano Radiante, e o espírito pode escolher a si mesmo ou a outra criatura que possa ver a até 3 metros do alvo. A criatura escolhida ganha 1d10 Pontos de Vida Temporários.\n\nToque de Cura (1/Dia). O espírito toca outra criatura. O alvo recupera Pontos de Vida iguais a 2d8 + o nível da magia.", "en": "You call forth a Celestial spirit. It manifests in an angelic form in an unoccupied space that you can see within range and uses the Celestial Spirit stat block. When you cast the spell, choose Avenger or Defender. Your choice determines certain details in its stat block. The creature disappears when it drops to 0 Hit Points or when the spell ends.\nThe creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot’s level for the spell’s level in the stat block.\n\nCelestial Spirit\n\nLarge Celestial, Neutral\n\nAC 11 + the spell’s level + 2 (Defender only)\nHP 40 + 10 for each spell level above 5\nSpeed 30 ft., Fly 40 ft.\n\nMOD SAVE\nStr 16 +3 +3 · Dex 14 +2 +2 · Con 16 +3 +3\nInt 10 +0 +0 · Wis 14 +2 +2 · Cha 16 +3 +3\n\nResistances Radiant\nImmunities Charmed, Frightened\nSenses Darkvision 60 ft., Passive Perception 12\nLanguages Celestial, understands the languages you know\nCR None (XP 0; PB equals your Proficiency Bonus)\n\nActions\n\nMultiattack. The spirit makes a number of attacks equal to half this spell’s level (round down).\n\nRadiant Bow (Avenger Only). Ranged Attack Roll: Bonus equals your spell attack modifier, range 600 ft. Hit: 2d6 + 2 + the spell’s level Radiant damage.\n\nRadiant Mace (Defender Only). Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: 1d10 + 3 + the spell’s level Radiant damage, and the spirit can choose itself or another creature it can see within 10 feet of the target. The chosen creature gains 1d10 Temporary Hit Points.\n\nHealing Touch (1/Day). The spirit touches another creature. The target regains Hit Points equal to 2d8 + the spell’s level."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "yolandesRegalPresence", "name": {"pt": "Presença Régia de Yolande", "en": "Yolande's Regal Presence"}, "level": 5, "school": "enchantment", "classes": ["bard", "wizard"], "castingTime": "Action", "range": "Self (10-foot Emanation)", "components": "V, S, M (A miniature tiara)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você se cerca de majestade sobrenatural em uma Emanação de 3 metros. Sempre que a Emanação adentrar o espaço de uma criatura que você possa ver e sempre que uma criatura que você possa ver adentrar a Emanação ou terminar o turno dela ali, você pode forçar essa criatura a fazer uma salvaguarda de Sabedoria. Em uma salvaguarda com falha, o alvo sofre 4d6 de dano Psíquico e fica com a condição Caído, e você pode empurrá-lo até 3 metros para longe. Em uma salvaguarda bem-sucedida, o alvo sofre apenas metade do dano. Uma criatura faz esta salvaguarda apenas uma vez por turno.", "en": "You surround yourself with unearthly majesty in a 10-foot Emanation. Whenever the Emanation enters the space of a creature you can see and whenever a creature you can see enters the Emanation or ends its turn there, you can force that creature to make a Wisdom saving throw. On a failed save, the target takes 4d6 Psychic damage and has the Prone condition, and you can push it up to 10 feet away. On a successful save, the target takes half as much damage only. A creature makes this save only once per turn."}, "rulesVersion": "2024", "source": "PHB24"},
  // Player's Handbook 2024 (fora do SRD)
  {"id": "bladeWard", "name": {"pt": "Proteção contra Lâminas", "en": "Blade Ward"}, "level": 0, "school": "abjuration", "classes": ["bard", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "Self", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Sempre que uma criatura fizer uma jogada de ataque contra você antes da magia acabar, o atacante subtrai 1d4 da jogada de ataque.", "en": "Whenever a creature makes an attack roll against you before the spell ends, the attacker subtracts 1d4 from the attack roll."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "friends", "name": {"pt": "Amizade", "en": "Friends"}, "level": 0, "school": "enchantment", "classes": ["bard", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "10 feet", "components": "S, M (some makeup)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você emana magicamente uma sensação de amizade em direção a uma criatura que possa ver dentro do alcance. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou ficará com a condição Enfeitiçado pela duração. O alvo é bem-sucedido automaticamente se não for um Humanoide, se você estiver lutando contra ele ou se tiver conjurado esta magia sobre ele nas últimas 24 horas.\nA magia termina antecipadamente se o alvo sofrer dano ou se você fizer uma jogada de ataque, causar dano ou forçar qualquer pessoa a fazer uma salvaguarda. Quando a magia acaba, o alvo sabe que foi Enfeitiçado por você.", "en": "You magically emanate a sense of friendship toward one creature you can see within range. The target must succeed on a Wisdom saving throw or have the Charmed condition for the duration. The target succeeds automatically if it isn't a Humanoid, if you're fighting it, or if you have cast this spell on it within the past 24 hours.\nThe spell ends early if the target takes damage or if you make an attack roll, deal damage, or force anyone to make a saving throw. When the spell ends, the target knows it was Charmed by you."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "thornWhip", "name": {"pt": "Chicote de Espinhos", "en": "Thorn Whip"}, "level": 0, "school": "transmutation", "classes": ["artificer", "druid"], "castingTime": "Action", "range": "30 feet", "components": "V, S, M (the stem of a plant with thorns)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você cria um chicote semelhante a uma videira coberto de espinhos que chicoteia sob o seu comando em direção a uma criatura dentro do alcance. Faça um ataque mágico corpo a corpo contra o alvo. Em um acerto, o alvo sofre 1d6 de dano Perfurante e, se for Grande ou menor, você pode puxá-lo até 3 metros para mais perto de você.\n\nAprimoramento de Truque. O dano aumenta em 1d6 quando você atinge os níveis 5 (2d6), 11 (3d6) e 17 (4d6).", "en": "You create a vine-like whip covered in thorns that lashes out at your command toward a creature in range. Make a melee spell attack against the target. On a hit, the target takes 1d6 Piercing damage, and if it is Large or smaller, you can pull it up to 10 feet closer to you.\n\nCantrip Upgrade. The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6)."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "thunderclap", "name": {"pt": "Trovão", "en": "Thunderclap"}, "level": 0, "school": "evocation", "classes": ["artificer", "bard", "druid", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "Self (5-foot Emanation)", "components": "S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Cada criatura em uma Emanação de 1,5 metro originada de você deve ser bem-sucedida em uma salvaguarda de Constituição ou sofrerá 1d6 de dano Trovejante. O estrondo trovejante da magia pode ser ouvido a até 30 metros de distância.\n\nAprimoramento de Truque. O dano aumenta em 1d6 quando você atinge os níveis 5 (2d6), 11 (3d6) e 17 (4d6).", "en": "Each creature in a 5-foot Emanation originating from you must succeed on a Constitution saving throw or take 1d6 Thunder damage. The spell's thunderous sound can be heard up to 100 feet away.\n\nCantrip Upgrade. The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6)."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "tollTheDead", "name": {"pt": "Dobre Fúnebre", "en": "Toll the Dead"}, "level": 0, "school": "necromancy", "classes": ["cleric", "warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você aponta para uma criatura que possa ver dentro do alcance, e a badalada fúnebre de um sino doloroso ecoa a até 3 metros do alvo. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou sofrerá 1d8 de dano Necrótico. Se o alvo estiver com menos do que o total de seus Pontos de Vida, ele sofre 1d12 de dano Necrótico em vez disso.\n\nAprimoramento de Truque. O dano aumenta em um dado quando você atinge os níveis 5 (2d8 ou 2d12), 11 (3d8 ou 3d12) e 17 (4d8 ou 4d12).", "en": "You point at one creature you can see within range, and the single chime of a dolorous bell is audible within 10 feet of the target. The target must succeed on a Wisdom saving throw or take 1d8 Necrotic damage. If the target is missing any of its Hit Points, it instead takes 1d12 Necrotic damage.\n\nCantrip Upgrade. The damage increases by one die when you reach levels 5 (2d8 or 2d12), 11 (3d8 or 3d12), and 17 (4d8 or 4d12)."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "wordOfRadiance", "name": {"pt": "Palavra Radiante", "en": "Word of Radiance"}, "level": 0, "school": "evocation", "classes": ["cleric"], "castingTime": "Action", "range": "Self (5-foot Emanation)", "components": "V, M (a sunburst token)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Um resplendor ardente irrompe de você em uma Emanação de 1,5 metro. Cada criatura à sua escolha que você possa ver dentro dela deve ser bem-sucedida em uma salvaguarda de Constituição ou sofrerá 1d6 de dano Radiante.\n\nAprimoramento de Truque. O dano aumenta em 1d6 quando você atinge os níveis 5 (2d6), 11 (3d6) e 17 (4d6).", "en": "Burning radiance erupts from you in a 5-foot Emanation. Each creature of your choice that you can see in it must succeed on a Constitution saving throw or take 1d6 Radiant damage.\n\nCantrip Upgrade. The damage increases by 1d6 when you reach levels 5 (2d6), 11 (3d6), and 17 (4d6)."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "hailOfThorns", "name": {"pt": "Chuva de Espinhos", "en": "Hail of Thorns"}, "level": 1, "school": "conjuration", "classes": ["ranger"], "castingTime": "Bonus Action, which you take immediately after hitting a creature with a Ranged weapon", "range": "Self", "components": "V", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Quando você atinge a criatura, esta magia cria uma chuva de espinhos que brota de sua arma à Distância ou munição. O alvo do ataque e cada criatura a até 1,5 metro dele fazem uma salvaguarda de Destreza, sofrendo 1d10 de dano Perfurante em uma salvaguarda com falha ou metade desse dano em uma bem-sucedida.\n\nUsando um Espaço de Magia de Círculo Superior. O dano aumenta em 1d10 para cada círculo do espaço de magia acima do 1º.", "en": "As you hit the creature, this spell creates a rain of thorns that sprouts from your Ranged weapon or ammunition. The target of the attack and each creature within 5 feet of it make a Dexterity saving throw, taking 1d10 Piercing damage on a failed save or half as much damage on a successful one.\n\nUsing a Higher-Level Spell Slot. The damage increases by 1d10 for each spell slot level above 1."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "thunderousSmite", "name": {"pt": "Destruição Trovejante", "en": "Thunderous Smite"}, "level": 1, "school": "evocation", "classes": ["paladin"], "castingTime": "Bonus Action, which you take immediately after hitting a target with a Melee weapon or an Unarmed Strike", "range": "Self", "components": "V", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Seu golpe ressoa com um trovão audível a até 90 metros de você, e o alvo sofre 2d6 de dano Trovejante adicional pelo ataque. Além disso, se o alvo for uma criatura, ele deve ser bem-sucedido em uma salvaguarda de Força ou será empurrado 3 metros para longe de você e ficará com a condição Caído.\n\nUsando um Espaço de Magia de Círculo Superior. O dano aumenta em 1d6 para cada círculo do espaço de magia acima do 1º.", "en": "Your strike rings with thunder that is audible within 300 feet of you, and the target takes an extra 2d6 Thunder damage from the attack. Additionally, if the target is a creature, it must succeed on a Strength saving throw or be pushed 10 feet away from you and have the Prone condition.\n\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 1."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "witchBolt", "name": {"pt": "Raio de Bruxa", "en": "Witch Bolt"}, "level": 1, "school": "evocation", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (a twig struck by lightning)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Um feixe de energia crepitante dispara em direção a uma criatura dentro do alcance, formando um arco sustentado de relâmpagos entre você e o alvo. Faça um ataque mágico à distância contra ele. Em um acerto, o alvo sofre 2d12 de dano Elétrico.\nEm cada um dos seus turnos subsequentes, você pode usar uma Ação Bônus para causar 1d12 de dano Elétrico ao alvo automaticamente, mesmo se o primeiro ataque tiver errado.\nA magia termina se o alvo ficar fora do alcance da magia em qualquer momento ou se tiver Cobertura Total contra você.\n\nUsando um Espaço de Magia de Círculo Superior. O dano inicial aumenta em 1d12 para cada círculo do espaço de magia acima do 1º.", "en": "A beam of crackling energy lances toward a creature within range, forming a sustained arc of lightning between you and the target. Make a ranged spell attack against it. On a hit, the target takes 2d12 Lightning damage.\nOn each of your subsequent turns, you can take a Bonus Action to deal 1d12 Lightning damage to the target automatically, even if the first attack missed.\nThe spell ends if the target is ever outside the spell's range or if it has Total Cover from you.\n\nUsing a Higher-Level Spell Slot. The initial damage increases by 1d12 for each spell slot level above 1."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "arcaneVigor", "name": {"pt": "Vigor Arcano", "en": "Arcane Vigor"}, "level": 2, "school": "abjuration", "classes": ["sorcerer", "wizard"], "castingTime": "Bonus Action", "range": "Self", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você recorre à sua força vital para curar a si mesmo. Role um ou dois dos seus Dados de Pontos de Vida não gastos e recupere uma quantidade de Pontos de Vida igual ao total rolado mais o seu modificador de habilidade de conjuração. Esses dados são então gastos.\n\nUsando um Espaço de Magia de Círculo Superior. O número de Dados de Vida não gastos que você pode rolar aumenta em um para cada círculo do espaço de magia acima do 2º.", "en": "You tap into your life force to heal yourself. Roll one or two of your unexpended Hit Point Dice, and regain a number of Hit Points equal to the roll's total plus your spellcasting ability modifier. Those dice are then expended.\n\nUsing a Higher-Level Spell Slot. The number of unexpended Hit Dice you can roll increases by one for each spell slot level above 2."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "cloudOfDaggers", "name": {"pt": "Nuvem de Adagas", "en": "Cloud of Daggers"}, "level": 2, "school": "conjuration", "classes": ["bard", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (a sliver of glass)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você conjura adagas giratórias em um Cubo de 1,5 metro centrado em um ponto dentro do alcance. Cada criatura naquela área sofre 4d4 de dano Cortante. Uma criatura também sofre este dano se entrar no Cubo ou terminar seu turno ali, ou se o Cubo se mover para o espaço dela. Uma criatura sofre este dano apenas uma vez por turno.\nEm seus turnos posteriores, você pode realizar uma ação de Magia para teletransportar o Cubo até 9 metros.\n\nUsando um Espaço de Magia de Círculo Superior. O dano aumenta em 2d4 para cada círculo do espaço de magia acima do 2º.", "en": "You conjure spinning daggers in a 5-foot Cube centered on a point within range. Each creature in that area takes 4d4 Slashing damage. A creature also takes this damage if it enters the Cube or ends its turn there or if the Cube moves into its space. A creature takes this damage only once per turn.\nOn your later turns, you can take a Magic action to teleport the Cube up to 30 feet.\n\nUsing a Higher-Level Spell Slot. The damage increases by 2d4 for each spell slot level above 2."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "cordonOfArrows", "name": {"pt": "Cordão de Flechas", "en": "Cordon of Arrows"}, "level": 2, "school": "transmutation", "classes": ["ranger"], "castingTime": "Action", "range": "Touch", "components": "V, S, M (an ornamental braid)", "duration": "8 hours", "ritual": false, "concentration": false, "desc": {"pt": "Você toca até quatro Flechas ou Virotes não mágicos e os finca no chão em seu espaço. Até a magia acabar, a munição não pode ser arrancada fisicamente e, sempre que uma criatura que não seja você entrar em um espaço a até 9 metros da munição pela primeira vez em um turno ou terminar seu turno ali, uma peça de munição voa para golpeá-la. A criatura deve ser bem-sucedida em uma salvaguarda de Destreza ou sofrerá 2d4 de dano Perfurante. A peça de munição é então destruída. A magia termina quando nenhuma das munições permanecer fincada no chão.\nQuando você conjura esta magia, pode designar quaisquer criaturas que escolher, e a magia as ignora.\n\nUsando um Espaço de Magia de Círculo Superior. A quantidade de munição que pode ser afetada aumenta em duas para cada círculo do espaço de magia acima do 2º.", "en": "You touch up to four nonmagical Arrows or Bolts and plant them in the ground in your space. Until the spell ends, the ammunition can't be physically uprooted, and whenever a creature other than you enters a space within 30 feet of the ammunition for the first time on a turn or ends its turn there, one piece of ammunition flies up to strike it. The creature must succeed on a Dexterity saving throw or take 2d4 Piercing damage. The piece of ammunition is then destroyed. The spell ends when none of the ammunition remains planted in the ground.\nWhen you cast this spell, you can designate any creatures you choose, and the spell ignores them.\n\nUsing a Higher-Level Spell Slot. The amount of ammunition that can be affected increases by two for each spell slot level above 2."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "blindingSmite", "name": {"pt": "Destruição Cegante", "en": "Blinding Smite"}, "level": 3, "school": "evocation", "classes": ["paladin"], "castingTime": "Bonus Action, which you take immediately after hitting a creature with a Melee weapon or an Unarmed Strike", "range": "Self", "components": "V", "duration": "1 minute", "ritual": false, "concentration": false, "desc": {"pt": "O alvo atingido pelo golpe sofre 3d8 de dano Radiante adicional pelo ataque, e o alvo fica com a condição Cego até a magia acabar. No final de cada um dos turnos dele, o alvo Cego faz uma salvaguarda de Constituição, encerrando a magia sobre si mesmo em caso de sucesso.\n\nUsando um Espaço de Magia de Círculo Superior. O dano adicional aumenta em 1d8 para cada círculo do espaço de magia acima do 3º.", "en": "The target hit by the strike takes an extra 3d8 Radiant damage from the attack, and the target has the Blinded condition until the spell ends. At the end of each of its turns, the Blinded target makes a Constitution saving throw, ending the spell on itself on a success.\n\nUsing a Higher-Level Spell Slot. The extra damage increases by 1d8 for each spell slot level above 3."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "lightningArrow", "name": {"pt": "Flecha Relampejante", "en": "Lightning Arrow"}, "level": 3, "school": "transmutation", "classes": ["ranger"], "castingTime": "Bonus Action, which you take immediately after hitting or missing a target with a ranged attack using a weapon", "range": "Self", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Quando seu ataque atinge ou erra o alvo, a arma ou munição que você está usando se transforma em um relâmpago. Em vez de sofrer qualquer dano ou outros efeitos do ataque, o alvo sofre 4d8 de dano Elétrico em um acerto ou metade desse dano em um erro. Cada criatura a até 3 metros do alvo faz então uma salvaguarda de Destreza, sofrendo 2d8 de dano Elétrico em uma salvaguarda com falha ou metade desse dano em uma bem-sucedida.\nA arma ou munição então retorna à sua forma normal.\n\nUsando um Espaço de Magia de Círculo Superior. O dano de ambos os efeitos da magia aumenta em 1d8 para cada círculo do espaço de magia acima do 3º.", "en": "As your attack hits or misses the target, the weapon or ammunition you're using transforms into a lightning bolt. Instead of taking any damage or other effects from the attack, the target takes 4d8 Lightning damage on a hit or half as much damage on a miss. Each creature within 10 feet of the target then makes a Dexterity saving throw, taking 2d8 Lightning damage on a failed save or half as much damage on a successful one.\nThe weapon or ammunition then returns to its normal form.\n\nUsing a Higher-Level Spell Slot. The damage for both effects of the spell increases by 1d8 for each spell slot level above 3."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "summonUndead", "name": {"pt": "Invocar Morto-Vivo", "en": "Summon Undead"}, "level": 3, "school": "necromancy", "classes": ["warlock", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V, S, M (a gilded skull worth 300+ GP)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você invoca um espírito morto-vivo. Ele se manifesta em um espaço desocupado que você possa ver dentro do alcance e usa o bloco de estatísticas de Espírito Morto-Vivo. Quando você conjura a magia, escolha a forma da criatura: Fantasmagórico, Pútrido ou Esquelético. O espírito se assemelha a uma criatura Morta-Viva com a forma escolhida, o que determina certos detalhes em seu bloco de estatísticas. A criatura desaparece quando cai a 0 Pontos de Vida ou quando a magia acaba.\nA criatura é uma aliada para você e seus aliados. Em combate, a criatura compartilha sua contagem de Iniciativa, mas realiza o turno dela imediatamente após o seu. Ela obedece aos seus comandos verbais (nenhuma ação exigida de você). Se você não der nenhum comando, ela realiza a ação de Desviar e usa seu movimento para evitar perigo.\n\nUsando um Espaço de Magia de Círculo Superior. Use o círculo do espaço de magia para o nível da magia no bloco de estatísticas.\n\nEspírito Morto-Vivo\n\nMorto-Vivo Médio, Neutro\n\nCA 11 + o nível da magia\nPV 30 (apenas Fantasmagórico e Pútrido) ou 20 (apenas Esquelético) + 10 para cada círculo de magia acima do 3º\nDeslocamento 9 m; Voo 12 m (flutuar; apenas Fantasmagórico)\n\nMOD SALVAGUARDA\nFor 12 +1 +1 · Des 16 +3 +3 · Con 15 +2 +2\nInt 4 -3 -3 · Sab 10 +0 +0 · Car 9 -1 -1\n\nImunidades Necrótico, Veneno; Exaustão, Amedrontado, Paralisado, Envenenado\nSentidos Visão no Escuro 18 m, Percepção Passiva 10\nIdiomas Compreende os idiomas que você conhece\nND Nenhum (XP 0; BP é igual ao seu Bônus de Proficiência)\n\nTraços\n\nAura Purulenta (Apenas Pútrido). Salvaguarda de Constituição: CD igual à CD de salvaguarda de sua magia, qualquer criatura (que não seja você) que iniciar seu turno dentro de uma Emanação de 1,5 metro originada do espírito. Falha: A criatura fica com a condição Envenenado até o início do próximo turno dela.\n\nPassagem Incorpórea (Apenas Fantasmagórico). O espírito pode se mover através de outras criaturas e objetos como se fossem Terreno Difícil. Se terminar seu turno dentro de um objeto, ele é expelido para o espaço desocupado mais próximo e sofre 1d10 de dano de Força para cada 1,5 metro percorrido.\n\nAções\n\nAtaque Múltiplo. O espírito faz uma quantidade de ataques igual à metade do nível desta magia (arredondado para baixo).\n\nToque Mortal (Apenas Fantasmagórico). Jogada de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque mágico, alcance 1,5 m. Acerto: 1d8 + 3 + o nível da magia de dano Necrótico, e o alvo fica com a condição Amedrontado até o final do próximo turno dele.\n\nDisparo da Cova (Apenas Esquelético). Jogada de Ataque à Distância: Bônus igual ao seu modificador de ataque mágico, alcance 45 m. Acerto: 2d4 + 3 + o nível da magia de dano Necrótico.\n\nGarra Apodrecida (Apenas Pútrido). Jogada de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque mágico, alcance 1,5 m. Acerto: 1d6 + 3 + o nível da magia de dano Cortante. Se o alvo estiver com a condição Envenenado, ele fica com a condição Paralisado até o final do próximo turno dele.", "en": "You call forth an Undead spirit. It manifests in an unoccupied space that you can see within range and uses the Undead Spirit stat block. When you cast the spell, choose the creature's form: Ghostly, Putrid, or Skeletal. The spirit resembles an Undead creature with the chosen form, which determines certain details in its stat block. The creature disappears when it drops to 0 Hit Points or when the spell ends.\nThe creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot’s level for the spell’s level in the stat block.\n\nUndead Spirit\n\nMedium Undead, Neutral\n\nAC 11 + the spell’s level\nHP 30 (Ghostly and Putrid only) or 20 (Skeletal only) + 10 for each spell level above 3\nSpeed 30 ft.; Fly 40 ft. (hover; Ghostly only)\n\nMOD SAVE\nStr 12 +1 +1 · Dex 16 +3 +3 · Con 15 +2 +2\nInt 4 -3 -3 · Wis 10 +0 +0 · Cha 9 -1 -1\n\nImmunities Necrotic, Poison; Exhaustion, Frightened, Paralyzed, Poisoned\nSenses Darkvision 60 ft., Passive Perception 10\nLanguages Understands the languages you know\nCR None (XP 0; PB equals your Proficiency Bonus)\n\nTraits\n\nFestering Aura (Putrid Only). Constitution Saving Throw: DC equals your spell save DC, any creature (other than you) that starts its turn within a 5-foot Emanation originating from the spirit. Failure: The creature has the Poisoned condition until the start of its next turn.\n\nIncorporeal Passage (Ghostly Only). The spirit can move through other creatures and objects as if they were Difficult Terrain. If it ends its turn inside an object, it is shunted to the nearest unoccupied space and takes 1d10 Force damage for every 5 feet traveled.\n\nActions\n\nMultiattack. The spirit makes a number of attacks equal to half this spell’s level (round down).\n\nDeathly Touch (Ghostly Only). Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: 1d8 + 3 + the spell’s level Necrotic damage, and the target has the Frightened condition until the end of its next turn.\n\nGrave Bolt (Skeletal Only). Ranged Attack Roll: Bonus equals your spell attack modifier, range 150 ft. Hit: 2d4 + 3 + the spell’s level Necrotic damage.\n\nRotting Claw (Putrid Only). Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: 1d6 + 3 + the spell’s level Slashing damage. If the target has the Poisoned condition, it has the Paralyzed condition until the end of its next turn."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "conjureVolley", "name": {"pt": "Conjurar Saraivada", "en": "Conjure Volley"}, "level": 5, "school": "conjuration", "classes": ["ranger"], "castingTime": "Action", "range": "150 feet", "components": "V, S, M (a Melee or Ranged weapon worth at least 1 CP)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você brande a arma usada para conjurar a magia e escolhe um ponto dentro do alcance. Centenas de armas espectrais semelhantes (ou munição apropriada para a arma) caem em uma saraivada e depois desaparecem. Cada criatura à sua escolha que você possa ver em um Cilindro de 12 metros de raio e 6 metros de altura centrado naquele ponto faz uma salvaguarda de Destreza. Uma criatura sofre 8d8 de dano de Força em uma salvaguarda com falha ou metade desse dano em uma bem-sucedida.", "en": "You brandish the weapon used to cast the spell and choose a point within range. Hundreds of similar spectral weapons (or ammunition appropriate to the weapon) fall in a volley and then disappear. Each creature of your choice that you can see in a 40-foot-radius, 20-foot-high Cylinder centered on that point makes a Dexterity saving throw. A creature takes 8d8 Force damage on a failed save or half as much damage on a successful one."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "jallarzisStormOfRadiance", "name": {"pt": "Tempestade Radiante de Jallarzi", "en": "Jallarzi's Storm of Radiance"}, "level": 5, "school": "evocation", "classes": ["warlock", "wizard"], "castingTime": "Action", "range": "120 feet", "components": "V, S, M (a pinch of phosphorus)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você desencadeia uma tempestade de luz lampejante e trovões furiosos em um Cilindro com 3 metros de raio e 12 metros de altura centrado em um ponto que você possa ver dentro do alcance. Enquanto estiverem nesta área, as criaturas ficam com as condições Cego e Surdo, e não podem conjurar magias com um componente Verbal.\nQuando a tempestade surge, cada criatura dentro dela faz uma salvaguarda de Constituição, sofrendo 2d10 de dano Radiante e 2d10 de dano Trovejante em uma salvaguarda com falha, ou metade desse dano em uma bem-sucedida. Uma criatura também faz esta salvaguarda quando entra na área da magia pela primeira vez em um turno ou termina o turno dela ali. Uma criatura faz esta salvaguarda apenas uma vez por turno.\n\nUsando um Espaço de Magia de Círculo Superior. O dano Radiante e Trovejante aumentam em 1d10 para cada círculo do espaço de magia acima do 5º.", "en": "You unleash a storm of flashing light and raging thunder in a 10-foot-radius, 40-foot-high Cylinder centered on a point you can see within range. While in this area, creatures have the Blinded and Deafened conditions, and they can't cast spells with a Verbal component.\nWhen the storm appears, each creature in it makes a Constitution saving throw, taking 2d10 Radiant damage and 2d10 Thunder damage on a failed save or half as much damage on a successful one. A creature also makes this save when it enters the spell's area for the first time on a turn or ends its turn there. A creature makes this save only once per turn.\n\nUsing a Higher-Level Spell Slot. The Radiant and Thunder damage increase by 1d10 for each spell slot level above 5."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "swiftQuiver", "name": {"pt": "Aljava Veloz", "en": "Swift Quiver"}, "level": 5, "school": "transmutation", "classes": ["ranger"], "castingTime": "Bonus Action", "range": "Self", "components": "V, S, M (a Quiver worth 1+ GP)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Quando você conjura a magia e como uma Ação Bônus até ela acabar, você pode realizar dois ataques com uma arma que dispara Flechas ou Virotes, como um Arco Longo ou uma Besta Leve. A magia cria magicamente a munição necessária para cada ataque. Cada Flecha ou Virote criado pela magia causa dano como uma peça de munição não mágica de seu tipo e se desintegra imediatamente após atingir ou errar.", "en": "When you cast the spell and as a Bonus Action until it ends, you can make two attacks with a weapon that fires Arrows or Bolts, such as a Longbow or a Light Crossbow. The spell magically creates the ammunition needed for each attack. Each Arrow or Bolt created by the spell deals damage like a nonmagical piece of ammunition of its kind and disintegrates immediately after it hits or misses."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "synapticStatic", "name": {"pt": "Estática Sináptica", "en": "Synaptic Static"}, "level": 5, "school": "enchantment", "classes": ["bard", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "120 feet", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você faz com que energia psíquica irrompa em um ponto dentro do alcance. Cada criatura em uma Esfera com raio de 6 metros centrada naquele ponto faz uma salvaguarda de Inteligência, sofrendo 8d6 de dano Psíquico em uma salvaguarda com falha ou metade desse dano em uma bem-sucedida.\nEm uma salvaguarda com falha, o alvo também fica com os pensamentos confusos durante 1 minuto. Durante esse tempo, ele subtrai 1d6 de todas as suas jogadas de ataque e testes de habilidade, assim como de quaisquer salvaguardas de Constituição para manter Concentração. O alvo faz uma salvaguarda de Inteligência no final de cada um dos turnos dele, encerrando o efeito sobre si mesmo em caso de sucesso.", "en": "You cause psychic energy to erupt at a point within range. Each creature in a 20-foot-radius Sphere centered on that point makes an Intelligence saving throw, taking 8d6 Psychic damage on a failed save or half as much damage on a successful one.\nOn a failed save, a target also has muddled thoughts for 1 minute. During that time, it subtracts 1d6 from all its attack rolls and ability checks, as well as any Constitution saving throws to maintain Concentration. The target makes an Intelligence saving throw at the end of each of its turns, ending the effect on itself on a success."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "arcaneGate", "name": {"pt": "Portal Arcano", "en": "Arcane Gate"}, "level": 6, "school": "conjuration", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "500 feet", "components": "V, S", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Você cria portais de teletransporte vinculados. Escolha dois espaços Grandes e desocupados no chão que você possa ver, um espaço dentro do alcance e o outro a até 3 metros de você. Um portal circular se abre em cada um desses espaços e permanece pela duração.\nOs portais são anéis brilhantes bidimensionais preenchidos com névoa que bloqueia a visão. Eles flutuam a poucos centímetros do chão e ficam perpendiculares a ele.\nUm portal fica aberto em apenas um dos lados (você escolhe qual). Qualquer coisa que adentrar o lado aberto de um portal sai pelo lado aberto do outro portal como se os dois fossem adjacentes um ao outro. Como uma Ação Bônus, você pode mudar a orientação dos lados abertos.", "en": "You create linked teleportation portals. Choose two Large, unoccupied spaces on the ground that you can see, one space within range and the other one within 10 feet of you. A circular portal opens in each of those spaces and remains for the duration.\nThe portals are two-dimensional glowing rings filled with mist that blocks sight. They hover inches from the ground and are perpendicular to it.\nA portal is open on only one side (you choose which). Anything entering the open side of a portal exits from the open side of the other portal as if the two were adjacent to each other. As a Bonus Action, you can change the facing of the open sides."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "summonFiend", "name": {"pt": "Invocar Corruptor", "en": "Summon Fiend"}, "level": 6, "school": "conjuration", "classes": ["warlock", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V, S, M (a bloody vial worth 600+ GP)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você invoca um espírito corruptor. Ele se manifesta em um espaço desocupado que você possa ver dentro do alcance e usa o bloco de estatísticas de Espírito Corruptor. Quando você conjura a magia, escolha Demônio, Diabo ou Yugoloth. A criatura se assemelha a um Corruptor do tipo escolhido, o que determina certos detalhes em seu bloco de estatísticas. A criatura desaparece quando cai a 0 Pontos de Vida ou quando a magia acaba.\nA criatura é uma aliada para você e seus aliados. Em combate, a criatura compartilha sua contagem de Iniciativa, mas realiza o turno dela imediatamente após o seu. Ela obedece aos seus comandos verbais (nenhuma ação exigida de você). Se você não der nenhum comando, ela realiza a ação de Desviar e usa seu movimento para evitar perigo.\n\nUsando um Espaço de Magia de Círculo Superior. Use o círculo do espaço de magia para o nível da magia no bloco de estatísticas.\n\nEspírito Corruptor\n\nCorruptor Grande, Neutro\n\nCA 12 + o nível da magia\nPV 50 (apenas Demônio) ou 40 (apenas Diabo) ou 60 (apenas Yugoloth) + 15 para cada círculo de magia acima do 6º\nDeslocamento 12 m; Escalada 12 m (apenas Demônio); Voo 18 m (apenas Diabo)\n\nMOD SALVAGUARDA\nFor 13 +1 +1 · Des 16 +3 +3 · Con 15 +2 +2\nInt 10 +0 +0 · Sab 10 +0 +0 · Car 16 +3 +3\n\nResistências Fogo\nImunidades Veneno; Envenenado\nSentidos Visão no Escuro 18 m, Percepção Passiva 10\nIdiomas Abissal, Infernal, Telepatia 18 m\nND Nenhum (XP 0; BP é igual ao seu Bônus de Proficiência)\n\nTraços\n\nAgonia Mortal (Apenas Demônio). Quando o espírito cai a 0 Pontos de Vida ou a magia acaba, o espírito explode. Salvaguarda de Destreza: CD igual à CD de salvaguarda de sua magia, cada criatura em uma Emanação de 3 metros originada do espírito. Falha: 2d10 mais o nível desta magia de dano de Fogo. Sucesso: Metade do dano.\n\nVisão do Diabo (Apenas Diabo). Escuridão mágica não impede a Visão no Escuro do espírito.\n\nResistência à Magia. O espírito tem Vantagem em salvaguardas contra magias e outros efeitos mágicos.\n\nAções\n\nAtaque Múltiplo. O espírito faz uma quantidade de ataques igual à metade do nível desta magia (arredondado para baixo).\n\nMordida (Apenas Demônio). Jogada de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque mágico, alcance 1,5 m. Acerto: 1d12 + 3 + o nível da magia de dano Necrótico.\n\nGarras (Apenas Yugoloth). Jogada de Ataque Corpo a Corpo: Bônus igual ao seu modificador de ataque mágico, alcance 1,5 m. Acerto: 1d8 + 3 + o nível da magia de dano Cortante. Imediatamente após o ataque acertar ou errar, o espírito pode se teletransportar até 9 metros para um espaço desocupado que possa ver.\n\nGolpe Ígneo (Apenas Diabo). Jogada de Ataque Corpo a Corpo ou à Distância: Bônus igual ao seu modificador de ataque mágico, alcance 1,5 m ou alcance 45 m. Acerto: 2d6 + 3 + o nível da magia de dano de Fogo.", "en": "You call forth a fiendish spirit. It manifests in an unoccupied space that you can see within range and uses the Fiendish Spirit stat block. When you cast the spell, choose Demon, Devil, or Yugoloth. The creature resembles a Fiend of the chosen type, which determines certain details in its stat block. The creature disappears when it drops to 0 Hit Points or when the spell ends.\nThe creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot’s level for the spell’s level in the stat block.\n\nFiendish Spirit\n\nLarge Fiend, Neutral\n\nAC 12 + the spell’s level\nHP 50 (Demon only) or 40 (Devil only) or 60 (Yugoloth only) + 15 for each spell level above 6\nSpeed 40 ft.; Climb 40 ft. (Demon only); Fly 60 ft. (Devil only)\n\nMOD SAVE\nStr 13 +1 +1 · Dex 16 +3 +3 · Con 15 +2 +2\nInt 10 +0 +0 · Wis 10 +0 +0 · Cha 16 +3 +3\n\nResistances Fire\nImmunities Poison; Poisoned\nSenses Darkvision 60 ft., Passive Perception 10\nLanguages Abyssal, Infernal, Telepathy 60 ft.\nCR None (XP 0; PB equals your Proficiency Bonus)\n\nTraits\n\nDeath Throes (Demon Only). When the spirit drops to 0 Hit Points or the spell ends, the spirit explodes. Dexterity Saving Throw: DC equals your spell save DC, each creature in a 10-foot Emanation originating from the spirit. Failure: 2d10 plus this spell’s level Fire damage. Success: Half damage.\n\nDevil’s Sight (Devil Only). Magical Darkness doesn’t impede the spirit’s Darkvision.\n\nMagic Resistance. The spirit has Advantage on saving throws against spells and other magical effects.\n\nActions\n\nMultiattack. The spirit makes a number of attacks equal to half this spell’s level (round down).\n\nBite (Demon Only). Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: 1d12 + 3 + the spell’s level Necrotic damage.\n\nClaws (Yugoloth Only). Melee Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. Hit: 1d8 + 3 + the spell’s level Slashing damage. Immediately after the attack hits or misses, the spirit can teleport up to 30 feet to an unoccupied space it can see.\n\nFiery Strike (Devil Only). Melee or Ranged Attack Roll: Bonus equals your spell attack modifier, reach 5 ft. or range 150 ft. Hit: 2d6 + 3 + the spell’s level Fire damage."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "tashasBubblingCauldron", "name": {"pt": "Caldeirão Borbulhante de Tasha", "en": "Tasha's Bubbling Cauldron"}, "level": 6, "school": "conjuration", "classes": ["warlock", "wizard"], "castingTime": "Action", "range": "5 feet", "components": "V, S, M (a gilded ladle worth 500+ GP)", "duration": "10 minutes", "ritual": false, "concentration": false, "desc": {"pt": "Você conjura um caldeirão sustentado por garras repleto de líquido borbulhante. O caldeirão surge em um espaço desocupado no chão a até 1,5 metro de você e dura pela duração da magia. O caldeirão não pode ser movido e desaparece quando a magia acaba, junto com o líquido borbulhante em seu interior.\nO líquido no caldeirão reproduz as propriedades de uma poção Comum ou Incomum de sua escolha (como uma Poção de Cura). Como uma Ação Bônus, você ou um aliado pode enfiar a mão no caldeirão e retirar uma poção desse tipo. A poção fica contida em um frasco que desaparece quando a poção é consumida. O caldeirão pode produzir uma quantidade dessas poções igual ao seu modificador de habilidade de conjuração (mínimo de 1). Quando a última dessas poções for retirada do caldeirão, o caldeirão desaparece e a magia termina.\nPoções obtidas do caldeirão que não forem consumidas desaparecem quando você conjurar esta magia novamente.", "en": "You conjure a claw-footed cauldron filled with bubbling liquid. The cauldron appears in an unoccupied space on the ground within 5 feet of you and lasts for the duration. The cauldron can't be moved and disappears when the spell ends, along with the bubbling liquid inside it.\nThe liquid in the cauldron duplicates the properties of a Common or an Uncommon potion of your choice (such as a Potion of Healing). As a Bonus Action, you or an ally can reach into the cauldron and withdraw one potion of that kind. The potion is contained in a vial that disappears when the potion is consumed. The cauldron can produce a number of these potions equal to your spellcasting ability modifier (minimum 1). When the last of these potions is withdrawn from the cauldron, the cauldron disappears, and the spell ends.\nPotions obtained from the cauldron that aren't consumed disappear when you cast this spell again."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "powerWordFortify", "name": {"pt": "Palavra de Poder: Fortalecer", "en": "Power Word Fortify"}, "level": 7, "school": "enchantment", "classes": ["bard", "cleric"], "castingTime": "Action", "range": "60 feet", "components": "V", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você fortifica até seis criaturas que possa ver dentro do alcance. A magia concede 120 Pontos de Vida Temporários, os quais você divide entre os destinatários da magia.", "en": "You fortify up to six creatures you can see within range. The spell bestows 120 Temporary Hit Points, which you divide among the spell's recipients."}, "rulesVersion": "2024", "source": "PHB24"},
  {"id": "telepathy", "name": {"pt": "Telepatia", "en": "Telepathy"}, "level": 8, "school": "divination", "classes": ["wizard"], "castingTime": "Action", "range": "Unlimited", "components": "V, S, M (a pair of linked silver rings)", "duration": "24 hours", "ritual": false, "concentration": false, "desc": {"pt": "Você cria um elo telepático entre você e uma criatura voluntária com a qual esteja familiarizado. A criatura pode estar em qualquer lugar no mesmo plano de existência em que você se encontra. A magia termina se você ou o alvo não estiverem mais no mesmo plano.\nAté a magia acabar, você e o alvo podem compartilhar instantaneamente palavras, imagens, sons e outras mensagens sensoriais entre si através do elo, e o alvo reconhece você como a criatura com quem está se comunicando. A magia permite que uma criatura compreenda o significado de suas palavras e quaisquer mensagens sensoriais enviadas por você a ela.", "en": "You create a telepathic link between yourself and a willing creature with which you are familiar. The creature can be anywhere on the same plane of existence as you. The spell ends if you or the target are no longer on the same plane.\nUntil the spell ends, you and the target can instantly share words, images, sounds, and other sensory messages with each other through the link, and the target recognizes you as the creature it is communicating with. The spell enables a creature to understand the meaning of your words and any sensory messages you send to it."}, "rulesVersion": "2024", "source": "PHB24"},
  // AAG
  {"id": "airBubble", "name": {"pt": "Bolha de Ar", "en": "Air Bubble"}, "level": 2, "school": "conjuration", "classes": ["artificer", "druid", "ranger", "sorcerer", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "S", "duration": "24 hours", "ritual": false, "concentration": false, "desc": {"pt": "Você cria um globo espectral ao redor da cabeça de uma criatura voluntária que você possa ver dentro do alcance. O globo fica cheio de ar fresco que dura até a magia terminar. Se a criatura tiver mais de uma cabeça, o globo de ar surge ao redor de apenas uma das cabeças dela (o que é tudo de que a criatura precisa para evitar sufocamento, presumindo que todas as suas cabeças compartilhem o mesmo sistema respiratório).\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, você pode criar dois globos adicionais de ar fresco para cada círculo do espaço acima do 2º.", "en": "You create a spectral globe around the head of a willing creature you can see within range. The globe is filled with fresh air that lasts until the spell ends. If the creature has more than one head, the globe of air appears around only one of its heads (which is all the creature needs to avoid suffocation, assuming that all its heads share the same respiratory system).\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you can create two additional globes of fresh air for each slot level above 2nd."}, "rulesVersion": "2024", "source": "AAG"},
  {"id": "createSpelljammingHelm", "name": {"pt": "Criar Leme de Spelljamming", "en": "Create Spelljamming Helm"}, "level": 5, "school": "transmutation", "classes": ["artificer", "wizard"], "castingTime": "Action", "range": "Touch", "components": "V, S, M (a crystal rod worth at least 5,000 gp, which the spell consumes)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Segurando a haste usada na conjuração da magia, você toca uma cadeira Grande ou menor que esteja desocupada. A haste desaparece e a cadeira é transformada em um elmo de spelljammer.", "en": "Holding the rod used in the casting of the spell, you touch a Large or smaller chair that is unoccupied. The rod disappears, and the chair is transformed into a spelljamming helm."}, "rulesVersion": "2024", "source": "AAG"},
  // AI
  {"id": "distortValue", "name": {"pt": "Distorcer Valor", "en": "Distort Value"}, "level": 1, "school": "illusion", "classes": ["bard", "sorcerer", "warlock", "wizard"], "castingTime": "1 minute", "range": "Touch", "components": "V", "duration": "8 hours", "ritual": false, "concentration": false, "desc": {"pt": "Você precisa arrancar mais algumas peças de ouro de um comerciante ao tentar vender aquela estátua esquisita de polvo que você libertou do templo do caos? Precisa diminuir o valor aparente de alguns bens mágicos quando o cobrador de impostos aparece? Distorcer valor resolve o seu problema.\n\nVocê conjura esta magia em um objeto com não mais de 30 centímetros de lado, dobrando o valor percebido do objeto ao adicionar adornos ou polimento ilusórios a ele, ou reduzindo seu valor percebido pela metade com a ajuda de arranhões, amassados e outros detalhes desagradáveis ilusórios. Qualquer pessoa que examinar o objeto pode determinar seu verdadeiro valor com um teste bem-sucedido de Inteligência (Investigação) contra a CD de salvaguarda da sua magia.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o tamanho máximo do objeto aumenta em 30 centímetros para cada círculo do espaço acima do 1º.", "en": "Do you need to squeeze a few more gold pieces out of a merchant as you try to sell that weird octopus statue you liberated from the chaos temple? Do you need to downplay the worth of some magical assets when the tax collector stops by? Distort value has you covered.\n\nYou cast this spell on an object no more than 1 foot on a side, doubling the object’s perceived value by adding illusory flourishes or polish to it, or reducing its perceived value by half with the help of illusory scratches, dents, and other unsightly features. Anyone examining the object can ascertain its true value with a successful Intelligence (Investigation) check against your spell save DC.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the maximum size of the object increases by 1 foot for each slot level above 1st."}, "rulesVersion": "2024", "source": "AI"},
  {"id": "jimsMagicMissile", "name": {"pt": "Mísseis Mágicos de Jim", "en": "Jim's Magic Missile"}, "level": 1, "school": "evocation", "classes": ["wizard"], "castingTime": "Action", "range": "120 feet", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "“Míssil mágico de Jim é uma magia antiga e poderosa, além de ser o nome da minha banda na Academia de Magos.” — Jim Darkmagic\n\nQualquer aprendiz de mago pode conjurar um míssil mágico comum e sem graça. Claro, ele sempre atinge o alvo. Que tédio. Acabe com a mesmice da magia do seu avô com esta versão aprimorada da magia, como usada por Jim Darkmagic!\n\nVocê cria três dardos giratórios, sibilantes, hipoalergênicos e sem glúten de energia mágica. Cada dardo tem como alvo uma criatura à sua escolha que você possa ver dentro do alcance. Faça um ataque à distância com magia para cada dardo. Se atingir, um dardo causa 2d4 de dano de energia ao seu alvo.\n\nSe a jogada de ataque obtiver um acerto crítico, o alvo daquele dardo sofre 5d4 de dano de energia em vez de você rolar o dano duas vezes para um acerto crítico. Se a jogada de ataque para qualquer dardo for um 1, todos os dardos erram seus alvos e explodem na sua cara, causando 1 de dano de energia por dardo a você.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, a magia cria um dardo adicional, e o componente de royalties aumenta em 1 po, para cada círculo do espaço acima do 1º.", "en": "“Jim’s magic missile is an ancient and powerful spell, as well as being the name of my band in Wizard Academy.” — Jim Darkmagic\n\nAny apprentice wizard can cast a boring old magic missile. Sure, it always strikes its target. Yawn. Do away with the drudgery of your grandfather’s magic with this improved version of the spell, as used by Jim Darkmagic!\n\nYou create three twisting, whistling, hypoallergenic, gluten-free darts of magical force. Each dart targets a creature of your choice that you can see within range. Make a ranged spell attack for each missile. On a hit, a missile deals 2d4 force damage to its target.\n\nIf the attack roll scores a critical hit, the target of that missile takes 5d4 force damage instead of you rolling damage twice for a critical hit. If the attack roll for any missile is a 1, all missiles miss their targets and blow up in your face, dealing 1 force damage per missile to you.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the spell creates one more dart, and the royalty component increases by 1 gp, for each slot level above 1st."}, "rulesVersion": "2024", "source": "AI"},
  {"id": "giftOfGab", "name": {"pt": "Dom da Palavra", "en": "Gift of Gab"}, "level": 2, "school": "enchantment", "classes": ["bard", "wizard"], "castingTime": "Reaction, which you take when you speak to another creature", "range": "Self", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "“Quando conheci Jim Darkmagic, me perguntei como ele conseguia fazer qualquer coisa com aquela roupa. Desde então, aprendi que a maioria dos seus talentos envolve ficar de pé e conversar. O traje dele é perfeito para isso.” — Môrgæn\n\nDiz-se que Jim Darkmagic inventou esta magia, originalmente chamando-a de Eu disse o quê?! Você já estava conversando com o monarca local e acidentalmente mencionou como o filho dele se parece com o seu porco favorito da época em que você crescia na fazenda da família? Todos nós já passamos por isso! Mas em vez de ser decapitado por um sincero deslize de língua, você pode fingir que isso nunca aconteceu — garantindo que ninguém saiba o que houve.\n\nQuando conjura esta magia, você remodela com habilidade as memórias dos ouvintes na sua área imediata, de modo que cada criatura à sua escolha a até 1,5 metro de você se esquece de tudo o que você disse nos últimos 6 segundos. Essas criaturas então se lembram de que você realmente disse as palavras que pronuncia como o componente verbal da magia.", "en": "“When I met Jim Darkmagic, I wondered how he got anything done in that outfit. I have since learned that most of his talents involve standing and talking. His outfit is perfect for that.” — Môrgæn\n\nJim Darkmagic is said to have invented this spell, originally calling it I said what?! Have you ever been talking to the local monarch and accidentally mentioned how their son looks like your favorite hog from when you were growing up on the family farm? We’ve all been there! But rather than being beheaded for an honest slip of the tongue, you can pretend it never happened—by ensuring that no one knows it happened.\n\nWhen you cast this spell, you skillfully reshape the memories of listeners in your immediate area, so that each creature of your choice within 5 feet of you forgets everything you said within the last 6 seconds. Those creatures then remember that you actually said the words you speak as the verbal component of the spell."}, "rulesVersion": "2024", "source": "AI"},
  {"id": "jimsGlowingCoin", "name": {"pt": "Moeda Brilhante de Jim", "en": "Jim's Glowing Coin"}, "level": 2, "school": "enchantment", "classes": ["wizard"], "castingTime": "Action", "range": "60 feet", "components": "S, M (a coin)", "duration": "1 minute", "ritual": false, "concentration": false, "desc": {"pt": "Nome: Moeda Brilhante de Jim\n\nTipo: Magia\n\nFonte: Acquisitions Incorporated\n\nAurora ID: ID_WOTC_ACQINC_SPELL_JIMS_GLOWING_COIN\n\nSuporta: Mago, Teste de Resistência de Magia\n\nDefinições:\npalavras-chave: realeza\nnível: 2\nescola: Encantamento\ntempo: 1 ação\nduração: 1 minuto\nalcance: 18 metros\ntemComponenteVerbal: falso\ntemComponenteSomatico: verdadeiro\ntemComponenteMaterial: verdadeiro\ncomponenteMaterial: uma moeda\néConcentração: falso\néRitual: falso\n\nDescrição:\nDas muitas táticas empregadas pelo mestre mago e renomado aventureiro Jim Darkmagic, o velho truque da moeda brilhante é um clássico consagrado pelo tempo. Quando você conjura a magia, arremessa a moeda que é o componente material da magia para qualquer ponto dentro do alcance. A moeda se ilumina como se estivesse sob o efeito de uma magia de luz. Cada criatura à sua escolha que você possa ver a até 9 metros da moeda deve ser bem-sucedida em um teste de resistência de Sabedoria ou ficará distraída pela duração. Enquanto distraída, a criatura tem desvantagem em testes de Sabedoria (Percepção) e em jogadas de iniciativa.", "en": "Name: Jim’s Glowing Coin\n\nType: Spell\n\nSource: Acquisitions Incorporated\n\nAurora ID: ID_WOTC_ACQINC_SPELL_JIMS_GLOWING_COIN\n\nSupports: Wizard, Spell Saving Throw\n\nSetters:\nkeywords: royalty\nlevel: 2\nschool: Enchantment\ntime: 1 action\nduration: 1 minute\nrange: 60 feet\nhasVerbalComponent: false\nhasSomaticComponent: true\nhasMaterialComponent: true\nmaterialComponent: a coin\nisConcentration: false\nisRitual: false\n\nDescription:\nOf the many tactics employed by master magician and renowned adventurer Jim Darkmagic, the old glowing coin trick is a time-honored classic. When you cast the spell, you hurl the coin that is the spell’s material component to any spot within range. The coin lights up as if under the effect of a light spell. Each creature of your choice that you can see within 30 feet of the coin must succeed on a Wisdom saving throw or be distracted for the duration. While distracted, a creature has disadvantage on Wisdom (Perception) checks and initiative rolls."}, "rulesVersion": "2024", "source": "AI"},
  {"id": "fastFriends", "name": {"pt": "Amigos Rápidos", "en": "Fast Friends"}, "level": 3, "school": "enchantment", "classes": ["bard", "cleric", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "V", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Nome: Amigos Rápidos\n\nTipo: Magia\n\nFonte: Acquisitions Incorporated\n\nAurora ID: ID_WOTC_ACQINC_SPELL_FAST_FRIENDS\n\nSuporta: Bardo, Clérigo, Mago, Teste de Resistência de Magia\n\nDefinições:\npalavras-chave: enfeitiçar\nnível: 3\nescola: Encantamento\ntempo: 1 ação\nduração: Concentração, até 1 hora\nalcance: 9 metros\ntemComponenteVerbal: verdadeiro\ntemComponenteSomatico: falso\ntemComponenteMaterial: falso\néConcentração: verdadeiro\néRitual: falso\n\nDescrição:\nQuando você precisa ter certeza de que algo será feito, não pode confiar em promessas vagas, juramentos prestados ou contratos de trabalho vinculativos. Quando conjurar esta magia, escolha um humanoide dentro do alcance que possa ver e ouvir você, e que possa compreender você. A criatura deve ser bem-sucedida em um teste de resistência de Sabedoria ou ficará enfeitiçada por você pela duração. Enquanto a criatura estiver enfeitiçada dessa maneira, ela se compromete a prestar quaisquer serviços ou atividades que você pedir a ela de maneira amigável, com o melhor de suas habilidades.\nVocê pode definir novas tarefas para a criatura quando uma tarefa anterior for concluída, ou se decidir encerrar a tarefa atual dela. Se o serviço ou atividade puder causar dano à criatura, ou se entrar em conflito com as atividades e desejos normais da criatura, ela pode fazer outro teste de resistência de Sabedoria para tentar encerrar o efeito. Esse teste é feito com vantagem se você ou seus companheiros estiverem lutando contra a criatura. Se a atividade resultar em morte certa para a criatura, a magia termina.\nQuando a magia termina, a criatura sabe que foi enfeitiçada por você.\nEm Níveis Superiores.\nQuando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 3º.", "en": "Name: Fast Friends\n\nType: Spell\n\nSource: Acquisitions Incorporated\n\nAurora ID: ID_WOTC_ACQINC_SPELL_FAST_FRIENDS\n\nSupports: Bard, Cleric, Wizard, Spell Saving Throw\n\nSetters:\nkeywords: charm\nlevel: 3\nschool: Enchantment\ntime: 1 action\nduration: Concentration, up to 1 hour\nrange: 30 feet\nhasVerbalComponent: true\nhasSomaticComponent: false\nhasMaterialComponent: false\nisConcentration: true\nisRitual: false\n\nDescription:\nWhen you need to make sure something gets done, you can’t rely on vague promises, sworn oaths, or binding contracts of employment. When you cast this spell, choose one humanoid within range that can see and hear you, and that can understand you. The creature must succeed on a Wisdom saving throw or become charmed by you for the duration. While the creature is charmed in this way, it undertakes to perform any services or activities you ask of it in a friendly manner, to the best of its ability.\nYou can set the creature new tasks when a previous task is completed, or if you decide to end its current task. If the service or activity might cause harm to the creature. or if it conflicts with the creature’s normal activities and desires, the creature can make another Wisdom saving throw to try to end the effect. This save is made with advantage if you or your companions are fighting the creature. If the activity would result in certain death for the creature, the spell ends.\nWhen the spell ends, the creature knows it was charmed by you.\nAt Higher Levels.\nWhen you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd."}, "rulesVersion": "2024", "source": "AI"},
  {"id": "inciteGreed", "name": {"pt": "Incitar Ganância", "en": "Incite Greed"}, "level": 3, "school": "enchantment", "classes": ["cleric", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "V, S, M (a gem worth at least 50 gp)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Nome: Incitar Ganância\n\nTipo: Magia\n\nFonte: Acquisitions Incorporated\n\nAurora ID: ID_WOTC_ACQINC_SPELL_INCITE_GREED\n\nSuporta: Clérigo, Feiticeiro, Mago, Bruxo, Teste de Resistência de Magia\n\nDefinições:\npalavras-chave: enfeitiçar\nnível: 3\nescola: Encantamento\ntempo: 1 ação\nduração: Concentração, até 1 minuto\nalcance: 9 metros\ntemComponenteVerbal: verdadeiro\ntemComponenteSomatico: verdadeiro\ntemComponenteMaterial: verdadeiro\ncomponenteMaterial: uma gema que valha pelo menos 50 po\néConcentração: verdadeiro\néRitual: falso\n\nDescrição:\nQuando você conjura esta magia, apresenta a gema usada como componente material e escolhe qualquer quantidade de criaturas dentro do alcance que possam ver você. Cada alvo deve ser bem-sucedido em um teste de resistência de Sabedoria ou ficará enfeitiçado por você até a magia terminar, ou até que você ou seus companheiros façam qualquer coisa prejudicial a ele. Enquanto estiver enfeitiçada dessa maneira, uma criatura não pode fazer nada além de usar seu movimento para se aproximar de você de maneira segura. Enquanto uma criatura afetada estiver a até 1,5 metro de você, ela não pode se mover, apenas olhando fixamente com ganância para a gema que você apresenta.\nNo final de cada um dos turnos dele, um alvo afetado pode fazer um teste de resistência de Sabedoria. Se for bem-sucedido, este efeito termina para aquele alvo.", "en": "Name: Incite Greed\n\nType: Spell\n\nSource: Acquisitions Incorporated\n\nAurora ID: ID_WOTC_ACQINC_SPELL_INCITE_GREED\n\nSupports: Cleric, Sorcerer, Wizard, Warlock, Spell Saving Throw\n\nSetters:\nkeywords: charm\nlevel: 3\nschool: Enchantment\ntime: 1 action\nduration: Concentration, up to 1 minute\nrange: 30 feet\nhasVerbalComponent: true\nhasSomaticComponent: true\nhasMaterialComponent: true\nmaterialComponent: a gem worth at least 50 gp\nisConcentration: true\nisRitual: false\n\nDescription:\nWhen you cast this spell, you present the gem used as the material component and choose any number of creatures within range that can see you. Each target must succeed on a Wisdom saving throw or be charmed by you until the spell ends, or until you or your companions do anything harmful to it. While charmed in this way, a creature can do nothing but use its movement to approach you in a safe manner. While an affected creature is within 5 feet of you, it cannot move, but simply stares greedily at the gem you present.\nAt the end of each of its turns, an affected target can make a Wisdom saving throw. If it succeeds, this effect ends for that target."}, "rulesVersion": "2024", "source": "AI"},
  {"id": "motivationalSpeech", "name": {"pt": "Discurso Motivacional", "en": "Motivational Speech"}, "level": 3, "school": "enchantment", "classes": ["bard", "cleric"], "castingTime": "1 minute", "range": "60 feet", "components": "V", "duration": "1 hour", "ritual": false, "concentration": false, "desc": {"pt": "Nome: Discurso Motivacional\n\nTipo: Magia\n\nFonte: Acquisitions Incorporated\n\nAurora ID: ID_WOTC_ACQINC_SPELL_MOTIVATIONAL_SPEECH\n\nSuporta: Bardo, Clérigo\n\nDefinições:\npalavras-chave: pontos de vida temporários,vantagem\nnível: 3\nescola: Encantamento\ntempo: 1 minuto\nduração: 1 hora\nalcance: 18 metros\ntemComponenteVerbal: verdadeiro\ntemComponenteSomatico: falso\ntemComponenteMaterial: falso\néConcentração: falso\néRitual: falso\n\nDescrição:\nVocê se dirige a aliados, funcionários ou espectadores inocentes para exortá-los e inspirá-los à grandeza, tenham eles algo para se empolgar ou não. Escolha até cinco criaturas dentro do alcance que possam ouvir você. Pela duração, cada criatura afetada ganha 5 Pontos de Vida Temporários e tem vantagem em testes de resistência de Sabedoria. Se uma criatura afetada for atingida por um ataque, ela tem vantagem na próxima jogada de ataque que fizer. Assim que uma criatura afetada perde os Pontos de Vida Temporários concedidos por esta magia, a magia termina para aquela criatura.\nEm Níveis Superiores.\nQuando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, os Pontos de Vida Temporários aumentam em 5 para cada círculo do espaço acima do 3º.", "en": "Name: Motivational Speech\n\nType: Spell\n\nSource: Acquisitions Incorporated\n\nAurora ID: ID_WOTC_ACQINC_SPELL_MOTIVATIONAL_SPEECH\n\nSupports: Bard, Cleric\n\nSetters:\nkeywords: temporary hit points,advantage\nlevel: 3\nschool: Enchantment\ntime: 1 minute\nduration: 1 hour\nrange: 60 feet\nhasVerbalComponent: true\nhasSomaticComponent: false\nhasMaterialComponent: false\nisConcentration: false\nisRitual: false\n\nDescription:\nYou address allies, staff, or innocent bystanders to exhort and inspire them to greatness, whether they have anything to get excited about or not. Choose up to five creatures within range that can hear you. For the duration, each affected creature gains 5 temporary hit points and has advantage on Wisdom saving throws. If an affected creature is hit by an attack, it has advantage on the next attack roll it makes. Once an affected creature loses the temporary hit points granted by this spell, the spell ends for that creature.\nAt Higher Levels.\nWhen you cast this spell using a spell slot of 4th level or higher, the temporary hit points increase by 5 for each slot level above 3rd."}, "rulesVersion": "2024", "source": "AI"},
  // BMT
  {"id": "sprayOfCards", "name": {"pt": "Chuva de Cartas", "en": "Spray of Cards"}, "level": 2, "school": "conjuration", "classes": ["bard", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "Self (15-foot cone)", "components": "V, S, M (a deck of cards)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você espalha um Cone de 4,5 metros de cartas espectrais. Cada criatura nessa área deve fazer um teste de resistência de Destreza. Em uma falha na salvaguarda, uma criatura sofre 2d10 de dano de Força e fica com a condição cego até o final do próximo turno dela. Em um sucesso na salvaguarda, uma criatura sofre apenas metade desse dano.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 2º.", "en": "You spray a 15-foot cone of spectral cards. Each creature in that area must make a Dexterity saving throw. On a failed save, a creature takes 2d10 force damage and has the blinded condition until the end of its next turn. On a successful save, a creature takes half as much damage only.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d10 for each slot level above 2nd."}, "rulesVersion": "2024", "source": "BMT"},
  {"id": "antagonize", "name": {"pt": "Antagonizar", "en": "Antagonize"}, "level": 3, "school": "enchantment", "classes": ["bard", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "V, S, M (a playing card depicting a rogue)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você sussurra palavras mágicas que hostilizam uma criatura à sua escolha dentro do alcance. O alvo deve fazer um teste de resistência de Sabedoria. Em uma falha na salvaguarda, o alvo sofre 4d4 de dano Psíquico e deve imediatamente usar a reação dele para fazer um ataque corpo a corpo contra outra criatura à sua escolha que você possa ver. Se o alvo não puder fazer esse ataque (por exemplo, porque não há ninguém ao seu alcance ou porque a reação dele está indisponível), o alvo em vez disso tem desvantagem na próxima jogada de ataque que fizer antes do início do seu próximo turno. Em um sucesso na salvaguarda, o alvo sofre apenas metade do dano.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d4 para cada círculo do espaço acima do 3º.", "en": "You whisper magical words that antagonize one creature of your choice within range. The target must make a Wisdom saving throw. On a failed save, the target takes 4d4 psychic damage and must immediately use its reaction to make a melee attack against another creature of your choice that you can see. If the target can’t make this attack (for example, because there is no one within its reach or because its reaction is unavailable), the target instead has disadvantage on the next attack roll it makes before the start of your next turn. On a successful save, the target takes half as much damage only.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d4 for each slot level above 3rd."}, "rulesVersion": "2024", "source": "BMT"},
  {"id": "spiritOfDeath", "name": {"pt": "Espírito da Morte", "en": "Spirit of Death"}, "level": 4, "school": "necromancy", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (a gilded playing card worth at least 400 gp and depicting an avatar of death)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Nome: Espírito da Morte\n\nTipo: Magia\n\nFonte: Unearthed Arcana: Wonders of the Multiverse\n\nAurora ID: ID_WOTC_UA20220718_SPELL_SPIRIT_OF_DEATH\n\nSuporta: Feiticeiro, Bruxo, Mago\n\nDefinições:\npalavras-chave: carta\nnível: 4\nescola: Necromancia\néRitual: falso\ntempo: 1 ação\nalcance: 18 metros\ntemComponenteVerbal: verdadeiro\ntemComponenteSomatico: verdadeiro\ntemComponenteMaterial: verdadeiro\ncomponenteMaterial: uma carta de baralho dourada retratando um avatar da morte que valha pelo menos 400 po\nduração: Concentração, até 1 minuto\néConcentração: verdadeiro\n\nDescrição:\nVocê invoca um espírito que personifica a própria morte. Escolha uma criatura que você possa ver dentro do alcance. O espírito se manifesta em um espaço desocupado que você possa ver a até 3 metros do alvo, e o alvo se torna assombrado pelo espírito. O espírito usa o bloco de estatísticas do Espírito Ceifador. O espírito desaparece quando ele ou a criatura assombrada for reduzido a 0 Pontos de Vida, ou quando a magia terminar.\nO espírito ceifador é um aliado para você e seus companheiros. Em combate, o espírito compartilha a sua contagem de iniciativa, mas realiza o turno dele imediatamente após o seu. Ele obedece aos seus comandos verbais (nenhuma ação exigida de você), mas atacará apenas a criatura assombrada. Se você não der nenhum comando ao espírito, ele realiza a ação de Esquiva e usa seu movimento para evitar o perigo.\nEm Níveis Superiores.\nQuando você conjurar esta magia usando um espaço de magia de 5º círculo ou superior, use o círculo superior onde o círculo da magia aparece no bloco de estatísticas.", "en": "Name: Spirit of Death\n\nType: Spell\n\nSource: Unearthed Arcana: Wonders of the Multiverse\n\nAurora ID: ID_WOTC_UA20220718_SPELL_SPIRIT_OF_DEATH\n\nSupports: Sorcerer, Warlock, Wizard\n\nSetters:\nkeywords: card\nlevel: 4\nschool: Necromancy\nisRitual: false\ntime: 1 action\nrange: 60 feet\nhasVerbalComponent: true\nhasSomaticComponent: true\nhasMaterialComponent: true\nmaterialComponent: a gilded playing card depicting an avatar of death worth at least 400 gp\nduration: Concentration, up to 1 minute\nisConcentration: true\n\nDescription:\nYou call forth a spirit that embodies death itself. Choose a creature you can see within range. The spirit manifests in an unoccupied space that you can see within 10 feet of the target, and the target becomes haunted by the spirit. The spirit uses the Reaper Spirit stat block. The spirit disappears when it or the haunted creature is reduced to 0 hit points, or when the spell ends.\nThe reaper spirit is an ally to you and your companions. In combat, the spirit shares your initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you), but it will only attack the haunted creature. If you don’t issue the spirit any commands, it takes the Dodge action and uses its move to avoid danger.\nAt Higher Levels.\nWhen you cast this spell using a spell slot of 5th level or higher, use the higher level wherever the spell’s level appears in the stat block."}, "rulesVersion": "2024", "source": "BMT"},
  // EGW
  {"id": "sappingSting", "name": {"pt": "Ferroada Drenante", "en": "Sapping Sting"}, "level": 0, "school": "necromancy", "classes": ["wizard"], "castingTime": "Action", "range": "30 feet", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você drena a vitalidade de uma criatura que possa ver dentro do alcance. O alvo deve ser bem-sucedido em uma salvaguarda de Constituição ou sofrerá 1d4 de dano necrótico e ficará caído.\n\nO dano desta magia aumenta em 1d4 quando você alcança o 5º nível (2d4), 11º nível (3d4) e 17º nível (4d4).", "en": "You sap the vitality of one creature you can see in range. The target must succeed on a Constitution saving throw or take 1d4 necrotic damage and fall prone.\n\nThis spell’s damage increases by 1d4 when you reach 5th level (2d4), 11th level (3d4), and 17th level (4d4)."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "giftOfAlacrity", "name": {"pt": "Dom da Presteza", "en": "Gift of Alacrity"}, "level": 1, "school": "divination", "classes": ["wizard"], "castingTime": "Action", "range": "Touch", "components": "V, S", "duration": "8 hours", "ritual": false, "concentration": false, "desc": {"pt": "Você toca em uma criatura voluntária. Pela duração, o alvo pode adicionar 1d8 às suas rolagens de iniciativa.", "en": "You touch a willing creature. For the duration, the target can add 1d8 to its initiative rolls."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "magnifyGravity", "name": {"pt": "Ampliar Gravidade", "en": "Magnify Gravity"}, "level": 1, "school": "transmutation", "classes": ["wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S", "duration": "1 round", "ritual": false, "concentration": false, "desc": {"pt": "A gravidade em uma esfera com raio de 3 metros centrada em um ponto que você possa ver dentro do alcance aumenta por um momento. Cada criatura na esfera no turno em que você conjurar a magia deve fazer uma salvaguarda de Constituição. Se falhar na salvaguarda, a criatura sofre 2d8 de dano de energia e seu deslocamento é reduzido pela metade até o final do próximo turno dela. Em um sucesso na salvaguarda, a criatura sofre metade do dano e não tem seu deslocamento reduzido.\n\nAté o início do seu próximo turno, qualquer objeto na esfera que não esteja sendo vestido ou carregado requer um teste bem-sucedido de Força contra a CD de salvaguarda da sua magia para ser apanhado ou movido.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 1º.", "en": "The gravity in a 10-foot-radius sphere centered on a point you can see within range increases for a moment. Each creature in the sphere on the turn when you cast the spell must make a Constitution saving throw. On a failed save, a creature takes 2d8 force damage, and its speed is halved until the end of its next turn. On a successful save, a creature takes half as much damage and suffers no reduction to its speed.\n\nUntil the start of your next turn, any object that isn’t being worn or carried in the sphere requires a successful Strength check against your spell save DC to pick up or move.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "fortunesFavor", "name": {"pt": "Favor da Fortuna", "en": "Fortune's Favor"}, "level": 2, "school": "divination", "classes": ["wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (a white pearl worth at least 100 gp, which the spell consumes)", "duration": "1 hour", "ritual": false, "concentration": false, "desc": {"pt": "Você concede sorte latente a si mesmo ou a uma criatura voluntária que possa ver dentro do alcance. Quando a criatura escolhida fizer uma jogada de ataque, um teste de atributo ou uma salvaguarda antes da magia terminar, ela pode encerrar esta magia sobre si mesma para rolar um d20 adicional e escolher qual dos d20s usar. Alternativamente, quando uma jogada de ataque for feita contra a criatura escolhida, ela pode encerrar esta magia sobre si mesma para rolar um d20 e escolher qual dos d20s usar: o que ela rolou ou o que o atacante rolou.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 2º.", "en": "You impart latent luck to yourself or one willing creature you can see within range. When the chosen creature makes an attack roll, an ability check, or a saving throw before the spell ends, it can dismiss this spell on itself to roll an additional d20 and choose which of the d20s to use. Alternatively, when an attack roll is made against the chosen creature, it can dismiss this spell on itself to roll a d20 and choose which of the d20s to use, the one it rolled or the one the attacker rolled.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "immovableObject", "name": {"pt": "Objeto Imóvel", "en": "Immovable Object"}, "level": 2, "school": "transmutation", "classes": ["wizard"], "castingTime": "Action", "range": "Touch", "components": "V, S, M (gold dust worth at least 25 gp, which the spell consumes)", "duration": "1 hour", "ritual": false, "concentration": false, "desc": {"pt": "Você toca um objeto que pese no máximo 4,5 kg e faz com que ele se torne magicamente fixo no lugar. Você e as criaturas que designar ao conjurar esta magia podem mover o objeto normalmente. Você também pode definir uma palavra-passe que, quando dita a até 1,5 metro do objeto, suprime esta magia por 1 minuto.\n\nSe o objeto estiver fixado no ar, ele pode suportar até 1.800 kg de peso. Mais peso faz com que o objeto caia. Do contrário, uma criatura pode usar uma ação para fazer um teste de Força contra a CD de resistência da sua magia. Em um sucesso, a criatura pode mover o objeto em até 3 metros.\n\nEm Níveis Superiores. Se você conjurar esta magia usando um espaço de magia de 4º ou 5º círculo, a CD para mover o objeto aumenta em 5, ele pode suportar até 3.600 kg de peso e a duração aumenta para 24 horas. Se você conjurar esta magia usando um espaço de magia de 6º círculo ou superior, a CD para mover o objeto aumenta em 10, ele pode suportar até 9.000 kg de peso e o efeito se torna permanente até ser dissipado.", "en": "You touch an object that weighs no more than 10 pounds and cause it to become magically fixed in place. You and the creatures you designate when you cast this spell can move the object normally. You can also set a password that, when spoken within 5 feet of the object, suppresses this spell for 1 minute.\n\nIf the object is fixed in the air, it can hold up to 4,000 pounds of weight. More weight causes the object to fall. Otherwise, a creature can use an action to make a Strength check against your spell save DC. On a success, the creature can move the object up to 10 feet.\n\nAt Higher Levels. If you cast this spell using a spell slot of 4th or 5th level, the DC to move the object increases by 5, it can carry up to 8,000 pounds of weight, and the duration increases to 24 hours. If you cast this spell using a spell slot of 6th level or higher, the DC to move the object increases by 10, it can carry up to 20,000 pounds of weight, and the effect is permanent until dispelled."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "wristpocket", "name": {"pt": "Bolso de Pulso", "en": "Wristpocket"}, "level": 2, "school": "conjuration", "classes": ["wizard"], "castingTime": "Action or Ritual", "range": "Self", "components": "S", "duration": "Concentration, up to 1 hour", "ritual": true, "concentration": true, "desc": {"pt": "Você move seu pulso, fazendo com que um objeto em sua mão desapareça. O objeto, que apenas você pode estar segurando e que não pode pesar mais de 2,2 kg, é transportado para um espaço extradimensional, onde permanece pela duração.\n\nAté a magia terminar, você pode usar sua ação para invocar o objeto para a sua mão livre e pode usar sua ação para enviar o objeto de volta ao espaço extradimensional. Um objeto que ainda esteja no plano de bolso quando a magia terminar aparece no chão do seu espaço.", "en": "You flick your wrist, causing one object in your hand to vanish. The object, which only you can be holding and can weigh no more than 5 pounds, is transported to an extradimensional space, where it remains for the duration.\n\nUntil the spell ends, you can use your action to summon the object to your free hand, and you can use your action to return the object to the extradimensional space. An object still in the pocket plane when the spell ends appears in your space, at your feet."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "pulseWave", "name": {"pt": "Onda de Pulso", "en": "Pulse Wave"}, "level": 3, "school": "evocation", "classes": ["wizard"], "castingTime": "Action", "range": "Self (30-foot cone)", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você cria uma pressão intensa, liberando-a em um Cone de 9 metros, e decide se a pressão puxa ou empurra criaturas e objetos. Cada criatura naquele cone deve fazer um teste de resistência de Constituição. Uma criatura sofre 6d6 de dano de Força em uma falha na salvaguarda, ou metade desse dano em um sucesso. E cada criatura que falhar na salvaguarda é puxada 4,5 metros em sua direção ou empurrada 4,5 metros para longe de você, dependendo da escolha que fez para a magia.\n\nAlém disso, objetos soltos que estejam completamente dentro do cone são da mesma forma puxados ou empurrados por 4,5 metros.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d6 e a distância puxada ou empurrada aumenta em 1,5 metro para cada círculo do espaço acima do 3º.", "en": "You create intense pressure, unleash it in a 30-foot cone, and decide whether the pressure pulls or pushes creatures and objects. Each creature in that cone must make a Constitution saving throw. A creature takes 6d6 force damage on a failed save, or have as much damage on a successful one. And every creature that fails the save is either pulled 15 feet toward you or pushed 15 feet away from you, depending on the choice you made for the spell.\n\nIn addition, unsecured objects that are completely within the cone are likewise pulled or pushed 15 feet.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d6 and the distance pulled or pushed increases by 5 feet for each slot level above 3rd."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "gravitySinkhole", "name": {"pt": "Sumidouro Gravitacional", "en": "Gravity Sinkhole"}, "level": 4, "school": "evocation", "classes": ["wizard"], "castingTime": "Action", "range": "120 feet", "components": "V, S, M (a black marble)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Uma Esfera com raio de 6 metros de força esmagadora se forma em um ponto que você possa ver dentro do alcance e atrai as criaturas ali presentes. Cada criatura na esfera deve fazer um teste de resistência de Constituição. Em uma falha na salvaguarda, a criatura sofre 5d10 de dano de Força e é puxada em linha reta em direção ao centro da esfera, terminando em um espaço desocupado o mais próximo possível do centro (mesmo que esse espaço esteja no ar). Em um sucesso na salvaguarda, a criatura sofre metade desse dano e não é puxada.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 5º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 4º.", "en": "A 20-foot-radius sphere of crushing force forms at a point you can see within range and tugs at the creatures there. Each creature in the sphere must make a Constitution saving throw. On a failed save, the creature takes 5d10 force damage and is pulled in a straight line toward the center of the sphere, ending in an unoccupied space as close to the center as possible (even if that space is in the air). On a successful save, the creature takes half as much damage and isn’t pulled.\n\nAt Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d10 for each slot level above 4th."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "temporalShunt", "name": {"pt": "Desvio Temporal", "en": "Temporal Shunt"}, "level": 5, "school": "transmutation", "classes": ["wizard"], "castingTime": "Reaction, which you take when a creature you can see makes an attack roll or starts to cast a spell", "range": "120 feet", "components": "V, S", "duration": "1 round", "ritual": false, "concentration": false, "desc": {"pt": "Você alveja a criatura que desencadeou a reação, que deve ser bem-sucedida em um teste de resistência de Sabedoria ou desaparecerá, sendo lançada para outro ponto no tempo e fazendo com que o ataque erre ou a magia seja desperdiçada. No início do próximo turno dela, o alvo reaparece onde estava ou no espaço desocupado mais próximo. O alvo não se lembra de você conjurar a magia ou de ter sido afetado por ela.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 6º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 5º. Todos os alvos devem estar a até 9 metros uns dos outros.", "en": "You target the triggering creature, which must succeed on a Wisdom saving throw or vanish, being thrown to another point in time and causing the attack to miss or the spell to be wasted. At the start of its next turn, the target reappears where it was or in the closest unoccupied space. The target doesn’t remember you casting the spell or being affected by it.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you can target one additional creature for each slot level above 5th. All targets must be within 30 feet of each other."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "gravityFissure", "name": {"pt": "Fissura Gravitacional", "en": "Gravity Fissure"}, "level": 6, "school": "evocation", "classes": ["wizard"], "castingTime": "Action", "range": "Self (100-foot line)", "components": "V, S, M (a fistful of iron filings)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você manifesta uma fenda de energia gravitacional em uma Linha originada em você que tem 30 metros de comprimento e 1,5 metro de largura. Cada criatura nessa linha deve fazer um teste de resistência de Constituição, sofrendo 8d8 de dano de Força em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n\nCada criatura a até 3 metros da linha, mas fora dela, deve ser bem-sucedida em um teste de resistência de Constituição ou sofrerá 8d8 de dano de Força e será puxada em direção à linha até que a criatura esteja em sua área.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 7º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 6º.", "en": "You manifest a ravine of gravitational energy in a line originating from you that is 100 feet long and 5 feet wide. Each creature in that line must make a Constitution saving throw, taking 8d8 force damage on a failed save, or half as much damage on a successful one.\n\nEach creature within 10 feet of the line but not in it must succeed on a Constitution saving throw or take 8d8 force damage and be pulled toward the line until the creature is in its area.\n\nAt Higher Levels. When you cast this spell using a spell slot of 7th level or higher, the damage increases by 1d8 for each slot level above 6th."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "tetherEssence", "name": {"pt": "Vincular Essência", "en": "Tether Essence"}, "level": 7, "school": "necromancy", "classes": ["wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (a spool of platinum cord worth at least 250 gp, which the spell consumes)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Duas criaturas que você possa ver dentro do alcance devem fazer uma salvaguarda de Constituição, com desvantagem se estiverem a até 9 metros uma da outra. Qualquer uma das criaturas pode falhar voluntariamente na salvaguarda. Se qualquer uma das salvaguardas for bem-sucedida, a magia não tem efeito. Se ambas as salvaguardas falharem, as criaturas ficam magicamente vinculadas pela duração, independentemente da distância entre elas. Quando dano for causado a uma delas, o mesmo dano é causado à outra. Se Pontos de Vida forem restaurados a uma delas, a mesma quantidade de Pontos de Vida é restaurada à outra. Se qualquer uma das criaturas vinculadas for reduzida a 0 Pontos de Vida, a magia termina em ambas. Se a magia for encerrada em uma criatura, encerra-se em ambas.", "en": "Two creatures you can see within range must make a Constitution saving throw, with disadvantage if they are within 30 feet of each other. Either creature can willingly fail the save. If either save succeeds, the spell has no effect. If both saves fail, the creatures are magically linked for the duration, regardless of the distance between them. When damage is dealt to one of them, the same damage is dealt to the other one. If hit points are restored to one of them, the same number of hit points are restored to the other one. If either of the tethered creatures is reduced to 0 hit points, the spell ends on both. If the spell ends on one creature, it ends on both."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "darkStar", "name": {"pt": "Estrela Negra", "en": "Dark Star"}, "level": 8, "school": "evocation", "classes": ["wizard"], "castingTime": "Action", "range": "150 feet", "components": "V, S, M (a shard of onyx and a drop of the caster’s blood, both of which the spell consumes)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Esta magia cria uma esfera centrada em um ponto que você escolher dentro do alcance. A esfera pode ter um raio de até 12 metros. A área dentro dessa esfera fica repleta de escuridão mágica e de uma esmagadora força gravitacional.\n\nPela duração, a área da magia é terreno difícil. Uma criatura com visão no escuro não pode enxergar através da escuridão mágica, e luz não mágica não pode iluminá-la. Nenhum som pode ser criado dentro ou atravessar a área. Qualquer criatura ou objeto inteiramente dentro da esfera é imune a dano trovejante, e criaturas ficam surdas enquanto estiverem inteiramente dentro dela. Conjurar uma magia que inclua um componente verbal é impossível ali.\n\nQualquer criatura que entrar na área da magia pela primeira vez em um turno ou começar seu turno ali deve fazer uma salvaguarda de Constituição. A criatura sofre 8d10 de dano de força em uma falha na salvaguarda, ou metade desse dano em um sucesso. Uma criatura reduzida a 0 Pontos de Vida por este dano é desintegrada. Uma criatura desintegrada e tudo o que ela estiver vestindo e carregando, exceto itens mágicos, são reduzidos a uma pilha de pó cinzento fino.", "en": "This spell creates a sphere centered on a point you choose within range. The sphere can have a radius of up to 40 feet. The area within this sphere is filled with magical darkness and crushing gravitational force.\n\nFor the duration, the spell’s area is difficult terrain. A creature with darkvision can’t see through the magical darkness, and nonmagical light can’t illuminate it. No sound can be created within or pass through the area. Any creature or object entirely inside the sphere is immune to thunder damage, and creatures are deafened while entirely inside it. Casting a spell that includes a verbal component is impossible there.\n\nAny creature that enters the spell’s area for the first time on a turn or starts its turn there must make a Constitution saving throw. The creature takes 8d10 force damage on a failed save, or half as much damage on a successful one. A creature reduced to 0 hit points by this damage is disintegrated. A disintegrated creature and everything it is wearing and carrying, except magic items, are reduced to a pile of fine gray dust."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "realityBreak", "name": {"pt": "Ruptura da Realidade", "en": "Reality Break"}, "level": 8, "school": "conjuration", "classes": ["wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (a crystal prism)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você estilhaça as barreiras entre realidades e linhas temporais, lançando uma criatura em tumulto e loucura. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou não poderá realizar reações até a magia acabar. O alvo afetado também deve rolar um d10 no início de cada um dos turnos dele; o número rolado determina o que acontece com o alvo, conforme mostrado na tabela Efeitos da Ruptura da Realidade.\n\nNo final de cada um dos turnos dele, o alvo afetado pode repetir a salvaguarda de Sabedoria, encerrando a magia sobre si mesmo em caso de sucesso.\n\nd10 | Efeito\n1-2 | Visão do Reino Distante. O alvo sofre 6d12 de dano psíquico e fica atordoado até o final do turno.\n3-5 | Fenda Dilacerante. O alvo deve fazer uma salvaguarda de Destreza, sofrendo 8d12 de dano de força em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n6-8 | Buraco de Minhoca. O alvo é teletransportado, junto com tudo o que estiver vestindo e carregando, até 9 metros para um espaço desocupado à sua escolha que você possa ver. O alvo também sofre 10d12 de dano de força e é derrubado no chão.\n9-10 | Frio do Vácuo Sombrio. O alvo sofre 10d12 de dano de frio e fica cego até o final do turno.", "en": "You shatter the barriers between realities and timelines, thrusting a creature into turmoil and madness. The target must succeed on a Wisdom saving throw, or it can’t take reactions until the spell ends. The affected target must also roll a d10 at the start of each of its turns; the number rolled determines what happens to the target, as shown on the Reality Break Effects table.\n\nAt the end of each of its turns, the affected target can repeat the Wisdom saving throw, ending the spell on itself on a success.\n\nd10 | Effect\n1-2 | Vision of the Far Realm. The target takes 6d12 psychic damage, and it is stunned until the end of the turn.\n3-5 | Rending Rift. The target must make a Dexterity saving throw, taking 8d12 force damage on a failed save, or half as much damage on a successful one.\n6-8 | Wormhole. The target is teleported, along with everything it is wearing and carrying, up to 30 feet to an unoccupied space of your choice that you can see. The target also takes 10d12 force damage and is knocked prone.\n9-10 | Chill of the Dark Void. The target takes 10d12 cold damage, and it is blinded until the end of the turn."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "ravenousVoid", "name": {"pt": "Vazio Voraz", "en": "Ravenous Void"}, "level": 9, "school": "evocation", "classes": ["wizard"], "castingTime": "Action", "range": "1,000 feet", "components": "V, S, M (a small, nine-pointed star made of iron)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você cria uma esfera com raio de 6 metros de força gravitacional destruidora centrada em um ponto que possa ver dentro do alcance. Pela duração da magia, a esfera e qualquer espaço a até 30 metros dela são terreno difícil, e objetos não mágicos totalmente dentro da esfera são destruídos se não estiverem sendo vestidos ou carregados.\n\nQuando a esfera surge e no início de cada um dos seus turnos até a magia acabar, objetos soltos a até 30 metros da esfera são puxados em direção ao centro da esfera, terminando em um espaço desocupado o mais próximo possível do centro.\n\nUma criatura que iniciar seu turno a até 30 metros da esfera deve ser bem-sucedida em uma salvaguarda de Força ou será puxada em linha reta em direção ao centro da esfera, terminando em um espaço desocupado o mais próximo possível do centro. Uma criatura que entrar na esfera pela primeira vez em um turno ou iniciar seu turno ali sofre 5d10 de dano de força e fica impedida até que não esteja mais na esfera. Se a esfera estiver no ar, a criatura impedida flutua dentro da esfera. Uma criatura pode usar sua ação para realizar um teste de Força contra a CD de salvaguarda de sua magia, encerrando esta condição de impedido em si mesma ou em outra criatura na esfera que ela possa alcançar. Uma criatura reduzida a 0 Pontos de Vida por esta magia é aniquilada, juntamente com quaisquer itens não mágicos que esteja vestindo ou carregando.", "en": "You create a 20-foot-radius sphere of destructive gravitational force centered on a point you can see within range. For the spell’s duration, the sphere and any space within 100 feet of it are difficult terrain, and nonmagical objects fully inside the sphere are destroyed if they aren’t being worn or carried.\n\nWhen the sphere appears and at the start of each of your turns until the spell ends, unsecured objects within 100 feet of the sphere are pulled toward the sphere’s center, ending in an unoccupied space as close to the center as possible.\n\nA creature that starts its turn within 100 feet of the sphere must succeed on a Strength saving throw or be pulled straight toward the sphere’s center, ending in an unoccupied space as close to the center as possible. A creature that enters the sphere for the first time on a turn or starts its turn there takes 5d10 force damage and is restrained until it is no longer in the sphere. If\nthe sphere is in the air, the restrained creature hovers inside the sphere. A creature can use its action to make a Strength check against your spell save DC, ending this restrained condition on itself or another creature in the sphere that it can reach. A creature reduced to 0 hit points by this spell is annihilated, along with any nonmagical items it is wearing or carrying."}, "rulesVersion": "2024", "source": "EGW"},
  {"id": "timeRavage", "name": {"pt": "Devastação Temporal", "en": "Time Ravage"}, "level": 9, "school": "necromancy", "classes": ["wizard"], "castingTime": "Action", "range": "90 feet", "components": "V, S, M (an hourglass filled with diamond dust worth at least 5,000gp, which the spell consumes.)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você mira em uma criatura que possa ver dentro do alcance, submetendo a forma física dela à devastação do envelhecimento rápido. O alvo deve fazer uma salvaguarda de Constituição, sofrendo 10d12 de dano necrótico em uma salvaguarda com falha, ou metade desse dano em um sucesso. Se a salvaguarda falhar, o alvo também envelhece a ponto de restar-lhe apenas 30 dias de vida antes de morrer de velhice. Neste estado envelhecido, o alvo tem desvantagem em jogadas de ataque, testes de habilidade e salvaguardas, e seu deslocamento de caminhada é reduzido pela metade. Apenas a magia desejo ou restauração maior conjurada com um espaço de magia de 9º círculo podem encerrar esses efeitos e restaurar o alvo à sua idade anterior.", "en": "You target a creature you can see within range, putting its physical form through the devastation of rapid aging. The target must make a Constitution saving throw, taking 10dl2 necrotic damage on a failed save, or half as much damage on a successful one. If the save fails, the target also ages to the point where it has only 30 days left before it dies of old age. In this aged state, the target has disadvantage on attack rolls, ability checks, and saving throws, and its walking speed is halved. Only the wish spell or the greater restoration cast with a 9th-level spell slot can end these effects and restore the target to its previous age."}, "rulesVersion": "2024", "source": "EGW"},
  // FTD
  {"id": "nathairsMischief", "name": {"pt": "Travessura de Nathair", "en": "Nathair's Mischief"}, "level": 2, "school": "illusion", "classes": ["bard", "sorcerer", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "S, M (a piece of crust from an apple pie)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você preenche um Cubo de 6 metros que possa ver dentro do alcance com magia feérica e dracônica. Role na tabela Surto Travesso para determinar o efeito mágico produzido e role novamente no início de cada um dos seus turnos até a magia terminar. Você pode mover o cubo em até 3 metros antes de rolar.\n\nSurto Travesso\n1: O cheiro de torta de maçã preenche o ar, e cada criatura no cubo deve ser bem-sucedida em um teste de resistência de Sabedoria ou ficará enfeitiçada por você até o início do seu próximo turno.\n\n2: Buquês de flores surgem por toda parte, e cada criatura no cubo deve ser bem-sucedida em um teste de resistência de Destreza ou ficará cega até o início do seu próximo turno conforme as flores espirram água no rosto dela.\n\n3: Cada criatura no cubo deve ser bem-sucedida em um teste de resistência de Sabedoria ou começará a dar risadinhas até o início do seu próximo turno. Uma criatura dando risadinhas fica incapacitada e gasta todo o seu movimento para se mover em uma direção aleatória.\n\n4: Gotas de melaço pairam no cubo, tornando-o terreno difícil até o início do seu próximo turno.", "en": "You fill a 20-foot cube you can see within range with fey and draconic magic. Roll on the Mischievous Surge table to determine the magical effect produced, and roll again at the start of each of your turns until the spell ends. You can move the cube up to 10 feet before you roll.\n\nMischievous Surge\n1: The smell of apple pie fills the air, and each creature in the cube must succeed on a Wisdom saving throw or become charmed by you until the start of your next turn.\n\n2: Bouquets of flowers appear all around, and each creature in the cube must succeed on a Dexterity saving throw or be blinded until the start of your next turn as the flowers spray water in their faces.\n\n3: Each creature in the cube must succeed on a Wisdom saving throw or begin giggling until the start of your next turn. A giggling creature is incapacitated and uses all its movement to move in a random direction.\n\n4: Drops of molasses hover in the cube, making it difficult terrain until the start of your next turn."}, "rulesVersion": "2024", "source": "FTD"},
  {"id": "rimesBindingIce", "name": {"pt": "Gelo Aprisionador de Rime", "en": "Rime's Binding Ice"}, "level": 2, "school": "evocation", "classes": ["sorcerer", "wizard"], "castingTime": "Action", "range": "Self (30-foot cone)", "components": "S, M (a vial of meltwater)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Uma explosão de energia gélida emana de você em um Cone de 9 metros. Cada criatura nessa área deve fazer um teste de resistência de Constituição. Em uma falha na salvaguarda, uma criatura sofre 3d8 de dano de Frio e fica impedida por formações de gelo por 1 minuto, ou até que ela ou outra criatura ao alcance use uma ação para quebrar o gelo. Uma criatura impedida pelo gelo tem seu Deslocamento reduzido a 0. Em um sucesso na salvaguarda, uma criatura sofre metade desse dano e não fica impedida pelo gelo.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, aumente o dano de Frio em 1d8 para cada círculo do espaço acima do 2º.", "en": "A burst of cold energy emanates from you in a 30-foot cone. Each creature in that area must make a Constitution saving throw. On a failed save, a creature takes 3d8 cold damage and is hindered by ice formations for 1 minute, or until it or another creature within reach of it uses an action to break away the ice. A creature hindered by ice has its speed reduced to 0. On a successful save, a creature takes half as much damage and isn’t hindered by ice.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, increase the cold damage by 1d8 for each slot level above 2nd."}, "rulesVersion": "2024", "source": "FTD"},
  {"id": "ashardalonsStride", "name": {"pt": "Passada de Ashardalon", "en": "Ashardalon's Stride"}, "level": 3, "school": "transmutation", "classes": ["artificer", "ranger", "sorcerer", "wizard"], "castingTime": "Bonus Action", "range": "Self", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "As chamas revoltas de um dragão irrompem sob seus passos, concedendo a você velocidade explosiva. Pela duração, seu Deslocamento aumenta em 6 metros e se mover não provoca ataques de oportunidade.\n\nQuando você se move a até 1,5 metro de uma criatura ou de um objeto que não esteja sendo vestido ou carregado, ele sofre 1d6 de dano de Fogo do seu rastro de calor. Uma criatura ou objeto pode sofrer esse dano apenas uma vez durante um turno.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, aumente seu Deslocamento em 1,5 metro para cada círculo do espaço acima do 3º. A magia causa 1d6 de dano de Fogo adicional para cada círculo do espaço acima do 3º.", "en": "The billowing flames of a dragon blast from your feet, granting you explosive speed. For the duration, your speed increases by 20 feet and moving doesn’t provoke opportunity attacks.\n\nWhen you move within 5 feet of a creature or an object that isn’t being worn or carried, it takes 1d6 fire damage from your trail of heat. A creature or object can take this damage only once during a turn.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, increase your speed by 5 feet for each spell slot level above 3rd. The spell deals an additional 1d6 fire damage for each slot level above 3rd."}, "rulesVersion": "2024", "source": "FTD"},
  {"id": "raulothimsPsychicLance", "name": {"pt": "Lança Psíquica de Raulothim", "en": "Raulothim's Psychic Lance"}, "level": 4, "school": "enchantment", "classes": ["bard", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "120 feet", "components": "V", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você dispara uma lança reluzente de poder psíquico da sua testa contra uma criatura que possa ver dentro do alcance. Alternativamente, você pode pronunciar o nome de uma criatura. Se o alvo nomeado estiver dentro do alcance, ele se torna o alvo da magia mesmo que você não possa vê-lo. Se o alvo nomeado não estiver dentro do alcance, a lança se dissipa sem efeito.\n\nO alvo deve fazer um teste de resistência de Inteligência. Em uma falha na salvaguarda, o alvo sofre 7d6 de dano Psíquico e fica incapacitado até o início do seu próximo turno. Em um sucesso na salvaguarda, a criatura sofre metade desse dano e não fica incapacitada.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 5º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 4º.", "en": "You unleash a shimmering lance of psychic power from your forehead at a creature that you can see within range. Alternatively, you can utter a creature’s name. If the named target is within range, it becomes the spell’s target even if you can’t see it. If the named target isn’t within range, the lance dissipates without effect.\n\nThe target must make an Intelligence saving throw. On a failed save, the target takes 7d6 psychic damage and is incapacitated until the start of your next turn. On a successful save, the creature takes half as much damage and isn’t incapacitated.\n\nAt Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the damage increases by 1d6 for each slot level above 4th."}, "rulesVersion": "2024", "source": "FTD"},
  {"id": "summonDraconicSpirit", "name": {"pt": "Invocar Espírito Dracônico", "en": "Summon Draconic Spirit"}, "level": 5, "school": "conjuration", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (an object with the image of a dragon engraved on it, worth at least 500gp)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Nome: Invocar Espírito Dracônico\n\nTipo: Magia\n\nFonte: Fizban’s Treasury of Dragons\n\nAurora ID: ID_WOTC_FTOD_SPELL_SUMMON_DRACONIC_SPIRIT\n\nSuporta: Druida, Feiticeiro, Mago\n\nDefinições:\nnível: 5\nescola: Conjuração\ntempo: 1 ação\nduração: Concentração, até 1 hora\nalcance: 18 metros\ntemComponenteVerbal: verdadeiro\ntemComponenteSomatico: verdadeiro\ntemComponenteMaterial: verdadeiro\ncomponenteMaterial: um objeto com a imagem de um dragão gravada nele, que valha pelo menos 500 po\néConcentração: verdadeiro\néRitual: falso\n\nDescrição:\nVocê invoca um espírito dracônico. Ele se manifesta em um espaço desocupado que você possa ver dentro do alcance. Essa forma corpórea usa o bloco de estatísticas do Espírito Dracônico. Quando conjurar esta magia, escolha uma família de dragão: cromático, metálico ou de gema. A criatura se assemelha a um dragão da família escolhida, o que determina certas características em seu bloco de estatísticas. A criatura desaparece quando cai a 0 Pontos de Vida ou quando a magia termina.\n\nA criatura é uma aliada para você e seus companheiros. Em combate, a criatura compartilha a sua contagem de iniciativa, mas realiza o turno dela imediatamente após o seu. Ela obedece aos seus comandos verbais (nenhuma ação exigida de você). Se você não der nenhum comando, ela realiza a ação de Esquiva e usa seu movimento para evitar o perigo.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 6º círculo ou superior, use o círculo superior onde o círculo da magia aparece no bloco de estatísticas.", "en": "Name: Summon Draconic Spirit\n\nType: Spell\n\nSource: Fizban’s Treasury of Dragons\n\nAurora ID: ID_WOTC_FTOD_SPELL_SUMMON_DRACONIC_SPIRIT\n\nSupports: Druid, Sorcerer, Wizard\n\nSetters:\nlevel: 5\nschool: Conjuration\ntime: 1 action\nduration: Concentration, up to 1 hour\nrange: 60 feet\nhasVerbalComponent: true\nhasSomaticComponent: true\nhasMaterialComponent: true\nmaterialComponent: an object with the image of a dragon engraved on it, worth at least 500 gp\nisConcentration: true\nisRitual: false\n\nDescription:\nYou call forth a draconic spirit. It manifests in an unoccupied space that you can see within range. This corporeal form uses the Draconic Spirit stat block. When you cast this spell, choose a family of dragon: chromatic, gem, or metallic. The creature resembles a dragon of the chosen family, which determines certain traits in its stat block. The creature disappears when it drops to 0 hit points or when the spell ends.\n\nThe creature is an ally to you and your companions. In combat, the creature shares your initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don’t issue any, it takes the Dodge action and uses its move to avoid danger.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, use the higher level wherever the spell’s level appears in the stat block."}, "rulesVersion": "2024", "source": "FTD"},
  {"id": "fizbansPlatinumShield", "name": {"pt": "Escudo de Platina de Fizban", "en": "Fizban's Platinum Shield"}, "level": 6, "school": "abjuration", "classes": ["sorcerer", "wizard"], "castingTime": "Bonus Action", "range": "60 feet", "components": "V, S, M (a platinum-plated dragon scale, worth at least 500 gp)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você cria um campo de luz prateada que envolve uma criatura à sua escolha dentro do alcance (você pode escolher a si mesmo). O campo emite penumbra a até 1,5 metro. Enquanto estiver envolvida pelo campo, uma criatura ganha os seguintes benefícios:\n\nCobertura. A criatura tem meia cobertura.\n\nResistência a Dano. A criatura tem resistência a dano Ácido, de Frio, de Fogo, Elétrico e de Veneno.\n\nEvasão. Se a criatura for submetida a um efeito que permita fazer um teste de resistência de Destreza para sofrer apenas metade do dano, a criatura em vez disso não sofre nenhum dano se for bem-sucedida na salvaguarda, e apenas metade do dano se falhar.\n\nCom uma ação bônus em turnos subsequentes, você pode mover o campo para outra criatura a até 18 metros do campo.", "en": "You create a field of silvery light that surrounds a creature of your choice within range (you can choose yourself). The field sheds dim light out to 5 feet. While surrounded by the field, a creature gains the following benefits:\n\nCover. The creature has half cover.\n\nDamage Resistance. The creature has resistance to acid, cold, fire, lightning, and poison damage.\n\nEvasion. If the creature is subjected to an effect that allows it to make a Dexterity saving throw to take only half damage, the creature instead takes no damage if it succeeds on the saving throw, and only half damage if it fails.\n\nAs a bonus action on subsequent turns, you can move the field to another creature within 60 feet of the field."}, "rulesVersion": "2024", "source": "FTD"},
  {"id": "draconicTransformation", "name": {"pt": "Transformação Dracônica", "en": "Draconic Transformation"}, "level": 7, "school": "transmutation", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Bonus Action", "range": "Self", "components": "V, S, M (a statuette of a dragon, worth at least 500 gp)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Com um rugido, você recorre à magia dos dragões para transformar a si mesmo, assumindo feições dracônicas. Você ganha os seguintes benefícios até a magia acabar:\n\nPercepção às Cegas. Você tem percepção às cegas com alcance de 9 metros. Dentro desse alcance, você pode efetivamente enxergar qualquer coisa que não esteja sob cobertura total, mesmo se estiver cego ou na escuridão. Além disso, você pode ver uma criatura invisível, a menos que ela se esconda de você com sucesso.\n\nArma de Sopro. Quando você conjura esta magia, e como uma ação bônus em turnos subsequentes pela duração, você pode exalar energia cintilante em um cone de 18 metros. Cada criatura naquela área deve fazer uma salvaguarda de Destreza, sofrendo 6d8 de dano de força em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n\nAsas. Asas incorpóreas brotam de suas costas, concedendo a você um deslocamento de voo de 18 metros.", "en": "With a roar, you draw on the magic of dragons to transform yourself, taking on draconic features. You gain the following benefits until the spell ends:\n\nBlindsight. You have blindsight with a range of 30 feet. Within that range, you can effectively see anything that isn’t behind total cover, even if you’re blinded or in darkness. Moreover, you can see an invisible creature, unless the creature successfully hides from you.\n\nBreath Weapon. When you cast this spell, and as a bonus action on subsequent turns for the duration, you can exhale shimmering energy in a 60-foot cone. Each creature in that area must make a Dexterity saving throw, taking 6d8 force damage on a failed save, or half as much damage on a successful one.\n\nWings. Incorporeal wings sprout from your back, giving you a flying speed of 60 feet."}, "rulesVersion": "2024", "source": "FTD"},
  // GGR
  {"id": "encodeThoughts", "name": {"pt": "Codificar Pensamentos", "en": "Encode Thoughts"}, "level": 0, "school": "enchantment", "classes": [], "castingTime": "Action", "range": "Self", "components": "S", "duration": "Up to 8 hours", "ritual": false, "concentration": false, "desc": {"pt": "Colocando um dedo na cabeça, você extrai uma memória, uma ideia ou uma mensagem de sua mente e a transforma em um fio tangível de energia brilhante chamado fio de pensamento, que persiste pela duração ou até você conjurar esta magia novamente. O fio de pensamento surge em um espaço desocupado a até 1,5 metro de você como um objeto Miúdo, sem peso e semissólido que pode ser segurado e carregado como uma fita. Caso contrário, ele permanece estacionário.\n\nSe você conjurar esta magia enquanto estiver se concentrando em uma magia ou habilidade que permita ler ou manipular os pensamentos de outras criaturas (como detectar pensamentos ou modificar memória), você pode transformar os pensamentos ou memórias que ler, em vez dos seus próprios, em um fio de pensamento.\n\nConjurar esta magia enquanto segura um fio de pensamento permite receber instantaneamente qualquer memória, ideia ou mensagem que o fio de pensamento contenha. (Conjurar detectar pensamentos no fio produz o mesmo efeito.)", "en": "Putting a finger to your head, you pull a memory, an idea, or a message from your mind and transform it into a tangible string of glowing energy called a thought strand, which persists for the duration or until you cast this spell again. The thought strand appears in an unoccupied space within 5 feet of you as a Tiny, weightless, semisolid object that can be held and carried like a ribbon. It is otherwise stationary.\n\nIf you cast this spell while concentrating on a spell or an ability that allows you to read or manipulate the thoughts of others (such as detect thoughts or modify memory), you can transform the thoughts or memories you read, rather than your own, into a thought strand.\n\nCasting this spell while holding a thought strand allows you to instantly receive whatever memory, idea, or message the thought strand contains. (Casting detect thoughts on the strand has the same effect.)"}, "rulesVersion": "2024", "source": "GGR"},
  // IDRotF
  {"id": "frostFingers", "name": {"pt": "Dedos Gélidos", "en": "Frost Fingers"}, "level": 1, "school": "evocation", "classes": ["wizard"], "castingTime": "Action", "range": "Self (15-foot cone)", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Um frio congelante irrompe da ponta dos seus dedos em um cone de 4,5 metros. Cada criatura nessa área deve fazer uma salvaguarda de Constituição, sofrendo 2d8 de dano de frio se falhar na salvaguarda, ou metade desse dano em um sucesso.\n\nO frio congela líquidos não mágicos na área que não estejam sendo vestidos ou carregados.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 1º.", "en": "Freezing cold blasts from your fingertips in a 15-foot cone. Each creature in that area must make a Constitution saving throw, taking 2d8 cold damage on a failed save, or half as much damage on a successful one.\n\nThe cold freezes nonmagical liquids in the area that aren’t being worn or carried.\n\nAt higher levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."}, "rulesVersion": "2024", "source": "IDRotF"},
  {"id": "createMagen", "name": {"pt": "Criar Magen", "en": "Create Magen"}, "level": 7, "school": "transmutation", "classes": ["wizard"], "castingTime": "1 hour", "range": "Touch", "components": "V, S, M (a vial of quicksilver worth 500 gp and a life-sized human doll, both of which the spell consumes, and an intricate crystal rod worth at least 1,500 gp that is not consumed)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Nome: Criar Magen\n\nTipo: Magia\n\nFonte: Icewind Dale: Rime of the Frostmaiden\n\nID Aurora: ID_WOTC_IDROTF_SPELL_CREATE_MAGEN\n\nSuporta: Mago\n\nDefinições:\nnível: 7\nescola: Transmutação\ntempo: 1 hora\nalcance: Toque\nduração: Instantânea\npossuiComponenteVerbal: true\npossuiComponenteSomatico: true\npossuiComponenteMaterial: true\ncomponenteMaterial: um frasco de mercúrio no valor de 500 po e um boneco humano em tamanho real, ambos consumidos pela magia, e uma haste intrincada de cristal no valor de pelo menos 1.500 po que não é consumida\néConcentração: false\néRitual: false\n\nDescrição:\nEnquanto conjura a magia, você coloca um frasco de mercúrio no peito de um boneco humano em tamanho real recheado com cinzas ou poeira. Você então costura o boneco e pinga seu sangue sobre ele. Ao término da conjuração, você toca o boneco com uma haste de cristal, transformando-o em um magen vestido com as roupas que o boneco usava. O tipo de magen é escolhido por você durante a conjuração da magia. Consulte o apêndice C para os diferentes tipos de magen e suas estatísticas.\nQuando o magen surge, seu máximo de Pontos de Vida diminui em uma quantidade igual ao nível de desafio do magen (redução mínima de 1). Apenas uma magia desejo pode desfazer essa redução em seu máximo de Pontos de Vida.\nQualquer magen que você criar com esta magia obedece aos seus comandos sem questionar.", "en": "Name: Create Magen\n\nType: Spell\n\nSource: Icewind Dale: Rime of the Frostmaiden\n\nAurora ID: ID_WOTC_IDROTF_SPELL_CREATE_MAGEN\n\nSupports: Wizard\n\nSetters:\nlevel: 7\nschool: Transmutation\ntime: 1 hour\nrange: Touch\nduration: Instantaneous\nhasVerbalComponent: true\nhasSomaticComponent: true\nhasMaterialComponent: true\nmaterialComponent: a vial of quicksilver worth 500 gp and a life-sized human doll, both of which the spell consumes, and an intricate crystal rod worth at least 1,500 gp that is not consumed\nisConcentration: false\nisRitual: false\n\nDescription:\nWhile casting the spell, you place a vial of quicksilver in the chest of a life-sized human doll stuffed with ash or dust. You then stitch up the doll and drip your blood on it. At the end of the casting, you tap the doll with a crystal rod, transforming it into a magen clothed in whatever the doll was wearing. The type of magen is chosen by you during the casting of the spell. See appendix C for different kinds of magen and their statistics.\nWhen the magen appears, your hit point maximum decreases by an amount equal to the magen's challenge rating (minimum reduction of 1). Only a wish spell can undo this reduction to your hit point maximum.\nAny magen you create with this spell obeys your commands without question."}, "rulesVersion": "2024", "source": "IDRotF"},
  // LLK
  {"id": "flockOfFamiliars", "name": {"pt": "Bando de Familiares", "en": "Flock of Familiars"}, "level": 2, "school": "conjuration", "classes": ["warlock", "wizard"], "castingTime": "1 minute", "range": "Touch", "components": "V, S", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você conjura temporariamente três familiares — espíritos que assumem formas animais à sua escolha. Cada familiar utiliza as mesmas regras e opções para um familiar conjurado pela magia encontrar familiar. Todos os familiares conjurados por esta magia devem ser do mesmo tipo de criatura (celestiais, fadas ou corruptores; sua escolha). Se você já possuir um familiar conjurado pela magia encontrar familiar ou por meios semelhantes, então um familiar a menos é conjurado por esta magia. Familiares invocados por esta magia podem se comunicar telepaticamente com você e compartilhar seus sentidos visuais ou auditivos enquanto estiverem a até 1,5 quilômetro de você. Quando você conjura uma magia com alcance de toque, um dos familiares conjurados por esta magia pode desferir a magia normalmente. No entanto, você pode conjurar uma magia de toque através de apenas um familiar por turno.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, você conjura um familiar adicional para cada círculo do espaço acima do 2º.", "en": "You temporarily summon three familiars—spirits that take animal forms of your choice. Each familiar uses the same rules and options for a familiar conjured by the find familiar spell. All the familiars conjured by this spell must be the same type of creature (celestials, fey, or fiends; your choice). If you already have a familiar conjured by the find familiar spell or similar means, then one fewer familiars are conjured by this spell. Familiars summoned by this spell can telepathically communicate with you and share their visual or auditory senses while they are within 1 mile of you. When you cast a spell with a range of touch, one of the familiars conjured by this spell can deliver the spell, as normal. However, you can cast a touch spell through only one familiar per turn.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you conjure an additional familiar for each slot level above 2nd."}, "rulesVersion": "2024", "source": "LLK"},
  {"id": "galdersTower", "name": {"pt": "Torre de Galder", "en": "Galder's Tower"}, "level": 3, "school": "conjuration", "classes": ["wizard"], "castingTime": "10 minutes", "range": "30 feet", "components": "V, S, M (a fragment of stone, wood, or other building material)", "duration": "24 hours", "ritual": false, "concentration": false, "desc": {"pt": "Você conjura uma torre de dois andares feita de pedra, madeira ou materiais similares adequadamente resistentes. A torre pode ter formato redondo ou quadrado. Cada nível da torre tem 3 metros de altura e possui uma área de até 9 metros quadrados. O acesso entre os níveis consiste em uma escada simples e alçapão. Cada nível assume uma das seguintes formas, escolhida por você quando conjura a magia:\n\n• Um quarto com cama, cadeiras, baú e lareira mágica\na torre pode ter formato redondo ou quadrado. Cada nível da torre tem 3 metros de altura e possui uma área de até 9 metros quadrados. O acesso entre os níveis consiste em uma escada simples e alçapão. Cada nível assume uma das seguintes formas, escolhida por você quando conjura a magia:\n\n• Um quarto com cama, cadeiras, baú e lareira mágica\n\n• Um escritório com escrivaninhas, livros, estantes de livros, pergaminhos, tinta e canetas de pena\n\n• Uma sala de jantar com mesa, cadeiras, lareira mágica, recipientes e utensílios de cozinha\n\n• Uma sala de estar com sofás, poltronas, mesas laterais e apoios para os membros inferiores\n\n• Um lavabo com sanitários, banheiras, um braseiro mágico e bancos de sauna\n\n• Um observatório com telescópio e mapas do céu noturno\n\n• Um cômodo vazio, não mobiliado\n\nO interior da torre é quente e seco, independentemente das condições externas. Qualquer equipamento ou mobília conjurada com a torre dissipa-se em fumaça se for removida dela. Ao final da duração da magia, todas as criaturas e objetos dentro da torre que não foram criados pela magia aparecem em segurança do lado de fora no chão, e todos os vestígios da torre e de suas mobílias desaparecem.\n\nVocê pode conjurar esta magia novamente enquanto ela estiver ativa para manter a existência da torre por mais 24 horas. Você pode criar uma torre permanente conjurando esta magia no mesmo local e com a mesma configuração todos os dias durante um ano.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, a torre pode ter um andar adicional para cada círculo do espaço além do 3º.", "en": "You conjure a two-story tower made of stone, wood, or similar suitably sturdy materials. The tower can be round or square in shape. Each level of the tower is 10 feet tall and has an area of up to 100 square feet. Access between levels consists of a simple ladder and hatch. Each level takes one of the following forms, chosen by you when you cast the spell:\n\n• A bedroom with a bed, chairs, chest, and magical fireplace\ntower can be round or square in shape. Each level of the tower is 10 feet tall and has an area of up to 100 square feet. Access between levels consists of a simple ladder and hatch. Each level takes one of the following forms, chosen by you when you cast the spell:\n\n• A bedroom with a bed, chairs, chest, and magical fireplace\n\n• A study with desks, books, bookshelves, parchments, ink, and ink pens\n\n• A dining space with a table, chairs, magical fireplace, containers, and cooking utensils\n\n• A lounge with couches, armchairs, side tables and footstools\n\n• A washroom with toilets, washtubs, a magical brazier, and sauna benches\n\n• An observatory with a telescope and maps of the night sky\n\n• An unfurnished, empty room\n\nThe interior of the tower is warm and dry, regardless of conditions outside. Any equipment or furnishings conjured with the tower dissipate into smoke if removed from it. At the end of the spell's duration, all creatures and objects within the tower that were not created by the spell appear safely outside on the ground, and all traces of the tower and its furnishings disappear.\n\nYou can cast this spell again while it is active to maintain the tower's existence for another 24 hours. You can create a permanent tower by casting this spell in the same location and with the same configuration every day for one year\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the tower can have one additional story for each slot level beyond 3rd."}, "rulesVersion": "2024", "source": "LLK"},
  {"id": "galdersSpeedyCourier", "name": {"pt": "Mensageiro Veloz de Galder", "en": "Galder's Speedy Courier"}, "level": 4, "school": "conjuration", "classes": ["warlock", "wizard"], "castingTime": "Action", "range": "10 feet", "components": "V, S, M (25 gold pieces, or mineral goods of equivalent value, which the spell consumes)", "duration": "10 minutes", "ritual": false, "concentration": false, "desc": {"pt": "Você invoca um elemental do ar Pequeno em um local dentro do alcance. O elemental do ar não tem forma definida, é quase transparente, imune a todo tipo de dano e não pode interagir com outras criaturas ou objetos. Ele carrega um baú aberto e vazio cujas dimensões internas são de 1 metro de cada lado.\n\nEnquanto a magia durar, você pode depositar quantos itens couberem dentro do baú. Você pode então nomear uma criatura viva que já tenha conhecido e visto pelo menos uma vez antes, ou qualquer criatura da qual possua uma parte do corpo, mecha de cabelo, pedaço de unha ou porção similar do corpo da criatura.\nsões são de 1 metro de cada lado.\n\nEnquanto a magia durar, você pode depositar quantos itens couberem dentro do baú. Você pode então nomear uma criatura viva que já tenha conhecido e visto pelo menos uma vez antes, ou qualquer criatura da qual possua uma parte do corpo, mecha de cabelo, pedaço de unha ou porção similar do corpo da criatura.\n\nAssim que a tampa do baú for fechada, o elemental e o baú desaparecem e reaparecem adjacentes à criatura-alvo. Se a criatura-alvo estiver em outro plano, ou se for protegida contra detecção ou localização mágica, o conteúdo do baú reaparece no chão diante de você.\n\nA criatura-alvo toma ciência do conteúdo do baú antes de escolher abri-lo ou não, e sabe quanto tempo resta da duração da magia para recuperá-lo. Nenhuma outra criatura pode abrir o baú e retirar seu conteúdo. Quando a magia expira ou quando todo o conteúdo do baú é retirado, o elemental e o baú desaparecem. O elemental também desaparece se a criatura-alvo ordenar que ele retorne os itens para você. Quando o elemental desaparece, quaisquer itens não retirados do baú reaparecem no chão diante de você.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 8º círculo, você pode enviar o baú para uma criatura em um plano de existência diferente do seu.", "en": "You summon a Small air elemental to a spot within range. The air elemental is formless, nearly transparent, immune to all damage, and cannot interact with other creatures or objects. It carries an open, empty chest whose interior dimensions are 3 feet on each side.\n\nWhile the spell lasts, you can deposit as many items inside the chest as will fit. You can then name a living creature you have met and seen at least once before, or any creature for which you possess a body part, lock of hair, clipping from a nail, or similar portion of the creature's body.\nons are 3 feet on each side.\n\nWhile the spell lasts, you can deposit as many items inside the chest as will fit. You can then name a living creature you have met and seen at least once before, or any creature for which you possess a body part, lock of hair, clipping from a nail, or similar portion of the creature's body.\n\nAs soon as the lid of the chest is closed, the elemental and the chest disappear, then reappear adjacent to the target creature. If the target creature is on another plane, or if it is proofed against magical detection or location, the contents of the chest reappear on the ground at your feet.\n\nThe target creature is made aware of the chest's contents before it chooses whether or not to open it, and knows how much of the spell's duration remains in which it can retrieve them. No other creature can open the chest and retrieve its contents. When the spell expires or when all the contents of the chest have been removed, the elemental and the chest disappear. The elemental also disappears if the target creature orders it to return the items to you. When the elemental disappears, any items not taken from the chest reappear on the ground at your feet.\n\nAt Higher Levels. When you cast this spell using an 8th-level spell slot, you can send the chest to a creature on a different plane of existence from you."}, "rulesVersion": "2024", "source": "LLK"},
  // SCC
  {"id": "silveryBarbs", "name": {"pt": "Farpas Prateadas", "en": "Silvery Barbs"}, "level": 1, "school": "enchantment", "classes": ["bard", "sorcerer", "wizard"], "castingTime": "Reaction, which you take when a creature you can see within 60 feet of yourself succeeds on an attack roll, an ability check, or a saving throw", "range": "60 feet", "components": "V", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você distrai magicamente a criatura desencadeadora e transforma sua incerteza momentânea em encorajamento para outra criatura. A criatura desencadeadora deve rolar o d20 novamente e usar o menor resultado.\n\nVocê pode então escolher uma criatura diferente que você possa ver dentro do alcance (você pode escolher a si mesmo). A criatura escolhida tem vantagem na próxima jogada de ataque, teste de atributo ou salvaguarda que fizer dentro de um minuto. Uma criatura pode ser fortalecida por apenas um uso desta magia por vez.", "en": "You magically distract the triggering creature and turn its momentary uncertainty into encouragement for another creature. The triggering creature must reroll the d20 and use the lower roll.\n\nYou can then choose a different creature you can see within range (you can choose yourself). The chosen creature has advantage on the next attack roll, ability check, or saving throw it makes within one minute. A creature can be empowered by only one use of this spell at a time."}, "rulesVersion": "2024", "source": "SCC"},
  {"id": "borrowedKnowledge", "name": {"pt": "Conhecimento Emprestado", "en": "Borrowed Knowledge"}, "level": 2, "school": "divination", "classes": ["bard", "cleric", "warlock", "wizard"], "castingTime": "Action", "range": "Self", "components": "V, S, M (a book worth at least 25gp)", "duration": "1 hour", "ritual": false, "concentration": false, "desc": {"pt": "Você recorre ao conhecimento de espíritos do passado. Escolha uma perícia na qual você não tenha proficiência. Pela duração da magia, você tem proficiência na perícia escolhida. A magia termina antecipadamente se você conjurá-la de novo.", "en": "You draw on knowledge from spirits of the past. Choose one skill in which you lack proficiency. For the spell’s duration, you have proficiency in the chosen skill. The spell ends early if you cast it again."}, "rulesVersion": "2024", "source": "SCC"},
  {"id": "kineticJaunt", "name": {"pt": "Deslocamento Cinético", "en": "Kinetic Jaunt"}, "level": 2, "school": "transmutation", "classes": ["artificer", "bard", "sorcerer", "wizard"], "castingTime": "Bonus Action", "range": "Self", "components": "S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você fortalece magicamente seus movimentos com passos semelhantes a uma dança, concedendo a si mesmo os seguintes benefícios pela duração:\n\n- Seu Deslocamento de caminhada aumenta em 3 metros.\n- Você não provoca ataques de oportunidade.\n- Você pode se mover através do espaço de outra criatura, e isso não conta como terreno difícil. Se terminar seu turno no espaço de outra criatura, você é deslocado para o último espaço desocupado que ocupou e sofre 1d8 de dano de Força.", "en": "You magically empower your movement with dance-like steps, giving yourself the following benefits for the duration:\n\n- Your walking speed increases by 10 feet.\n- You don’t provoke opportunity attacks.\n- You can move through the space of another creature, and it doesn’t count as difficult terrain. If you end your turn in another creature’s space, you are shunted to the last unoccupied space you occupied, and you take 1d8 force damage."}, "rulesVersion": "2024", "source": "SCC"},
  {"id": "vortexWarp", "name": {"pt": "Dobra de Vórtice", "en": "Vortex Warp"}, "level": 2, "school": "conjuration", "classes": ["artificer", "sorcerer", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você distorce magicamente o espaço ao redor de outra criatura que possa ver dentro do alcance. O alvo deve ser bem-sucedido em um teste de resistência de Constituição (ele pode escolher falhar voluntariamente), ou o alvo é teletransportado para um espaço desocupado à sua escolha que você possa ver dentro do alcance. O espaço escolhido deve estar em uma superfície ou em um líquido que possa sustentar o alvo sem que ele precise se espremer.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o alcance da magia aumenta em 9 metros para cada círculo do espaço acima do 2º.", "en": "You magically twist space around another creature you can see within range. The target must succeed on a Constitution saving throw (it can choose to fail), or the target is teleported to an unoccupied space of your choice that you can see within range. The chosen space must be on a surface or in a liquid that can support the target without the target having to squeeze.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the range of the spell increases by 30 feet for each slot level above 2nd."}, "rulesVersion": "2024", "source": "SCC"},
  {"id": "witherAndBloom", "name": {"pt": "Murchar e Florescer", "en": "Wither and Bloom"}, "level": 2, "school": "necromancy", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (A withered vine twisted into a loop)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você invoca tanto a morte quanto a vida sobre uma Esfera com raio de 3 metros centrada em um ponto dentro do alcance. Cada criatura à sua escolha nessa área deve fazer um teste de resistência de Constituição, sofrendo 2d6 de dano Necrótico em uma falha na salvaguarda, ou metade desse dano em um sucesso. A vegetação não mágica nessa área murcha.\n\nAlém disso, uma criatura à sua escolha nessa área pode gastar e rolar um de seus Dados de Vida não gastos e recuperar uma quantidade de Pontos de Vida igual à rolagem mais o seu modificador de atributo de conjuração.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d6 para cada círculo acima do 2º, e a quantidade de Dados de Vida que podem ser gastos e adicionados à rolagem de cura aumenta em um para cada círculo acima do 2º.", "en": "You invoke both death and life upon a 10-foot radius sphere centered on a point within range. Each creature of your choice in that area much make a Constitution saving throw, taking 2d6 necrotic damage on a failed save, or half as much damage on a successful one. Nonmagical vegetation in that area withers.\n\nIn addition, one creature of your choice in that area can spend and roll one of its unspect Hit Dice and regain a number of hit points equal to the roll plus your spellcasting ability modifier.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot above 2nd, and the number of Hit Dice that can be spent and added to the healing roll increases by one for each slot above 2nd."}, "rulesVersion": "2024", "source": "SCC"},
  // SatO
  {"id": "warpSense", "name": {"pt": "Sentir Distorção", "en": "Warp Sense"}, "level": 2, "school": "divination", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "Self", "components": "V, S, M (a razorvine leaf)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Pela duração, você pressente a presença de portais, mesmo inativos, a até 9 metros de você.\n\nSe detectar um portal dessa forma, você pode usar sua ação para estudá-lo. Faça um teste de atributo CD 15 usando seu atributo de conjuração. Em um teste bem-sucedido, você descobre o plano de destino do portal e qual chave de portal ele exige, e então a magia termina. Em um teste que falhar, você não descobre nada e não pode estudar aquele portal novamente usando esta magia até conjurá-la de novo.\n\nA magia pode penetrar na maioria das barreiras, mas é bloqueada por 30 centímetros de pedra, 2,5 centímetros de metal comum, uma lâmina fina de chumbo ou 90 centímetros de madeira ou terra.", "en": "For the duration, you sense the presence of portals, even inactive ones, within 30 feet of yourself.\n\nIf you detect a portal in this way, you can use your action to study it. Make a DC 15 ability check using your spellcasting ability. On a successful check, you learn the destination plane of the portal and what portal key it requires, then the spell ends. On a failed check, you learn nothing and can’t study that portal again using this spell until you cast it again.\n\nThe spell can penetrate most barriers but is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt."}, "rulesVersion": "2024", "source": "SatO"},
  {"id": "gateSeal", "name": {"pt": "Selo de Portal", "en": "Gate Seal"}, "level": 4, "school": "abjuration", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (a broken portal key, which the spell consumes)", "duration": "24 hours", "ritual": false, "concentration": false, "desc": {"pt": "Você fortifica o tecido dos planos em um Cubo de 9 metros que possa ver dentro do alcance. Dentro dessa área, portais se fecham e não podem ser abertos pela duração. Magias e outros efeitos que permitem viagem planar ou abrem portais, como Portal ou Viagem Planar, falham se usados para entrar ou sair da área. O cubo é estacionário.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 6º círculo ou superior, a magia dura até ser dissipada.", "en": "You fortify the fabric of the planes in a 30-foot cube you can see within range. Within that area, portals close and can’t be opened for the duration. Spells and other effects that allow planar travel or open portals, such as Gate or Plane Shift, fail if used to enter or leave the area. The cube is stationary.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the spell lasts until dispelled."}, "rulesVersion": "2024", "source": "SatO"},
  // TCE
  {"id": "boomingBlade", "name": {"pt": "Lâmina Estrondosa", "en": "Booming Blade"}, "level": 0, "school": "evocation", "classes": ["artificer", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "Self (5-foot radius)", "components": "S, M (a melee weapon worth at least 1 sp)", "duration": "1 round", "ritual": false, "concentration": false, "desc": {"pt": "Você brande a arma usada na conjuração da magia e faz um ataque corpo a corpo com ela contra uma criatura a até 1,5 metro de você. Se atingir, o alvo sofre os efeitos normais do ataque com arma e então fica envolvido por energia ressonante até o início do seu próximo turno. Se o alvo se mover voluntariamente 1,5 metro ou mais antes disso, ele sofre 1d8 de dano trovejante, e a magia termina.\n\nO dano desta magia aumenta quando você alcança certos níveis. No 5º nível, o ataque corpo a corpo causa 1d8 de dano trovejante adicional ao alvo se atingir, e o dano que o alvo sofre por se mover aumenta para 2d8. Ambas as rolagens de dano aumentam em 1d8 no 11º nível (2d8 e 3d8) e novamente no 17º nível (3d8 e 4d8).", "en": "You brandish the weapon used in the spell’s cast­ing and make a melee attack with it against one creature within 5 feet of you. On a hit, the target suffers the weapon attack’s normal effects and then becomes sheathed in booming energy until the start of your next turn. If the target willingly moves 5 feet or more before then, the target takes 1d8 thunder damage, and the spell ends.\n\nThis spell’s damage increases when you reach certain levels. At 5th level, the melee attack deals an extra 1d8 thunder damage to the target on a hit, and the damage the target takes for moving increases to 2d8. Both damage rolls increase by 1d8 at 11th level (2d8 and 3d8) and again at 17th level (3d8 and 4d8)."}, "rulesVersion": "2024", "source": "TCE"},
  {"id": "greenFlameBlade", "name": {"pt": "Lâmina de Chama Verde", "en": "Green-Flame Blade"}, "level": 0, "school": "evocation", "classes": ["artificer", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "Self (5-foot radius)", "components": "S, M (a melee weapon worth at least 1 sp)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você brande a arma usada na conjuração da magia e faz um ataque corpo a corpo com ela contra uma criatura a até 1,5 metro de você. Se atingir, o alvo sofre os efeitos normais do ataque com arma, e você pode fazer um fogo esverdeado saltar do alvo para uma criatura diferente à sua escolha que você possa ver a até 1,5 metro dele. A segunda criatura sofre dano de fogo igual ao seu modificador de habilidade de conjuração.\n\nO dano desta magia aumenta quando você alcança certos níveis. No 5º nível, o ataque corpo a corpo causa 1d8 de dano de fogo adicional ao alvo em caso de acerto, e o dano de fogo à segunda criatura aumenta para 1d8 + seu modificador de habilidade de conjuração. Ambas as rolagens de dano aumentam em 1d8 no 11º nível (2d8 e 2d8) e no 17º nível (3d8 e 3d8).", "en": "You brandish the weapon used in the spell’s casting and make a melee attack with it against one crea­ture within 5 feet of you. On a hit, the target suffers the weapon attack’s normal effects, and you can cause green fire to leap from the target to a different creature of your choice that you can see within 5 feet of it. The second creature takes fire damage equal to your spellcasting ability modifier.\n\nThis spell’s damage increases when you reach certain levels. At 5th level, the melee attack deals an extra 1d8 fire damage to the target on a hit, and the fire damage to the second creature increases to 1d8 + your spellcasting ability modifier. Both damage rolls increase by 1d8 at 11th level (2d8 and 2d8) and 17th level (3d8 and 3d8)."}, "rulesVersion": "2024", "source": "TCE"},
  {"id": "lightningLure", "name": {"pt": "Atração Relampejante", "en": "Lightning Lure"}, "level": 0, "school": "evocation", "classes": ["artificer", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "Self (15-foot radius)", "components": "V", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você cria um chicote de energia elétrica que golpeia uma criatura à sua escolha que você possa ver dentro do alcance. O alvo deve ser bem-sucedido em uma salvaguarda de Força ou será puxado até 3 metros em linha reta em sua direção e sofrerá 1d8 de dano elétrico se estiver a até 1,5 metro de você.\n\nO dano desta magia aumenta em 1d8 quando você alcança o 5º nível (2d8), 11º nível (3d8) e 17º nível (4d8).", "en": "You create a lash of lightning energy that strikes at one creature of your choice that you can see within range. The target must succeed on a Strength saving throw or be pulled up to 10 feet in a straight line toward you and then take 1d8 lightning damage if it is within 5 feet of you.\n\nThis spell’s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."}, "rulesVersion": "2024", "source": "TCE"},
  {"id": "swordBurst", "name": {"pt": "Explosão de Espadas", "en": "Sword Burst"}, "level": 0, "school": "conjuration", "classes": ["artificer", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "Self (5-foot radius)", "components": "V", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você cria um círculo momentâneo de lâminas espectrais que varrem ao seu redor. Todas as outras criaturas a até 1,5 metro de você devem, cada uma, ser bem-sucedidas em uma salvaguarda de Destreza ou sofrerão 1d6 de dano de energia.\n\nO dano desta magia aumenta em 1d6 quando você alcança o 5º nível (2d6), 11º nível (3d6) e 17º nível (4d6).", "en": "You create a momentary circle of spectral blades that sweep around you. All other creatures within 5 feet of you must each succeed on a Dexterity saving throw or take 1d6 force damage.\n\nThis spell’s damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6)."}, "rulesVersion": "2024", "source": "TCE"},
  {"id": "tashasCausticBrew", "name": {"pt": "Infusão Cáustica de Tasha", "en": "Tasha's Caustic Brew"}, "level": 1, "school": "evocation", "classes": ["artificer", "sorcerer", "wizard"], "castingTime": "Action", "range": "Self (30-foot line)", "components": "V, S, M (a bit of rotten food)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Um fluxo de ácido emana de você em uma linha de 9 metros de comprimento e 1,5 metro de largura na direção que você escolher. Cada criatura na linha deve ser bem-sucedida em uma salvaguarda de Destreza ou ficará coberta de ácido pela duração da magia ou até que uma criatura use sua ação para raspar ou lavar o ácido de si mesma ou de outra criatura. Uma criatura coberta de ácido sofre 2d4 de dano ácido no início de cada um dos turnos dela.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 2d4 para cada círculo do espaço acima do 1º.", "en": "A stream of acid emanates from you in a line 30 feet long and 5 feet wide in a direction you choose. Each creature in the line must succeed on a Dexterity saving throw or be covered in acid for the spell’s duration or until a creature uses its action to scrape or wash the acid off itself or another creature. A creature covered in acid takes 2d4 acid damage at the start of each of its turns.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 2d4 for each slot level above 1st."}, "rulesVersion": "2024", "source": "TCE"},
  {"id": "tashasMindWhip", "name": {"pt": "Chicote Mental de Tasha", "en": "Tasha's Mind Whip"}, "level": 2, "school": "enchantment", "classes": ["sorcerer", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V", "duration": "1 round", "ritual": false, "concentration": false, "desc": {"pt": "Você açoita psiquicamente uma criatura que possa ver dentro do alcance. O alvo deve fazer um teste de resistência de Inteligência. Em uma falha na salvaguarda, o alvo sofre 3d6 de dano Psíquico e não pode realizar reações até o final do próximo turno dele. Além disso, no próximo turno dele, ele deve escolher se realiza um movimento, uma ação ou uma ação bônus; ele tem direito a apenas uma das três opções. Em um sucesso na salvaguarda, o alvo sofre metade do dano e não sofre nenhum dos outros efeitos da magia.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 2º. As criaturas devem estar a até 9 metros uma da outra quando você as escolher como alvo.", "en": "You psychically lash out at one creature you can see within range. The target must make an Intelligence saving throw. On a failed save, the target takes 3d6 psychic damage, and it cant take a reaction until the end of its next turn. Moreover, on its next turn, it must choose whether it gets a move, an action, or a bonus action; it gets only one of the three. On a successful save, the target takes half damage and suffers none of the spell’s other effects.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, you can target one additional creature for each slot level above 2nd. The creatures must be within 30 feet of each other when you target them."}, "rulesVersion": "2024", "source": "TCE"},
  {"id": "intellectFortress", "name": {"pt": "Fortaleza do Intelecto", "en": "Intellect Fortress"}, "level": 3, "school": "abjuration", "classes": ["artificer", "bard", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "V", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Pela duração, você ou uma criatura voluntária que possa ver dentro do alcance tem resistência a dano Psíquico, bem como vantagem em testes de resistência de Inteligência, Sabedoria e Carisma.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, você pode escolher uma criatura adicional como alvo para cada círculo do espaço acima do 3º. As criaturas devem estar a até 9 metros uma da outra quando você as escolher como alvo.", "en": "For the duration, you or one willing creature you can see within range has resistance to psychic damage, as well as advantage on Intelligence, Wisdom and Charisma saving throws.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can target one additional creature for each slot level above 3rd. The creatures must be within 30 feet of each other when you target them."}, "rulesVersion": "2024", "source": "TCE"},
  {"id": "spiritShroud", "name": {"pt": "Mortalha Espiritual", "en": "Spirit Shroud"}, "level": 3, "school": "necromancy", "classes": ["cleric", "paladin", "warlock", "wizard"], "castingTime": "Bonus Action", "range": "Self", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você invoca espíritos dos mortos, que esvoaçam ao seu redor pela duração da magia. Os espíritos são intangíveis e invulneráveis.\n\nAté a magia terminar, qualquer ataque que você fizer causa 1d8 de dano adicional quando você atingir uma criatura a até 3 metros de você. Esse dano é Radiante, Necrótico ou de Frio (à sua escolha quando conjura a magia). Qualquer criatura que sofrer esse dano não pode recuperar Pontos de Vida até o início do seu próximo turno.\n\nAlém disso, qualquer criatura à sua escolha que você possa ver que começar o turno dela a até 3 metros de você tem seu Deslocamento reduzido em 3 metros até o início do seu próximo turno.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d8 para cada dois círculos do espaço acima do 3º.", "en": "You call forth spirits of the dead, which flit around you for the spell’s duration. The spirits are intangible and invulnerable.\n\nUntil the spell ends, any attack you make deals 1d8 extra damage when you hit a creature within 10 feet of you. This damage is radiant, necrotic, or cold (your choice when you cast the spell). Any creature that takes this damage can’t regain hit points until the start of your next turn.\n\nIn addition, any creature of your choice that you can see that starts its turn within 10 feet of you has its speed reduced by 10 feet until the start of your next turn.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for every two slot levels above 3rd."}, "rulesVersion": "2024", "source": "TCE"},
  {"id": "summonShadowspawn", "name": {"pt": "Invocar Cria das Sombras", "en": "Summon Shadowspawn"}, "level": 3, "school": "conjuration", "classes": ["warlock", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V, S, M (tears inside a gem worth at least 300 gp)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Nome: Invocar Prole das Sombras\n\nTipo: Magia\n\nFonte: Tasha’s Cauldron of Everything\n\nAurora ID: ID_WOTC_TCOE_SPELL_SUMMON_SHADOWSPAWN\n\nSuporta: Bruxo, Mago\n\nDefinições:\nnível: 3\nescola: Conjuração\ntempo: 1 ação\nalcance: 27 metros\ntemComponenteVerbal: verdadeiro\ntemComponenteSomatico: verdadeiro\ntemComponenteMaterial: verdadeiro\ncomponenteMaterial: lágrimas dentro de uma gema que valha pelo menos 300 po\nduração: Concentração, até 1 hora\néConcentração: verdadeiro\n\nDescrição:\nVocê invoca um espírito sombrio. Ele se manifesta em um espaço desocupado que você possa ver dentro do alcance. Essa forma corpórea usa o bloco de estatísticas do Espírito da Sombra. Quando conjurar a magia, escolha uma emoção: Fúria, Desespero ou Medo. A criatura se assemelha a um bípede deformado marcado pela emoção escolhida, o que determina certas características em seu bloco de estatísticas. A criatura desaparece quando cai a 0 Pontos de Vida ou quando a magia termina.\n\nA criatura é uma aliada para você e seus companheiros. Em combate, a criatura compartilha a sua contagem de iniciativa, mas realiza o turno dela imediatamente após o seu. Ela obedece aos seus comandos verbais (nenhuma ação exigida de você). Se você não der nenhum comando, ela realiza a ação de Esquiva e usa seu movimento para evitar o perigo.\n\nEm Níveis Superiores. Quando você conjurar a magia usando um espaço de magia de 4º círculo ou superior, use o círculo superior onde o círculo da magia aparece no bloco de estatísticas.", "en": "Name: Summon Shadowspawn\n\nType: Spell\n\nSource: Tasha’s Cauldron of Everything\n\nAurora ID: ID_WOTC_TCOE_SPELL_SUMMON_SHADOWSPAWN\n\nSupports: Warlock, Wizard\n\nSetters:\nlevel: 3\nschool: Conjuration\ntime: 1 action\nrange: 90 feet\nhasVerbalComponent: true\nhasSomaticComponent: true\nhasMaterialComponent: true\nmaterialComponent: tears inside a gem worth at least 300 gp\nduration: Concentration, up to 1 hour\nisConcentration: true\n\nDescription:\nYou call forth a shadowy spirit. It manifests in an unoccupied space that you can see within range. This corporeal form uses the Shadow Spirit stat block. When you cast the spell, choose an emotion: Fury, Despair, or Fear. The creature resembles a misshapen biped marked by the chosen emotion, which determines certain traits in its stat block. The creature determines when it drop to 0 hit points or when the spell ends.\n\nThe creature is an ally to you and your companions. In combat, the creature shares your initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don’t issue any, it takes the Dodge action and it uses its move to avoid danger.\n\nAt Higher Levels. When you cast the spell using a spell slot of 4th level or higher, use the higher level wherever the spell’s level appears on the stat block."}, "rulesVersion": "2024", "source": "TCE"},
  {"id": "tashasOtherworldlyGuise", "name": {"pt": "Disfarce Extraplanar de Tasha", "en": "Tasha's Otherworldly Guise"}, "level": 6, "school": "transmutation", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Bonus Action", "range": "Self", "components": "V, S, M (an object engraved with a symbol of the Outer Planes)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Proferindo um encantamento, você recorre à magia dos Planos Inferiores ou dos Planos Superiores (à sua escolha) para transformar a si mesmo. Você ganha os seguintes benefícios até a magia acabar:\n\nVocê é imune a dano de fogo e veneno (Planos Inferiores) ou a dano radiante e necrótico (Planos Superiores).\n\nVocê é imune à condição envenenado (Planos Inferiores) ou à condição enfeitiçado (Planos Superiores).\n\nAsas espectrais surgem em suas costas, concedendo a você um deslocamento de voo de 12 metros.\n\nVocê tem um bônus de +2 na CA.\n\nTodos os seus ataques com arma são mágicos, e quando você faz um ataque com arma, pode usar seu modificador de habilidade de conjuração, em vez de Força ou Destreza, para as jogadas de ataque e dano.\n\nVocê pode atacar duas vezes, em vez de uma, sempre que realizar a ação de Ataque no seu turno. Você ignora este benefício se já possuir uma característica, como Ataque Extra, que permita atacar mais de uma vez ao realizar a ação de Ataque no seu turno.", "en": "Uttering an incantation, you draw on the magic of the Lower Planes or Upper Planes (your choice) to transform yourself. You gain the following benefits until the spell ends:\n\nYou are immune to fire and poison damage (Lower Planes) or radiant and necrotic damage (Upper Planes).\n\nYou are immune to the poisoned condition (Lower Planes) or the charmed condition (Upper Planes).\n\nSpectral wings appear on your back, giving you a flying speed of 40 feet.\n\nYou have a +2 bonus to AC.\n\nAll your weapon attacks are magical, and when you make a weapon attack, you can use your spellcasting ability modifier, instead of Strength or Dexterity, for the attack and damage rolls.\n\nYou can attack twice, instead of once, when you take the Attack action on your turn. You ignore this benefit if you already have a feature, like Extra Attack, that lets you attack more than once when you take the Attack action on your turn."}, "rulesVersion": "2024", "source": "TCE"},
  {"id": "dreamOfTheBlueVeil", "name": {"pt": "Sonho do Véu Azul", "en": "Dream Of The Blue Veil"}, "level": 7, "school": "conjuration", "classes": ["bard", "sorcerer", "warlock", "wizard"], "castingTime": "10 minutes", "range": "20 feet", "components": "V, S, M (a magic item or a willing creature from the destination world)", "duration": "6 hours", "ritual": false, "concentration": false, "desc": {"pt": "Você e até oito criaturas voluntárias dentro do alcance caem inconscientes pela duração da magia e vivenciam visões de outro mundo no Plano Material, como Oerth, Toril, Krynn ou Eberron. Se a magia atingir sua duração total, as visões se concluem com cada um de vocês encontrando e puxando uma misteriosa cortina azul. A magia então termina com vocês transportados mental e fisicamente para o mundo que estava nas visões.\n\nPara conjurar esta magia, você deve possuir um item mágico originário do mundo que deseja alcançar e deve ter ciência da existência desse mundo, mesmo que não saiba seu nome. Seu destino no outro mundo é um local seguro a até 1,5 quilômetro de onde o item mágico foi criado. Como alternativa, você pode conjurar a magia se uma das criaturas afetadas tiver nascido no outro mundo, o que faz com que seu destino seja um local seguro a até 1,5 quilômetro de onde essa criatura nasceu.\n\nA magia termina antecipadamente em uma criatura se ela sofrer qualquer dano, e a criatura não é transportada. Se você sofrer qualquer dano, a magia termina para você e para todas as outras criaturas, e nenhum de vocês é transportado.", "en": "You and up to eight willing creatures within range fall unconscious for the spell’s duration and experience visions of another world on the Material Plane, such as Oerth, Toril, Krynn, or Eberron. If the spell reaches its full duration, the visions conclude with each of you encountering and pulling back a mysterious blue curtain. The spell then ends with you mentally and physically transported to the world that was in the visions.\n\nTo cast this spell, you must have a magic item that originated in the world you wish to reach, and you must be aware of the world’s existence, even if you don’t know the world’s name. Your destination in the other world is a safe location within 1 mile of where the magic item was created. Alternatively, you can cast the spell if one of the affected creatures was born on the other world, which causes your destination to be a safe location within 1 mile of where that creature was born.\n\nThe spell ends early on a creature if that creature takes any damage, and the creature isn’t transported. If you take any damage, the spell ends for you and all the other creatures, with none of you being transported."}, "rulesVersion": "2024", "source": "TCE"},
  {"id": "bladeOfDisaster", "name": {"pt": "Lâmina do Desastre", "en": "Blade Of Disaster"}, "level": 9, "school": "conjuration", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Bonus Action", "range": "60 feet", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você cria uma fenda planar em forma de lâmina com cerca de 1 metro de comprimento em um espaço desocupado que possa ver dentro do alcance. A lâmina permanece pela duração. Ao conjurar esta magia, você pode realizar até dois ataques corpo a corpo com magia usando a lâmina, cada um contra uma criatura, objeto solto ou estrutura a até 1,5 metro da lâmina. Em um acerto, o alvo sofre 4d12 de dano de força. Esse ataque obtém um acerto crítico se o número no d20 for 18 ou superior. Em um acerto crítico, a lâmina causa 8d12 de dano de força adicional (para um total de 12d12 de dano de força).\n\nComo uma ação bônus no seu turno, você pode mover a lâmina até 9 metros para um espaço desocupado que possa ver e, então, realizar até dois ataques corpo a corpo com magia usando-a novamente.\n\nA lâmina pode atravessar inofensivamente qualquer barreira, incluindo uma parede de força.", "en": "You create a blade-shaped planar rift about 3 feet long in an unoccupied space you can see within range. The blade lasts for the duration. When you cast this spell, you can make up to two melee spell attacks with the blade, each one against a creature, loose object, or structure within 5 feet of the blade. On a hit, the target takes 4d12 force damage. This attack scores a critical hit if the number on the d20 is 18 or higher. On a critical hit, the blade deals an extra 8d12 force damage (for a total of 12d12 force damage).\n\nAs a bonus action on your turn, you can move the blade up to 30 feet to an unoccupied space you can see and then make up to two melee spell attacks with it again.\n\nThe blade can harmlessly pass through any barrier, including a wall of force."}, "rulesVersion": "2024", "source": "TCE"},
  // XGE
  {"id": "controlFlames", "name": {"pt": "Controlar Chamas", "en": "Control Flames"}, "level": 0, "school": "transmutation", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "S", "duration": "Instantaneous or 1 hour (see below)", "ritual": false, "concentration": false, "desc": {"pt": "Você escolhe uma chama não mágica que possa ver dentro do alcance e que caiba em um cubo de 1,5 metro. Você a afeta de uma das seguintes maneiras:\n\nVocê expande instantaneamente a chama em 1,5 metro em uma direção, desde que haja madeira ou outro combustível presente no novo local.\n\nVocê extingue instantaneamente as chamas dentro do cubo.\n\nVocê dobra ou reduz pela metade a área de luz plena e luz penumbrosa emitida pela chama, altera a cor dela ou ambos. A mudança dura por 1 hora.\n\nVocê faz formas simples — como a forma indistinta de uma criatura, um objeto inanimado ou um local — aparecerem dentro das chamas e se animarem como você preferir. As formas duram por 1 hora.\n\nSe conjurar esta magia várias vezes, você pode ter até três efeitos não instantâneos ativos simultaneamente, e pode dispensar tal efeito com uma ação.", "en": "You choose nonmagical flame that you can see within range and that fits within a 5-foot cube. You affect it in one of the following ways:\n\nYou instantaneously expand the flame 5 feet in one direction, provided that wood or other fuel is present in the new location.\n\nYou instantaneously extinguish the flames within the cube.\n\nYou double or halve the area of bright light and dim light cast by the flame, change its color, or both. The change lasts for 1 hour.\n\nYou cause simple shapes—such as the vague form of a creature, an inanimate object, or a location—to appear within the flames and animate as you like. The shapes last for 1 hour.\n\nIf you cast this spell multiple times, you can have up to three non-instantaneous effects active at a time, and you can dismiss such an effect as an action."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "createBonfire", "name": {"pt": "Criar Fogueira", "en": "Create Bonfire"}, "level": 0, "school": "conjuration", "classes": ["artificer", "druid", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você cria uma fogueira no chão que você possa ver dentro do alcance. Até a magia terminar, a fogueira preenche um cubo de 1,5 metro. Qualquer criatura no espaço da fogueira quando você conjurar a magia deve ser bem-sucedida em uma salvaguarda de Destreza ou sofrerá 1d8 de dano de fogo. Uma criatura também deve fazer a salvaguarda quando entrar no espaço da fogueira pela primeira vez em um turno ou terminar o turno dela lá.\n\nO dano da magia aumenta em 1d8 quando você alcança o 5º nível (2d8), 11º nível (3d8) e 17º nível (4d8).", "en": "You create a bonfire on ground that you can see within range. Until the spell ends, the bonfire fills a 5-foot cube. Any creature in the bonfire’s space when you cast the spell must succeed on a Dexterity saving throw or take 1d8 fire damage. A creature must also make the saving throw when it enters the bonfire’s space for the first time on a turn or ends its turn there.\n\nThe spell’s damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8)."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "frostbite", "name": {"pt": "Queimadura de Frio", "en": "Frostbite"}, "level": 0, "school": "evocation", "classes": ["druid", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você faz com que uma geada paralisante se forme sobre uma criatura que você possa ver dentro do alcance. O alvo deve fazer uma salvaguarda de Constituição. Se falhar na salvaguarda, o alvo sofre 1d6 de dano de frio e tem desvantagem na próxima jogada de ataque com arma que fizer antes do fim do próximo turno dele.\n\nO dano da magia aumenta em 1d6 quando você alcança o 5º nível (2d6), 11º nível (3d6) e 17º nível (4d6).", "en": "You cause numbing frost to form on one creature that you can see within range. The target must make a Constitution saving throw. On a failed save, the target takes 1d6 cold damage, and it has disadvantage on the next weapon attack roll it makes before the end of its next turn.\n\nThe spell’s damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6)."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "gust", "name": {"pt": "Lufada", "en": "Gust"}, "level": 0, "school": "transmutation", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você agarra o ar e o compele a criar um dos seguintes efeitos em um ponto que você possa ver dentro do alcance:\n\nUma criatura Média ou menor que você escolher deve ser bem-sucedida em uma salvaguarda de Força ou será empurrada até 1,5 metro para longe de você.\n\nVocê cria uma pequena rajada de ar capaz de mover um objeto que não esteja sendo segurado nem carregado e que não pese mais de 2,5 kg. O objeto é empurrado até 3 metros para longe de você. Ele não é empurrado com força suficiente para causar dano.\n\n* Você cria um efeito sensorial inofensivo usando ar, como fazer folhas farfalharem, o vento bater janelas ou suas roupas tremularem em uma brisa.", "en": "You seize the air and compel it to create one of the following effects at a point you can see within range:\n\nOne Medium or smaller creature that you choose must succeed on a Strength saving throw or be pushed up to 5 feet away from you.\n\nYou create a small blast of air capable of moving one object that is neither held nor carried and that weighs no more than 5 pounds. The object is pushed up to 10 feet away from you. It isn’t pushed with enough force to cause damage.\n\n* You create a harmless sensory effect using air, such as causing leaves to rustle, wind to slam shutters shut, or your clothing to ripple in a breeze."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "infestation", "name": {"pt": "Infestação", "en": "Infestation"}, "level": 0, "school": "conjuration", "classes": ["druid", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "V, S, M (a living flea)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você faz com que uma nuvem de ácaros, pulgas e outros parasitas apareça momentaneamente sobre uma criatura que você possa ver dentro do alcance. O alvo deve ser bem-sucedido em uma salvaguarda de Constituição ou sofrerá 1d6 de dano de veneno e se moverá 1,5 metro em uma direção aleatória, caso possa se mover e seu deslocamento seja de pelo menos 1,5 metro. Role um d4 para a direção: 1, norte; 2, sul; 3, leste; ou 4, oeste. Este movimento não provoca ataques de oportunidade e, se a direção rolada estiver bloqueada, o alvo não se move.\n\nO dano da magia aumenta em 1d6 quando você alcança o 5º nível (2d6), 11º nível (3d6) e 17º nível (4d6).", "en": "You cause a cloud of mites, fleas, and other parasites to appear momentarily on one creature you can see within range. The target must succeed on a Constitution saving throw, or it takes 1d6 poison damage and moves 5 feet in a random direction if it can move and its speed is at least 5 feet. Roll a d4 for the direction: 1, north; 2, south; 3, east; or 4, west. This movement doesn’t provoke opportunity attacks, and if the direction rolled is blocked, the target doesn’t move.\n\nThe spell’s damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6)."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "magicStone", "name": {"pt": "Pedra Mágica", "en": "Magic Stone"}, "level": 0, "school": "transmutation", "classes": ["artificer", "druid", "warlock"], "castingTime": "Bonus Action", "range": "Touch", "components": "V, S", "duration": "1 minute", "ritual": false, "concentration": false, "desc": {"pt": "Você toca em uma até três pedrinhas e as imbui de magia. Você ou outra pessoa pode fazer um ataque à distância com magia com uma das pedrinhas ao arremessá-la ou lançá-la com uma funda. Se arremessada, uma pedrinha tem alcance de 18 metros. Se outra pessoa atacar com a pedrinha, esse atacante adiciona o seu modificador de habilidade de conjuração, não o dele, à jogada de ataque. Se atingir, o alvo sofre dano contundente igual a 1d6 + seu modificador de habilidade de conjuração. Quer o ataque acerte ou erre, a magia se encerra naquela pedra.\n\nSe você conjurar esta magia novamente, a magia se encerra em quaisquer pedrinhas ainda afetadas pela sua conjuração anterior.", "en": "You touch one to three pebbles and imbue them with magic. You or someone else can make a ranged spell attack with one of the pebbles by throwing it or hurling it with a sling. If thrown, a pebble has a range of 60 feet. If someone else attacks with the pebble, that attacker adds your spellcasting ability modifier, not the attacker’s, to the attack roll. On a hit, the target takes bludgeoning damage equal to 1d6 + your spellcasting ability modifier. Whether the attack hits or misses, the spell then ends on the stone.\n\nIf you cast this spell again, the spell ends on any pebbles still affected by your previous casting."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "moldEarth", "name": {"pt": "Moldar Terra", "en": "Mold Earth"}, "level": 0, "school": "transmutation", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "S", "duration": "Instantaneous or 1 hour (see below)", "ritual": false, "concentration": false, "desc": {"pt": "Você escolhe uma porção de terra ou pedra que possa ver dentro do alcance e que caiba em um cubo de 1,5 metro. Você a manipula de uma das seguintes maneiras:\n\nSe escolher uma área de terra solta, você pode escavá-la instantaneamente, movê-la pelo chão e depositá-la a até 1,5 metro de distância. Esse movimento não envolve força suficiente para causar dano.\n\nVocê faz surgir formas, cores ou ambas na terra ou pedra, soletrando palavras, criando imagens ou desenhando padrões. As alterações duram por 1 hora.\n\n* Se a terra ou pedra que você escolher como alvo estiver no chão, você faz com que ela se torne terreno difícil. Alternativamente, você pode fazer com que o chão se torne terreno normal se já for terreno difícil. Essa alteração dura por 1 hora.\n\nSe conjurar esta magia várias vezes, você não pode ter mais de dois dos seus efeitos não instantâneos ativos simultaneamente, e pode dispensar tal efeito com uma ação.", "en": "You choose a portion of dirt or stone that you can see within range and that fits within a 5-foot cube. You manipulate it in one of the following ways.\n\nIf you target an area of loose earth, you can instantaneously excavate it, move it along the ground, and deposit it up to 5 feet away. This movement doesn’t involve enough force to cause damage.\n\nYou cause shapes, colors, or both to appear on the dirt or stone, spelling out words, creating images, or shaping patterns. The changes last for 1 hour.\n\n* If the dirt or stone you target is on the ground, you cause it to become difficult terrain. Alternatively, you can cause the ground to become normal terrain if it is already difficult terrain. This change lasts for 1 hour.\n\nIf you cast this spell multiple times, you can have no more than two of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "primalSavagery", "name": {"pt": "Selvageria Primal", "en": "Primal Savagery"}, "level": 0, "school": "transmutation", "classes": ["druid"], "castingTime": "Action", "range": "Self", "components": "S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você canaliza magia primordial para afiar seus dentes ou unhas, prontos para desferir um ataque corrosivo. Faça um ataque corpo a corpo com magia contra uma criatura a até 1,5 metro de você. Se atingir, o alvo sofre 1d10 de dano ácido. Depois de fazer o ataque, seus dentes ou unhas voltam ao normal.\n\nO dano da magia aumenta em 1d10 quando você alcança o 5º nível (2d10), 11º nível (3d10) e 17º nível (4d10).", "en": "You channel primal magic to cause your teeth or fingernails to sharpen, ready to deliver a corrosive attack. Make a melee spell attack against one creature within 5 feet of you. On a hit, the target takes 1d10 acid damage. After you make the attack, your teeth or fingernails return to normal.\n\nThe spell’s damage increases by 1d10 when you reach 5th level (2d10), 11th level (3d10), and 17th level (4d10)."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "shapeWater", "name": {"pt": "Moldar Água", "en": "Shape Water"}, "level": 0, "school": "transmutation", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "S", "duration": "Instantaneous or 1 hour (see below)", "ritual": false, "concentration": false, "desc": {"pt": "Você escolhe uma área de água que possa ver dentro do alcance e que caiba em um cubo de 1,5 metro. Você a manipula de uma das seguintes maneiras:\n\nVocê move ou altera instantaneamente o fluxo da água sob sua orientação, em até 1,5 metro em qualquer direção. Esse movimento não possui força suficiente para causar dano.\n\nVocê faz a água assumir formas simples e se animar sob seu comando. Essa alteração dura por 1 hora.\n\nVocê altera a cor ou opacidade da água. A água deve ser alterada da mesma maneira por completo. Essa alteração dura por 1 hora.\n\nVocê congela a água, desde que não haja criaturas nela. A água descongela em 1 hora.\n\nSe conjurar esta magia várias vezes, você não pode ter mais de dois dos seus efeitos não instantâneos ativos simultaneamente, e pode dispensar tal efeito com uma ação.", "en": "You choose an area of water that you can see within range and that fits within a 5-foot cube. You manipulate it in one of the following ways.\n\nYou instantaneously move or otherwise change the flow of the water as you direct, up to 5 feet in any direction. This movement doesn’t have enough force to cause damage.\n\nYou cause the water to form into simple shapes and animate at your direction. This change lasts for 1 hour.\n\nYou change the water’s color or opacity. The water must be changed in the same way throughout. This change lasts for 1 hour.\n\nYou freeze the water, provided that there are no creatures in it. The water unfreezes in 1 hour.\n\nIf you cast this spell multiple times, you can have no more than two of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "absorbElements", "name": {"pt": "Absorver Elementos", "en": "Absorb Elements"}, "level": 1, "school": "abjuration", "classes": ["artificer", "druid", "ranger", "sorcerer", "wizard"], "castingTime": "Reaction, which you take when you take acid, cold, fire, lightning, or thunder damage", "range": "Self", "components": "S", "duration": "1 round", "ritual": false, "concentration": false, "desc": {"pt": "A magia captura parte da energia recebida, diminuindo o efeito dela em você e armazenando-a para seu próximo ataque corpo a corpo. Você tem resistência ao tipo de dano desencadeador até o início do seu próximo turno. Além disso, na primeira vez em que você atingir com um ataque corpo a corpo em seu próximo turno, o alvo sofre 1d6 de dano adicional do tipo desencadeador, e a magia termina.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano adicional aumenta em 1d6 para cada círculo do espaço acima do 1º.", "en": "The spell captures some of the incoming energy, lessening its effect on you and storing it for your next melee attack. You have resistance to the triggering damage type until the start of your next turn. Also, the first time you hit with a melee attack on your next turn, the target takes an extra 1d6 damage of the triggering type, and the spell ends.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the extra damage increases by 1d6 for each slot level above 1st."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "beastBond", "name": {"pt": "Vínculo Bestial", "en": "Beast Bond"}, "level": 1, "school": "divination", "classes": ["druid", "ranger"], "castingTime": "Action", "range": "Touch", "components": "V, S, M (a bit of fur wrapped in a cloth)", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Você estabelece um elo telepático com uma besta que você tocar e que seja amigável com você ou esteja enfeitiçada por você. A magia falha se a Inteligência da besta for 4 ou superior. Até a magia terminar, o elo permanece ativo enquanto você e a besta estiverem na linha de visão um do outro. Através do elo, a besta pode compreender suas mensagens telepáticas para ela, e pode comunicar telepaticamente emoções e conceitos simples de volta para você. Enquanto o elo estiver ativo, a besta ganha vantagem em jogadas de ataque contra qualquer criatura a até 1,5 metro de você que você possa ver.", "en": "You establish a telepathic link with one beast you touch that is friendly to you or charmed by you. The spell fails if the beast’s Intelligence is 4 or higher. Until the spell ends, the link is active while you and the beast are within line of sight of each other. Through the link, the beast can understand your telepathic messages to it, and it can telepathically communicate simple emotions and concepts back to you. While the link is active, the beast gains advantage on attack rolls against any creature within 5 feet of you that you can see."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "catapult", "name": {"pt": "Catapulta", "en": "Catapult"}, "level": 1, "school": "transmutation", "classes": ["artificer", "sorcerer", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Escolha um objeto pesando de 0,5 a 2,5 kg dentro do alcance que não esteja sendo vestido ou carregado. O objeto voa em linha reta por até 27 metros em uma direção à sua escolha antes de cair no chão, parando antes se atingir uma superfície sólida. Se o objeto for atingir uma criatura, essa criatura deve fazer uma salvaguarda de Destreza. Se falhar na salvaguarda, o objeto atinge o alvo e para de se mover. Quando o objeto atinge algo, o objeto e o que ele atinge sofrem 3d8 de dano contundente cada um.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o peso máximo dos objetos que você pode ter como alvo com esta magia aumenta em 2,5 kg, e o dano aumenta em 1d8, para cada círculo do espaço acima do 1º.", "en": "Choose one object weighing 1 to 5 pounds within range that isn’t being worn or carried. The object flies in a straight line up to 90 feet in a direction you choose before falling to the ground, stopping early if it impacts against a solid surface. If the object would strike a creature, that creature must make a Dexterity saving throw. On a failed save, the object strikes the target and stops moving. When the object strikes something, the object and what it strikes each take 3d8 bludgeoning damage.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the maximum weight of objects that you can target with this spell increases by 5 pounds, and the damage increases by 1d8, for each slot level above 1st."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "causeFear", "name": {"pt": "Causar Medo", "en": "Cause Fear"}, "level": 1, "school": "necromancy", "classes": ["warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você desperta o senso de mortalidade em uma criatura que possa ver dentro do alcance. Um constructo ou morto-vivo é imune a este efeito. O alvo deve ser bem-sucedido em uma salvaguarda de Sabedoria ou ficará amedrontado por você até a magia terminar. O alvo amedrontado pode repetir a salvaguarda no final de cada um dos turnos dele, encerrando o efeito em si mesmo em caso de sucesso.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, você pode escolher como alvo uma criatura adicional para cada círculo do espaço acima do 1º. As criaturas devem estar a até 9 metros uma da outra quando você as escolher como alvo.", "en": "You awaken the sense of mortality in one creature you can see within range. A construct or an undead is immune to this effect. The target must succeed on a Wisdom saving throw or become frightened of you until the spell ends. The frightened target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, you can target one additional creature for each slot level above 1st. The creatures must be within 30 feet of each other when you target them."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "ceremony", "name": {"pt": "Cerimônia", "en": "Ceremony"}, "level": 1, "school": "abjuration", "classes": ["cleric", "paladin"], "castingTime": "1 hour or Ritual", "range": "Touch", "components": "V, S, M (25 gp worth of powdered silver, which the spell consumes)", "duration": "Instantaneous", "ritual": true, "concentration": false, "desc": {"pt": "Você realiza uma cerimônia religiosa especial que é infundida com magia. Quando conjurar a magia, escolha um dos seguintes ritos, cujo alvo deve estar a até 3 metros de você durante toda a conjuração.\n\nExpiação. Você toca em uma criatura voluntária cuja tendência tenha mudado e faz um teste de Sabedoria (Intuição) CD 20. Se obtiver sucesso no teste, você restaura o alvo à sua tendência original.\n\nAbençoar Água. Você toca em um frasco de água e faz com que ele se torne água benta.\n\nMaioridade. Você toca em um humanoide que seja um jovem adulto. Pelas próximas 24 horas, sempre que o alvo fizer um teste de atributo, ele pode rolar um d4 e adicionar o número rolado ao teste de atributo. Uma criatura pode se beneficiar deste rito apenas uma vez.\n\nDedicação. Você toca em um humanoide que deseje se dedicar ao serviço do seu deus. Pelas próximas 24 horas, sempre que o alvo fizer uma salvaguarda, ele pode rolar um d4 e adicionar o número rolado à salvaguarda. Uma criatura pode se beneficiar deste rito apenas uma vez.\n\nRito Fúnebre. Você toca em um cadáver e, pelos próximos 7 dias, o alvo não pode se tornar um morto-vivo por nenhum meio que não seja a magia Desejo.\n\nCasamento. Você toca em humanoides adultos dispostos a se unirem em matrimônio. Pelos próximos 7 dias, cada alvo ganha um bônus de +2 na CA enquanto estiverem a até 9 metros um do outro. Uma criatura pode se beneficiar deste rito novamente apenas se ficar viúva.", "en": "You perform a special religious ceremony that is infused with magic. When you cast the spell, choose one of the following rites, the target of which must be within 10 feet of you throughout the casting.\n\nAtonement. You touch one willing creature whose alignment has changed, and you make a DC 20 Wisdom (Insight) check. On a successful check, you restore the target to its original alignment.\n\nBless Water. You touch one vial of water and cause it to become holy water.\n\nComing of Age. You touch one humanoid who is a young adult. For the next 24 hours, whenever the target makes an ability check, it can roll a d4 and add the number rolled to the ability check. A creature can benefit from this rite only once.\n\nDedication. You touch one humanoid who wishes to be dedicated to your god’s service. For the next 24 hours, whenever the target makes a saving throw, it can roll a d4 and add the number rolled to the save. A creature can benefit from this rite only once.\n\nFuneral Rite. You touch one corpse, and for the next 7 days, the target can’t become undead by any means short of a Wish spell.\n\nWedding. You touch adult humanoids willing to be bonded together in marriage. For the next 7 days, each target gains a +2 bonus to AC while they are within 30 feet of each other. A creature can benefit from this rite again only if widowed."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "chaosBolt", "name": {"pt": "Raio do Caos", "en": "Chaos Bolt"}, "level": 1, "school": "evocation", "classes": ["sorcerer"], "castingTime": "Action", "range": "120 feet", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você arremessa uma massa ondulante e oscilante de energia caótica contra uma criatura dentro do alcance. Faça um ataque à distância com magia contra o alvo. Se atingir, o alvo sofre 2d8 de dano + 1d6 de dano. Escolha um dos d8s. O número rolado nesse dado determina o tipo de dano do ataque, conforme mostrado abaixo.\n\nd8 | Tipo de Dano\n1 | Ácido\n2 | Frio\n3 | Fogo\n4 | Energia\n5 | Elétrico\n6 | Veneno\n7 | Psíquico\n8 | Trovejante\n\nSe você rolar o mesmo número em ambos os d8s, a energia caótica salta do alvo para uma criatura diferente à sua escolha a até 9 metros dele. Faça uma nova jogada de ataque contra o novo alvo e faça uma nova rolagem de dano, o que pode fazer com que a energia caótica salte novamente.\n\nUma criatura pode ser alvo apenas uma vez por cada conjuração desta magia.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, cada alvo sofre 1d6 de dano adicional do tipo rolado para cada círculo do espaço acima do 1º.", "en": "You hurl an undulating, warbling mass of chaotic energy at one creature in range. Make a ranged spell attack against the target. On a hit, the target takes 2d8 damage + 1d6 damage. Choose one of the d8s. The number rolled on that die determines the attack’s damage type, as shown below.\n\nd8 | Damage Type\n1 | Acid\n2 | Cold\n3 | Fire\n4 | Force\n5 | Lightning\n6 | Poison\n7 | Psychic\n8 | Thunder\n\nIf you roll the same number on both d8s, the chaotic energy leaps from the target to a different creature of your choice within 30 feet of it. Make a new attack roll against the new target, and make a new damage roll, which could cause the chaotic energy to leap again.\n\nA creature can be targeted only once by each casting of this spell.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, each target takes 1d6 extra damage of the type rolled for each slot level above 1st."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "earthTremor", "name": {"pt": "Tremor de Terra", "en": "Earth Tremor"}, "level": 1, "school": "evocation", "classes": ["bard", "druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "10 feet", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você provoca um tremor no chão dentro do alcance. Cada criatura além de você nessa área deve fazer uma salvaguarda de Destreza. Se falhar na salvaguarda, uma criatura sofre 1d6 de dano contundente e fica caída. Se o chão nessa área for de terra solta ou pedra, ele se torna terreno difícil até ser limpo, com cada porção de 1,5 metro de diâmetro exigindo pelo menos 1 minuto para ser limpa manualmente.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 1º.", "en": "You cause a tremor in the ground within range. Each creature other than you in that area must make a Dexterity saving throw. On a failed save, a creature takes 1d6 bludgeoning damage and is knocked prone. If the ground in that area is loose earth or stone, it becomes difficult terrain until cleared, with each 5-foot diameter portion requiring at least 1 minute to clear by hand.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "snare", "name": {"pt": "Laço", "en": "Snare"}, "level": 1, "school": "abjuration", "classes": ["artificer", "druid", "ranger", "wizard"], "castingTime": "1 minute", "range": "Touch", "components": "S, M (25 feet of rope, which the spell consumes)", "duration": "8 hours", "ritual": false, "concentration": false, "desc": {"pt": "Enquanto conjura esta magia, você usa a corda para criar um círculo com raio de 1,5 metro no solo ou no chão. Quando terminar de conjurar, a corda desaparece e o círculo se torna uma armadilha mágica.\n\nA armadilha é quase invisível, exigindo um teste bem-sucedido de Inteligência (Investigação) contra a CD de salvaguarda da sua magia para ser discernida.\n\nA armadilha é disparada quando uma criatura Pequena, Média ou Grande se mover para o solo ou chão dentro do raio da magia. Essa criatura deve ser bem-sucedida em uma salvaguarda de Destreza ou será magicamente içada no ar, ficando pendurada de cabeça para baixo a 1 metro acima do solo ou chão. A criatura fica impedida lá até a magia terminar.\n\nUma criatura impedida pode fazer uma salvaguarda de Destreza no final de cada um dos turnos dela, encerrando o efeito em si mesma em caso de sucesso. Como alternativa, a criatura ou outra pessoa que possa alcançá-la pode usar uma ação para fazer um teste de Inteligência (Arcanismo) contra a CD de salvaguarda da sua magia. Em caso de sucesso, o efeito de impedido termina.\n\nDepois que a armadilha é disparada, a magia termina quando nenhuma criatura estiver impedida por ela.", "en": "As you cast this spell, you use the rope to create a circle with a 5-foot radius on the ground or the floor. When you finish casting, the rope disappears and the circle becomes a magical trap.\n\nThe trap is nearly invisible, requiring a successful Intelligence (Investigation) check against your spell save DC to be discerned.\n\nThe trap triggers when a Small, Medium, or Large creature moves onto the ground or the floor in the spell’s radius. That creature must succeed on a Dexterity saving throw or be magically hoisted into the air, leaving it hanging upside down 3 feet above the ground or the floor. The creature is restrained there until the spell ends.\n\nA restrained creature can make a Dexterity saving throw at the end of each of its turns, ending the effect on itself on a success. Alternatively, the creature or someone else who can reach it can use an action to make an Intelligence (Arcana) check against your spell save DC. On a success, the restrained effect ends.\n\nAfter the trap is triggered, the spell ends when no creature is restrained by it."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "zephyrStrike", "name": {"pt": "Golpe de Zéfiro", "en": "Zephyr Strike"}, "level": 1, "school": "transmutation", "classes": ["ranger"], "castingTime": "Bonus Action", "range": "Self", "components": "V", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você se move como o vento. Até a magia terminar, seu movimento não provoca ataques de oportunidade.\n\nUma vez antes de a magia terminar, você pode conceder vantagem a si mesmo em uma jogada de ataque com arma no seu turno. Esse ataque causa 1d8 de dano de energia adicional se atingir. Quer você acerte ou erre, seu deslocamento de caminhada aumenta em 9 metros até o final daquele turno.", "en": "You move like the wind. Until the spell ends, your movement doesn’t provoke opportunity attacks.\n\nOnce before the spell ends, you can give yourself advantage on one weapon attack roll on your turn. That attack deals an extra 1d8 force damage on a hit. Whether you hit or miss, your walking speed increases by 30 feet until the end of that turn."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "aganazzarsScorcher", "name": {"pt": "Chamuscador de Aganazzar", "en": "Aganazzar's Scorcher"}, "level": 2, "school": "evocation", "classes": ["sorcerer", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "V, S, M (a red dragon’s scale)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Uma linha de chamas estrondosas de 9 metros de comprimento e 1,5 metro de largura emana de você na direção que você escolher. Cada criatura na linha deve fazer uma salvaguarda de Destreza. Uma criatura sofre 3d8 de dano de fogo se falhar na salvaguarda, ou metade desse dano em um sucesso.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 2º.", "en": "A line of roaring flame 30 feet long and 5 feet wide emanates from you in a direction you choose. Each creature in the line must make a Dexterity saving throw. A creature takes 3d8 fire damage on a failed save, or half as much damage on a successful one.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "dustDevil", "name": {"pt": "Redemoinho de Poeira", "en": "Dust Devil"}, "level": 2, "school": "conjuration", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (a pinch of dust)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Escolha um cubo desocupado de ar de 1,5 metro que você possa ver dentro do alcance. Uma força elemental semelhante a um redemoinho de poeira surge no cubo e permanece pela duração da magia.\n\nQualquer criatura que terminar seu turno a até 1,5 metro do redemoinho de poeira deve fazer uma salvaguarda de Força. Se falhar na salvaguarda, a criatura sofre 1d8 de dano contundente e é empurrada 3 metros para longe do redemoinho. Em um sucesso na salvaguarda, a criatura sofre metade do dano e não é empurrada.\n\nCom uma ação bônus, você pode mover o redemoinho de poeira em até 9 metros em qualquer direção. Se o redemoinho de poeira se mover sobre areia, poeira, terra solta ou cascalho fino, ele suga o material e forma uma nuvem de detritos com raio de 3 metros ao redor de si que dura até o início do seu próximo turno. A nuvem confere escuridão densa à sua área.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 2º.", "en": "Choose an unoccupied 5-foot cube of air that you can see within range. An elemental force that resembles a dust devil appears in the cube and lasts for the spell’s duration.\n\nAny creature that ends its turn within 5 feet of the dust devil must make a Strength saving throw. On a failed save, the creature takes 1d8 bludgeoning damage and is pushed 10 feet away from the dust devil. On a successful save, the creature takes half as much damage and isn’t pushed.\n\nAs a bonus action, you can move the dust devil up to 30 feet in any direction. If the dust devil moves over sand, dust, loose dirt, or light gravel, it sucks up the material and forms a 10-foot-radius cloud of debris around itself that lasts until the start of your next turn. The cloud heavily obscures its area.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "earthbind", "name": {"pt": "Prender à Terra", "en": "Earthbind"}, "level": 2, "school": "transmutation", "classes": ["druid", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "300 feet", "components": "V", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Escolha uma criatura que você possa ver dentro do alcance. Faixas amarelas de energia mágica se enrolam ao redor da criatura. O alvo deve ser bem-sucedido em uma salvaguarda de Força ou seu deslocamento de voo (se houver) será reduzido a 0 metro pela duração da magia. Uma criatura no ar afetada por esta magia desce em segurança a 18 metros por rodada até atingir o chão ou a magia terminar.", "en": "Choose one creature you can see within range. Yellow strips of magical energy loop around the creature. The target must succeed on a Strength saving throw, or its flying speed (if any) is reduced to 0 feet for the spell’s duration. An airborne creature affected by this spell safely descends at 60 feet per round until it reaches the ground or the spell ends."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "healingSpirit", "name": {"pt": "Espírito Curador", "en": "Healing Spirit"}, "level": 2, "school": "conjuration", "classes": ["druid", "ranger"], "castingTime": "Bonus Action", "range": "60 feet", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você invoca um espírito da natureza para acalmar os feridos. O espírito intangível surge em um espaço correspondente a um Cubo de 1,5 metro que você possa ver dentro do alcance. O espírito se parece com uma fera ou criatura feérica transparente (à sua escolha).\n\nAté a magia terminar, sempre que você ou uma criatura que possa ver entrar no espaço do espírito pela primeira vez em um turno ou começar o turno dela lá, você pode fazer com que o espírito restaure 1d6 Pontos de Vida dessa criatura (nenhuma ação necessária). O espírito não pode curar constructos nem mortos-vivos. O espírito pode curar uma quantidade de vezes igual a 1 + o seu modificador de atributo de conjuração (mínimo de duas vezes). Após curar essa quantidade de vezes, o espírito desaparece.\n\nCom uma ação bônus no seu turno, você pode mover o espírito em até 9 metros para um espaço que possa ver.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, a cura aumenta em 1d6 para cada círculo do espaço acima do 2º.", "en": "You call forth a nature spirit to soothe the wounded. The intangible spirit appears in a space that is a 5-foot cube you can see within range. The spirit looks like a transparent beast or fey (your choice).\n\nUntil the spell ends, whenever you or a creature you can see moves into the spirit’s space for the first time on a turn or starts its turn there, you can cause the spirit to restore 1d6 hit points to that creature (no action required). The spirit can’t heal constructs or undead. The spirit can heal a number of times equal to 1 + your spellcasting ability modifier (minimum of twice). After healing that number of times, the spirit disappears.\n\nAs a bonus action on your turn, you can move the spirit up to 30 feet to a space you can see.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the healing increases by 1d6 for each slot level above 2nd."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "maximiliansEarthenGrasp", "name": {"pt": "Aperto Terreno de Maximilian", "en": "Maximilian's Earthen Grasp"}, "level": 2, "school": "transmutation", "classes": ["sorcerer", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "V, S, M (a miniature hand sculpted from clay)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você escolhe um espaço desocupado de 1,5 metro quadrado no chão que possa ver dentro do alcance. Uma mão Média feita de terra compactada ergue-se ali e tenta alcançar uma criatura que você possa ver a até 1,5 metro dela. O alvo deve fazer um teste de resistência de Força. Em uma falha na salvaguarda, o alvo sofre 2d6 de dano Contundente e fica impedido pela duração da magia.\n\nCom uma ação, você pode fazer com que a mão esmague o alvo impedido, que deve fazer um teste de resistência de Força. O alvo sofre 2d6 de dano Contundente em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n\nPara se libertar, o alvo impedido pode usar a ação dele para fazer um teste de Força contra a CD de resistência da sua magia. Em um sucesso, o alvo escapa e não fica mais impedido pela mão.\n\nCom uma ação, você pode fazer a mão tentar alcançar uma criatura diferente ou se mover para um espaço desocupado diferente dentro do alcance. A mão solta um alvo impedido se você fizer qualquer uma dessas ações.", "en": "You choose a 5-foot-square unoccupied space on the ground that you can see within range. A Medium hand made from compacted soil rises there and reaches for one creature you can see within 5 feet of it. The target must make a Strength saving throw. On a failed save, the target takes 2d6 bludgeoning damage and is restrained for the spell’s duration.\n\nAs an action, you can cause the hand to crush the restrained target, which must make a Strength saving throw. The target takes 2d6 bludgeoning damage on a failed save, or half as much damage on a successful one.\n\nTo break out, the restrained target can use its action to make a Strength check against your spell save DC. On a success, the target escapes and is no longer restrained by the hand.\n\nAs an action, you can cause the hand to reach for a different creature or to move to a different unoccupied space within range. The hand releases a restrained target if you do either."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "pyrotechnics", "name": {"pt": "Pirotecnia", "en": "Pyrotechnics"}, "level": 2, "school": "transmutation", "classes": ["artificer", "bard", "sorcerer", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Escolha uma área de chamas não mágicas que você possa ver e que caiba em um cubo de 1,5 metro dentro do alcance. Você pode extinguir o fogo nessa área e criar fogos de artifício ou fumaça ao fazer isso.\n\nFogos de Artifício. O alvo explode com uma exibição ofuscante de cores. Cada criatura a até 3 metros do alvo deve ser bem-sucedida em uma salvaguarda de Constituição ou ficará cega até o final do seu próximo turno.\n\nFumaça. Uma fumaça preta e espessa se espalha a partir do alvo em um raio de 6 metros, contornando cantos. A área da fumaça fica sob escuridão densa. A fumaça persiste por 1 minuto ou até que um vento forte a disperse.", "en": "Choose an area of nonmagical flame that you can see and that fits within a 5-foot cube within range. You can extinguish the fire in that area, and you create either fireworks or smoke when you do so.\n\nFireworks. The target explodes with a dazzling display of colors. Each creature within 10 feet of the target must succeed on a Constitution saving throw or become blinded until the end of your next turn.\n\nSmoke. Thick black smoke spreads out from the target in a 20-foot radius, moving around corners. The area of the smoke is heavily obscured. The smoke persists for 1 minute or until a strong wind disperses it."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "shadowBlade", "name": {"pt": "Lâmina Sombria", "en": "Shadow Blade"}, "level": 2, "school": "illusion", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Bonus Action", "range": "Self", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você entrelaça fios de sombra para criar uma espada de penumbra solidificada em sua mão. Esta espada mágica dura até a magia terminar. Ela conta como uma arma simples corpo a corpo com a qual você é proficiente. Ela causa 2d8 de dano Psíquico em um acerto e possui as propriedades acuidade, leve e arremesso (alcance 6/18 metros). Além disso, quando você usa a espada para atacar um alvo que esteja em penumbra ou escuridão, você faz a jogada de ataque com vantagem.\n\nSe você soltar a arma ou arremessá-la, ela se dissipa no final do turno. A partir de então, enquanto a magia persistir, você pode usar uma ação bônus para fazer a espada reaparecer na sua mão.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º ou 4º círculo, o dano aumenta para 3d8. Quando conjurar usando um espaço de magia de 5º ou 6º círculo, o dano aumenta para 4d8. Quando conjurar usando um espaço de magia de 7º círculo ou superior, o dano aumenta para 5d8.", "en": "You weave together threads of shadow to create a sword of solidified gloom in your hand. This magic sword lasts until the spell ends. It counts as a simple melee weapon with which you are proficient. It deals 2d8 psychic damage on a hit and has the finesse, light, and thrown properties (range 20/60). In addition, when you use the sword to attack a target that is in dim light or darkness, you make the attack roll with advantage.\n\nIf you drop the weapon or throw it, it dissipates at the end of the turn. Thereafter, while the spell persists, you can use a bonus action to cause the sword to reappear in your hand.\n\nAt Higher Levels. When you cast this spell using a 3rd- or 4th-level spell slot, the damage increases to 3d8. When you cast it using a 5th- or 6th-level spell slot, the damage increases to 4d8. When you cast it using a spell slot of 7th level or higher, the damage increases to 5d8."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "skywrite", "name": {"pt": "Escrita Celeste", "en": "Skywrite"}, "level": 2, "school": "transmutation", "classes": ["artificer", "bard", "druid", "wizard"], "castingTime": "Action or Ritual", "range": "Sight", "components": "V, S", "duration": "Concentration, up to 1 hour", "ritual": true, "concentration": true, "desc": {"pt": "Você faz com que até dez palavras se formem em uma parte do céu que você possa ver. As palavras parecem ser feitas de nuvem e permanecem no lugar pela duração da magia. As palavras se dissipam quando a magia termina. Um vento forte pode dispersar as nuvens e encerrar a magia mais cedo.", "en": "You cause up to ten words to form in a part of the sky you can see. The words appear to be made of cloud and remain in place for the spell’s duration. The words dissipate when the spell ends. A strong wind can disperse the clouds and end the spell early."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "snillocsSnowballSwarm", "name": {"pt": "Enxame de Bolas de Neve de Snilloc", "en": "Snilloc's Snowball Swarm"}, "level": 2, "school": "evocation", "classes": ["sorcerer", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V, S, M (a piece of ice or a small white rock chip)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Uma rajada de bolas de neve mágicas irrompe de um ponto que você escolher dentro do alcance. Cada criatura em uma Esfera com 1,5 metro de raio centrada naquele ponto deve fazer um teste de resistência de Destreza. Uma criatura sofre 3d6 de dano de Frio em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 2º.", "en": "A flurry of magic snowballs erupts from a point you choose within range. Each creature in a 5-foot-radius sphere centered on that point must make a Dexterity saving throw. A creature takes 3d6 cold damage on a failed save, or half as much damage on a successful one.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "wardingWind", "name": {"pt": "Vento Protetor", "en": "Warding Wind"}, "level": 2, "school": "evocation", "classes": ["bard", "druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "Self", "components": "V", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Um vento forte (32 quilômetros por hora) sopra ao seu redor em um raio de 3 metros e se move com você, permanecendo centrado em você. O vento dura pela duração da magia.\n\nO vento tem os seguintes efeitos:\n\nEle ensurdece você e outras criaturas na área dele.\n\nEle apaga chamas desprotegidas na área dele que sejam do tamanho de uma tocha ou menores.\n\nEle afasta vapor, gás e névoa que possam ser dispersados por vento forte.\n\nA área é terreno difícil para criaturas além de você.\n\n* As jogadas de ataque de ataques com armas à distância têm desvantagem se passarem entrando ou saindo do vento.", "en": "A strong wind (20 miles per hour) blows around you in a 10-foot radius and moves with you, remaining centered on you. The wind lasts for the spell’s duration.\n\nThe wind has the following effects:\n\nIt deafens you and other creatures in its area.\n\nIt extinguishes unprotected flames in its area that are torch-sized or smaller.\n\nIt hedges out vapor, gas, and fog that can be dispersed by strong wind.\n\nThe area is difficult terrain for creatures other than you.\n\n* The attack rolls of ranged weapon attacks have disadvantage if they pass in or out of the wind."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "catnap", "name": {"pt": "Soneca", "en": "Catnap"}, "level": 3, "school": "enchantment", "classes": ["artificer", "bard", "sorcerer", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "S, M (a pinch of sand)", "duration": "10 minutes", "ritual": false, "concentration": false, "desc": {"pt": "Você faz um gesto calmante, e até três criaturas voluntárias à sua escolha que você possa ver dentro do alcance caem inconscientes pela duração da magia. A magia se encerra antecipadamente em um alvo se ele sofrer dano ou se alguém usar uma ação para sacudi-lo ou estapeá-lo para acordar. Se um alvo permanecer inconsciente por toda a duração, esse alvo ganha os benefícios de um descanso curto e não pode ser afetado por esta magia novamente até terminar um descanso longo.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, você pode escolher como alvo uma criatura voluntária adicional para cada círculo do espaço acima do 3º.", "en": "You make a calming gesture, and up to three willing creatures of your choice that you can see within range fall unconscious for the spell’s duration. The spell ends on a target early if it takes damage or someone uses an action to shake or slap it awake. If a target remains unconscious for the full duration, that target gains the benefit of a short rest, and it can’t be affected by this spell again until it finishes a long rest.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, you can target one additional willing creature for each slot level above 3rd."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "enemiesAbound", "name": {"pt": "Inimigos por Toda Parte", "en": "Enemies Abound"}, "level": 3, "school": "enchantment", "classes": ["bard", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "120 feet", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você alcança a mente de uma criatura que possa ver e a força a fazer um teste de resistência de Inteligência. Uma criatura é automaticamente bem-sucedida se for imune a ficar amedrontada. Em uma falha na salvaguarda, o alvo perde a capacidade de distinguir amigos de inimigos, considerando todas as criaturas que pode ver como inimigas até a magia terminar. Cada vez que o alvo sofrer dano, ele pode repetir o teste de resistência, encerrando o efeito sobre si mesmo em um sucesso.\n\nSempre que a criatura afetada escolher outra criatura como alvo, ela deve escolher o alvo aleatoriamente entre as criaturas que puder ver dentro do alcance do ataque, magia ou outra habilidade que estiver usando. Se um inimigo provocar um ataque de oportunidade da criatura afetada, a criatura deve fazer esse ataque se puder.", "en": "You reach into the mind of one creature you can see and force it to make an Intelligence saving throw. A creature automatically succeeds if it is immune to being frightened. On a failed save, the target loses the ability to distinguish friend from foe, regarding all creatures it can see as enemies until the spell ends. Each time the target takes damage, it can repeat the saving throw, ending the effect on itself on a success.\n\nWhenever the affected creature chooses another creature as a target, it must choose the target at random from among the creatures it can see within range of the attack, spell, or other ability it’s using. If an enemy provokes an opportunity attack from the affected creature, the creature must make that attack if it is able to."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "eruptingEarth", "name": {"pt": "Terra Irrompente", "en": "Erupting Earth"}, "level": 3, "school": "transmutation", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "120 feet", "components": "V, S, M (a piece of obsidian)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Escolha um ponto que possa ver no chão dentro do alcance. Uma fonte de terra revolta e pedra irrompe em um Cubo de 6 metros centrado naquele ponto. Cada criatura nessa área deve fazer um teste de resistência de Destreza. Uma criatura sofre 3d12 de dano Contundente em uma falha na salvaguarda, ou metade desse dano em um sucesso. Além disso, o solo nessa área se torna terreno difícil até ser limpo. Cada porção de 1,5 metro quadrado da área exige pelo menos 1 minuto para ser limpa manualmente.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d12 para cada círculo do espaço acima do 3º.", "en": "Choose a point you can see on the ground within range. A fountain of churned earth and stone erupts in a 20-foot cube centered on that point. Each creature in that area must make a Dexterity saving throw. A creature takes 3d12 bludgeoning damage on a failed save, or half as much damage on a successful one. Additionally, the ground in that area becomes difficult terrain until cleared. Each 5-foot-square portion of the area requires at least 1 minute to clear by hand.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d12 for each slot level above 3rd."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "flameArrows", "name": {"pt": "Flechas Flamejantes", "en": "Flame Arrows"}, "level": 3, "school": "transmutation", "classes": ["artificer", "druid", "ranger", "sorcerer", "wizard"], "castingTime": "Action", "range": "Touch", "components": "V, S", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você toca uma aljava contendo flechas ou virotes. Quando um alvo é atingido por um ataque à distância com arma usando uma peça de munição tirada da aljava, o alvo sofre 1d6 de dano de fogo adicional. A magia termina na peça de munição quando ela atinge ou erra, e a magia termina quando doze peças de munição tiverem sido retiradas da aljava.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o número de peças de munição que você pode afetar com esta magia aumenta em duas para cada círculo do espaço acima do 3º.", "en": "You touch a quiver containing arrows or bolts. When a target is hit by a ranged weapon attack using a piece of ammunition drawn from the quiver, the target takes an extra 1d6 fire damage. The spell’s magic ends on the piece of ammunition when it hits or misses, and the spell ends when twelve pieces of ammunition have been drawn from the quiver.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the number of pieces of ammunition you can affect with this spell increases by two for each slot level above 3rd."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "lifeTransference", "name": {"pt": "Transferência de Vida", "en": "Life Transference"}, "level": 3, "school": "necromancy", "classes": ["cleric", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você sacrifica parte de sua saúde para curar os ferimentos de outra criatura. Você sofre 4d8 de dano Necrótico, que não pode ser reduzido de nenhuma forma, e uma criatura à sua escolha que possa ver dentro do alcance recupera uma quantidade de Pontos de Vida igual ao dobro do dano Necrótico que você sofreu.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 3º.", "en": "You sacrifice some of your health to mend another creature’s injuries. You take 4d8 necrotic damage, which can’t be reduced in any way, and one creature of your choice that you can see within range regains a number of hit points equal to twice the necrotic damage you take.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d8 for each slot level above 3rd."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "melfsMinuteMeteors", "name": {"pt": "Meteoros Diminutos de Melf", "en": "Melf's Minute Meteors"}, "level": 3, "school": "evocation", "classes": ["sorcerer", "wizard"], "castingTime": "Action", "range": "Self", "components": "V, S, M (niter, sulfur, and pine tar formed into a bead)", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Você cria seis meteoros minúsculos no seu espaço. Eles flutuam no ar e orbitam você pela duração da magia. Quando conjurar a magia — e como uma ação bônus em cada um dos seus turnos subsequentes — você pode gastar um ou dois dos meteoros, enviando-os em disparada na direção de um ponto ou pontos que você escolher a até 36 metros de você. Assim que um meteoro atinge seu destino ou se choca contra uma superfície sólida, ele explode. Cada criatura a até 1,5 metro do ponto onde o meteoro explode deve fazer um teste de resistência de Destreza. Uma criatura sofre 2d6 de dano de Fogo em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, a quantidade de meteoros criados aumenta em dois para cada círculo do espaço acima do 3º.", "en": "You create six tiny meteors in your space. They float in the air and orbit you for the spell’s duration. When you cast the spell—and as a bonus action on each of your turns thereafter—you can expend one or two of the meteors, sending them streaking toward a point or points you choose within 120 feet of you. Once a meteor reaches its destination or impacts against a solid surface, the meteor explodes. Each creature within 5 feet of the point where the meteor explodes must make a Dexterity saving throw. A creature takes 2d6 fire damage on a failed save, or half as much damage on a successful one.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the number of meteors created increases by two for each slot level above 3rd."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "summonLesserDemons", "name": {"pt": "Invocar Demônios Menores", "en": "Summon Lesser Demons"}, "level": 3, "school": "conjuration", "classes": ["warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (a vial of blood from a humanoid killed within the past 24 hours)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você profere palavras vis, invocando demônios do caos do Abismo. Role na tabela a seguir para determinar o que aparece.\n\nd6 | Demônios Invocados\n1–2 | Dois demônios de nível de desafio 1 ou menor\n3–4 | Quatro demônios de nível de desafio 1/2 ou menor\n5–6 | Oito demônios de nível de desafio 1/4 ou menor\n\nO Mestre escolhe os demônios, como manes ou dretches, e você escolhe os espaços desocupados que possa ver dentro do alcance onde eles aparecem. Um demônio invocado desaparece quando cai a 0 Pontos de Vida ou quando a magia termina.\n\nOs demônios são hostis a todas as criaturas, incluindo você. Role iniciativa para os demônios invocados como um grupo, que tem seus próprios turnos. Os demônios perseguem e atacam os não demônios mais próximos com o melhor de suas habilidades.\n\nComo parte da conjuração da magia, você pode formar um círculo no chão com o sangue usado como componente material. O círculo é grande o suficiente para englobar seu espaço. Enquanto a magia durar, os demônios invocados não podem cruzar o círculo nem danificá-lo, e não podem alvejar ninguém dentro dele. Usar o componente material dessa maneira o consome quando a magia termina.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 6º ou 7º círculo, você invoca o dobro de demônios. Se conjurá-la usando um espaço de magia de 8º ou 9º círculo, você invoca o triplo de demônios.", "en": "You utter foul words, summoning demons from the chaos of the Abyss. Roll on the following table to determine what appears.\n\nd6 | Demons Summoned\n1–2 | Two demons of challenge rating 1 or lower\n3–4 | Four demons of challenge rating 1/2 or lower\n5–6 | Eight demons of challenge rating 1/4 or lower\n\nThe DM chooses the demons, such as manes or dretches, and you choose the unoccupied spaces you can see within range where they appear. A summoned demon disappears when it drops to 0 hit points or when the spell ends.\n\nThe demons are hostile to all creatures, including you. Roll initiative for the summoned demons as a group, which has its own turns. The demons pursue and attack the nearest non-demons to the best of their ability.\n\nAs part of casting the spell, you can form a circle on the ground with the blood used as a material component. The circle is large enough to encompass your space. While the spell lasts, the summoned demons can’t cross the circle or harm it, and they can’t target anyone within it. Using the material component in this manner consumes it when the spell ends.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th or 7th level, you summon twice as many demons. If you cast it using a spell slot of 8th or 9th level, you summon three times as many demons."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "thunderStep", "name": {"pt": "Passo Trovejante", "en": "Thunder Step"}, "level": 3, "school": "conjuration", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você se teletransporta para um espaço desocupado que possa ver dentro do alcance. Imediatamente após desaparecer, um estrondo trovejante ecoa, e cada criatura a até 3 metros do espaço que você deixou deve fazer um teste de resistência de Constituição, sofrendo 3d10 de dano Trovejante em uma falha na salvaguarda, ou metade desse dano em um sucesso. O estrondo pode ser ouvido a até 90 metros de distância.\n\nVocê pode levar objetos consigo, desde que o peso deles não exceda o que você pode carregar. Você também pode teletransportar uma criatura voluntária do seu tamanho ou menor que esteja carregando equipamento até a capacidade de carga dela. A criatura deve estar a até 1,5 metro de você quando conjurar esta magia, e deve haver um espaço desocupado a até 1,5 metro do seu espaço de destino para a criatura aparecer; do contrário, a criatura é deixada para trás.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 3º.", "en": "You teleport yourself to an unoccupied space you can see within range. Immediately after you disappear, a thunderous boom sounds, and each creature within 10 feet of the space you left must make a Constitution saving throw, taking 3d10 thunder damage on a failed save, or half as much damage on a successful one. The thunder can be heard from up to 300 feet away.\n\nYou can bring along objects as long as their weight doesn’t exceed what you can carry. You can also teleport one willing creature of your size or smaller who is carrying gear up to its carrying capacity. The creature must be within 5 feet of you when you cast this spell, and there must be an unoccupied space within 5 feet of your destination space for the creature to appear in; otherwise, the creature is left behind.\n\nAt Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 1d10 for each slot level above 3rd."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "tidalWave", "name": {"pt": "Onda de Maré", "en": "Tidal Wave"}, "level": 3, "school": "conjuration", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "120 feet", "components": "V, S, M (a drop of water)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você invoca uma onda de água que desaba sobre uma área dentro do alcance. A área pode ter até 9 metros de comprimento, até 3 metros de largura e até 3 metros de altura. Cada criatura nessa área deve fazer um teste de resistência de Destreza. Em uma falha, uma criatura sofre 4d8 de dano Contundente e é derrubada no chão (ficando caída). Em um sucesso, uma criatura sofre metade desse dano e não é derrubada. A água então se espalha pelo chão em todas as direções, apagando chamas desprotegidas na área dela e a até 9 metros dela, e depois desaparece.", "en": "You conjure up a wave of water that crashes down on an area within range. The area can be up to 30 feet long, up to 10 feet wide, and up to 10 feet tall. Each creature in that area must make a Dexterity saving throw. On a failure, a creature takes 4d8 bludgeoning damage and is knocked prone. On a success, a creature takes half as much damage and isn’t knocked prone. The water then spreads out across the ground in all directions, extinguishing unprotected flames in its area and within 30 feet of it, and then vanishes."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "tinyServant", "name": {"pt": "Servo Minúsculo", "en": "Tiny Servant"}, "level": 3, "school": "transmutation", "classes": ["artificer", "wizard"], "castingTime": "1 minute", "range": "Touch", "components": "V, S", "duration": "8 hours", "ritual": false, "concentration": false, "desc": {"pt": "Nome: Servo Miúdo\n\nTipo: Magia\n\nFonte: Xanathar’s Guide to Everything\n\nAurora ID: ID_XGTE_SPELL_TINY_SERVANT\n\nSuporta: Mago, Artífice\n\nDefinições:\nnível: 3\nescola: Transmutação\ntempo: 1 minuto\nduração: 8 horas\nalcance: Toque\ntemComponenteVerbal: verdadeiro\ntemComponenteSomatico: verdadeiro\ntemComponenteMaterial: falso\néConcentração: falso\néRitual: falso\n\nDescrição:\nVocê toca um objeto Miúdo e não mágico que não esteja preso a outro objeto ou a uma superfície e não esteja sendo carregado por outra criatura. O alvo se anima e ganha pequenos braços e pernas, tornando-se uma criatura sob seu controle até a magia terminar ou a criatura cair a 0 Pontos de Vida. Consulte o bloco de estatísticas para ver suas estatísticas.\nCom uma ação bônus, você pode comandar mentalmente a criatura se ela estiver a até 36 metros de você. (Se controlar várias criaturas com esta magia, você pode comandar qualquer uma delas ou todas ao mesmo tempo, emitindo o mesmo comando para cada uma.) Você decide qual ação a criatura realizará e para onde ela se moverá durante o próximo turno dela, ou pode emitir um comando simples e geral, como buscar uma chave, ficar de guarda ou empilhar alguns livros. Se não emitir nenhum comando, o servo não faz nada além de se defender contra criaturas hostis. Uma vez dada uma ordem, o servo continua a segui-la até que sua tarefa seja concluída.\nQuando a criatura cai a 0 Pontos de Vida, ela reverte à sua forma original e qualquer dano restante é transferido para essa forma.\nEm Níveis Superiores.\nQuando você conjurar esta magia usando um espaço de magia de 4º círculo ou superior, você pode animar dois objetos adicionais para cada círculo do espaço acima do 3º.", "en": "Name: Tiny Servant\n\nType: Spell\n\nSource: Xanathar’s Guide to Everything\n\nAurora ID: ID_XGTE_SPELL_TINY_SERVANT\n\nSupports: Wizard, Artificer\n\nSetters:\nlevel: 3\nschool: Transmutation\ntime: 1 minute\nduration: 8 hours\nrange: Touch\nhasVerbalComponent: true\nhasSomaticComponent: true\nhasMaterialComponent: false\nisConcentration: false\nisRitual: false\n\nDescription:\nYou touch one Tiny, nonmagical object that isn’t attached to another object or a surface and isn’t being carried by another creature. The target animates and sprouts little arms and legs, becoming a creature under your control until the spell ends or the creature drops to 0 hit points. See the stat block for its statistics.\nAs a bonus action, you can mentally command the creature if it is within 120 feet of you. (If you control multiple creatures with this spell, you can command any or all of them at the same time, issuing the same command to each one.) You decide what action the creature will take and where it will move during its next turn, or you can issue a simple, general command, such as to fetch a key, stand watch, or stack some books. If you issue no commands, the servant does nothing other than defend itself against hostile creatures. Once given an order, the servant continues to follow that order until its task is complete.\nWhen the creature drops to 0 hit points, it reverts to its original form, and any remaining damage carries over to that form.\nAt Higher Levels.\nWhen you cast this spell using a spell slot of 4th level or higher, you can animate two additional objects for each slot level above 3rd."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "wallOfSand", "name": {"pt": "Muralha de Areia", "en": "Wall of Sand"}, "level": 3, "school": "evocation", "classes": ["wizard"], "castingTime": "Action", "range": "90 feet", "components": "V, S, M (a handful of sand)", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Você cria uma muralha de areia revolta no chão em um ponto que possa ver dentro do alcance. Você pode fazer a muralha com até 9 metros de comprimento, 3 metros de altura e 3 metros de espessura, e ela desaparece quando a magia termina. Ela bloqueia a linha de visão, mas não o movimento. Uma criatura fica cega enquanto estiver no espaço da muralha e deve gastar 3 metros de movimento para cada 1 metro que se mover ali.", "en": "You create a wall of swirling sand on the ground at a point you can see within range. You can make the wall up to 30 feet long, 10 feet high, and 10 feet thick, and it vanishes when the spell ends. It blocks line of sight but not movement. A creature is blinded while in the wall’s space and must spend 3 feet of movement for every 1 foot it moves there."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "wallOfWater", "name": {"pt": "Muralha de Água", "en": "Wall of Water"}, "level": 3, "school": "evocation", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (a drop of water)", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Você cria uma muralha de água no chão em um ponto que possa ver dentro do alcance. Você pode fazer a muralha com até 9 metros de comprimento, 3 metros de altura e 30 centímetros de espessura, ou pode fazer uma muralha circular com até 6 metros de diâmetro, 6 metros de altura e 30 centímetros de espessura. A muralha desaparece quando a magia termina. O espaço da muralha é terreno difícil.\n\nQualquer ataque com arma à distância que entrar no espaço da muralha tem desvantagem na jogada de ataque, e o dano de Fogo é reduzido pela metade se o efeito de fogo atravessar a muralha para alcançar seu alvo. Magias que causam dano de Frio que atravessarem a muralha fazem com que a área da muralha que atravessaram congele solidamente (pelo menos uma seção quadrada de 1,5 metro é congelada). Cada seção congelada de 1,5 metro quadrado tem CA 5 e 15 Pontos de Vida. Reduzir uma seção congelada a 0 Pontos de Vida a destrói. Quando uma seção é destruída, a água da muralha não a preenche.", "en": "You create a wall of water on the ground at a point you can see within range. You can make the wall up to 30 feet long, 10 feet high, and 1 foot thick, or you can make a ringed wall up to 20 feet in diameter, 20 feet high, and 1 foot thick. The wall vanishes when the spell ends. The wall’s space is difficult terrain.\n\nAny ranged weapon attack that enters the wall’s space has disadvantage on the attack roll, and fire damage is halved if the fire effect passes through the wall to reach its target. Spells that deal cold damage that pass through the wall cause the area of the wall they pass through to freeze solid (at least a 5-foot square section is frozen). Each 5-foot-square frozen section has AC 5 and 15 hit points. Reducing a frozen section to 0 hit points destroys it. When a section is destroyed, the wall’s water doesn’t fill it."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "elementalBane", "name": {"pt": "Ruína Elemental", "en": "Elemental Bane"}, "level": 4, "school": "transmutation", "classes": ["artificer", "druid", "warlock", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Escolha uma criatura que você possa ver dentro do alcance e escolha um dos seguintes tipos de dano: ácido, elétrico, fogo, frio ou trovejante. O alvo deve ser bem-sucedido em uma salvaguarda de Constituição ou será afetado pela magia pela duração dela. Na primeira vez em cada turno que o alvo afetado sofrer dano do tipo escolhido, o alvo sofre 2d6 de dano adicional desse tipo. Além disso, o alvo perde qualquer resistência a esse tipo de dano até a magia terminar.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 5º círculo ou superior, você pode escolher como alvo uma criatura adicional para cada círculo do espaço acima do 4º. As criaturas devem estar a até 9 metros uma da outra quando você as escolher como alvo.", "en": "Choose one creature you can see within range, and choose one of the following damage types: acid, cold, fire, lightning, or thunder. The target must succeed on a Constitution saving throw or be affected by the spell for its duration. The first time each turn the affected target takes damage of the chosen type, the target takes an extra 2d6 damage of that type. Moreover, the target loses any resistance to that damage type until the spell ends.\n\nAt Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can target one additional creature for each slot level above 4th. The creatures must be within 30 feet of each other when you target them."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "findGreaterSteed", "name": {"pt": "Encontrar Corcel Maior", "en": "Find Greater Steed"}, "level": 4, "school": "conjuration", "classes": ["paladin"], "castingTime": "10 minutes", "range": "30 feet", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você invoca um espírito que assume a forma de uma montaria leal e majestosa. Surgindo em um espaço desocupado dentro do alcance, o espírito assume uma forma à sua escolha: um grifo, um pégaso, um peryton, um lobo atroz, um rinoceronte ou um tigre-dentes-de-sabre. A criatura tem as estatísticas fornecidas no Monster Manual para a forma escolhida, embora seja um celestial, uma criatura feérica ou um corruptor (à sua escolha) em vez de seu tipo normal de criatura. Além disso, se ela tiver um valor de Inteligência de 5 ou menor, sua Inteligência se torna 6 e ela ganha a capacidade de compreender um idioma à sua escolha que você fale.\n\nVocê controla a montaria em combate. Enquanto a montaria estiver a até 1,5 quilômetro de você, você pode se comunicar com ela telepaticamente. Enquanto estiver montado nela, você pode fazer com que qualquer magia que você conjurar que tenha como alvo apenas você também tenha a montaria como alvo.\n\nA montaria desaparece temporariamente quando cai a 0 Pontos de Vida ou quando você a dispensa com uma ação. Conjurar esta magia novamente reinvoca a montaria vinculada, com todos os seus Pontos de Vida restaurados e quaisquer condições removidas.\n\nVocê não pode ter mais de uma montaria vinculada por esta magia ou por encontrar montaria ao mesmo tempo. Com uma ação, você pode liberar uma montaria de seu vínculo, fazendo-a desaparecer permanentemente.\n\nSempre que a montaria desaparece, ela deixa para trás quaisquer objetos que estivesse vestindo ou carregando.", "en": "You summon a spirit that assumes the form of a loyal, majestic mount. Appearing in an unoccupied space within range, the spirit takes on a form you choose: a griffon, a pegasus, a peryton, a dire wolf, a rhinoceros, or a saber-toothed tiger. The creature has the statistics provided in the Monster Manual for the chosen form, though it is a celestial, a fey, or a fiend (your choice) instead of its normal creature type. Additionally, if it has an Intelligence score of 5 of lower, its Intelligence becomes 6, and it gains the ability to understand one language of your choice that you speak.\n\nYou control the mount in combat. While the mount is within 1 mile of you, you can communicate with it telepathically. While mounted on it, you can make any spell you cast that targets only you also target the mount.\n\nThe mount disappears temporarily when it drops to 0 hit points or when you dismiss it as an action. Casting this spell again re-summons the bonded mount, with all its hit points restored and any conditions removed.\n\nYou can’t have more than one mount bonded by this spell or find steed at any time. As an action, you can release a mount from its bond, causing it to disappear permanently.\n\nWhenever the mount disappears, it leaves behind any objects it was wearing or carrying."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "guardianOfNature", "name": {"pt": "Guardião da Natureza", "en": "Guardian of Nature"}, "level": 4, "school": "transmutation", "classes": ["druid", "ranger"], "castingTime": "Bonus Action", "range": "Self", "components": "V", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Um espírito da natureza responde ao seu chamado e transforma você em um poderoso guardião. A transformação dura até a magia terminar. Você escolhe uma das seguintes formas para assumir: Fera Primitiva ou Grande Árvore.\n\nFera Primitiva. Pelos bestiais cobrem seu corpo, suas feições faciais tornam-se ferozes e você ganha os seguintes benefícios:\n\nSeu Deslocamento de caminhada aumenta em 3 metros.\n\nVocê ganha visão no escuro com alcance de 36 metros.\n\nVocê faz jogadas de ataque baseadas em Força com vantagem.\n\nSeus ataques corpo a corpo com arma causam 1d6 de dano de Força adicional em um acerto.\n\nGrande Árvore. Sua pele se assemelha a casca de árvore, folhas brotam do seu cabelo e você ganha os seguintes benefícios:\n\nVocê ganha 10 Pontos de Vida Temporários.\n\nVocê faz testes de resistência de Constituição com vantagem.\n\nVocê faz jogadas de ataque baseadas em Destreza e Sabedoria com vantagem.\n\nEnquanto você estiver no chão, o solo a até 4,5 metros de você é terreno difícil para os seus inimigos.", "en": "A nature spirit answers your call and transforms you into a powerful guardian. The transformation lasts until the spell ends. You choose one of the following forms to assume: Primal Beast or Great Tree.\n\nPrimal Beast. Bestial fur covers your body, your facial feature becomes feral, and you gain the following benefits.\n\nYour walking speed increases by 10 feet.\n\nYou gain darkvision with a range of 120 feet.\n\nYou make Strength-based attack rolls with advantage.\n\nYour melee weapon attacks deal an extra 1d6 force damage on a hit.\n\nGreat Tree. Your skin appears barky, leaves sprout from your hair, and you gain the following benefits:\n\nYou gain 10 temporary hit points.\n\nYou make Constitution saving throws with advantage.\n\nYou make Dexterity- and Wisdom-based attack rolls with advantage.\n\nWhile you are on the ground, the ground within 15 feet of you is difficult terrain for your enemies."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "shadowOfMoil", "name": {"pt": "Sombra de Moil", "en": "Shadow of Moil"}, "level": 4, "school": "necromancy", "classes": ["warlock"], "castingTime": "Action", "range": "Self", "components": "V, S, M (an undead eyeball encased in a gem worth at least 150 gp)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Sombras semelhantes a chamas envolvem seu corpo até a magia terminar, fazendo com que você fique pesadamente obscurecido para os outros. As sombras transformam a penumbra a até 3 metros de você em escuridão, e a luz brilhante na mesma área em penumbra.\n\nAté a magia terminar, você tem resistência a dano Radiante. Além disso, sempre que uma criatura a até 3 metros de você atingir você com um ataque, as sombras açoitam aquela criatura, causando-lhe 2d8 de dano Necrótico.", "en": "Flame-like shadows wreathe your body until the spell ends, causing you to become heavily obscured to others. The shadows turn dim light within 10 feet of you into darkness, and bright light in the same area to dim light.\n\nUntil the spell ends, you have resistance to radiant damage. In addition, whenever a creature within 10 feet of you hits you with an attack, the shadows lash out at that creature, dealing it 2d8 necrotic damage."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "sickeningRadiance", "name": {"pt": "Radiância Nauseante", "en": "Sickening Radiance"}, "level": 4, "school": "evocation", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "120 feet", "components": "V, S", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Uma luz esverdeada e tênue se espalha dentro de uma Esfera com raio de 9 metros centrada em um ponto que você escolher dentro do alcance. A luz contorna cantos e dura até a magia terminar.\n\nQuando uma criatura se mover para a área da magia pela primeira vez em um turno ou começar o turno dela lá, essa criatura deve ser bem-sucedida em um teste de resistência de Constituição ou sofrerá 4d10 de dano Radiante, sofrerá um nível de exaustão e emitirá uma luz tênue e esverdeada em um raio de 1,5 metro. Essa luz torna impossível para a criatura se beneficiar de estar invisível. A luz e quaisquer níveis de exaustão causados por esta magia desaparecem quando a magia termina.", "en": "Dim, greenish light spreads within a 30-foot-radius sphere centered on a point you choose within range. The light spreads around corners, and it lasts until the spell ends.\n\nWhen a creature moves into the spell’s area for the first time on a turn or starts its turn there, that creature must succeed on a Constitution saving throw or take 4d10 radiant damage, and it suffers one level of exhaustion and emits a dim, greenish light in a 5-foot radius. This light makes it impossible for the creature to benefit from being invisible. The light and any levels of exhaustion caused by this spell go away when the spell ends."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "stormSphere", "name": {"pt": "Esfera Tempestuosa", "en": "Storm Sphere"}, "level": 4, "school": "evocation", "classes": ["sorcerer", "wizard"], "castingTime": "Action", "range": "150 feet", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Uma Esfera com raio de 6 metros de ar rodopiante passa a existir, centrada em um ponto que você escolher dentro do alcance. A esfera permanece pela duração da magia. Cada criatura na esfera quando ela surge ou que terminar o turno dela lá deve ser bem-sucedida em um teste de resistência de Força ou sofrerá 2d6 de dano Contundente. O espaço da esfera é terreno difícil.\n\nAté a magia terminar, você pode usar uma ação bônus em cada um dos seus turnos para fazer com que um relâmpago salte do centro da esfera em direção a uma criatura à sua escolha a até 18 metros do centro. Faça um ataque mágico à distância. Você tem vantagem na jogada de ataque se o alvo estiver na esfera. Em um acerto, o alvo sofre 4d6 de dano Elétrico.\n\nCriaturas a até 9 metros da esfera têm desvantagem em testes de Sabedoria (Percepção) feitos para ouvir.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 5º círculo ou superior, o dano aumenta para cada um dos seus efeitos em 1d6 para cada círculo do espaço acima do 4º.", "en": "A 20-foot-radius sphere of whirling air springs into existence, centered on a point you choose within range. The sphere remains for the spell’s duration. Each creature in the sphere when it appears or that ends its turn there must succeed on a Strength saving throw or take 2d6 bludgeoning damage. The sphere’s space is difficult terrain.\n\nUntil the spell ends, you can use a bonus action on each of your turns to cause a bolt of lightning to leap from the center of the sphere toward one creature you choose within 60 feet of the center. Make a ranged spell attack. You have advantage on the attack roll if the target is in the sphere. On a hit, the target takes 4d6 lightning damage.\n\nCreatures within 30 feet of the sphere have disadvantage on Wisdom (Perception) checks made to listen.\n\nAt Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the damage increases for each of its effects by 1d6 for each slot level above 4th."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "summonGreaterDemon", "name": {"pt": "Invocar Demônio Maior", "en": "Summon Greater Demon"}, "level": 4, "school": "conjuration", "classes": ["warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (a vial of blood from a humanoid killed within the past 24 hours)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você profere palavras vis, invocando um demônio do caos do Abismo. Você escolhe o tipo do demônio, que deve ser de nível de desafio 5 ou menor, como um demônio das sombras ou um barlgura. O demônio aparece em um espaço desocupado que você possa ver dentro do alcance, e o demônio desaparece quando cai a 0 Pontos de Vida ou quando a magia termina.\n\nRole iniciativa para o demônio, que tem seus próprios turnos. Quando você o invoca e em cada um dos seus turnos subsequentes, você pode emitir um comando verbal a ele (não exigindo nenhuma ação de sua parte), dizendo o que ele deve fazer no próximo turno dele. Se não emitir nenhum comando, ele passa o turno atacando qualquer criatura ao alcance que o tenha atacado.\n\nNo final de cada um dos turnos do demônio, ele faz um teste de resistência de Carisma. O demônio tem desvantagem nesse teste de resistência se você pronunciar o nome verdadeiro dele. Em um sucesso na salvaguarda, seu controle sobre o demônio termina pelo restante da duração, e o demônio passa seus turnos perseguindo e atacando os não demônios mais próximos com o melhor de suas habilidades. Se você parar de se concentrar na magia antes que ela atinja sua duração total, um demônio descontrolado não desaparece por 1d6 rodadas se ainda tiver Pontos de Vida.\n\nComo parte da conjuração da magia, você pode formar um círculo no chão com o sangue usado como componente material. O círculo é grande o suficiente para englobar seu espaço. Enquanto a magia durar, o demônio invocado não pode cruzar o círculo nem danificá-lo, e não pode alvejar ninguém dentro dele. Usar o componente material dessa maneira o consome quando a magia termina.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 5º círculo ou superior, o nível de desafio aumenta em 1 para cada círculo do espaço acima do 4º.", "en": "You utter foul words, summoning one demon from the chaos of the Abyss. You chose the demons type, which must be one of challenge rating 5 or lower, such as a shadow demon or a barlgura. The demon appears in an unoccupied space you can see within range, and the demon disappears when it drops to 0 hit points or when the spell ends.\n\nRoll initiative for the demon, which has its own turns. When you summon it and on each of your turns thereafter, you can issue a verbal command to it (requiring no action on your part), telling it what it must do on its next turn. If you issue no command, it spends its turn attacking any creature within reach that has attacked it.\n\nAt the end of each of the demon’s turns, it makes a Charisma saving throw. The demon has disadvantage on this saving throw if you say its true name. On a successful save, your control of the demon ends for the rest of the duraton, and the demon spends its turns pursuing and attacking the nearest non-demons to the best of its ability. If you stop concentrating on the spell before it reaches its full duration, an uncontrolled demon doesn’t disappear for 1d6 rounds if it still has hit points.\n\nAs part of casting the spell, you can form a circle on the ground with the blood used as a material component. The circle is large enough to encompass your space. While the spell lasts, the summoned demon can’t cross the circle or harm it, and they can’t target anyone within it. Using the material component in this manner consumes it when the spell ends.\n\nAt Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the challenge rating increases by 1 for each slot level above 4th."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "waterySphere", "name": {"pt": "Esfera Aquosa", "en": "Watery Sphere"}, "level": 4, "school": "conjuration", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V, S, M (a droplet of water)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você conjura uma esfera de água com raio de 1,5 metro em um ponto que possa ver dentro do alcance. A esfera pode pairar, mas a não mais de 3 metros do chão. A esfera permanece pela duração da magia.\n\nQualquer criatura no espaço da esfera deve fazer um teste de resistência de Força. Em um sucesso na salvaguarda, a criatura é ejetada daquele espaço para o espaço desocupado mais próximo à escolha da criatura fora dela. Uma criatura Imensa ou maior é bem-sucedida automaticamente no teste de resistência, e uma criatura Grande ou menor pode escolher falhar voluntariamente nele. Em uma falha na salvaguarda, uma criatura fica impedida pela esfera e é envolvida pela água. No final de cada um dos turnos dela, um alvo impedido pode repetir o teste de resistência, encerrando o efeito sobre si mesmo em um sucesso.\n\nA esfera pode conter até quatro criaturas Médias ou menores, ou uma criatura Grande. Se a esfera prender uma criatura que faça com que ela exceda essa capacidade, uma criatura aleatória que já estava presa pela esfera cai para fora dela e cai no chão (ficando caída) em um espaço a até 1,5 metro dela.\n\nCom uma ação, você pode mover a esfera em até 9 metros em linha reta. Se ela se mover sobre um fosso, penhasco ou outro desnível, ela desce com segurança até ficar pairando a 3 metros do chão. Qualquer criatura presa pela esfera se move com ela. Você pode arremeter a esfera contra criaturas, forçando-as a fazer o teste de resistência.\n\nQuando a magia termina, a esfera cai no chão e apaga todas as chamas normais a até 9 metros dela. Qualquer criatura presa pela esfera é derrubada no chão (ficando caída) no espaço onde cai. A água então desaparece.", "en": "You conjure up a sphere of water with a 5-foot radius at a point you can see within range. The sphere can hover but no more than 10 feet off the ground. The sphere remains for the spell’s duration.\n\nAny creature in the sphere’s space must make a Strength saving throw. On a successful save, a creature is ejected from that space to the nearest unoccupied space of the creature’s choice outside it. A Huge or larger creature succeeds on the saving throw automatically, and a Large or smaller creature can choose to fail it. On a failed save, a creature is restrained by the sphere and is engulfed by the water. At the end of each of its turns, a restrained target can repeat the saving throw, ending the effect on itself on a success.\n\nThe sphere can restrain as many as four Medium or smaller creatures or one Large creature. If the sphere restrains a creature that causes it to exceed this capacity, a random creature that was already restrained by the sphere falls out of it and lands prone in a space within 5 feet of it.\n\nAs an action, you can move the sphere up to 30 feet in a straight line. If it moves over a pit, cliff, or other drop-off, it safely descends until it is hovering 10 feet above the ground. Any creature restrained by the sphere moves with it. You can ram the sphere into creatures, forcing them to make the saving throw.\n\nWhen the spell ends, the sphere falls to the ground and extinguishes all normal flames within 30 feet of it. Any creature restrained by the sphere is knocked prone in the space where it falls. The water then vanishes."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "controlWinds", "name": {"pt": "Controlar Ventos", "en": "Control Winds"}, "level": 5, "school": "transmutation", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "300 feet", "components": "V, S", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você assume o controle do ar em um Cubo de 30 metros que possa ver dentro do alcance. Escolha um dos seguintes efeitos ao conjurar a magia. O efeito dura pela duração da magia, a menos que você use sua ação em um turno posterior para alternar para um efeito diferente. Você também pode usar sua ação para interromper temporariamente o efeito ou reiniciar um que tenha interrompido.\n\nRajadas. Um vento se intensifica dentro do cubo, soprando continuamente em uma direção horizontal que você designar. Você escolhe a intensidade do vento: calmo, moderado ou forte. Se o vento for moderado ou forte, ataques com armas à distância que passarem por ele ou que forem feitos contra alvos dentro do cubo têm desvantagem em suas jogadas de ataque. Se o vento for forte, qualquer criatura que se mover contra o vento deve gastar 1 metro adicional de movimento para cada metro percorrido.\n\nCorrente Descendente. Você provoca uma rajada contínua de vento forte soprando para baixo a partir do topo do cubo. Ataques com armas à distância que passarem pelo cubo ou que forem feitos contra alvos dentro dele têm desvantagem em suas jogadas de ataque. Uma criatura deve fazer um teste de resistência de Força se voar para dentro do cubo pela primeira vez em um turno ou começar o turno dela voando lá dentro. Em uma falha na salvaguarda, a criatura é derrubada no chão (ficando caída).\n\nCorrente Ascendente. Você provoca uma corrente ascendente contínua dentro do cubo, subindo a partir da base do cubo. Criaturas que terminarem uma queda dentro do cubo sofrem apenas metade do dano da queda. Quando uma criatura dentro do cubo fizer um salto vertical, ela pode saltar até 3 metros mais alto do que o normal.", "en": "You take control of the air in a 100-foot cube that you can see within range. Choose one of the following effects when you cast the spell. The effect lasts for the spell’s duration, unless you use your action on a later turn to switch to a different effect. You can also use your action to temporarily halt the effect or to restart one you’ve halted.\n\nGusts. A wind picks up within the cube, continually blowing in a horizontal direction you designate. You choose the intensity of the wind: calm, moderate, or strong. If the wind is moderate or strong, ranged weapon attacks that pass through it or that are made against targets within the cube have disadvantage on their attack rolls. If the wind is strong, any creature moving against the wind must spend 1 extra foot of movement for each foot moved.\n\nDowndraft. You cause a sustained blast of strong wind to blow downward from the top of the cube. Ranged weapon attacks that pass through the cube or that are made against targets within it have disadvantage on their attack rolls. A creature must make a Strength saving throw if it flies into the cube for the first time on a turn or starts its turn there flying. On a failed save, the creature is knocked prone.\n\nUpdraft. You cause a sustained updraft within the cube, rising upward from the cube’s bottom side. Creatures that end a fall within the cube take only half damage from the fall. When a creature in the cube makes a vertical jump, the creature can jump up to 10 feet higher than normal."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "danseMacabre", "name": {"pt": "Dança Macabra", "en": "Danse Macabre"}, "level": 5, "school": "necromancy", "classes": ["warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Fios de poder sombrio saltam dos seus dedos para perfurar até cinco cadáveres Pequenos ou Médios que você possa ver dentro do alcance. Cada cadáver imediatamente se levanta e se torna um morto-vivo. Você decide se ele é um zumbi ou um esqueleto (as estatísticas para zumbis e esqueletos estão no Monster Manual), e ele ganha um bônus em suas jogadas de ataque e de dano igual ao seu modificador de atributo de conjuração.\n\nVocê pode usar uma ação bônus para comandar mentalmente as criaturas que criou com esta magia, emitindo o mesmo comando para todas elas. Para receber o comando, uma criatura deve estar a até 18 metros de você. Você decide qual ação as criaturas realizarão e para onde elas se moverão durante o próximo turno delas, ou pode emitir um comando geral, como guardar uma câmara ou passagem contra os seus inimigos. Se não emitir nenhum comando, as criaturas não fazem nada além de se defender contra criaturas hostis. Uma vez dada uma ordem, as criaturas continuam a segui-la até que sua tarefa seja concluída.\n\nAs criaturas ficam sob seu controle até a magia terminar, após o que se tornam inanimadas mais uma vez.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 6º círculo ou superior, você anima até dois cadáveres adicionais para cada círculo do espaço acima do 5º.", "en": "Threads of dark power leap from your fingers to pierce up to five Small or Medium corpses you can see within range. Each corpse immediately stands up and becomes undead. You decide whether it is a zombie or a skeleton (the statistics for zombies and skeletons are in the Monster Manual), and it gains a bonus to its attack and damage rolls equal to your spellcasting ability modifier.\n\nYou can use a bonus action to mentally command the creatures you make with this spell, issuing the same command to all of them. To receive the command, a creature must be within 60 feet of you. You decide what action the creatures will take and where they will move during their next turn, or you can issue a general command, such as to guard a chamber or passageway against your foes. If you issue no commands, the creature do nothing except defend themselves against hostile creatures. Once given an order, the creatures continue to follow it until their task is complete.\n\nThe creatures are under your control until the spell ends, after which they become inanimate once more.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, you animate up to two additional corpses for each slot level above 5th."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "dawn", "name": {"pt": "Aurora", "en": "Dawn"}, "level": 5, "school": "evocation", "classes": ["cleric", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S, M (a sunburst pendant worth at least 100 gp)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "A luz da alvorada brilha sobre um local que você especificar dentro do alcance. Até a magia terminar, um Cilindro de luz brilhante com 9 metros de raio e 12 metros de altura reluz ali. Essa luz é luz solar.\n\nQuando o cilindro aparece, cada criatura dentro dele deve fazer um teste de resistência de Constituição, sofrendo 4d10 de dano Radiante em uma falha na salvaguarda, ou metade desse dano em um sucesso. Uma criatura também deve fazer esse teste de resistência sempre que terminar o turno dela dentro do cilindro.\n\nSe você estiver a até 18 metros do cilindro, pode movê-lo em até 18 metros com uma ação bônus no seu turno.", "en": "The light of dawn shines down on a location you specify within range. Until the spell ends, a 30-foot-radius, 40-foot-high cylinder of bright light glimmers there. This light is sunlight.\n\nWhen the cylinder appears, each creature in it must make a Constitution saving throw, taking 4d10 radiant damage on a failed save, or half as much damage on a successful one. A creature must also make this saving throw whenever it ends its turn in the cylinder.\n\nIf you’re within 60 feet of the cylinder, you can move it up to 60 feet as a bonus action on your turn."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "enervation", "name": {"pt": "Enervação", "en": "Enervation"}, "level": 5, "school": "necromancy", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Uma gavinha de escuridão profunda se estende de você, tocando uma criatura que você possa ver dentro do alcance para drenar a vida dela. O alvo deve fazer um teste de resistência de Destreza. Em um sucesso na salvaguarda, o alvo sofre 2d8 de dano Necrótico e a magia termina. Em uma falha na salvaguarda, o alvo sofre 4d8 de dano Necrótico e, até a magia terminar, você pode usar sua ação em cada um dos seus turnos para automaticamente causar 4d8 de dano Necrótico ao alvo. A magia termina se você usar sua ação para fazer qualquer outra coisa, se o alvo em algum momento estiver fora do alcance da magia ou se o alvo tiver cobertura total contra você.\n\nSempre que a magia causar dano a um alvo, você recupera uma quantidade de Pontos de Vida igual à metade do dano Necrótico que o alvo sofreu.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 6º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 5º.", "en": "A tendril of inky darkness reaches out from you, touching a creature you can see within range to drain life from it. The target must make a Dexterity saving throw. On a successful save, the target takes 2d8 necrotic damage, and the spell ends. On a failed save, the target takes 4d8 necrotic damage, and until the spell ends, you can use your action on each of your turns to automatically deal 4d8 necrotic damage to the target. The spell ends if you use your action to do anything else, if the target is ever outside the spell’s range, or if the target has total cover from you.\n\nWhenever the spell deals damage to a target, you regain hit points equal to half the amount of necrotic damage the target takes.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "farStep", "name": {"pt": "Passo Distante", "en": "Far Step"}, "level": 5, "school": "conjuration", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Bonus Action", "range": "Self", "components": "V", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você se teletransporta em até 18 metros para um espaço desocupado que possa ver. Em cada um dos seus turnos antes da magia terminar, você pode usar uma ação bônus para se teletransportar dessa forma novamente.", "en": "You teleport up to 60 feet to an unoccupied space you can see. On each of your turns before the spell ends, you can use a bonus action to teleport in this way again."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "holyWeapon", "name": {"pt": "Arma Sagrada", "en": "Holy Weapon"}, "level": 5, "school": "evocation", "classes": ["cleric", "paladin"], "castingTime": "Bonus Action", "range": "Touch", "components": "V, S", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você imbui uma arma que tocar com poder sagrado. Até a magia terminar, a arma emite luz brilhante em um raio de 9 metros e penumbra por mais 9 metros adicionais. Além disso, ataques com armas feitos com ela causam 2d8 de dano Radiante adicional em um acerto. Se a arma ainda não for uma arma mágica, ela se torna uma pela duração.\n\nCom uma ação bônus no seu turno, você pode dissipar esta magia e fazer com que a arma emita uma explosão de radiação. Cada criatura à sua escolha que você possa ver a até 9 metros da arma deve fazer um teste de resistência de Constituição. Em uma falha na salvaguarda, uma criatura sofre 4d8 de dano Radiante e fica cega por 1 minuto. Em um sucesso na salvaguarda, uma criatura sofre metade desse dano e não fica cega. No final de cada um dos turnos dela, uma criatura cega pode fazer um teste de resistência de Constituição, encerrando o efeito sobre si mesma em um sucesso.", "en": "You imbue a weapon you touch with holy power. Until the spell ends, the weapon emits bright light in a 30-foot radius and dim light for an additional 30 feet. In addition, weapon attacks made with it deal an extra 2d8 radiant damage on a hit. If the weapon isn’t already a magic weapon, it becomes one for the duration.\n\nAs a bonus action on your turn, you can dismiss this spell and cause the weapon to emit a burst of radiance. Each creature of your choice that you can see within 30 feet of the weapon must make a Constitution saving throw. On a failed save, a creature takes 4d8 radiant damage, and it is blinded for 1 minute. On a successful save, a creature takes half as much damage and isn’t blinded. At the end of each of its turns, a blinded creature can make a Constitution saving throw, ending the effect on itself on a success."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "immolation", "name": {"pt": "Imolação", "en": "Immolation"}, "level": 5, "school": "evocation", "classes": ["sorcerer", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "V", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Chamas envolvem uma criatura que você possa ver dentro do alcance. O alvo deve fazer um teste de resistência de Destreza. Ele sofre 8d6 de dano de Fogo em uma falha na salvaguarda, ou metade desse dano em um sucesso. Em uma falha na salvaguarda, o alvo também continua queimando pela duração da magia. O alvo em chamas emite luz brilhante em um raio de 9 metros e penumbra por mais 9 metros adicionais. No final de cada um dos turnos dele, o alvo repete o teste de resistência. Ele sofre 4d6 de dano de Fogo em uma falha na salvaguarda, e a magia termina em um sucesso. Essas chamas mágicas não podem ser extintas por meios não mágicos.\n\nSe o dano desta magia matar um alvo, ele é reduzido a cinzas.", "en": "Flames wreathe one creature you can see within range. The target must make a Dexterity saving throw. It takes 8d6 fire damage on a failed save, or half as much damage on a successful one. On a failed save, the target also burns for the spell’s duration. The burning target sheds bright light in a 30-foot radius and dim light for an additional 30 feet. At the end of each of its turns, the target repeats the saving throw. It takes 4d6 fire damage on a failed save, and the spell ends on a successful one. These magical flames can’t be extinguished by nonmagical means.\n\nIf damage from this spell kills a target, the target is turned to ash."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "infernalCalling", "name": {"pt": "Chamado Infernal", "en": "Infernal Calling"}, "level": 5, "school": "conjuration", "classes": ["warlock", "wizard"], "castingTime": "1 minute", "range": "90 feet", "components": "V, S, M (a ruby worth at least 999 gp)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Proferindo um encantamento sombrio, você invoca um diabo dos Nove Infernos. Você escolhe o tipo do diabo, que deve ser de nível de desafio 6 ou menor, como um diabo farpado ou um diabo barbado. O diabo aparece em um espaço desocupado que você possa ver dentro do alcance. O diabo desaparece quando cai a 0 Pontos de Vida ou quando a magia termina.\n\nO diabo é hostil contra você e seus companheiros. Role iniciativa para o diabo, que tem seus próprios turnos. Ele fica sob o controle do Mestre e age de acordo com sua natureza em cada um dos turnos dele, o que pode resultar em ele atacar você se achar que pode prevalecer, ou tentar induzir você a praticar um ato maligno em troca de serviços limitados. O Mestre possui as estatísticas da criatura.\n\nEm cada um dos seus turnos, você pode tentar emitir um comando verbal ao diabo (nenhuma ação exigida de você). Ele obedece ao comando se o resultado provável estiver de acordo com os desejos dele, especialmente se o resultado levar você em direção ao mal. Do contrário, você deve fazer um teste de Carisma (Enganação, Intimidação ou Persuasão) resistido pelo teste de Sabedoria (Intuição) dele. Você faz o teste com vantagem se disser o nome verdadeiro do diabo. Se o seu teste falhar, o diabo se torna imune aos seus comandos verbais pela duração da magia, embora ainda possa executar seus comandos se desejar. Se o seu teste for bem-sucedido, o diabo executa seu comando — como \"ataque meus inimigos\", \"explore a sala adiante\" ou \"leve esta mensagem para a rainha\" — até concluir a atividade, momento em que retorna a você para relatar que o fez.\n\nSe a sua concentração terminar antes que a magia atinja a duração total, o diabo não desaparece se tiver se tornado imune aos seus comandos verbais. Em vez disso, ele age da maneira que escolher por 3d6 minutos e depois desaparece.\n\nSe você possuir o talismã individual de um diabo, você pode invocar aquele diabo se ele for do nível de desafio apropriado mais 1, e ele obedece a todos os seus comandos, sem necessidade de testes de Carisma.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 6º círculo ou superior, o nível de desafio aumenta em 1 para cada círculo do espaço acima do 5º.", "en": "Uttering a dark incantation, you summon a devil from the Nine Hells. You choose the devil’s type, which must be one of challenge rating 6 or lower, such as a barbed devil or a bearded devil. The devil appears in an unoccupied space that you can see within range. The devil disappears when it drops to 0 hit points or when the spell ends.\n\nThe devil is unfriendly toward you and your companions. Roll initiative for the devil, which has its own turns. It is under the Dungeon Master’s control and acts according to its nature on each of its turns, which might result in its attacking you if it thinks it can prevail, or trying to tempt you to undertake an evil act in exchange for limited service. The DM has the creature’s statistics.\n\nOn each of your turns, you can try to issue a verbal command to the devil (no action required by you). It obeys the command if the likely outcome is in accordance with its desires, especially if the result would draw you toward evil. Otherwise, you must make a Charisma (Deception, Intimidation, or Persuasion) check contested by its Wisdom (Insight) check. You make the check with advantage if you say the devil’s true name. If your check fails, the devil becomes immune to your verbal commands for the duration of the spell, though it can still carry out your commands if it chooses. If your check succeeds, the devil carries out your command---such as \"attack my enemies,\" \"explore the room ahead,\" or \"bear this message to the queen\"---until it completes the activity, at which point it returns to you to report having done so.\n\nIf your concentration ends before the spell reaches its full duration, the devil doesn’t disappear if it has become immune to your verbal commands. Instead, it acts in whatever manner it chooses for 3d6 minutes, and then it disappears.\n\nIf you possess an individual devil’s talisman, you can summon that devil if it is of the appropriate challenge rating plus 1, and it obeys all your commands, with no Charisma checks required.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the challenge rating increases by 1 for each slot level above 5th."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "maelstrom", "name": {"pt": "Turbilhão", "en": "Maelstrom"}, "level": 5, "school": "evocation", "classes": ["druid"], "castingTime": "Action", "range": "120 feet", "components": "V, S, M (paper or leaf in the shape of a funnel)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Uma massa rodopiante de água com 1,5 metro de profundidade surge em um raio de 9 metros centrado em um ponto que você possa ver dentro do alcance. O ponto deve estar no chão ou em um corpo d'água. Até a magia terminar, aquela área é terreno difícil, e qualquer criatura que começar o turno dela lá deve ser bem-sucedida em um teste de resistência de Força ou sofrerá 6d6 de dano Contundente e será puxada 3 metros em direção ao centro.", "en": "A swirling mass of 5-foot-deep water appears in a 30-foot radius centered on a point you can see within range. The point must be on ground or in a body of water. Until the spell ends, that area is difficult terrain, and any creature that starts its turn there must succeed on a Strength saving throw or take 6d6 bludgeoning damage and be pulled 10 feet toward the center."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "negativeEnergyFlood", "name": {"pt": "Inundação de Energia Negativa", "en": "Negative Energy Flood"}, "level": 5, "school": "necromancy", "classes": ["warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V, M (a broken bone and a square of black silk)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você dispara fitas de energia negativa contra uma criatura que possa ver dentro do alcance. A menos que o alvo seja um morto-vivo, ele deve fazer um teste de resistência de Constituição, sofrendo 5d12 de dano Necrótico em uma falha na salvaguarda, ou metade desse dano em um sucesso. Um alvo morto por esse dano se ergue como um zumbi no início do seu próximo turno. O zumbi persegue qualquer criatura que possa ver que esteja mais próxima dele. As estatísticas para o zumbi estão no Monster Manual.\n\nSe você alvejar um morto-vivo com esta magia, o alvo não faz teste de resistência. Em vez disso, role 5d12. O alvo ganha metade do total como Pontos de Vida Temporários.", "en": "You send ribbons of negative energy at one creature you can see within range. Unless the target is undead, it must make a Constitution saving throw, taking 5d12 necrotic damage on a failed save, or half as much damage on a successful one. A target killed by this damage rises up as a zombie at the start of your next turn. The zombie pursues whatever creature it can see that is closest to it. Statistics for the zombie are in the Monster Manual.\n\nIf you target an undead with this spell, the target doesn’t make a saving throw. Instead, roll 5d12. The target gains half the total as temporary hit points."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "skillEmpowerment", "name": {"pt": "Aprimorar Perícia", "en": "Skill Empowerment"}, "level": 5, "school": "transmutation", "classes": ["artificer", "bard", "sorcerer", "wizard"], "castingTime": "Action", "range": "Touch", "components": "V, S", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Sua magia aprofunda a compreensão de uma criatura sobre seu próprio talento. Você toca uma criatura voluntária e concede a ela especialização em uma perícia à sua escolha; até a magia terminar, a criatura dobra seu bônus de proficiência em testes de atributo que façam uso da perícia escolhida.\n\nVocê deve escolher uma perícia na qual o alvo seja proficiente e que já não esteja se beneficiando de um efeito, como Especialização, que dobre seu bônus de proficiência.", "en": "Your magic deepens a creature’s understanding of its own talent. You touch one willing creature and give it expertise in one skill of your choice; until the spell ends, the creature doubles its proficiency bonus for ability checks it makes that use the chosen skill.\n\nYou must choose a skill in which the target is proficient and that isn’t already benefiting from an effect, such as Expertise, that doubles its proficiency bonus."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "transmuteRock", "name": {"pt": "Transmutar Rocha", "en": "Transmute Rock"}, "level": 5, "school": "transmutation", "classes": ["artificer", "druid", "wizard"], "castingTime": "Action", "range": "120 feet", "components": "V, S, M (clay and water)", "duration": "Until dispelled", "ritual": false, "concentration": false, "desc": {"pt": "Você escolhe uma área de pedra ou lama que possa ver e que caiba em um cubo de 12 metros dentro do alcance, e escolhe um dos seguintes efeitos.\n\nTransmutar Pedra em Lama. Rocha não mágica de qualquer tipo na área se torna um volume igual de lama espessa e viscosa que permanece pela duração da magia.\n\nO chão na área da magia se torna lamacento o bastante para que as criaturas possam afundar nele. Cada metro que uma criatura se deslocar pela lama custa 4 metros de deslocamento, e qualquer criatura no chão quando você conjurar a magia deve fazer uma salvaguarda de Força. Uma criatura também deve fazer a salvaguarda quando se mover para a área pela primeira vez em um turno ou terminar o turno dela lá. Se falhar na salvaguarda, a criatura afunda na lama e fica impedida, embora possa usar uma ação para encerrar a condição impedido em si mesma puxando-se para fora da lama.\n\nSe você conjurar a magia em um teto, a lama cai. Qualquer criatura sob a lama quando ela cair deve fazer uma salvaguarda de Destreza. Uma criatura sofre 4d8 de dano contundente se falhar na salvaguarda, ou metade desse dano em um sucesso.\n\nTransmutar Lama em Pedra. Lama ou areia movediça não mágica na área com no máximo 3 metros de profundidade se transforma em pedra macia pela duração da magia. Qualquer criatura na lama quando ela se transformar deve fazer uma salvaguarda de Destreza. Em um sucesso na salvaguarda, a criatura é deslocada com segurança para a superfície em um espaço desocupado. Se falhar na salvaguarda, a criatura fica impedida pela rocha. Uma criatura impedida, ou outra criatura ao alcance, pode usar uma ação para tentar quebrar a rocha obtendo sucesso em um teste de Força CD 20 ou causando dano a ela. A rocha tem CA 15 e 25 pontos de vida, e é imune a dano de veneno e psíquico.", "en": "You choose an area of stone or mud that you can see that fits within a 40-foot cube and that is within range, and choose one of the following effects.\n\nTransmute Rock to Mud. Nonmagical rock of any sort in the area becomes an equal volume of thick, flowing mud that remains for the spell’s duration.\n\nThe ground in the spell’s area becomes muddy enough that creatures can sink into it. Each foot that a creature moves through the mud costs 4 feet of movement, and any creature on the ground when you cast the spell must make a Strength saving throw. A creature must also make the saving throw when it moves into the area for the first time on a turn or ends its turn there. On a failed save, a creature sinks into the mud and is restrained, though it can use an action to end the restrained condition on itself by pulling itself free of the mud.\n\nIf you cast the spell on a ceiling, the mud falls. Any creature under the mud when it falls must make a Dexterity saving throw. A creature takes 4d8 bludgeoning damage on a failed save, or half as much damage on a successful one.\n\nTransmute Mud to Rock. Nonmagical mud or quicksand in the area no more than 10 feet deep transforms into soft stone for the spell’s duration. Any creature in the mud when it transforms must make a Dexterity saving throw. On a successful save, a creature is shunted safely to the surface in an unoccupied space. On a failed save, a creature becomes restrained by the rock. A restrained creature, or another creature within reach, can use an action to try to break the rock by succeeding on a DC 20 Strength check or by dealing damage to it. The rock has AC 15 and 25 hit points, and is immune to poison and psychic damage."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "wallOfLight", "name": {"pt": "Muralha de Luz", "en": "Wall of Light"}, "level": 5, "school": "evocation", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "120 feet", "components": "V, S, M (a hand mirror)", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Uma muralha cintilante de luz brilhante surge em um ponto que você escolher dentro do alcance. A muralha surge em qualquer orientação que você escolher: horizontalmente, verticalmente ou diagonalmente. Ela pode ficar flutuando livremente ou repousar sobre uma superfície sólida. A muralha pode ter até 18 metros de comprimento, 3 metros de altura e 1,5 metro de espessura. A muralha bloqueia a linha de visão, mas criaturas e objetos podem passar através dela. Ela emite luz brilhante em até 36 metros e penumbra por mais 36 metros adicionais.\n\nQuando a muralha aparece, cada criatura em sua área deve fazer um teste de resistência de Constituição. Em uma falha na salvaguarda, uma criatura sofre 4d8 de dano Radiante e fica cega por 1 minuto. Em um sucesso na salvaguarda, ela sofre metade desse dano e não fica cega. Uma criatura cega pode fazer um teste de resistência de Constituição no final de cada um dos turnos dela, encerrando o efeito sobre si mesma em um sucesso.\n\nUma criatura que terminar o turno dela na área da muralha sofre 4d8 de dano Radiante.\n\nAté a magia terminar, você pode usar uma ação para disparar um feixe de radiação da muralha contra uma criatura que possa ver a até 18 metros dela. Faça um ataque mágico à distância. Em um acerto, o alvo sofre 4d8 de dano Radiante. Quer você acerte ou erre, reduza o comprimento da muralha em 3 metros. Se o comprimento da muralha cair para 0 metro, a magia termina.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 6º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 5º.", "en": "A shimmering wall of bright light appears at a point you choose within range. The wall appears in any orientation you choose: horizontally, vertically, or diagonally. It can be free floating, or it can rest on a solid surface. The wall can be up to 60 feet long, 10 feet high, and 5 feet thick. The wall blocks line of sight, but creatures and objects can pass through it. It emits bright light out to 120 feet and dim light for an additional 120 feet.\n\nWhen the wall appears, each creature in its area must make a Constitution saving throw. On a failed save, a creature takes 4d8 radiant damage, and it is blinded for 1 minute. On a successful save, it takes half as much damage and isn’t blinded. A blinded creature can make a Constitution saving throw at the end of each of its turns, ending the effect on itself on a success.\n\nA creature that ends its turn in the wall’s area takes 4d8 radiant damage.\n\nUntil the spell ends, you can use an action to launch a beam of radiance from the wall at one creature you can see within 60 feet of it. Make a ranged spell attack. On a hit, the target takes 4d8 radiant damage. Whether you hit or miss, reduce the length of the wall by 10 feet. If the wall’s length drops to 0 feet, the spell ends.\n\nAt Higher Levels. When you cast this spell using a spell slot of 6th level or higher, the damage increases by 1d8 for each slot level above 5th."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "wrathOfNature", "name": {"pt": "Ira da Natureza", "en": "Wrath of Nature"}, "level": 5, "school": "evocation", "classes": ["druid", "ranger"], "castingTime": "Action", "range": "120 feet", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você clama aos espíritos da natureza para despertá-los contra seus inimigos. Escolha um ponto que possa ver dentro do alcance. Os espíritos fazem com que árvores, rochas e relvas em um Cubo de 18 metros centrado naquele ponto se animem até a magia terminar.\n\nRelvas e Vegetação Rasteira. Qualquer área de solo no cubo que esteja coberta por relva ou vegetação rasteira é terreno difícil para os seus inimigos.\n\nÁrvores. No início de cada um dos seus turnos, cada um dos seus inimigos a até 3 metros de qualquer árvore no cubo deve ser bem-sucedido em um teste de resistência de Destreza ou sofrerá 4d6 de dano Cortante de galhos chicoteantes.\n\nRaízes e Cipós. No final de cada um dos seus turnos, uma criatura à sua escolha que esteja no chão no cubo deve ser bem-sucedida em um teste de resistência de Força ou ficará impedida até a magia terminar. Uma criatura impedida pode usar uma ação para fazer um teste de Força (Atletismo) contra a CD de resistência da sua magia, encerrando o efeito sobre si mesma em um sucesso.\n\nRochas. Com uma ação bônus no seu turno, você pode fazer uma rocha solta no cubo ser arremessada contra uma criatura que possa ver no cubo. Faça um ataque mágico à distância contra o alvo. Em um acerto, o alvo sofre 3d8 de dano Contundente não mágico e deve ser bem-sucedido em um teste de resistência de Força ou cairá no chão (ficando caído).", "en": "You call out to the spirits of nature to rouse them against your enemies. Choose a point you can see within range. The spirits cause trees, rocks, and grasses in a 60-foot cube centered on that point to become animated until the spell ends.\n\nGrasses and Undergrowth. Any area of ground in the cube that is covered by grass or undergrowth is difficult terrain for your enemies.\n\nTrees. At the start of each of your turns, each of your enemies within 10 feet of any tree in the cube must succeed on a Dexterity saving throw or take 4d6 slashing damage from whipping branches.\n\nRoots and Vines. At the end of each of your turns, one creature of your choice that is on the ground in the cube must succeed on a Strength saving throw or become restrained until the spell ends. A restrained creature can use an action to make a Strength (Athletics) check against your spell save DC, ending the effect on itself on a success.\n\nRocks. As a bonus action on your turn, you can cause a loose rock in the cube to launch at a creature you can see in the cube. Make a ranged spell attack against the target. On a hit, the target takes 3d8 nonmagical bludgeoning damage, and it must succeed on a Strength saving throw or fall prone."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "bonesOfTheEarth", "name": {"pt": "Ossos da Terra", "en": "Bones of the Earth"}, "level": 6, "school": "transmutation", "classes": ["druid"], "castingTime": "Action", "range": "120 feet", "components": "V, S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você faz até seis pilares de pedra irromperem de locais no chão que possa ver dentro do alcance. Cada pilar é um cilindro com diâmetro de 1,5 metro e altura de até 9 metros. O chão onde um pilar surge deve ser largo o suficiente para o seu diâmetro, e você pode alvejar o solo sob uma criatura se ela for Média ou menor. Cada pilar tem CA 5 e 30 Pontos de Vida. Quando reduzido a 0 Pontos de Vida, um pilar desmorona em escombros, criando uma área de terreno difícil com raio de 3 metros que dura até os escombros serem limpos. Cada porção de 1,5 metro de diâmetro da área exige pelo menos 1 minuto para ser limpa manualmente.\n\nSe um pilar for criado sob uma criatura, essa criatura deve ser bem-sucedida em um teste de resistência de Destreza ou será erguida pelo pilar. Uma criatura pode escolher falhar voluntariamente na salvaguarda.\n\nSe um pilar for impedido de atingir sua altura total devido a um teto ou outro obstáculo, uma criatura sobre o pilar sofre 6d6 de dano Contundente e fica impedida, prensada entre o pilar e o obstáculo. A criatura impedida pode usar uma ação para fazer um teste de Força ou Destreza (à escolha da criatura) contra a CD de resistência da magia. Em um sucesso, a criatura não fica mais impedida e deve ou sair do pilar ou cair dele.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 7º círculo ou superior, você pode criar dois pilares adicionais para cada círculo do espaço acima do 6º.", "en": "You cause up to six pillars of stone to burst from places on the ground that you can see within range. Each pillar is a cylinder that has a diameter of 5 feet and a height of up to 30 feet. The ground where a pillar appears must be wide enough for its diameter, and you can target ground under a creature if that creature is Medium or smaller. Each pillar has AC 5 and 30 hit points. When reduced to 0 hit points, a pillar crumbles into rubble, which creates an area of difficult terrain with a 10-foot radius that lasts until the rubble is cleared. Each 5-foot diameter portion of the area requires at least 1 minute to clear by hand.\n\nIf a pillar is created under a creature, that creature must succeed on a Dexterity saving throw or be lifted by the pillar. A creature can choose to fail the save.\n\nIf a pillar is prevented from reaching its full height because of a ceiling or other obstacle, a creature on the pillar takes 6d6 bludgeoning damage and is restrained, pinched between the pillar and the obstacle. The restrained creature can use an action to make a Strength or Dexterity check (the creature’s choice) against the spell’s save DC. On a success, the creature is no longer restrained and must either move off the pillar or fall off it.\n\nAt Higher Levels. When you cast this spell using a spell slot of 7th level or higher, you can create two additional pillars for each slot level above 6th."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "createHomunculus", "name": {"pt": "Criar Homúnculo", "en": "Create Homunculus"}, "level": 6, "school": "transmutation", "classes": ["wizard"], "castingTime": "1 hour", "range": "Touch", "components": "V, S, M (clay, ash, and mandrake root, all of which the spell consumes, and a jewel-encrusted dagger worth at least 1,000 gp)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Enquanto pronuncia um encantamento complexo, você se corta com uma adaga incrustada de joias, sofrendo 2d4 de dano Perfurante que não pode ser reduzido de nenhuma forma. Você então pinga seu sangue sobre os outros componentes da magia e os toca, transformando-os em um constructo especial chamado homúnculo.\n\nAs estatísticas do homúnculo estão no Monster Manual. Ele é seu companheiro fiel e morre se você morrer. Sempre que você terminar um Descanso Longo, pode gastar até metade dos seus Dados de Vida se o homúnculo estiver no mesmo plano de existência que você. Ao fazer isso, role cada dado e adicione seu modificador de Constituição a ele. O seu máximo de Pontos de Vida é reduzido por esse total, e o máximo de Pontos de Vida e os Pontos de Vida atuais do homúnculo aumentam por ele. Esse processo não pode reduzir você a menos de 1 Ponto de Vida, e a alteração nos seus Pontos de Vida e nos do homúnculo termina quando você terminar seu próximo Descanso Longo. A redução no seu máximo de Pontos de Vida não pode ser removida por nenhum meio antes disso, exceto pela morte do homúnculo.\n\nVocê pode ter apenas um homúnculo por vez. Se você conjurar esta magia enquanto seu homúnculo estiver vivo, a magia falha.", "en": "While speaking an intricate incantation, you cut yourself with a jewel-encrusted dagger, taking 2d4 piercing damage that can’t be reduced in any way. You then drip your blood on the spell’s other components and touch them, transforming them into a special construct called a homunculus.\n\nThe statistics of the homunculus are in the Monster Manual. It is you faithful companion, and it dies if you die. Whenever you finish a long rest, you can spend up to half your Hit Dice if the homunculus is on the same plane of existence as you. When you do so, roll each die and add your Constitution modifier to it. Your hit point maximum is reduced by that total, and the homunculus’s hit point maximum and current hit points are both increased by it. This process can reduce you to no lower than 1 hit point, and the change to your and the homunculus’s hit points ends when you finish your next long rest. The reduction your hit point maximum can’t be removed by any means before then, except by the homunculus’s death.\n\nYou can have only one homunculus at a time. If you cast this spell while your homunculus lives, the spell fails."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "druidGrove", "name": {"pt": "Bosque Druídico", "en": "Druid Grove"}, "level": 6, "school": "abjuration", "classes": ["druid"], "castingTime": "10 minutes", "range": "Touch", "components": "V, S, M (mistletoe, which the spell consumes, that was harvested with a golden sickle under the light of a full moon)", "duration": "24 hours", "ritual": false, "concentration": false, "desc": {"pt": "Você invoca os espíritos da natureza para proteger uma área ao ar livre ou subterrânea. A área pode ser tão pequena quanto um Cubo de 9 metros ou tão grande quanto um Cubo de 27 metros. Edifícios e outras estruturas são excluídos da área afetada. Se você conjurar esta magia na mesma área todos os dias durante um ano, a magia dura até ser dissipada.\n\nA magia cria os seguintes efeitos dentro da área. Quando você conjurar esta magia, pode especificar criaturas como amigas que sejam imunes aos efeitos. Você também pode especificar uma palavra-passe que, quando dita em voz alta, torna quem a pronunciou imune a esses efeitos.\n\nToda a área protegida irradia magia. Uma magia Dissipar Magia conjurada sobre a área, se bem-sucedida, remove apenas um dos seguintes efeitos, não a área inteira. O conjurador daquela magia escolhe qual efeito encerrar. Apenas quando todos os seus efeitos desaparecerem esta magia é dissipada.\n\nNévoa Sólida. Você pode preencher qualquer quantidade de quadrados de 1,5 metro no chão com névoa espessa, tornando-os pesadamente obscurecidos. A névoa atinge 3 metros de altura. Além disso, cada metro de movimento através da névoa custa 2 metros extras. Para uma criatura imune a este efeito, a névoa não obscurece nada e se parece com uma névoa suave, com fagulhas de luz verde flutuando no ar.\n\nVegetação Agarradora. Você pode preencher qualquer quantidade de quadrados de 1,5 metro no chão que não estejam preenchidos com névoa com ervas daninhas e cipós agarradores, como se estivessem afetados por uma magia Constrição. Para uma criatura imune a este efeito, as ervas daninhas e os cipós parecem macios e se remodelam para servir como assentos ou camas temporárias.\n\nGuardiões do Bosque. Você pode animar até quatro árvores na área, fazendo com que elas se desenraizem do chão. Essas árvores têm as mesmas estatísticas de uma árvore desperta, que aparece no Monster Manual, exceto que não podem falar e sua casca é coberta por símbolos druídicos. Se qualquer criatura não imune a este efeito entrar na área protegida, os guardiões do bosque lutam até afugentar ou matar os invasores. Os guardiões do bosque também obedecem aos seus comandos orais (nenhuma ação exigida de você) que você emitir enquanto estiver na área. Se você não der comandos a eles e nenhum invasor estiver presente, os guardiões do bosque não fazem nada. Os guardiões do bosque não podem deixar a área protegida. Quando a magia termina, a magia que os anima desaparece e as árvores criam raízes novamente, se possível.\n\nEfeito Mágico Adicional. Você pode colocar uma de sua escolha entre as seguintes magias dentro da área protegida:\n\nUma Rajada de Vento constante em dois locais à sua escolha\n\nCrescimento de Espinhos em um local à sua escolha\n\nMuralha de Vento em dois locais à sua escolha\n\nPara uma criatura imune a este efeito, os ventos são uma brisa suave e aromática, e a área de crescimento de espinhos é inofensiva.", "en": "You invoke the spirits of nature to protect an area outdoors or underground. The area can be as small as a 30-foot cube or as large as 90-foot cube. Buildings and other structures are excluded from the affected area. If you can cast this spell in the same area every day for a year, the spell lasts until dispelled.\n\nThe spell creates the following effects within the area. When you cast this spell, you can specify creatures as friends who are immune to the effects. You can also specify a password that, when spoken aloud, makes the speaker immune to these effects.\n\nThe entire warded area radiates magic. A Dispel Magic cast on the area, if successful, removes only one of the following effects, not the entire area. That spell’s caster chooses which effect to end. Only when all its effects are gone is this spell dispelled.\n\nSolid Fog. You can fill any number of 5-foot squares on the ground with thick fog, making them heavily obscured. The fog reaches 10 feet high. In addition, every foot of movement through the fog costs 2 extra feet. To a creature immune to this effect, the fog obscures nothing and looks like soft mist, with motes of green light floating in the air.\n\nGrasping Undergrowth. You can fill any number of 5-foot squares on the ground that aren’t filled with fog with grasping weeds and vines, as if they were affected by an Entangle spell. To a creature immune to this effect the weeds and vines feel soft and reshape themselves to serve as temporary seats or beds.\n\nGrove Guardians. You can animate up to four trees in the area, causing them to uproot themselves from the ground. These trees have the same statistics as an awakened tree, which appears in the Monster Manual, except they can’t speak, and their bark is covered with druidic symbols. If any creature not immune to this effect enters the warded area, the grove guardians fight until they have driven off or slain the intruders. The grove guardians also obey your spoken commands (no action required by you) that you issue while in the area. If you don’t give them commands and no intruders are present, the grove guardians do nothing. The grove guardians can’t leave the warded area. When the spell ends, the magic animating them disappears, and the trees take root again if possible.\n\nAdditional Spell Effect. You can place your choice of one of the following magical effects within the warded area:\n\nA constant Gust of Wind in two locations of your choice\n\nSpike Growth in one location of your choice\n\nWind Wall* in two locations of your choice\n\nTo a creature immune to this effect, the winds are a fragrant, gentle breeze, and the area of spike growth is harmless."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "investitureOfFlame", "name": {"pt": "Investidura de Chamas", "en": "Investiture of Flame"}, "level": 6, "school": "transmutation", "classes": ["druid", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "Self", "components": "V, S", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Chamas percorrem seu corpo, emitindo luz brilhante em um raio de 9 metros e penumbra por mais 9 metros adicionais pela duração da magia. As chamas não causam dano a você. Até a magia terminar, você ganha os seguintes benefícios:\n\nVocê é imune a dano de Fogo e tem resistência a dano de Frio.\n\nQualquer criatura que se mover a até 1,5 metro de você pela primeira vez em um turno ou terminar o turno dela ali sofre 1d10 de dano de Fogo.\n\n* Você pode usar sua ação para criar uma linha de fogo com 4,5 metros de comprimento e 1,5 metro de largura estendendo-se de você em uma direção que escolher. Cada criatura na linha deve fazer um teste de resistência de Destreza. Uma criatura sofre 4d8 de dano de Fogo em uma falha na salvaguarda, ou metade desse dano em um sucesso.", "en": "Flames race across your body, shedding bright light in a 30-foot radius and dim light for an additional 30 feet for the spell’s duration. The flames don’t harm you. Until the spell ends, you gain the following benefits:\n\nYou are immune to fire damage and have resistance to cold damage.\n\nAny creature that moves within 5 feet of you for the first time on a turn or ends its turn there takes 1d10 fire damage.\n\n* You can use your action to create a line of fire 15 feet long and 5 feet wide extending from you in a direction you choose. Each creature in the line must make a Dexterity saving throw. A creature takes 4d8 fire damage on a failed save, or half as much damage on a successful one."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "investitureOfIce", "name": {"pt": "Investidura de Gelo", "en": "Investiture of Ice"}, "level": 6, "school": "transmutation", "classes": ["druid", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "Self", "components": "V, S", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Até a magia acabar, o gelo cobre seu corpo com uma crosta de geada, e você ganha os seguintes benefícios:\n\nVocê é imune a dano de frio e tem resistência a dano de fogo.\n\nVocê pode se mover através de terreno difícil criado por gelo ou neve sem gastar movimento adicional.\n\nO chão em um raio de 3 metros ao seu redor fica congelado e é terreno difícil para criaturas que não sejam você. O raio se move com você.\n\nVocê pode usar sua ação para criar um cone de 4,5 metros de vento congelante que se estende de sua mão estendida na direção que você escolher. Cada criatura no cone deve fazer uma salvaguarda de Constituição. Uma criatura sofre 4d6 de dano de frio se falhar na salvaguarda, ou metade desse dano se obtiver sucesso. Uma criatura que falhar na salvaguarda contra este efeito tem seu deslocamento reduzido pela metade até o início do seu próximo turno.", "en": "Until the spell ends, ice rimes your body, and you gain the following benefits:\n\nYou are immune to cold damage and have resistance to fire damage.\n\nYou can move across difficult terrain created by ice or snow without spending extra movement.\n\nThe ground in a 10-foot radius around you is icy and is difficult terrain for creatures other than you. The radius moves with you.\n\nYou can use your action to create a 15-foot cone of freezing wind extending from your outstretched hand in a direction you choose. Each creature in the cone must make a Constitution saving throw. A creature takes 4d6 cold damage on a failed save, or half as much damage on a successful one. A creature that fails its save against this effect has its speed halved until the start of your next turn."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "investitureOfStone", "name": {"pt": "Investidura de Pedra", "en": "Investiture of Stone"}, "level": 6, "school": "transmutation", "classes": ["druid", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "Self", "components": "V, S", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Até a magia acabar, pedaços de rocha se espalham pelo seu corpo, e você ganha os seguintes benefícios:\n\nVocê tem resistência a dano contundente, perfurante e cortante de ataques não mágicos.\n\nVocê pode usar sua ação para criar um pequeno terremoto no chão em um raio de 4,5 metros centrado em você. Outras criaturas naquele chão devem ser bem-sucedidas em uma salvaguarda de Destreza ou cairão no chão.\n\n* Você pode se mover através de terreno difícil feito de terra ou pedra sem gastar movimento adicional. Você pode se mover através de terra ou pedra sólida como se fosse ar e sem desestabilizá-la, mas não pode terminar seu movimento ali. Se o fizer, você é ejetado para o espaço desocupado mais próximo, esta magia termina e você fica atordoado até o final do seu próximo turno.", "en": "Until the spell ends, bits of rock spread across your body, and you gain the following benefits:\n\nYou have resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks.\n\nYou can use your action to create a small earthquake on the ground in a 15-foot radius centered on you. Other creatures on that ground must succeed on a Dexterity saving throw or be knocked prone.\n\n* You can move across difficult terrain made of earth or stone without spending extra movement. You can move through solid earth or stone as if it was air and without destabilizing it, but you can’t end your movement there. If you do so, you are ejected to the nearest unoccupied space, this spell ends, and you are stunned until the end of your next turn."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "investitureOfWind", "name": {"pt": "Investidura de Vento", "en": "Investiture of Wind"}, "level": 6, "school": "transmutation", "classes": ["druid", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "Self", "components": "V, S", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Até a magia acabar, o vento rodopia ao seu redor, e você ganha os seguintes benefícios:\n\nAtaques com armas à distância feitos contra você têm desvantagem na jogada de ataque.\n\nVocê ganha um deslocamento de voo de 18 metros. Se você ainda estiver voando quando a magia acabar, você cai, a menos que possa de alguma forma evitar isso.\n\n* Você pode usar sua ação para criar um cubo de 4,5 metros de vento rodopiante centrado em um ponto que você possa ver a até 18 metros de você. Cada criatura naquela área deve fazer uma salvaguarda de Constituição. Uma criatura sofre 2d10 de dano contundente se falhar na salvaguarda, ou metade desse dano se obtiver sucesso. Se uma criatura Grande ou menor falhar na salvaguarda, essa criatura também é empurrada até 3 metros para longe do centro do cubo.", "en": "Until the spell ends, wind whirls around you, and you gain the following benefits:\n\nRanged weapon attacks made against you have disadvantage on the attack roll.\n\nYou gain a flying speed of 60 feet. If you are still flying when the spell ends, you fall, unless you can somehow prevent it.\n\n* You can use your action to create a 15-foot cube of swirling wind centered on a point you can see within 60 feet of you. Each creature in that area must make a Constitution saving throw. A creature takes 2d10 bludgeoning damage on a failed save, or half as much damage on a successful one. If a Large or smaller creature fails the save, that creature is also pushed up to 10 feet away from the center of the cube."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "mentalPrison", "name": {"pt": "Prisão Mental", "en": "Mental Prison"}, "level": 6, "school": "illusion", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você tenta prender uma criatura dentro de uma cela ilusória que somente ela percebe. Uma criatura que você possa ver dentro do alcance deve fazer uma salvaguarda de Inteligência. O alvo é bem-sucedido automaticamente se for imune à condição enfeitiçado. Em uma salvaguarda bem-sucedida, o alvo sofre 5d10 de dano psíquico, e a magia termina. Em uma falha na salvaguarda, o alvo sofre 5d10 de dano psíquico, e você faz com que a área imediatamente ao redor do espaço do alvo pareça perigosa para ele de alguma forma. Você pode fazer com que o alvo se percebe cercado por fogo, navalhas flutuantes ou mandíbulas horrendas repletas de dentes gotejantes. Qualquer que seja a forma da ilusão, o alvo não pode ver nem ouvir nada além dela e fica impedido pela duração da magia. Se o alvo for movido para fora da ilusão, fizer um ataque corpo a corpo através dela ou estender qualquer parte do seu corpo através dela, o alvo sofre 10d10 de dano psíquico, e a magia termina.", "en": "You attempt to bind a creature within an illusory cell that only it perceives. One creature you can see within range must make an Intelligence saving throw. The target succeeds automatically if it is immune to being charmed. On a successful save, the target takes 5d10 psychic damage, and the spell ends. On a failed save, the target takes 5d10 psychic damage, and you make the area immediately around the target’s space appear dangerous to it in some way. You might cause the target to perceive itself as being surrounded by fire, floating razors, or hideous maws filled with dripping teeth. Whatever form the illusion takes, the target can’t see or hear anything beyond it and is restrained for the spell’s duration. If the target is moved out of the illusion, makes a melee attack through it, or reaches any part of its body through it, the target takes 10d10 psychic damage, and the spell ends."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "primordialWard", "name": {"pt": "Proteção Primordial", "en": "Primordial Ward"}, "level": 6, "school": "abjuration", "classes": ["druid"], "castingTime": "Action", "range": "Self", "components": "V, S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Você tem resistência a dano de ácido, frio, fogo, elétrico e trovejante pela duração da magia.\n\nQuando sofrer dano de um desses tipos, você pode usar sua reação para ganhar imunidade àquele tipo de dano, incluindo contra o dano desencadeador. Se o fizer, as resistências terminam, e você mantém a imunidade até o final do seu próximo turno, momento em que a magia termina.", "en": "You have resistance to acid, cold, fire, lightning, and thunder damage for the spell’s duration.\n\nWhen you take damage of one of those types, you can use your reaction to gain immunity to that type of damage, including against the triggering damage. If you do so, the resistances end, and you have the immunity until the end of your next turn, at which time the spell ends."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "scatter", "name": {"pt": "Dispersar", "en": "Scatter"}, "level": 6, "school": "conjuration", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "30 feet", "components": "V", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "O ar estremece ao redor de até cinco criaturas à sua escolha que você possa ver dentro do alcance. Uma criatura relutante deve ser bem-sucedida em uma salvaguarda de Sabedoria para resistir a esta magia. Você teletransporta cada alvo afetado para um espaço desocupado que possa ver a até 36 metros de você. Esse espaço deve ser no solo ou em um piso.", "en": "The air quivers around up to five creatures of your choice that you can see within range. An unwilling creature must succeed on a Wisdom saving throw to resist this spell. You teleport each affected target to an unoccupied space that you can see within 120 feet of you. That space must be on the ground or on a floor."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "soulCage", "name": {"pt": "Gaiola de Almas", "en": "Soul Cage"}, "level": 6, "school": "necromancy", "classes": ["warlock", "wizard"], "castingTime": "Reaction, which you take when a humanoid you can see within 60 feet of you dies", "range": "60 feet", "components": "V, S, M (a tiny silver cage worth 100 gp)", "duration": "8 hours", "ritual": false, "concentration": false, "desc": {"pt": "Esta magia arrebata a alma de um humanoide no momento de sua morte e a aprisiona dentro da minúscula gaiola que você usa como componente material. Uma alma roubada permanece dentro da gaiola até a magia acabar ou até você destruir a gaiola, o que encerra a magia. Enquanto mantiver uma alma dentro da gaiola, você pode explorá-la de qualquer uma das maneiras descritas abaixo. Você pode usar uma alma aprisionada até seis vezes. Uma vez que explore uma alma pela sexta vez, ela é libertada e a magia termina. Enquanto a alma estiver aprisionada, o humanoide morto do qual ela se originou não pode ser revivido.\n\nRoubar Vida. Você pode usar uma ação bônus para drenar vigor da alma e recuperar 2d8 Pontos de Vida.\n\nInterrogar Alma. Você faz uma pergunta à alma (nenhuma ação necessária) e recebe uma resposta telepática breve, a qual você pode compreender independentemente do idioma utilizado. A alma sabe apenas o que sabia em vida, mas deve responder a você com sinceridade e com o melhor de sua capacidade. A resposta não tem mais do que uma ou duas frases e pode ser enigmática.\n\nTomar Experiência Emprestada. Você pode usar uma ação bônus para fortalecer a si mesmo com a experiência de vida da alma, realizando sua próxima jogada de ataque, teste de habilidade ou salvaguarda com vantagem. Se você não usar esse benefício antes do início do seu próximo turno, ele é perdido.\n\nOlhos dos Mortos. Você pode usar uma ação para nomear um lugar que o humanoide viu em vida, o que cria um sensor invisível em algum ponto daquele lugar se ele estiver no mesmo plano de existência em que você se encontra atualmente. O sensor permanece enquanto você se concentrar, até 10 minutos (como se estivesse se concentrando em uma magia). Você recebe informações visuais e auditivas do sensor como se estivesse no espaço dele usando seus próprios sentidos.\n\nUma criatura capaz de ver o sensor (como alguém usando ver o invisível ou visão verdadeira) vê uma imagem translúcida do humanoide atormentado cuja alma você aprisionou.", "en": "This spell snatches the soul of a humanoid as it dies and traps it inside the tiny cage you use for the material component. A stolen soul remains inside the cage until the spell ends or until you destroy the cage, which ends the spell. While you have a soul inside the cage, you can exploit it in any of the ways described below. You can use a trapped soul up to six times. Once you exploit a soul for the sixth time, it is released, and the spell ends. While a soul is trapped, the dead humanoid it came from can’t be revived.\n\nSteal Life. You can use a bonus action to drain vigor from the soul and regain 2d8 hit points.\n\nQuery Soul. You ask the soul a question (no action required) and receive a brief telepathic answer, which you can understand regardless of the language used. The soul knows only what it knew in life, but it must answer you truthfully and to the best of its ability. The answer is no more than a sentence or two and might be cryptic.\n\nBorrow Experience. You can use a bonus action to bolster yourself with the soul’s life experience, making your next attack roll, ability check, or saving throw with advantage. If you don’t use this benefit before the start of your next turn, it is lost.\n\nEyes of the Dead. You can use an action to name a place the humanoid saw in life, which creates an invisible sensor somewhere in that place if it is on the plane of existence you’re currently on. The sensor remains for as long as you concentrate, up to 10 minutes (as if you were concentrating on a spell). You receive visual and auditory information from the sensor as if you were in its space using your senses.\n\nA creature that can see the sensor (such as one using see invisibility or truesight) sees a translucent image of the tormented humanoid whose soul you caged."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "tensersTransformation", "name": {"pt": "Transformação de Tenser", "en": "Tenser's Transformation"}, "level": 6, "school": "transmutation", "classes": ["wizard"], "castingTime": "Action", "range": "Self", "components": "V, S, M (a few hairs from a bull)", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Você se dota de resistência e proeza marcial alimentadas por magia. Até a magia acabar, você não pode conjurar magias e ganha os seguintes benefícios:\n\n- Você ganha 50 Pontos de Vida Temporários. Se algum deles restar quando a magia terminar, ele é perdido.\n- Você tem vantagem em jogadas de ataque feitas com armas simples e marciais.\n- Quando você atinge um alvo com um ataque com arma, esse alvo sofre 2d12 de dano de força adicional.\n- Você tem proficiência com todas as armaduras, escudos, armas simples e armas marciais.\n- Você tem proficiência em salvaguardas de Força e Constituição.\n- Você pode atacar duas vezes, em vez de uma, sempre que realizar a ação de Ataque no seu turno. Você ignora este benefício se já possuir uma característica, como Ataque Extra, que conceda ataques adicionais.\n\nImediatamente após a magia acabar, você deve ser bem-sucedido em uma salvaguarda de Constituição CD 15 ou sofrerá um nível de exaustão.", "en": "You endow yourself with endurance and martial prowess fueled by magic. Until the spell ends, you can’t cast spells, and you gain the following benefits:\n\n- You gain 50 temporary hit points. If any of these remain when the spell ends, they are lost.\n- You have advantage on attack rolls that you make with simple and martial weapons.\n- When you hit a target with a weapon attack, that target takes an extra 2d12 force damage.\n- You have proficiency with all armor, shields, simple weapons, and martial weapons.\n- You have proficiency in Strength and Constitution saving throws.\n- You can attack twice, instead of once, when you take the Attack action on your turn. You ignore this benefit if you already have a feature, like Extra Attack, that gives you extra attacks.\n\nImmediately after the spell ends, you must succeed on a DC 15 Constitution saving throw or suffer one level of exhaustion."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "crownOfStars", "name": {"pt": "Coroa de Estrelas", "en": "Crown of Stars"}, "level": 7, "school": "evocation", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "Self", "components": "V, S", "duration": "1 hour", "ritual": false, "concentration": false, "desc": {"pt": "Sete partículas de luz semelhantes a estrelas surgem e orbitam sua cabeça até a magia acabar. Você pode usar uma ação bônus para disparar uma das partículas em direção a uma criatura ou objeto a até 36 metros de você. Ao fazê-lo, faça um ataque mágico à distância. Em um acerto, o alvo sofre 4d12 de dano radiante. Acertando ou errando, a partícula é gasta. A magia termina antecipadamente se você gastar a última partícula.\n\nSe ainda restarem quatro ou mais partículas, elas emitem luz brilhante em um raio de 9 metros e meia-luz por 9 metros adicionais. Se restarem de uma a três partículas, elas emitem meia-luz em um raio de 9 metros.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 8º círculo ou superior, o número de partículas criadas aumenta em duas para cada círculo do espaço acima do 7º.", "en": "Seven star-like motes of light appear and orbit your head until the spell ends. You can use a bonus action to send one of the motes streaking toward one creature or object within 120 feet of you. When you do so, make a ranged spell attack. On a hit, the target takes 4d12 radiant damage. Whether you hit or miss, the mote is expended. The spell ends early if you expend the last mote.\n\nIf you have four or more motes remaining, they shed bright light in a 30-foot radius and dim light for an additional 30 feet. If you have one to three motes remaining, they shed dim light in a 30-foot radius.\n\nAt Higher Levels. When you cast this spell using a spell slot of 8th level or higher, the number of motes created increases by two for each slot level above 7th."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "powerWordPain", "name": {"pt": "Palavra de Poder: Dor", "en": "Power Word Pain"}, "level": 7, "school": "enchantment", "classes": ["sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "60 feet", "components": "V", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você profere uma palavra de poder que faz ondas de dor intensa assolarem uma criatura que você possa ver dentro do alcance. Se o alvo tiver 100 Pontos de Vida ou menos, ele é submetido a uma dor incapacitante. Caso contrário, a magia não tem efeito sobre ele. Um alvo também não é afetado se for imune à condição enfeitiçado.\n\nEnquanto o alvo estiver sob o efeito da dor incapacitante, qualquer deslocamento que possua não pode ser superior a 3 metros. O alvo também tem desvantagem em jogadas de ataque, testes de habilidade e salvaguardas, com exceção de salvaguardas de Constituição. Por fim, se o alvo tentar conjurar uma magia, deve primeiro obter sucesso em uma salvaguarda de Constituição, ou a conjuração falha e a magia é desperdiçada.\n\nUm alvo que esteja sofrendo essa dor pode fazer uma salvaguarda de Constituição no final de cada um dos turnos dele. Em uma salvaguarda bem-sucedida, a dor termina.", "en": "You speak a word of power that causes waves of intense pain to assail one creature you can see within range. If the target has 100 hit points or fewer, it is subject to crippling pain. Otherwise, the spell has no effect on it. A target is also unaffected if it is immune to being charmed.\n\nWhile the target is affected by crippling pain, any speed it has can be no higher than 10 feet. The target also has disadvantage on attack rolls, ability checks, and saving throws, other than Constitution saving throws. Finally, if the target tries to cast a spell, it must ﬁrst succeed on a Constitution saving throw, or the casting fails and the spell is wasted.\n\nA target suffering this pain can make a Constitution saving throw at the end of each of its turns. On a successful save, the pain ends."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "templeOfTheGods", "name": {"pt": "Templo dos Deuses", "en": "Temple of the Gods"}, "level": 7, "school": "conjuration", "classes": ["cleric"], "castingTime": "1 hour", "range": "120 feet", "components": "V, S, M (a holy symbol worth at least 5 gp)", "duration": "24 hours", "ritual": false, "concentration": false, "desc": {"pt": "Você faz com que um templo surja cintilando no solo que você possa ver dentro do alcance. O templo deve caber dentro de um cubo de espaço desocupado de até 36 metros de cada lado. O templo permanece até a magia acabar. Ele é dedicado a qualquer divindade, panteão ou filosofia representada pelo símbolo sagrado utilizado na conjuração.\n\nVocê toma todas as decisões sobre a aparência do templo. O interior é delimitado por um piso, paredes e um teto, com uma porta que concede acesso ao interior e quantas janelas desejar. Apenas você e quaisquer criaturas que designar no momento em que conjurar a magia podem abrir ou fechar a porta.\n\nO interior do templo é um espaço aberto com um ídolo ou altar em uma das extremidades. Você decide se o templo é iluminado e se essa iluminação é de luz brilhante ou meia-luz. O aroma de incenso queimando preenche o ar em seu interior, e a temperatura é amena.\n\nO templo se opõe a tipos de criaturas que você escolher quando conjurar esta magia. Escolha um ou mais dos seguintes: celestiais, elementais, fadas, corruptores ou mortos-vivos. Se uma criatura do tipo escolhido tentar entrar no templo, ela deve fazer uma salvaguarda de Carisma. Em uma falha, ela não pode entrar no templo por 24 horas. Mesmo se a criatura puder entrar no templo, a magia do local a prejudica: sempre que fizer uma jogada de ataque, teste de habilidade ou salvaguarda dentro do templo, ela deve rolar um d4 e subtrair o valor rolado do resultado do d20.\n\nAlém disso, sensores criados por magias de adivinhação não podem surgir dentro do templo, e criaturas em seu interior não podem ser alvo de magias de adivinhação.\n\nPor fim, sempre que qualquer criatura dentro do templo recuperar Pontos de Vida através de uma magia de 1º círculo ou superior, a criatura recupera Pontos de Vida adicionais iguais ao seu modificador de Sabedoria (mínimo de 1 Ponto de Vida).\n\nO templo é feito de força mágica opaca que se estende para o Plano Etéreo, bloqueando assim viagens etéreas para o interior do templo. Nada pode atravessar fisicamente o exterior do templo. Ele não pode ser dissipado por dissipar magia, e campo antimagia não surte efeito sobre ele. Uma magia desintegrar destrói o templo instantaneamente.\n\nConjurar esta magia no mesmo local todos os dias durante um ano torna este efeito permanente.", "en": "You cause a temple to shimmer into existence on ground you can see within range. The temple must fit within an unoccupied cube of space, up to 120 feet on each side. The temple remains until the spell ends. It is dedicated to whatever god, pantheon, or philosophy is represented by the holy symbol used in the casting.\n\nYou make all decisions about the temple’s appearance. The interior is enclosed by a floor, walls, and a roof, with one door granting access to the interior and as many windows as you wish. Only you and any creatures you designate when you cast the spell can open or close the door.\n\nThe temple’s interior is an open space with an idol or altar at one end. You decide whether the temple is illuminated and whether that illumination is bright light or dim light. The smell of burning incense fills the air within, and the temperature is mild.\n\nThe temple opposes types of creatures you choose when you cast this spell. Choose one or more of the following: celestials, elementals, fey, fiends, or undead. If a creature of the chosen type attempts to enter the temple, that creature must make a Charisma saving throw. On a failed save, it can’t enter the temple for 24 hours. Even if the creature can enter the temple, the magic there hinders it; whenever it makes an attack roll, an ability check, or a saving throw inside the temple, it must roll a d4 and subtract the number rolled from the d20 roll.\n\nIn addition, the sensors created by divination spells can’t appear inside the temple, and creatures within can’t be targeted by divination spells.\n\nFinally, whenever any creature in the temple regains hit points from a spell of 1st level or higher, the creature regains additional hit points equal to your Wisdom modifier (minimum 1 hit point).\n\nThe temple is made from opaque magical force that extends into the Ethereal Plane, thus blocking ethereal travel into the temple’s interior. Nothing can physically pass through the temple’s exterior. It can’t be dispelled by dispel magic, and antimagic field has no effect on it. A disintegrate spell destroys the temple instantly.\n\nCasting this spell on the same spot every day for a year makes this effect permanent."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "whirlwind", "name": {"pt": "Furacão", "en": "Whirlwind"}, "level": 7, "school": "evocation", "classes": ["druid", "sorcerer", "wizard"], "castingTime": "Action", "range": "300 feet", "components": "V, M (a piece of straw)", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Um redemoinho uiva em direção a um ponto que você possa ver no chão dentro do alcance. O redemoinho é um cilindro com raio de 3 metros e 9 metros de altura centrado naquele ponto. Até a magia acabar, você pode usar sua ação para mover o redemoinho até 9 metros em qualquer direção pelo chão. O redemoinho suga quaisquer objetos Médios ou menores que não estejam fixados a nada e que não estejam sendo vestidos ou carregados por ninguém.\n\nUma criatura deve fazer uma salvaguarda de Destreza na primeira vez em um turno em que entrar no redemoinho ou em que o redemoinho entrar no espaço dela, inclusive quando o redemoinho surge pela primeira vez. Uma criatura sofre 10d6 de dano contundente se falhar na salvaguarda, ou metade desse dano se obtiver sucesso. Além disso, uma criatura Grande ou menor que falhe na salvaguarda deve obter sucesso em uma salvaguarda de Força ou ficará impedida dentro do redemoinho até a magia terminar. Quando uma criatura inicia seu turno impedida pelo redemoinho, ela é puxada 1,5 metro mais alto dentro dele, a menos que já esteja no topo. Uma criatura impedida se move com o redemoinho e cai quando a magia termina, a menos que tenha algum meio de permanecer no ar.\n\nUma criatura impedida pode usar uma ação para realizar um teste de Força ou Destreza contra a CD de salvaguarda de sua magia. Se obtiver sucesso, a criatura deixa de estar impedida pelo redemoinho e é arremessada a 3d6 × 3 metros para longe dele em uma direção aleatória.", "en": "A whirlwind howls down to a point that you can see on the ground within range. The whirlwind is a 10-foot-radius, 30-foot-high cylinder centered on that point. Until the spell ends, you can use your action to move the whirlwind up to 30 feet in any direction along the ground. The whirlwind sucks up any Medium or smaller objects that aren’t secured to anything and that aren’t worn or carried by anyone.\n\nA creature must make a Dexterity saving throw the first time on a turn that it enters the whirlwind or that the whirlwind enters its space, including when the whirlwind first appears. A creature takes 10d6 bludgeoning damage on a failed save, or half as much damage on a successful one. In addition, a Large or smaller creature that fails the save must succeed on a Strength saving throw or become restrained in the whirlwind until the spell ends. When a creature starts its turn restrained by the whirlwind, the creature is pulled 5 feet higher inside it, unless the creature is at the top. A restrained creature moves with the whirlwind and falls when the spell ends, unless the creature has some means to stay aloft.\n\nA restrained creature can use an action to make a Strength or Dexterity check against your spell save DC. If successful, the creature is no longer restrained by the whirlwind and is hurled 3d6 × 10 feet away from it in a random direction."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "abiDalzimsHorridWilting", "name": {"pt": "Murchar Horrível de Abi-Dalzim", "en": "Abi-Dalzim's Horrid Wilting"}, "level": 8, "school": "necromancy", "classes": ["sorcerer", "wizard"], "castingTime": "Action", "range": "150 feet", "components": "V, S, M (a bit of sponge)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você drena a umidade de cada criatura em um cubo de 9 metros centrado em um ponto que você escolher dentro do alcance. Cada criatura naquela área deve fazer uma salvaguarda de Constituição. Constructos e mortos-vivos não são afetados, e plantas e elementais da água fazem esta salvaguarda com desvantagem. Uma criatura sofre 12d8 de dano necrótico se falhar na salvaguarda, ou metade desse dano se obtiver sucesso.\n\nPlantas não mágicas na área que não sejam criaturas, como árvores e arbustos, murcham e morrem instantaneamente.", "en": "You draw the moisture from every creature in a 30-foot cube centered on a point you choose within range. Each creature in that area must make a Constitution saving throw. Constructs and undead aren’t affected, and plants and water elementals make this saving throw with disadvantage. A creature takes 12d8 necrotic damage on a failed save, or half as much damage on a successful one.\n\nNonmagical plants in the area that aren’t creatures, such as trees and shrubs, wither and die instantly."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "illusoryDragon", "name": {"pt": "Dragão Ilusório", "en": "Illusory Dragon"}, "level": 8, "school": "illusion", "classes": ["wizard"], "castingTime": "Action", "range": "120 feet", "components": "S", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Ao reunir filamentos de matéria sombria da Agonia das Sombras, você cria um dragão sombrio Implacável (Enorme) em um espaço desocupado que possa ver dentro do alcance. A ilusão dura pela duração da magia e ocupa seu espaço como se fosse uma criatura.\n\nQuando a ilusão surge, quaisquer inimigos seus que possam vê-la devem ser bem-sucedidos em uma salvaguarda de Sabedoria ou ficarão amedrontados por ela durante 1 minuto. Se uma criatura amedrontada terminar seu turno em um local onde não tenha linha de visão para a ilusão, ela pode repetir a salvaguarda, encerrando o efeito sobre si mesma em caso de sucesso.\n\nComo uma ação bônus no seu turno, você pode mover a ilusão até 18 metros. Em qualquer ponto durante seu movimento, você pode fazer com que ela exale uma rajada de energia em um cone de 18 metros originado do espaço dela. Quando você cria o dragão, escolha um tipo de dano: ácido, frio, fogo, elétrico, necrótico ou veneno. Cada criatura no cone deve fazer uma salvaguarda de Inteligência, sofrendo 7d6 de dano do tipo escolhido em caso de falha, ou metade desse dano em caso de sucesso.\n\nA ilusão é tangível por causa da matéria sombria usada para criá-la, mas ataques erram contra ela automaticamente, ela é bem-sucedida em todas as salvaguardas e é imune a todo tipo de dano e a todas as condições. Uma criatura que use uma ação para examinar o dragão pode determinar que se trata de uma ilusão obtendo sucesso em um teste de Inteligência (Investigação) contra a CD de salvaguarda de sua magia. Se uma criatura discernir a ilusão pelo que ela é, ela pode enxergar através dela e tem vantagem em salvaguardas contra o sopro dela.", "en": "By gathering threads of shadow material from the Shadowfell, you create a Huge shadowy dragon in an unoccupied space that you can see within range. The illusion lasts for the spell’s duration and occupies its space, as if it were a creature.\n\nWhen the illusion appears, any of your enemies that can see it must succeed on a Wisdom saving throw or become frightened of it for 1 minute. If a frightened creature ends its turn in a location where it doesn’t have line of sight to the illusion, it can repeat the saving throw, ending the effect on itself on a success.\n\nAs a bonus action on your turn, you can move the illusion up to 60 feet. At any point during its movement, you can cause it to exhale a blast of energy in a 60-foot cone originating from its space. When you create the dragon, choose a damage type: acid, cold, ﬁre, lightning, necrotic, or poison. Each creature in the cone must make an Intelligence saving throw, taking 7d6 damage of the chosen damage type on a failed save, or half as much damage on a successful one.\n\nThe illusion is tangible because of the shadow stuff used to create it, but attacks miss it automatically, it succeeds on all saving throws, and it is immune to all damage and conditions. A creature that uses an action to examine the dragon can determine that it is an illusion by succeeding on an Intelligence (Investigation) check against your spell save DC. If a creature discerns the illusion for what it is, the creature can see through it and has advantage on saving throws against its breath."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "maddeningDarkness", "name": {"pt": "Escuridão Enlouquecedora", "en": "Maddening Darkness"}, "level": 8, "school": "evocation", "classes": ["warlock", "wizard"], "castingTime": "Action", "range": "150 feet", "components": "V, M (a drop of pitch mixed with a drop of mercury)", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Uma escuridão mágica se espalha a partir de um ponto escolhido por você dentro do alcance para preencher uma esfera com raio de 18 metros até a magia acabar. A escuridão se espalha contornando cantos. Uma criatura com visão no escuro não pode ver através dessa escuridão. Luz não mágica, assim como luz criada por magias de 8º círculo ou inferior, não pode iluminar a área.\n\nGritos, balbucios e risadas ensandecidas podem ser ouvidos dentro da esfera. Sempre que uma criatura iniciar seu turno na esfera, ela deve fazer uma salvaguarda de Sabedoria, sofrendo 8d8 de dano psíquico em caso de falha, ou metade desse dano em caso de sucesso.", "en": "Magical darkness spreads from a point you choose within range to ﬁll a 60-foot-radius sphere until the spell ends. The darkness spreads around corners. A creature with darkvision can’t see through this darkness. Non-magical light, as well as light created by spells of 8th level or lower, can't illuminate the area.\n\nShrieks, gibbering, and mad laughter can be heard within the sphere. Whenever a creature starts its turn in the sphere, it must make a Wisdom saving throw, taking 8d8 psychic damage on a failed save, or half as much damage on a successful one."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "mightyFortress", "name": {"pt": "Fortaleza Poderosa", "en": "Mighty Fortress"}, "level": 8, "school": "conjuration", "classes": ["wizard"], "castingTime": "1 minute", "range": "1 mile", "components": "V, S, M (a diamond worth at least 500 gp, which the spell consumes)", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Uma fortaleza de pedra irrompe de uma área quadrada de solo à sua escolha que você possa ver dentro do alcance. A área tem 36 metros de cada lado e não deve ter quaisquer edifícios ou outras estruturas sobre ela. Quaisquer criaturas na área são erguidas ilesas conforme a fortaleza se eleva.\n\nA fortaleza possui quatro torres com bases quadradas, cada uma com 6 metros de lado e 9 metros de altura, com uma torre em cada canto. As torres são conectadas entre si por muralhas de pedra que têm 24 metros de comprimento cada, criando uma área murada. Cada muralha tem 30 centímetros de espessura e é composta por painéis com 3 metros de largura e 6 metros de altura. Cada painel é contíguo a dois outros painéis ou a outro painel e uma torre. Você pode colocar até quatro portas de pedra na muralha externa da fortaleza.\n\nUma pequena torre de menagem ergue-se dentro da área murada. A menagem tem uma base quadrada com 15 metros de cada lado e possui três andares com tetos de 3 metros de altura. Cada um dos andares pode ser dividido em quantos cômodos você desejar, desde que cada cômodo tenha pelo menos 1,5 metro de cada lado. Os andares da menagem são conectados por escadarias de pedra, suas paredes têm 15 centímetros de espessura e os cômodos internos podem ter portas de pedra ou arcos abertos, conforme você escolher. A menagem é mobiliada e decorada como você preferir, e contém comida suficiente para servir um banquete de nove pratos para até 100 pessoas a cada dia. Mobílias, comida e outros objetos criados por esta magia viram pó se forem removidos da fortaleza.\n\nUma equipe de cem servos invisíveis obedece a qualquer comando dado a eles pelas criaturas que você designar ao conjurar a magia. Cada servo funciona como se tivesse sido criado pela magia servo invisível.\n\nAs muralhas, torres e a menagem são todas feitas de pedra passível de dano. Cada seção de pedra de 3 por 3 metros possui CA 15 e 30 Pontos de Vida por cada 2,5 centímetros de espessura. Ela é imune a dano psíquico e de veneno. Reduzir uma seção de pedra a 0 Pontos de Vida a destrói e pode fazer com que seções conectadas cedam e desabem, a critério do Mestre.\n\nApós 7 dias ou quando você conjurar esta magia em outro lugar, a fortaleza desmorona inofensivamente e afunda de volta na terra, deixando quaisquer criaturas que estivessem em seu interior em segurança no solo.\n\nConjurar esta magia no mesmo local uma vez a cada 7 dias durante um ano torna esta fortaleza permanente.", "en": "A fortress of stone erupts from a square area of ground of your choice that you can see within range. The area is 120 feet on each side, and it must not have any buildings or other structures on it. Any creatures in the area are harmlessly lifted up as the fortress rises.\n\nThe fortress has four turrets with square bases, each one 20 feet on a side and 30 feet tall, with one turret on each corner. The turrets are connected to each other by stone walls that are each 80 feet long, creating an enclosed area. Each wall is 1 foot thick and is composed of panels that are 10 feet wide and 20 feet tall. Each panel is contiguous with two other panels or one other panel and a turret. You can place up to four stone doors in the fortress’s outer wall.\n\nA small keep stands inside the enclosed area. The keep has a square base that is 50 feet on each side, and it has three floors with 10-foot-high ceilings. Each of the floors can be divided into as many room as you like, provided each room is at least 5 feet on each side. The floors of the keep are connected by stone staircases, its walls are 6 inches thick, and interior rooms can have stone doors or open archways as you choose. The keep is furnished and decorated however you like, and it contains sufficient food to serve a nine-course banquet for up to 100 people each day. Furnishings, food, and other objects created by this spell crumble to dust if removed from the fortress.\n\nA staff of one hundred invisible servants obeys any command given to them by creatures you designate when you cast the spell. Each servant functions as if created by the unseen servant spell.\n\nThe walls, turrets, and keep are all made of stone that can be damaged. Each 10-foot-by-10-foot section of stone has AC 15 and 30 hit points per inch of thickness. It is immune to poison and psychic damage. Reducing a section of stone to 0 hit points destroys it and might cause connected sections to buckle and collapse at the DM’s discretion.\n\nAfter 7 days or when you cast this spell somewhere else, the fortress harmlessly crumbles and sinks back into the ground, leaving any creatures that were inside it safely on the ground.\n\nCasting this spell on the same spot once every 7 days for a year makes this fortress permanent."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "invulnerability", "name": {"pt": "Invulnerabilidade", "en": "Invulnerability"}, "level": 9, "school": "abjuration", "classes": ["wizard"], "castingTime": "Action", "range": "Self", "components": "V, S, M (a small piece of adamantine worth at least 500 gp, which the spell consumes)", "duration": "Concentration, up to 10 minutes", "ritual": false, "concentration": true, "desc": {"pt": "Você é imune a todo tipo de dano até a magia acabar.", "en": "You are immune to all damage until the spell ends."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "massPolymorph", "name": {"pt": "Metamorfose em Massa", "en": "Mass Polymorph"}, "level": 9, "school": "transmutation", "classes": ["bard", "sorcerer", "wizard"], "castingTime": "Action", "range": "120 feet", "components": "V, S, M (a caterpillar cocoon)", "duration": "Concentration, up to 1 hour", "ritual": false, "concentration": true, "desc": {"pt": "Você transforma até dez criaturas à sua escolha que possa ver dentro do alcance. Um alvo involuntário deve ser bem-sucedido em uma salvaguarda de Sabedoria para resistir à transformação. Um metamorfo involuntário é bem-sucedido automaticamente na salvaguarda.\n\nCada alvo assume a forma de uma besta à sua escolha, e você pode escolher a mesma forma ou formas diferentes para cada alvo. A nova forma pode ser qualquer besta que você tenha visto cujo nível de desafio seja igual ou inferior ao do alvo (ou metade do nível do alvo, caso o alvo não possua nível de desafio). As estatísticas de jogo do alvo, incluindo valores de habilidades mentais, são substituídas pelas estatísticas da besta escolhida, mas o alvo retém seus Pontos de Vida, alinhamento e personalidade.\n\nCada alvo ganha uma quantidade de Pontos de Vida Temporários igual aos Pontos de Vida de sua nova forma. Esses Pontos de Vida Temporários não podem ser substituídos por Pontos de Vida Temporários de outra fonte. O alvo reverte à sua forma normal quando não tiver mais Pontos de Vida Temporários ou morrer. Se a magia terminar antes disso, a criatura perde todos os seus Pontos de Vida Temporários e reverte à sua forma normal.\n\nA criatura é limitada nas ações que pode realizar pela natureza de sua nova forma. Ela não pode falar, conjurar magias ou fazer qualquer outra coisa que exija mãos ou fala.\n\nO equipamento do alvo se funde à nova forma. O alvo não pode ativar, usar, empunhar ou se beneficiar de qualquer forma de seu equipamento.", "en": "You transform up to ten creatures of your choice that you can see within range. An unwilling target must succeed on a Wisdom saving throw to resist the transformation. An unwilling shapechanger automatically succeeds on the save.\n\nEach target assumes a beast form of your choice, and you can choose the same form or a different ones for each target. The new form can be any beast you have seen whose challenge rating is equal to or less than the target’s (or half the target’s level, if the target doesn’t have a challenge rating). The target’s game statistics, including mental ability score, are replaced by the statistics of the chosen beast, but the target retains its hit points, alignment, and personality.\n\nEach target gains a number of temporary hit points equal to hit points of its new form. These temporary hit points can’t be replaced by temporary hit points from another source. A target reverts to its normal form when it has no more temporary hit points or it dies. If the spell ends before then, the creature loses all its temporary hit points and reverts to its normal form.\n\nThe creature is limited in the actions it can perform by the nature of its new form. It can’t speak, cast spells, or do anything else that requires hands or speech.\n\nThe target’s gear melds into the new form. The target can’t activate, use, wield, or otherwise benefit from any of its equipment."}, "rulesVersion": "2024", "source": "XGE"},
  {"id": "psychicScream", "name": {"pt": "Grito Psíquico", "en": "Psychic Scream"}, "level": 9, "school": "enchantment", "classes": ["bard", "sorcerer", "warlock", "wizard"], "castingTime": "Action", "range": "90 feet", "components": "S", "duration": "Instantaneous", "ritual": false, "concentration": false, "desc": {"pt": "Você libera o poder de sua mente para golpear o intelecto de até dez criaturas à sua escolha que possa ver dentro do alcance. Criaturas que possuam um valor de Inteligência de 2 ou menor não são afetadas.\n\nCada alvo deve fazer uma salvaguarda de Inteligência. Em uma salvaguarda com falha, o alvo sofre 14d6 de dano psíquico e fica atordoado. Em uma salvaguarda bem-sucedida, o alvo sofre metade desse dano e não fica atordoado. Se um alvo for morto por este dano, sua cabeça explode, caso possua uma.\n\nUm alvo atordoado pode fazer uma salvaguarda de Inteligência no final de cada um dos turnos dele. Em uma salvaguarda bem-sucedida, o efeito de atordoamento termina.", "en": "You unleash the power of your mind to blast the intellect of up to ten creatures of your choice that you can see within range. Creatures that have an Intelligence score of 2 or lower are unaffected.\n\nEach target must make an Intelligence saving throw. On a failed save, a target takes 14d6 psychic damage and is stunned. On a successful save, a target takes half as much damage and isn’t stunned. If a target is killed by this damage, its head explodes, assuming it has one.\n\nA stunned target can make an Intelligence saving throw at the end of each of its turns. On a successful save, the stunning effect ends."}, "rulesVersion": "2024", "source": "XGE"},
  // PHB14
  {"id": "brandingSmite", "name": {"pt": "Destruição Marcante", "en": "Branding Smite"}, "level": 2, "school": "evocation", "classes": [], "castingTime": "Bonus Action", "range": "Self", "components": "V", "duration": "Concentration, up to 1 minute", "ritual": false, "concentration": true, "desc": {"pt": "Na próxima vez que você atingir uma criatura com um ataque com arma antes desta magia terminar, a arma brilha com radiância astral enquanto você golpeia. O ataque causa 2d6 de dano radiante extra ao alvo, que se torna visível se estiver invisível, e o alvo emite luz penumbrosa em um raio de 1,5 metro e não pode ficar invisível até a magia terminar.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano extra aumenta em 1d6 para cada círculo do espaço acima do 2º.", "en": "The next time you hit a creature with a weapon attack before this spell ends, the weapon gleams with astral radiance as you strike. The attack deals an extra 2d6 radiant damage to the target, which becomes visible if it’s invisible, and the target sheds dim light in a 5-foot radius and can’t become invisible until the spell ends.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the extra damage increases by 1d6 for each slot level above 2nd."}, "rulesVersion": "2024", "source": "PHB14"},
];

