// ---------------------------------------------------------------------------
// Tradução dos metadados (tempo de conjuração, alcance, componentes, duração)
// das magias sem texto pt do SRD 5.2.1: extras acima e as nativas 2014 (srd.js).
// Padrões comuns → pt-BR, distâncias em metros (1,5 m a cada 5 pés), como o SRD em pt.
// ---------------------------------------------------------------------------
const fmtNum = (n) => String(Math.round(n * 10) / 10).replace('.', ',');
/** "60" (pés) → "18 metros"; "5" → "1,5 metro". */
export function feetToMeters(ft) {
  const m = Number(String(ft).replace(/,/g, '')) * 0.3;
  return `${fmtNum(m)} ${m < 2 ? 'metro' : 'metros'}`;
}
const milesToKm = (mi) => { const km = Number(mi) * 1.5; return `${fmtNum(km)} ${km < 2 ? 'quilômetro' : 'quilômetros'}`; };

const UNIT_PT = {
  round: ['rodada', 'rodadas'], min: ['minuto', 'minutos'], minute: ['minuto', 'minutos'], hour: ['hora', 'horas'],
  h: ['hora', 'horas'], day: ['dia', 'dias'],
};
/** "10 min" / "1 hour" / "8h" / "7 days" → "10 minutos" / "1 hora" / "8 horas" / "7 dias" (ou null). */
function timePt(str) {
  const m = String(str).trim().match(/^(\d+)\s*(rounds?|min|minutes?|hours?|h|days?)\.?$/i);
  if (!m) return null;
  const n = Number(m[1]);
  const unit = m[2].toLowerCase().replace(/s$/, '');
  const names = UNIT_PT[unit];
  return names ? `${n} ${n === 1 ? names[0] : names[1]}` : null;
}

const SHAPE_PT = { cone: 'cone', cube: 'cubo', line: 'linha', radius: 'raio', emanation: 'emanação', sphere: 'esfera', cylinder: 'cilindro' };
/** Alcance: "Self (15-foot cone)" → "Pessoal (cone de 4,5 metros)", "120 ft" → "36 metros". */
export function rangePt(range) {
  const r = String(range || '').trim();
  const fixed = { self: 'Pessoal', touch: 'Toque', sight: 'Visão', unlimited: 'Ilimitado', special: 'Especial' }[r.toLowerCase()];
  if (fixed) return fixed;
  let m = r.match(/^([\d,]+)\s*(ft|feet|foot)\.?$/i);
  if (m) return feetToMeters(m[1]);
  m = r.match(/^([\d,]+)\s*miles?$/i);
  if (m) return milesToKm(m[1]);
  // SRD 5.1: "Self (10-foot radius sphere)", "Self (10-foot radius hemisphere)"
  m = r.match(/^Self\s*\(([\d,]+)[- ](?:ft|foot|feet)[- ]radius (sphere|hemisphere)\)$/i);
  if (m) return `Pessoal (${m[2].toLowerCase() === 'sphere' ? 'esfera' : 'hemisfério'} de ${feetToMeters(m[1])} de raio)`;
  m = r.match(/^Self\s*\(([\d,]+)[- ](ft|foot|feet|mile)[- ]?(cone|cube|line|radius|emanation|sphere|cylinder)\)$/i);
  if (m) {
    const dist = /mile/i.test(m[2]) ? milesToKm(m[1]) : feetToMeters(m[1]);
    return `Pessoal (${SHAPE_PT[m[3].toLowerCase()]} de ${dist})`;
  }
  return r;
}

// Gatilhos de reação/ação bônus ("…, which you take when …") — os que aparecem no catálogo.
const TRIGGER_PT = [
  [/^when you take acid, cold, fire, lightning, or thunder damage$/i, 'quando você sofre dano de ácido, frio, fogo, elétrico ou trovejante'],
  [/^when a creature you can see within 60 feet of (?:yourself|you) succeeds on an attack roll, an ability check, or a saving throw$/i, 'quando uma criatura que você vê a até 18 metros tem sucesso numa jogada de ataque, teste de atributo ou salvaguarda'],
  [/^when you speak to another creature$/i, 'quando você fala com outra criatura'],
  [/^when a creature you can see makes an attack roll or starts to cast a spell$/i, 'quando uma criatura que você vê faz uma jogada de ataque ou começa a conjurar uma magia'],
  [/^when a humanoid you can see within 60 feet of you dies$/i, 'quando um humanoide que você vê a até 18 metros morre'],
  [/^when (?:you are|you're) hit by an attack roll(?:.*)$/i, 'quando você é atingido por uma jogada de ataque'],
  [/^in response to being damaged by a creature within 60 feet of you that you can see$/i, 'quando uma criatura que você vê a até 18 metros causa dano a você'],
  [/^immediately after hitting a (creature|target) with a Melee weapon or an Unarmed Strike$/i, (_, w) => `imediatamente após atingir ${w === 'target' ? 'um alvo' : 'uma criatura'} com uma arma corpo a corpo ou um Ataque Desarmado`],
  [/^immediately after hitting a creature with a Ranged weapon$/i, 'imediatamente após atingir uma criatura com uma arma de ataque à distância'],
  [/^immediately after hitting a creature with a weapon$/i, 'imediatamente após atingir uma criatura com uma arma'],
  [/^immediately after hitting or missing a target with a ranged attack using a weapon$/i, 'imediatamente após acertar ou errar um ataque à distância com uma arma'],
];
const ACTION_PT = { action: 'Ação', 'bonus action': 'Ação Bônus', reaction: 'Reação' };
function actionPt(str) {
  const k = String(str).trim().replace(/^1\s+/, '').toLowerCase();
  return ACTION_PT[k] || timePt(str);
}
/** Tempo de conjuração: "1 action" → "Ação", "Action or Ritual" → "Ação ou Ritual", "Reaction, which you take when…" → "Reação, que você realiza quando…". */
export function castingTimePt(ct) {
  const s = String(ct || '').trim().replace(/\.$/, '').replace(/,\s*taken when\b/i, ', which you take when');
  const which = s.match(/^([^,]+),\s*which you take\s+(.+)$/i);
  if (which) {
    const base = actionPt(which[1]) || which[1];
    const trig = TRIGGER_PT.find(([re]) => re.test(which[2].trim()));
    if (!trig) return base;
    const text = typeof trig[1] === 'function' ? which[2].trim().replace(trig[0], trig[1]) : trig[1];
    return `${base}, que você realiza ${text}`;
  }
  const parts = s.split(/\s+(?:or|ou)\s+/i);
  const out = parts.map(p => (/^ritual$/i.test(p) ? 'Ritual' : actionPt(p)));
  if (out.every(Boolean)) return out.join(' ou ');
  return s;
}

/** Duração: "Concentration, up to 1 minute" / "1 min, conc" / "Conc. 1 hour" → "Concentração, até 1 minuto". */
export function durationPt(d) {
  const s = String(d || '').trim().replace(/^Concentration up to/i, 'Concentration, up to').replace(/\bone (minute|hour|round)\b/i, '1 $1');
  const fixed = {
    instant: 'Instantânea', 'inst.': 'Instantânea', instantaneous: 'Instantânea', 'until dispelled': 'Até ser dissipada',
    'until triggered': 'Até ser ativada', 'until dispelled or triggered': 'Até ser dissipada ou ativada', special: 'Especial',
  }[s.toLowerCase()];
  if (fixed) return fixed;
  if (/^Instantaneous or 1 hour \(see below\)$/i.test(s)) return 'Instantânea ou 1 hora (veja a descrição)';
  let m = s.match(/^Concentration,\s*up to\s+(.+)$/i) || s.match(/^Conc\.\s*(.+)$/i) || s.match(/^(.+?),\s*conc\.?$/i);
  if (m) { const t = timePt(m[1]); return t ? `Concentração, até ${t}` : s; }
  m = s.match(/^Up to\s+(.+)$/i);
  if (m) { const t = timePt(m[1]); return t ? `Até ${t}` : s; }
  return timePt(s) || s;
}

const COIN_PT = { gp: 'PO', sp: 'PP', cp: 'PC', ep: 'PE', pp: 'PL' };
/** Componentes: "V, S, M (a ruby worth at least 50 gp, which the spell consumes)" → "V, S, M (vale 50+ PO, consumido)". */
export function componentsPt(c) {
  const s = String(c || '').trim();
  const m = s.match(/^([VSM,\s]+?)\s*\((.*)\)$/);
  if (!m) return s;
  const letters = m[1].trim();
  const mat = m[2];
  const cost = mat.match(/worth\s+(?:at least\s+)?([\d,]+)\s*\+?\s*(gp|sp|cp|ep|pp)\b/i) || mat.match(/([\d,]+)\s*(gp|sp|cp|ep|pp)\s+worth\b/i);
  const notes = [];
  if (cost) notes.push(`vale ${cost[1].replace(/,/g, '.')}+ ${COIN_PT[cost[2].toLowerCase()]}`);
  if (/consume/i.test(mat)) notes.push('consumido');
  return notes.length ? `${letters} (${notes.join(', ')})` : letters;
}

/** metaPt de uma magia sem texto pt (mesmo formato do SRD: { castingTime, range, components, duration }). */
export function translateSpellMeta(sp) {
  return {
    castingTime: castingTimePt(sp?.castingTime),
    range: rangePt(sp?.range),
    components: componentsPt(sp?.components),
    duration: durationPt(sp?.duration),
  };
}

// Abreviações e unidades dos resumos 2014 antigos ("SAL DEST", "20 pés", "0 HP", "10 lb").
const SAVE_PT = {
  FOR: 'Força', STR: 'Força', DEST: 'Destreza', DES: 'Destreza', DEX: 'Destreza', CON: 'Constituição',
  INT: 'Inteligência', SAB: 'Sabedoria', WIS: 'Sabedoria', CAR: 'Carisma', CHA: 'Carisma',
};
/** Deixa um resumo pt mais claro para iniciante: salvaguardas por extenso, metros, PV, kg, litros. */
export function polishPtText(text) {
  if (typeof text !== 'string') return text;
  return text
    .replace(/\bSAL\.?\s+(FOR|STR|DEST|DES|DEX|CON|INT|SAB|WIS|CAR|CHA)\b/g, (_, a) => `salvaguarda de ${SAVE_PT[a]}`)
    .replace(/\bSAL\b/g, 'salvaguarda')
    .replace(/\bsalvamentos\b/g, 'salvaguardas').replace(/\bsalvamento\b/g, 'salvaguarda')
    .replace(/(-|−)?(\d[\d.,]*)\s*(?:pés|ft)\b/g, (_, sign, n) => `${sign || ''}${feetToMeters(n.replace(/\./g, ''))}`)
    .replace(/(\d[\d.,]*)\s*lb\b/g, (_, n) => `${fmtNum(Number(n.replace(/\./g, '')) * 0.5)} kg`)
    .replace(/(\d+)\s*galões/g, (_, n) => `${Number(n) * 4} litros`)
    .replace(/\bHP\b/g, 'PV');
}

/**
 * Resumos 2014 (uma linha, texto próprio) das magias que o catálogo 2014 copia do
 * SRD 5.2.1 (srd.js, LEGACY_SPELLS_FROM_2024): sem eles a ficha 2014 mostraria o texto
 * inteiro da versão 2024 — e com a regra errada (ex.: o salto do Orbe Cromático é de 2024).
 */
export const LEGACY_SUMMARIES_2014 = {
  // 1º círculo
  chromaticOrb: ["Você arremessa uma esfera de energia de 10 centímetros de diâmetro contra uma criatura que você possa ver dentro do alcance. Você escolhe ácido, elétrico, fogo, frio, veneno ou trovejante para o tipo de esfera criada e, em seguida, faz um ataque à distância com magia contra o alvo. Se o ataque atingir, a criatura sofre 3d8 de dano do tipo que você escolheu.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 1º.", "You hurl a 4-inch-diameter sphere of energy at a creature that you can see within range. You choose acid, cold, fire, lightning, poison, or thunder for the type of orb you create, and then make a ranged spell attack against the target. If the attack hits, the creature takes 3d8 of the type you chose.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d8 for each slot level above 1st."],
  dissonantWhispers: ["Você sussurra uma melodia dissonante que apenas uma criatura à sua escolha dentro do alcance pode ouvir, atormentando-a com uma dor terrível. O alvo deve fazer uma salvaguarda de Sabedoria. Se falhar na salvaguarda, ele sofre 3d6 de dano psíquico e deve usar imediatamente sua reação, se disponível, para se mover para tão longe de você quanto seu deslocamento permitir. A criatura não se move em direção a terrenos obviamente perigosos, como fogo ou um fosso. Em um sucesso na salvaguarda, o alvo sofre metade do dano e não precisa se afastar. Uma criatura surda é bem-sucedida automaticamente na salvaguarda.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 1º.", "You whisper a discordant melody that only one creature of your choice within range can hear, wracking it with terrible pain. The target must make a Wisdom saving throw. On a failed save, it takes 3d6 psychic damage and must immediately use its reaction, if available, to move as far as its speed allows away from you. The creature doesn’t move into obviously dangerous ground, such as a fire or a pit. On a successful save, the target takes half as much damage and doesn’t have to move away. A deafened creature automatically succeeds on the save.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st."],
  ensnaringStrike: ["Na próxima vez que você atingir uma criatura com um ataque com arma antes desta magia terminar, uma massa retorcida de vinhas com espinhos surge no ponto de impacto, e o alvo deve ser bem-sucedido em uma salvaguarda de Força ou ficará impedido pelas vinhas mágicas até a magia terminar. Uma criatura Grande ou maior tem vantagem nessa salvaguarda. Se o alvo for bem-sucedido na salvaguarda, as vinhas definham e somem.\n\nEnquanto estiver impedido por esta magia, o alvo sofre 1d6 de dano perfurante no início de cada um dos turnos dele. Uma criatura impedida pelas vinhas ou alguém que possa tocar nela pode usar sua ação para fazer um teste de Força contra a CD de salvaguarda da sua magia. Em caso de sucesso, o alvo é libertado.\n\nEm Níveis Superiores. Se você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 1º.", "The next time you hit a creature with a weapon attack before this spell ends, a writhing mass of thorny vines appears at the point of impact, and the target must succeed on a Strength saving throw or be restrained by the magical vines until the spell ends. A Large or larger creature has advantage on this saving throw. If the target succeeds on the save, the vines shrivel away.\n\nWhile restrained by this spell, the target takes 1d6 piercing damage at the start of each of its turns. A creature restrained by the vines or one that can touch a creature can use its action to make a Strength check against your spell save DC. On a success, the target is freed.\n\nAt Higher Levels. If you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st."],
  floatingDisk: ["Esta magia cria um plano de energia circular e horizontal, com 90 centímetros de diâmetro e 2,5 centímetros de espessura, que flutua a 90 centímetros do chão em um espaço desocupado à sua escolha que você possa ver dentro do alcance. O disco permanece pela duração e pode suportar até 250 kg. Se mais peso for colocado sobre ele, a magia termina, e tudo que estiver sobre o disco cai no chão.\nO disco fica imóvel enquanto você estiver a até 6 metros dele. Se você se afastar mais de 6 metros, o disco o segue de modo a permanecer a até 6 metros de você. Ele pode se mover por terreno irregular, subir ou descer escadas, ladeiras e similares, mas não pode atravessar uma mudança de elevação de 3 metros ou mais. Por exemplo, o disco não pode atravessar um fosso de 3 metros de profundidade, nem poderia sair de tal fosso se fosse criado no fundo dele.\nSe você se afastar mais de 30 metros do disco (normalmente porque ele não consegue contornar um obstáculo para segui-lo), a magia termina.", "This spell creates a circular, horizontal plane of force, 3 feet in diameter and 1 inch thick, that floats 3 feet above the ground in an unoccupied space of your choice that you can see within range. The disk remains for the duration, and can hold up to 500 pounds. If more weight is placed on it, the spell ends, and everything on the disk falls to the ground.\n\nThe disk is immobile while you are within 20 feet of it. If you move more than 20 feet away from it, the disk follows you so that it remains within 20 feet of you. It can move across uneven terrain, up or down stairs, slopes and the like, but it can't cross an elevation change of 10 feet or more. For example, the disk can't move across a 10-foot deep pit, nor could it leave such a pit if it was created at the bottom.\n\nIf you move more than 100 feet from the disk (typically because it can't move around an obstacle to follow you), the spell ends."],
  hellishRebuke: ["Você aponta o dedo e a criatura que causou dano a você é momentaneamente cercada por chamas infernais. A criatura deve realizar um teste de resistência de Destreza. Ela sofre 2d10 de dano de fogo em uma falha na salvaguarda, ou metade desse dano em um sucesso.\n\nEm Níveis Superiores. Quando você conjura esta magia usando um espaço de magia de 2º círculo ou superior, o dano aumenta em 1d10 para cada círculo do espaço acima do 1º.", "You point your finger, and the creature that damaged you is momentarily surrounded by hellish flames. The creature must make a Dexterity saving throw. It takes 2d10 fire damage on a failed save, or half as much damage on a successful one.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d10 for each slot level above 1st."],
  iceKnife: ["Você cria um estilhaço de gelo e o arremessa contra uma criatura dentro do alcance. Faça um ataque à distância com magia contra o alvo. Se atingir, o alvo sofre 1d10 de dano perfurante. Acertando ou errando, o estilhaço explode em seguida. O alvo e cada criatura a até 1,5 metro dele devem ser bem-sucedidos em uma salvaguarda de Destreza ou sofrerão 2d6 de dano de frio.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano de frio aumenta em 1d6 para cada círculo do espaço acima do 1º.", "You create a shard of ice and fling it at one creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 piercing damage. Hit or miss, the shard then explodes. The target and each creature within 5 feet of it must succeed on a Dexterity saving throw or take 2d6 cold damage.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the cold damage increases by 1d6 for each slot level above 1st."],
  illusoryScript: ["Você escreve em pergaminho, papel ou algum outro material de escrita adequado e o imbui com uma ilusão potente que perdura pela duração.\n\nPara você e quaisquer criaturas que você designar ao conjurar a magia, a escrita parece normal, feita pela sua própria mão, e transmite qualquer significado que você pretendia transmitir quando escreveu o texto. Para todos os outros, o texto parece como se tivesse sido escrito em uma caligrafia desconhecida ou mágica totalmente ininteligível. Alternativamente, você pode fazer com que a escrita pareça ser uma mensagem totalmente diferente, escrita em outra caligrafia e idioma, embora o idioma deva ser um que você conheça.\n\nSe a magia for dissipada, tanto a escrita original quanto a ilusão desaparecem.\n\nUma criatura com visão verdadeira pode ler a mensagem oculta.", "You write on parchment, paper, or some other suitable writing material and imbue it with a potent illusion that lasts for the duration.\n\nTo you and any creatures you designate when you cast the spell, the writing appears normal, written in your hand, and conveys whatever meaning you intended when you wrote the text. To all others, the writing appears as if it were written in an unknown or magical script that is unintelligible. Alternatively, you can cause the writing to appear to be an entirely different message, written in a different hand and language, though the language must be one you know.\n\nShould the spell be dispelled, the original script and the illusion both disappear.\n\nA creature with truesight can read the hidden message."],
  searingSmite: ["Na próxima vez que você atingir uma criatura com um ataque corpo a corpo com arma durante a duração da magia, sua arma reluz com intensidade incandescente, e o ataque causa 1d6 de dano de fogo adicional ao alvo e faz o alvo pegar fogo. No início de cada um dos turnos dele até a magia terminar, o alvo deve fazer uma salvaguarda de Constituição. Se falhar na salvaguarda, ele sofre 1d6 de dano de fogo. Em um sucesso na salvaguarda, a magia termina. Se o alvo ou uma criatura a até 1,5 metro dele usar uma ação para apagar as chamas, ou se algum outro efeito extinguir as chamas (como o alvo ser submergido em água), a magia termina.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 2º círculo ou superior, o dano adicional inicial causado pelo ataque aumenta em 1d6 para cada círculo do espaço acima do 1º.", "The next time you hit a creature with a melee weapon attack during the spell’s duration, your weapon flares with white-hot intensity, and the attack deals an extra 1d6 fire damage to the target and causes the target to ignite in flames. At the start of each of its turns until the spell ends, the target must make a Constitution saving throw. On a failed save, it takes 1d6 fire damage. On a successful save, the spell ends. If the target or a creature within 5 feet of it uses an action to put out the flames, or if some other effect douses the flames (such as the target being submerged in water), the spell ends.\n\nAt Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the initial extra damage dealt by the attack increases by 1d6 for each slot level above 1st."],
  unseenServant: ["Esta magia cria uma força Invisível, sem mente e sem forma, de tamanho Médio, que realiza tarefas simples sob o seu comando até a magia terminar. O servo surge em um espaço desocupado no chão dentro do alcance. Ele tem CA 10, 1 Ponto de Vida e Força 2, e não pode atacar. Se ele cair para 0 Pontos de Vida, a magia termina.\nUma vez em cada um dos seus turnos, como uma Ação Bônus, você pode comandar mentalmente o servo a se mover até 4,5 metros e interagir com um objeto. O servo pode realizar tarefas simples que um humano poderia fazer, como buscar coisas, limpar, remendar, dobrar roupas, acender fogueiras, servir comida e despejar bebidas. Assim que você dá o comando, o servo realiza a tarefa da melhor forma possível até completá-la e então aguarda o seu próximo comando.\nSe você comandar o servo a realizar uma tarefa que o faria se afastar mais de 18 metros de você, a magia termina.", "This spell creates an invisible, mindless, shapeless, Medium force that performs simple tasks at your command until the spell ends. The servant springs into existence in an unoccupied space on the ground within range. It has AC 10, 1 hit point, and a Strength of 2, and it can't attack. If it drops to 0 hit points, the spell ends.\n\nOnce on each of your turns as a bonus action, you can mentally command the servant to move up to 15 feet and interact with an object. The servant can perform simple tasks that a human servant could do, such as fetching things, cleaning, mending, folding clothes, lighting fires, serving food, and pouring wine. Once you give the command, the servant performs the task to the best of its ability until it completes the task, then waits for your next command.\n\nIf you command the servant to perform a task that would move it more than 60 feet away from you, the spell ends."],
  // 2º círculo
  acidArrow: ["Uma flecha verde cintilante dispara em direção a um alvo dentro do alcance e explode em uma borrifada de ácido. Faça um ataque à distância com magia contra o alvo. Se atingir, o alvo sofre 4d4 de dano de ácido imediatamente e 2d4 de dano de ácido no final do próximo turno dele. Se errar, a flecha espirra ácido no alvo causando metade do dano inicial e nenhum dano no final do próximo turno dele.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano (tanto o inicial quanto o posterior) aumenta em 1d4 para cada círculo do espaço acima do 2º.", "A shimmering green arrow streaks toward a target within range and bursts in a spray of acid. Make a ranged spell attack against the target. On a hit, the target takes 4d4 acid damage immediately and 2d4 acid damage at the end of its next turn. On a miss, the arrow splashes the target with acid for half as much of the initial damage and no damage at the end of its next turn.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage (both initial and later) increases by 1d4 for each slot level above 2nd."],
  augury: ["Ao lançar varetas incrustadas de pedras preciosas, rolar ossos de dragão, dispor cartas ornadas ou empregar outro instrumento de adivinhação, você recebe um presságio de uma entidade de outro mundo sobre os resultados de um curso de ação específico que planeja realizar dentro dos próximos 30 minutos. O Mestre escolhe entre os seguintes presságios possíveis:\n\n- Prosperidade, para bons resultados\n- Infortúnio, para maus resultados\n- Prosperidade e infortúnio, para resultados tanto bons quanto maus\n- Nada, para resultados que não sejam especialmente bons ou maus\n\nA magia não leva em consideração quaisquer circunstâncias possíveis que possam mudar o resultado, como a conjuração de magias adicionais ou a perda ou ganho de um companheiro.\n\nSe você conjurar a magia duas ou mais vezes antes de completar seu próximo descanso longo, há uma chance cumulativa de 25 por cento para cada conjuração após a primeira de obter uma leitura aleatória. O Mestre faz essa rolagem em segredo.", "By casting gem-inlaid sticks, rolling dragon bones, laying out ornate cards, or employing some other divining tool, you receive an omen from an otherworldly entity about the results of a specific course of action that you plan to take within the next 30 minutes. The GM chooses from the following possible omens:\n\n- Weal, for good results\n- Woe, for bad results\n- Weal and woe, for both good and bad results\n- Nothing, for results that aren't especially good or bad\n\nThe spell doesn't take into account any possible circumstances that might change the outcome, such as the casting of additional spells or the loss or gain of a companion.\n\nIf you cast the spell two or more times before completing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get a random reading. The GM makes this roll in secret."],
  blur: ["Seu corpo fica borrado. Pela duração, qualquer criatura tem Desvantagem nas jogadas de ataque contra você. Um atacante é imune a esse efeito se perceber você com Percepção às Cegas ou Visão Verdadeira.", "Your body becomes blurred, shifting and wavering to all who can see you. For the duration, any creature has disadvantage on attack rolls against you. An attacker is immune to this effect if it doesn't rely on sight, as with blindsight, or can see through illusions, as with truesight."],
  darkness: ["Uma escuridão mágica se espalha a partir de um ponto à sua escolha dentro do alcance para preencher uma esfera com 4,5 metros de raio pela duração. A escuridão contorna esquinas e cantos. Uma criatura com visão no escuro não pode ver através desta escuridão, e luz não mágica não pode iluminá-la.\n\nSe o ponto escolhida for em um objeto que você esteja segurando ou em um que não esteja sendo vestido ou carregado, a escuridão emana do objeto e se move com ele. Cobrir completamente a fonte da escuridão com um objeto opaco, como uma tigela ou um elmo, bloqueia a escuridão.\n\nSe qualquer parte da área desta magia se sobrepuser a uma área de luz criada por uma magia de 2º círculo ou inferior, a magia que criou a luz é dissipada.", "Magical darkness spreads from a point you choose within range to fill a 15-foot radius sphere for the duration. The darkness spreads around corners. A creature with darkvision can't see through this darkness, and nonmagical light can't illuminate it.\n\nIf the point you choose is on an object you are holding or one that isn't being worn or carried, the darkness emanates from the object and moves with it. Completely covering the source of the darkness with an opaque object, such as a bowl or a helm, blocks the darkness.\n\nIf any of this spell's area overlaps with an area of light created by a spell of 2nd level or lower, the spell that created the light is dispelled."],
  mirrorImage: ["Três duplicatas ilusórias de você surgem em seu espaço. Até a magia terminar, as duplicatas se movem com você e imitam suas ações, trocando de posição de modo que seja impossível rastrear qual imagem é a real. Você pode usar sua ação para dispensar as duplicatas ilusórias.\n\nCada vez que uma criatura tiver você como alvo de um ataque durante a duração da magia, role um d20 para determinar se o ataque tem como alvo uma de suas duplicatas.\n\nSe você tiver três duplicatas, deve rolar um 6 ou mais para mudar o alvo do ataque para uma duplicata. Com duas duplicatas, você deve rolar um 8 ou mais. Com uma duplicata, você deve rolar um 11 ou mais.\n\nA CA de uma duplicata é igual a 10 + seu modificador de Destreza. Se um ataque acertar uma duplicata, a duplicata é destruída. Uma duplicata só pode ser destruída por um ataque que a acerte. Ela ignora todos os outros danos e efeitos. A magia termina quando todas as três duplicatas forem destruídas.\n\nUma criatura não é afetada por esta magia se não puder ver, se depender de sentidos que não a visão (como percepção às cegas) ou se puder perceber ilusões como falsas, como por meio de visão verdadeira.", "Three illusory duplicates of yourself appear in your space. Until the spell ends, the duplicates move with you and mimic your actions, shifting position so it's impossible to track which image is real. You can use your action to dismiss the illusory duplicates.\n\nEach time a creature targets you with an attack during the spell's duration, roll a d20 to determine whether the attack instead targets one of your duplicates.\n\nIf you have three duplicates, you must roll a 6 or higher to change the attack's target to a duplicate. With two duplicates, you must roll an 8 or higher. With one duplicate, you must roll an 11 or higher.\n\nA duplicate's AC equals 10 + your Dexterity modifier. If an attack hits a duplicate, the duplicate is destroyed. A duplicate can be destroyed only by an attack that hits it. It ignores all other damage and effects. The spell ends when all three duplicates are destroyed.\n\nA creature is unaffected by this spell if it can't see, if it relies on senses other than sight, such as blindsight, or if it can perceive illusions as false, as with truesight."],
  spiderClimb: ["Até a magia terminar, uma criatura voluntária que você tocar adquire a capacidade de se mover para cima, para baixo e através de superfícies verticais e de cabeça para baixo ao longo de tetos, deixando as mãos livres. O alvo também adquire um deslocamento de escalada igual ao seu deslocamento de caminhada.", "Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and upside down along ceilings, while leaving its hands free. The target also gains a climbing speed equal to its walking speed."],
  wardingBond: ["Você toca outra criatura voluntária e cria uma conexão mística entre você e o alvo até a magia terminar. Enquanto o alvo estiver a até 18 metros de você, ele recebe +1 de bônus na CA e em testes de resistência, e tem Resistência a todo dano. Além disso, cada vez que ele sofrer dano, você sofre a mesma quantidade de dano.\nA magia termina se você cair para 0 Pontos de Vida ou se você e o alvo ficarem separados por mais de 18 metros. Ela também termina se a magia for conjurada novamente em qualquer uma das criaturas conectadas.", "This spell wards a willing creature you touch and creates a mystic connection between you and the target until the spell ends. While the target is within 60 feet of you, it gains a +1 bonus to AC and saving throws, and it has resistance to all damage. Also, each time it takes damage, you take the same amount of damage.\n\nThe spell ends if you drop to 0 hit points or if you and the target become separated by more than 60 feet. It also ends if the spell is cast again on either of the connected creatures. You can also dismiss the spell as an action."],
  web: ["Você conjura uma massa de teias pegajosas em um ponto dentro do alcance. As teias preenchem um Cubo de 6 metros ali pela duração. As teias são Terreno Difícil, e a área dentro delas é Levemente Obscurecida.\nSe as teias não estiverem ancoradas entre duas massas sólidas (como paredes ou árvores) ou estendidas sobre um piso, uma parede ou um teto, a teia desaba sobre si mesma, e a magia termina no início do seu próximo turno. Teias estendidas sobre uma superfície plana têm 1,5 metro de profundidade.\nNa primeira vez que uma criatura entrar nas teias em um turno ou começar seu turno nelas, ela deve ser bem-sucedida em um teste de resistência de Destreza ou ficará na condição Contido enquanto estiver nas teias ou até se libertar.\nUma criatura Contida pelas teias pode realizar uma ação para fazer um teste de Força (Atletismo) contra a CD de resistência da sua magia. Se for bem-sucedida, ela deixa de estar Contida.\nAs teias são inflamáveis. Qualquer Cubo de 1,5 metro de teias exposto ao fogo queima em 1 rodada, causando 2d4 de dano Ígneo a qualquer criatura que comece seu turno no fogo.", "You conjure a mass of thick, sticky webbing at a point of your choice within range. The webs fill a 20-foot cube from that point for the duration. The webs are difficult terrain and lightly obscure their area.\n\nIf the webs aren't anchored between two solid masses (such as walls or trees) or layered across a floor, wall, or ceiling, the conjured web collapses on itself, and the spell ends at the start of your next turn. Webs layered over a flat surface have a depth of 5 feet.\n\nEach creature that starts its turn in the webs or that enters them during its turn must make a\n\nDexterity saving throw. On a failed save, the creature is restrained as long as it remains in the webs or until it breaks free.\n\nA creature restrained by the webs can use its action to make a Strength check against your spell save DC. If it succeeds, it is no longer restrained.\n\nThe webs are flammable. Any 5-foot cube of webs exposed to fire burns away in 1 round, dealing 2d4 fire damage to any creature that starts its turn in the fire."],
  alterSelf: ["Você assume uma forma diferente. Quando você conjurar a magia, escolha uma das seguintes opções, cujos efeitos duram pela duração da magia. Enquanto a magia durar, você pode encerrar uma opção como uma ação para obter os benefícios de outra diferente.\n\nAdaptação Aquática. Você adapta seu corpo a um ambiente aquático, desenvolvendo guelras e membranas entre seus dedos. Você pode respirar debaixo d'água e ganha um deslocamento de natação igual ao seu deslocamento de caminhada.\n\nMudar Aparência. Você transforma sua aparência. Você decide como você parece, incluindo sua altura, peso, traços faciais, o som da sua voz, comprimento do cabelo, coloração e características marcantes, se houver. Você pode aparentar ser um membro de outra raça, embora nenhuma das suas estatísticas mude. Você também não pode parecer uma criatura de um tamanho diferente do seu, e seu formato básico permanece o mesmo; se você for bípede, não pode usar esta magia para se tornar quadrúpede, por exemplo. A qualquer momento pela duração da magia, você pode usar sua ação para mudar sua aparência dessa forma novamente.\n\nArmas Naturais. Você desenvolve garras, presas, espinhos, chifres ou uma arma natural diferente à sua escolha. Seus ataques desarmados causam 1d6 de dano contundente, perfurante ou cortante, conforme apropriado para a arma natural escolhida, e você é proficiente com seus ataques desarmados. Por fim, a arma natural é mágica e você tem um bônus de +1 nas jogadas de ataque e dano que fizer usando-a.", "You assume a different form. When you cast the spell, choose one of the following options, the effects of which last for the duration of the spell. While the spell lasts, you can end one option as an action to gain the benefits of a different one.\n\nAquatic Adaptation. You adapt your body to an aquatic environment, sprouting gills and growing webbing between your fingers. You can breathe underwater and gain a swimming speed equal to your walking speed.\n\nChange Appearance. You transform your appearance. You decide what you look like, including your height, weight, facial features, sound of your voice, hair length, coloration, and distinguishing characteristics, if any. You can make yourself appear as a member of another race, though none of your statistics change. You also can't appear as a creature of a different size than you, and your basic shape stays the same; if you're bipedal, you can't use this spell to become quadrupedal, for instance. At any time for the duration of the spell, you can use your action to change your appearance in this way again.\n\nNatural Weapons. You grow claws, fangs, spines, horns, or a different natural weapon of your choice. Your unarmed strikes deal 1d6 bludgeoning, piercing, or slashing damage, as appropriate to the natural weapon you chose, and you are proficient with your unarmed strikes. Finally, the natural weapon is magic and you have a +1 bonus to the attack and damage rolls you make using it."],
  arcaneLock: ["Você toca uma porta fechada, janela, portão, baú ou outra entrada, e o objeto se torna trancado pela duração. Você e as criaturas que você designar ao conjurar esta magia podem abrir o objeto normalmente. Você também pode definir uma senha que, quando pronunciada a até 1,5 metro do objeto, suprime esta magia por 1 minuto. Caso contrário, ele é intransponível até que seja quebrado ou que a magia seja dissipada ou suprimida. Conjurar arrombamento no objeto suprime tranca arcana por 10 minutos.\n\nEnquanto afetado por esta magia, o objeto fica mais difícil de quebrar ou forçar a abertura; a CD para quebrá-lo ou arrombar quaisquer fechaduras nele aumenta em 10.", "You touch a closed door, window, gate, chest, or other entryway, and it becomes locked for the duration. You and the creatures you designate when you cast this spell can open the object normally. You can also set a password that, when spoken within 5 feet of the object, suppresses this spell for 1 minute. Otherwise, it is impassable until it is broken or the spell is dispelled or suppressed. Casting knock on the object suppresses arcane lock for 10 minutes.\n\nWhile affected by this spell, the object is more difficult to break or force open; the DC to break it or pick any locks on it increases by 10."],
  continualFlame: ["Uma chama, equivalente em brilho a uma tocha, brota de um objeto que você toca. O efeito se parece com uma chama comum, mas não gera calor e não consome oxigênio. Uma chama contínua pode ser coberta ou ocultada, mas não pode ser abafada nem extinta.", "A flame, equivalent in brightness to a torch, springs forth from an object that you touch. The effect looks like a regular flame, but it creates no heat and doesn't use oxygen. A continual flame can be covered or hidden but not smothered or quenched."],
  enlargeReduce: ["Você faz com que uma criatura ou objeto que possa ver dentro do alcance fique maior ou menor pela duração. Escolha uma criatura ou um objeto que não esteja sendo vestido nem carregado. Se o alvo não for voluntário, ele pode fazer um teste de resistência de Constituição. Em um sucesso, a magia não tem efeito.\n\nSe o alvo for uma criatura, tudo o que ela estiver vestindo e carregando muda de tamanho com ela. Qualquer item largado por uma criatura afetada retorna instantaneamente ao tamanho normal.\n\nAumentar. O tamanho do alvo dobra em todas as dimensões e seu peso é multiplicado por oito. Esse crescimento aumenta sua categoria de tamanho em um grau — de Médio para Grande, por exemplo. Se não houver espaço suficiente para o alvo dobrar de tamanho, a criatura ou objeto atinge o tamanho máximo possível no espaço disponível. Até a magia terminar, o alvo também tem vantagem em testes de Força e em testes de resistência de Força. As armas do alvo também crescem para se adequar ao novo tamanho. Enquanto essas armas estiverem aumentadas, os ataques do alvo com elas causam 1d4 de dano adicional.\n\nReduzir. O tamanho do alvo é reduzido pela metade em todas as dimensões e seu peso é reduzido a um oitavo do normal. Essa redução diminui sua categoria de tamanho em um grau — de Médio para Pequeno, por exemplo. Até a magia terminar, o alvo também tem desvantagem em testes de Força e em testes de resistência de Força. As armas do alvo também encolhem para se adequar ao seu novo tamanho. Enquanto essas armas estiverem reduzidas, os ataques do alvo com elas causam 1d4 a menos de dano (isso não pode reduzir o dano a menos de 1).", "You cause a creature or an object you can see within range to grow larger or smaller for the duration. Choose either a creature or an object that is neither worn nor carried. If the target is unwilling, it can make a Constitution saving throw. On a success, the spell has no effect.\n\nIf the target is a creature, everything it is wearing and carrying changes size with it. Any item dropped by an affected creature returns to normal size at once.\n\nEnlarge. The target's size doubles in all dimensions, and its weight is multiplied by eight. This growth increases its size by one category- from Medium to Large, for example. If there isn't enough room for the target to double its size, the creature or object attains the maximum possible size in the space available. Until the spell ends, the target also has advantage on Strength checks and Strength saving throws. The target's weapons also grow to match its new size. While these weapons are enlarged, the target's attacks with them deal 1d4 extra damage.\n\nReduce. The target's size is halved in all dimensions, and its weight is reduced to one-eighth of normal. This reduction decreases its size by one category-from Medium to Small, for example. Until the spell ends, the target also has disadvantage on Strength checks and Strength saving throws. The target's weapons also shrink to match its new size. While these weapons are reduced, the target's attacks with them deal 1d4 less damage (this can't reduce the damage below 1)."],
  magicMouth: ["Você implanta uma mensagem em um objeto dentro do alcance — uma mensagem que é pronunciada quando uma condição de ativação é satisfeita. Escolha um objeto que você consiga ver e que não esteja sendo vestido ou carregado por outra criatura. Então, fale a mensagem, que deve ter 25 palavras ou menos, embora possa ser transmitida ao longo de até 10 minutos. Por fim, determine a circunstância que fará a magia transmitir sua mensagem.\nQuando esse gatilho ocorre, uma boca mágica aparece no objeto e recita a mensagem com a sua voz e no mesmo volume em que você falou. Se o objeto escolhido tiver uma boca ou algo parecido com uma boca (por exemplo, a boca de uma estátua), a boca mágica aparece ali, de modo que as palavras parecem sair da boca do objeto. Ao conjurar esta magia, você pode fazer com que ela termine após transmitir a mensagem, ou ela pode permanecer e repetir a mensagem sempre que o gatilho ocorrer.\nO gatilho pode ser tão geral ou tão detalhado quanto você quiser, mas deve se basear em condições visuais ou audíveis que ocorram a até 9 metros do objeto. Por exemplo, você poderia instruir a boca a falar quando qualquer criatura se mover a até 9 metros do objeto ou quando um sino de prata tocar a até 9 metros dele.", "You implant a message within an object in range, a message that is uttered when a trigger condition is met. Choose an object that you can see and that isn't being worn or carried by another creature. Then speak the message, which must be 25 words or less, though it can be delivered over as long as 10 minutes. Finally, determine the circumstance that will trigger the spell to deliver your message.\n\nWhen that circumstance occurs, a magical mouth appears on the object and recites the message in your voice and at the same volume you spoke. If the object you chose has a mouth or something that looks like a mouth (for example, the mouth of a statue), the magical mouth appears there so that the words appear to come from the object's mouth. When you cast this spell, you can have the spell end after it delivers its message, or it can remain and repeat its message whenever the trigger occurs.\n\nThe triggering circumstance can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 feet of the object. For example, you could instruct the mouth to speak when any creature moves within 30 feet of the object or when a silver bell rings within 30 feet of it."],
  ropeTrick: ["Você toca um pedaço de corda com até 18 metros de comprimento. Uma extremidade da corda então se eleva no ar até que toda a corda fique pendurada perpendicularmente ao chão. Na extremidade superior da corda, uma entrada invisível se abre para um espaço extradimensional que dura até a magia terminar.\n\nO espaço extradimensional pode ser alcançado escalando-se até o topo da corda. O espaço pode comportar até oito criaturas de tamanho Médio ou menor. A corda pode ser puxada para dentro do espaço, fazendo-a desaparecer da vista do lado de fora.\n\nAtaques e magias não podem atravessar a entrada para dentro ou para fora do espaço extradimensional, mas aqueles que estiverem dentro podem olhar para fora como se fosse através de uma janela de 0,9 metro por 1,5 metro centrada na corda.\n\nQualquer coisa dentro do espaço extradimensional cai para fora quando a magia termina.", "You touch a length of rope that is up to 60 feet long. One end of the rope then rises into the air until the whole rope hangs perpendicular to the ground. At the upper end of the rope, an invisible entrance opens to an extradimensional space that lasts until the spell ends.\n\nThe extradimensional space can be reached by climbing to the top of the rope. The space can hold as many as eight Medium or smaller creatures. The rope can be pulled into the space, making the rope disappear from view outside the space.\n\nAttacks and spells can't cross through the entrance into or out of the extradimensional space, but those inside can see out of it as if through a 3-foot-by-5-foot window centered on the rope.\n\nAnything inside the extradimensional space drops out when the spell ends."],
  arcanistsMagicAura: ["Você coloca uma ilusão em uma criatura ou objeto que tocar, de modo que magias de adivinhação revelem informações falsas sobre o alvo. O alvo pode ser uma criatura voluntária ou um objeto que não esteja sendo carregado ou vestido por outra criatura.\n\nQuando conjurar a magia, escolha um ou ambos os efeitos a seguir. O efeito dura pela duração da magia. Se você conjurar esta magia na mesma criatura ou objeto todos os dias por 30 dias, colocando o mesmo efeito a cada vez, a ilusão durará até ser dissipada.\n\nAura Falsa. Você altera a forma como o alvo aparenta para magias e efeitos mágicos, como detectar magia, que detectam auras mágicas. Você pode fazer um objeto não mágico parecer mágico, um objeto mágico parecer não mágico, ou alterar a aura mágica do objeto para que aparente pertencer a uma escola específica de magia à sua escolha. Quando você usar este efeito em um objeto, você pode fazer com que a magia falsa seja perceptível para qualquer criatura que manuseie o item.\n\nMáscara. Você altera a forma como o alvo aparenta para magias e efeitos mágicos que detectam tipos de criaturas, como o Sentido Divino de um paladino ou o gatilho da magia símbolo. Você escolhe um tipo de criatura, e outras magias e efeitos mágicos tratam o alvo como se ele fosse uma criatura daquele tipo ou daquela tendência.", "You place an illusion on a creature or an object you touch so that divination spells reveal false information about it. The target can be a willing creature or an object that isn't being carried or worn by another creature.\n\nWhen you cast the spell, choose one or both of the following effects. The effect lasts for the duration. If you cast this spell on the same creature or object every day for 30 days, placing the same effect on it each time, the illusion lasts until it is dispelled.\n\nFalse Aura. You change the way the target appears to spells and magical effects, such as detect magic, that detect magical auras. You can make a nonmagical object appear magical, a magical object appear nonmagical, or change the object's magical aura so that it appears to belong to a specific school of magic that you choose. When you use this effect on an object, you can make the false magic apparent to any creature that handles the item.\n\nMask. You change the way the target appears to spells and magical effects that detect creature types, such as a paladin's Divine Sense or the trigger of a symbol spell. You choose a creature type and other spells and magical effects treat the target as if it were a creature of that type or of that alignment."],
  calmEmotions: ["Você tenta suprimir emoções fortes em um grupo de pessoas. Cada humanoide em uma esfera com 6 metros de raio centrada em um ponto à sua escolha dentro do alcance deve fazer uma salvaguarda de Carisma; uma criatura pode optar por falhar nesta salvaguarda se desejar. Se uma criatura falhar na salvaguarda, escolha um dos dois efeitos a seguir.\n\nVocê pode suprimir qualquer efeito que esteja fazendo um alvo ficar enfeitiçado ou amedrontado. Quando esta magia termina, qualquer efeito suprimido é retomado, desde que sua duração não tenha expirado nesse meio-tempo.\n\nAlternativamente, você pode tornar um alvo indiferente em relação a criaturas à sua escolha com as quais ele seja hostil. Essa indiferença termina se o alvo for atacado ou ferido por uma magia ou se testemunhar qualquer um dos seus amigos sendo ferido. Quando a magia termina, a criatura se torna hostil novamente, a menos que o Mestre determine o contrário.", "You attempt to suppress strong emotions in a group of people. Each humanoid in a 20-foot radius sphere centered on a point you choose within range must make a Charisma saving throw; a creature can choose to fail this saving throw if it wishes. If a creature fails its saving throw, choose one of the following two effects.\n\nYou can suppress any effect causing a target to be charmed or frightened. When this spell ends, any suppressed effect resumes, provided that its duration has not expired in the meantime.\n\nAlternatively, you can make a target indifferent about creatures of your choice that it is hostile toward. This indifference ends if the target is attacked or harmed by a spell or if it witnesses any of its friends being harmed. When the spell ends, the creature becomes hostile again, unless the GM rules otherwise."],
  detectThoughts: ["Pela duração, você pode ler os pensamentos de certas criaturas. Quando você conjura a magia e como sua ação em cada turno até a magia terminar, você pode focar sua mente em qualquer criatura que você possa ver a até 9 metros de você. Se a criatura que você escolher tiver Inteligência 3 ou menor ou não falar nenhum idioma, a criatura não é afetada.\n\nInicialmente, você toma conhecimento dos pensamentos superficiais da criatura — aquilo que mais ocupa a mente dela naquele momento. Como uma ação, você pode deslocar sua atenção para os pensamentos de outra criatura ou tentar sondar mais profundamente na mente da mesma criatura. Se sondar mais profundamente, o alvo deve fazer uma salvaguarda de Sabedoria. Se falhar, você obtém discernimento do raciocínio dele (se houver), de seu estado emocional e de algo que pese significativamente em sua mente (como algo com que se preocupe, ame ou odeie). Se for bem-sucedido, a magia termina. De qualquer forma, o alvo sabe que você está sondando a mente dele e, a menos que você mude sua atenção para os pensamentos de outra criatura, ele pode usar uma ação no turno dele para fazer um teste de Inteligência resistido pelo seu teste de Inteligência; se obtiver sucesso, a magia termina.\n\nPerguntas direcionadas verbalmente à criatura alvo moldam naturalmente o curso dos pensamentos dela, de modo que esta magia é particularmente eficaz como parte de um interrogatório.\n\nVocê também pode usar esta magia para detectar a presença de criaturas pensantes que não consiga ver. Quando você conjurar a magia ou como sua ação durante a duração, você pode buscar por pensamentos a até 9 metros de você. A magia pode penetrar barreiras, mas 60 centímetros de rocha, 5 centímetros de qualquer metal exceto chumbo ou uma folha fina de chumbo bloqueiam você. Você não pode detectar uma criatura com Inteligência 3 ou menor ou uma que não fale nenhum idioma.\n\nUma vez que detecte a presença de uma criatura dessa forma, você pode ler os pensamentos dela pelo restante da duração conforme descrito acima, mesmo que não possa vê-la, mas ela ainda deve estar dentro do alcance.", "For the duration, you can read the thoughts of certain creatures. When you cast the spell and as your action on each turn until the spell ends, you can focus your mind on any one creature that you can see within 30 feet of you. If the creature you choose has an Intelligence of 3 or lower or doesn't speak any language, the creature is unaffected.\n\nYou initially learn the surface thoughts of the creature-what is most on its mind in that moment. As an action, you can either shift your attention to another creature's thoughts or attempt to probe deeper into the same creature's mind. If you probe deeper, the target must make a Wisdom saving throw. If it fails, you gain insight into its reasoning (if any), its emotional state, and something that looms large in its mind (such as something it worries over, loves, or hates). If it succeeds, the spell ends. Either way, the target knows that you are probing into its mind, and unless you shift your attention to another creature's thoughts, the creature can use its action on its turn to make an Intelligence check contested by your Intelligence check; if it succeeds, the spell ends.\n\nQuestions verbally directed at the target creature naturally shape the course of its thoughts, so this spell is particularly effective as part of an interrogation.\n\nYou can also use this spell to detect the presence of thinking creatures you can't see. When you cast the spell or as your action during the duration, you can search for thoughts within 30 feet of you. The spell can penetrate barriers, but 2 feet of rock, 2 inches of any metal other than lead, or a thin sheet of lead blocks you. You can't detect a creature with an Intelligence of 3 or lower or one that doesn't speak any language.\n\nOnce you detect the presence of a creature in this way, you can read its thoughts for the rest of the duration as described above, even if you can't see it, but it must still be within range."],
  dragonsBreath: ["Você toca em uma criatura voluntária e a imbui com o poder de cuspir energia mágica pela boca, desde que ela tenha uma. Escolha ácido, elétrico, fogo, frio ou veneno. Até a magia terminar, a criatura pode usar uma ação para exalar energia do tipo escolhido em um cone de 4,5 metros. Cada criatura nessa área deve fazer uma salvaguarda de Destreza, sofrendo 3d6 de dano do tipo escolhido se falhar na salvaguarda, ou metade desse dano em um sucesso.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d6 para cada círculo do espaço acima do 2º.", "You touch one willing creature and imbue it with the power to spew magical energy from its mouth, provided it has one. Choose acid, cold, fire, lightning, or poison. Until the spell ends, the creature can use an action to exhale energy of the chosen type in a 15-foot cone. Each creature in that area must make a Dexterity saving throw, taking 3d6 damage of the chosen type on a failed save, or half as much damage on a successful one.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d6 for each slot level above 2nd."],
  enthrall: ["Você tece uma sequência de palavras que distraem, fazendo com que criaturas à sua escolha que você possa ver dentro do alcance e que possam ouvi-lo realizem um teste de resistência de Sabedoria. Qualquer criatura que não possa ser enfeitiçada é bem-sucedida automaticamente nesta salvaguarda e, se você ou seus companheiros estiverem lutando contra a criatura, ela tem vantagem na salvaguarda. Em uma falha, o alvo tem desvantagem em testes de Sabedoria (Percepção) feitos para perceber qualquer criatura que não seja você até a magia terminar ou até o alvo não poder mais ouvi-lo. A magia termina se você estiver incapacitado ou não puder mais falar.", "You weave a distracting string of words, causing creatures of your choice that you can see within range and that can hear you to make a Wisdom saving throw. Any creature that can't be charmed succeeds on this saving throw automatically, and if you or your companions are fighting a creature, it has advantage on the save. On a failed save, the target has disadvantage on Wisdom (Perception) checks made to perceive any creature other than you until the spell ends or until the target can no longer hear you. The spell ends if you are incapacitated or can no longer speak."],
  knock: ["Escolha um objeto que você possa ver dentro do alcance. O objeto pode ser uma porta, uma caixa, um baú, um par de algemas, um cadeado ou outro objeto que contenha um meio mundano ou mágico de impedir o acesso.\nUm alvo mantido fechado por uma fechadura mundana, ou que esteja emperrado ou trancado com barra, fica destrancado, desemperrado ou desbloqueado. Se o objeto tiver várias fechaduras, apenas uma delas é destrancada.\nSe o alvo estiver mantido fechado por Tranca Arcana, essa magia é suprimida por 10 minutos, período durante o qual o alvo pode ser aberto e fechado.\nQuando você conjura a magia, uma batida alta, audível a até 90 metros de distância, emana do alvo.", "Choose an object that you can see within range. The object can be a door, a box, a chest, a set of manacles, a padlock, or another object that contains a mundane or magical means that prevents access.\n\nA target that is held shut by a mundane lock or that is stuck or barred becomes unlocked, unstuck, or unbarred. If the object has multiple locks, only one of them is unlocked.\n\nIf you choose a target that is held shut with arcane lock, that spell is suppressed for 10 minutes, during which time the target can be opened and shut normally.\n\nWhen you cast the spell, a loud knock, audible from as far away as 300 feet, emanates from the target object."],
  mindSpike: ["Você penetra na mente de uma criatura que possa ver dentro do alcance. O alvo deve fazer um teste de resistência de Sabedoria, sofrendo 3d8 de dano Psíquico em uma falha na salvaguarda, ou metade desse dano em um sucesso. Em uma falha na salvaguarda, você também sempre sabe a localização do alvo até a magia terminar, mas apenas enquanto vocês dois estiverem no mesmo plano de existência. Enquanto possuir esse conhecimento, o alvo não pode se esconder de você e, se for invisível, não recebe benefício dessa condição contra você.\n\nEm Níveis Superiores. Quando você conjurar esta magia usando um espaço de magia de 3º círculo ou superior, o dano aumenta em 1d8 para cada círculo do espaço acima do 2º.", "You reach into the mind of one creature you can see within range. The target must make a Wisdom saving throw, taking 3d8 psychic damage on a failed save, or half as much damage on a successful one. On a failed save, you also always know the target’s location until the spell ends, but only while the two of you are on the same plane of existence. While you have this knowledge, the target can’t become hidden from you, and if it’s invisible it gains no benefit from that condition against you.\n\nAt Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd."],
  phantasmalForce: ["Você cria uma ilusão que cria raízes na mente de uma criatura que você possa ver dentro do alcance. O alvo deve fazer um teste de resistência de Inteligência. Em uma falha, você cria um objeto, criatura ou outro fenômeno visível fantasmagórico à sua escolha que não ocupe mais do que um Cubo de 3 metros e que seja perceptível apenas para o alvo pela duração. Esta magia não surte efeito em mortos-vivos ou constructos.\n\nO fantasma inclui som, temperatura e outros estímulos, evidentes apenas para a criatura.\n\nO alvo pode usar a ação dele para examinar o fantasma com um teste de Inteligência (Investigação) contra a CD de resistência da sua magia. Se o teste for bem-sucedido, o alvo percebe que o fantasma é uma ilusão e a magia termina.\n\nEnquanto um alvo for afetado pela magia, ele trata o fantasma como se fosse real. O alvo racionaliza quaisquer desfechos ilógicos ao interagir com o fantasma. Por exemplo, um alvo tentando atravessar uma ponte fantasmagórica que cruza um abismo cai assim que pisa na ponte. Se o alvo sobreviver à queda, ele ainda acredita que a ponte existe e inventa alguma outra explicação para a queda — foi empurrado, escorregou ou um vento forte pode tê-lo derrubado.\n\nUm alvo afetado fica tão convencido da realidade do fantasma que pode até sofrer dano da ilusão. Um fantasma criado para se parecer com uma criatura pode atacar o alvo. Da mesma forma, um fantasma criado para se parecer com fogo, uma poça de ácido ou lava pode queimar o alvo. A cada rodada no seu turno, o fantasma pode causar 1d6 de dano Psíquico ao alvo se ele estiver na área do fantasma ou a até 1,5 metro dele, desde que a ilusão seja de uma criatura ou perigo que logicamente possa causar dano, como ao atacar. O alvo percebe o dano como de um tipo apropriado à ilusão.", "You craft an illusion that takes root in the mind of a creature that you can see within range. The target must make an Intelligence saving throw. On a failed save, you create a phantasmal object, creature, or other visible phenomenon of your choice that is no larger than a 10-foot cube and that is perceivable only to the target for the duration. This spell has no effect on undead or constructs.\n\nThe phantasm includes sound, temperature, and other stimuli, also evident only to the creature.\n\nThe target can use its action to examine the phantasm with an Intelligence (Investigation) check against your spell save DC. If the check succeeds, the target realizes that the phantasm is an illusion, and the spell ends.\n\nWhile a target is affected by the spell, the target treats the phantasm as if it were real. The target rationalizes any illogical outcomes from interacting with the phantasm. For example, a target attempting to walk across a phantasmal bridge that spans a chasm falls once it steps onto the bridge. If the target survives the fall, it still believes that the bridge exists and comes up with some other explanation for its fall--it was pushed, it slipped, or a strong wind might have knocked it off.\n\nAn affected target is so convinced of the phantasm’s reality that it can even take damage from the illusion. A phantasm created to appear as a creature can attack the target. Similarly, a phantasm created to appear as fire, a pool of acid, or lava can burn the target. Each round on your turn, the phantasm can deal 1d6 psychic damage to the target if it is in the phantasm’s area or within 5 feet of the phantasm, provided that the illusion is of a creature or hazard that could logically deal damage, such as by attacking. The target perceives the damage as a type appropriate to the illusion."],
};

/**
 * Prepara o catálogo 2014 (SRD.SPELLS) para a tela em pt: resumo 2014 nas cópias de
 * magias 2024, resumos antigos mais claros e `metaPt` traduzido (Utils.spellMeta usa).
 * Troca objetos (desc) em vez de alterar os compartilhados com o catálogo 2024. Idempotente.
 */
export function localizeLegacySpells(spells) {
  for (const sp of spells || []) {
    if (!sp || sp.__ptLocalized) continue;
    const sum = LEGACY_SUMMARIES_2014[sp.id];
    if (sum) sp.desc = { pt: sum[0], en: sum[1] };
    else if (sp.desc?.pt && !sp.metaPt) sp.desc = { ...sp.desc, pt: polishPtText(sp.desc.pt) };
    if (!sp.metaPt) sp.metaPt = translateSpellMeta(sp);
    Object.defineProperty(sp, '__ptLocalized', { value: true, enumerable: false });
  }
  return spells;
}

export const EXTRA_SPELLS_2024 = RAW_EXTRA_SPELLS.map(s => ({ ...s, metaPt: translateSpellMeta(s) }));
